window.LOL_CHAMPS={"aatrox":{"id":"Aatrox","k":266,"n":"Aatrox","en":"Aatrox","t":"Darkin Kılıcı","cls":["Fighter"],"d":2,"res":"Kan Kuyusu","b":{"hp":650,"hpL":114,"ar":38,"arL":4.8,"mr":32,"mrL":2.05,"ad":60,"adL":5,"as":0.651,"asR":0.651,"asL":2.5,"rng":175,"ms":345,"t":"P"},"ab":[["Ölümün Ulağı","P","Belli aralıklarla Aatrox'un bir sonraki normal saldırısı, hedefin azami canına bağlı olarak ilave büyü hasarı verir ve Aatrox'u iyileştirir.","img/abil/aatrox-p.png"],["Darkin Kılıcı","Q","Aatrox devasa kılıcını yere çarparak fiziksel hasar verir. Kılıcını üç kez ve her defasında farklı bir etki alanına doğru savurabilir.","img/abil/aatrox-q.png",[14,12,10,8,6]],["Cehennem Prangası","W","Aatrox yere vurarak isabet alan ilk rakibe hasar verir. Şampiyon ve büyük canavarlar çabucak etki alanından çıkmazsa orta kısma sürüklenir ve yeniden hasar alır.","img/abil/aatrox-w.png",[18,16.5,15,13.5,12]],["Karanlık Hücum","E","Aatrox rakip şampiyonlara hasar verdiğinde pasif olarak iyileşir. Yetenek etkinleştirildiğinde Aatrox belli bir yönde atılır.","img/abil/aatrox-e.png",[9,8,7,6,5]],["Dünyaların Sonu","R","Aatrox şeytani biçimini gözler önüne sererek yakınındaki rakip minyonları korkutmasının yanı sıra saldırı gücü, iyileşme artışı ve hareket hızı kazanır. Aatrox bir şampiyonu alt ederse, etkinin süresi artar.","img/abil/aatrox-r.png",[120,100,80]]],"wk":"Aatrox","p":"img/champ/aatrox.png","tip":[["Darkin Kılıcı sırasında Karanlık Hücum kullanarak yeteneği rakibine isabet ettirme şansını arttır.","Cehennem Prangası gibi kitle kontrolü yetenekleri veya takım arkadaşlarının hareketsiz bırakma etkileri Darkin Kılıcı'nı kullanırken sana yardımcı olabilir.","Dünyaların Sonu yeteneğini rakiplerini savaşa zorlayabileceğinden emin olduğun zamanlarda kullan."],["Aatrox saldırılarını göstere göstere yapan biri, bu yüzden sahip olduğun süreyi isabet alanlarından kaçmak için kullan.","Cehennem Prangası'ndan daha kolay şekilde kurtulmak istiyorsan yanlara veya Aatrox'a doğru koş.","Aatrox ultisini kullandığında dirilmesini engellemek için aranızdaki mesafeyi korumaya çalış."]]},"ahri":{"id":"Ahri","k":103,"n":"Ahri","en":"Ahri","t":"Dokuz Kuyruklu Tilki","cls":["Mage","Assassin"],"d":2,"res":"Mana","b":{"hp":590,"hpL":104,"ar":21,"arL":4.2,"mr":30,"mrL":1.3,"ad":53,"adL":3,"as":0.668,"asR":0.625,"asL":2.2,"rng":550,"ms":330,"t":"M"},"ab":[["Öz Hırsızı","P","Ahri 9 minyon biçtikten veya canavar kestikten sonra iyileşir. Ahri bir rakip şampiyonu alt ettikten sonra daha fazla iyileşir.","img/abil/ahri-p.png"],["Aldatan Küre","Q","Ahri küresini ileri fırlatıp geri çeker; küre giderken büyü hasarı, dönerken de gerçek hasar verir.","img/abil/ahri-q.png",[7,7,7,7,7]],["Tilki Ateşi","W","Ahri kısa süreliğine hareket hızı artışı kazanır ve yakınındaki hedeflere kilitlenip saldıran üç tilki ateşi fırlatır.","img/abil/ahri-w.png",[9,8,7,6,5]],["Ayartan Öpücük","E","Ahri'nin gönderdiği öpücük, isabet ettiği rakibe hasar verir, tüm hareket yeteneklerini anında sonlandırır ve hedefi ayartarak uslu uslu Ahri'ye doğru gelmesini sağlar.","img/abil/ahri-e.png",[12,12,12,12,12]],["Ruh Saldırısı","R","Ahri ileri atılarak yakındaki rakiplere hasar veren öz ışınları gönderir. Ruh Saldırısı, bekleme süresine girmeden önce üç defaya kadar kullanılabilir ve Ahri rakip şampiyonları alt ettikçe ilave kullanımlar kazanır.","img/abil/ahri-r.png",[140,120,100]]],"wk":"Ahri","p":"img/champ/ahri.png","tip":[["Kombinasyonlarına Ayartan Öpücük kullanarak başla. Bu, Aldatan Küre ve Tilki Ateşi ile hedefi bulmanı kolaylaştırır.","Takım çatışmalarına Ayartan Öpücük kullanarak gir ve kaçanları Ruh Saldırısı ile kovala.","Ruh Saldırısı, Ahri'nin yeteneklerine olanak tanır, Ayartan Öpücük'e alan açar, Aldatan Küre'nin ikili vuruş yapmasını kolaylaştırır ve mesafeyi kısaltarak Tilki Ateşi'ni kullanmanı sağlar."],["Ulti yeteneği olan Ruh Saldırısı kullanılabilir halde değilken, Ahri'nin hayatta kalma yeteneği belirgin bir şekilde azalır.","Ayartan Öpücük'ten korunmak için minyonların arkasında kal; bu, Ahri'nin hasar verme olasılığını fark edilir derecede azaltacaktır."]]},"akali":{"id":"Akali","k":84,"n":"Akali","en":"Akali","t":"Efendisiz Suikastçı","cls":["Assassin"],"d":3,"res":"Enerji","b":{"hp":600,"hpL":119,"ar":23,"arL":4.7,"mr":37,"mrL":2.05,"ad":62,"adL":3.3,"as":0.625,"asR":0.625,"asL":3.2,"rng":125,"ms":345,"t":"P"},"ab":[["Suikastçının Damgası","P","Bir şampiyona yetenek hasarı vermek, hedefin etrafında enerji halkası oluşturur. Bu halkadan geçmek Akali'nin bir sonraki saldırısına ilave menzil ve hasar sağlar.","img/abil/akali-p.png"],["Beş Nokta Saldırısı","Q","Akali beş kunai fırlatarak ilave saldırı gücü ve yetenek gücüne bağlı olarak hasar verip yavaşlatma etkisi uygular.","img/abil/akali-q.png",[1.5,1.5,1.5,1.5,1.5]],["Alacakaranlık Perdesi","W","Akali bir duman bombası atar ve kısa süreliğine hareket hızı kazanır. Perdenin içindeyken Akali görünmez olur ve rakiplerin yetenekleri veya saldırılarıyla hedef alınamaz hale gelir. Saldırmak veya yetenek kullanmak Akali'yi kısa süreliğine açığa çıkarır.","img/abil/akali-w.png",[20,19,18,17,16]],["Çevik Silah","E","Geriye doğru sıçrayarak büyü hasarı veren bir shuriken fırlatır. İsabet alan ilk rakip veya duman bulutu işaretlenir. Yetenek yeniden kullanıldığında işaretli hedefe atılarak fazladan hasar verir.","img/abil/akali-e.png",[16,14.5,13,11.5,10]],["Kusursuz İnfaz","R","Akali belli bir doğrultuda sıçrayarak isabet alan rakiplere hasar verir. Yeniden kullanım: Akali belli bir doğrultuda atılır ve isabet alan bütün rakipleri infaz eder.","img/abil/akali-r.png",[120,90,60]]],"wk":"Akali","p":"img/champ/akali.png","tip":[["Akali dayanıksız karakterleri alt etmekte ustadır. Saldırıyı takımının başlatmasına izin ver ve rakiplerine arkadan saldır.","Alacakaranlık Perdesi, en tehlikeli durumlarda bile kendini korumanı sağlar. Bu süreyi daha sonra gerçekleştireceğin hızlı bir saldırı için enerji biriktirmeye ayır."],["Akali, Alacakaranlık Perdesi'nin ardında maskelenmiş olsa da alan etkili yeteneklerden isabet alabilir. Bu durumda bulunduğu konum kısa süreliğine açığa çıkar.","Akali'nin Beş Nokta Saldırısı azami menzil ve enerji miktarında kullanıldığında çok güçlüdür. Takasları kazanma şansını arttırmak için ona düşük enerji seviyelerindeyken saldırmaya çalış.","Canın azsa ve Akali'nin ultisi hazırsa üssüne dön."]]},"akshan":{"id":"Akshan","k":166,"n":"Akshan","en":"Akshan","t":"Efendisiz Muhafız","cls":["Marksman","Assassin"],"d":2,"res":"Mana","b":{"hp":610,"hpL":107,"ar":26,"arL":4.7,"mr":33,"mrL":1.1,"ad":52,"adL":3,"as":0.638,"asR":0.4,"asL":4,"rng":500,"ms":330,"t":"P"},"ab":[["Kirli Dövüş","P","Akshan'ın isabet ettirdiği her üçüncü saldırı veya yetenek ilave hasar verir ve hedef bir şampiyonsa ona kalkan sağlar. Akshan saldırdığında daha az hasar veren ilave bir saldırı daha yapar. İlave saldırıyı iptal ederse hareket hızı kazanır.","img/abil/akshan-p.png"],["İntikam Bumerangı","Q","Akshan hem ileri giderken hem de geri dönerken hasar veren bir bumerang fırlatır. Bumerangın menzili, isabet ettiği her rakiple birlikte artar.","img/abil/akshan-q.png",[9,8,7,6,5]],["Görünmez Muhafız","W","Akshan, takım arkadaşlarını katleden rakip şampiyonları kendiliğinden madrabaz olarak işaretler. Akshan bir madrabazı katlettiğinde katledilen takım arkadaşlarını diriltir, ilave altın kazanır ve tüm işaretleri kaldırır. Yetenek etkinleştirildiğinde Akshan kamuflaja bürünür ve madrabazlara doğru ilerlerken hareket hızı ve mana yenilenmesi kazanır. Akshan kamuflaj etkisini bir çalı veya yüzey şeklinin yakınında değilken çabucak kaybeder.","img/abil/akshan-w.png",[18,14,10,6,2]],["Kahraman Sallanışı","E","Akshan kancasıyla bir yüzey şekline bağlanır ve daha sonra onun etrafında sallanarak en yakınındaki rakibe art arda ateş eder. Halatı erken bırakabilir veya bir şampiyon ya da yüzey şekline çarparsa yere iner.","img/abil/akshan-e.png",[18,16.5,15,13.5,12]],["Kısasa Kısas","R","Akshan bir rakip şampiyona kilitlenerek silahına mermi doldurmaya başlar. Yoğunlaşma sona erdiğinde doldurduğu tüm mermileri ateşleyerek isabet alan ilk şampiyona, minyona veya yapıya eksik cana bağlı olarak hasar verir.","img/abil/akshan-r.png",[100,85,70]]],"wk":"Akshan","p":"img/champ/akshan.png","tip":[["Tehlike karşısında gülümseyen erdemli intikamcı Akshan, baş döndüren karizmasıyla kötülüğe karşı savaşıyor. Ayrıca bunu yaparken asla bir gömlek giymemesi de cabası. Gizlenerek dövüşme sanatında son derece yetenekli savaşçı, ansızın gölgelere karışabiliyor ve düşmanlarına hiç ummadıkları bir anda saldırıyor. Keskin adalet görüşü ve ölümü geri çevirebilen efsanevi silahıyla Runeterra'daki birçok madrabazın yanlışlarını düzeltirken, bir yandan da yaşamını kendi ahlaki felsefesine göre sürdürüyor: ''Hıyarlığın lüzumu yok.''"],[]]},"alistar":{"id":"Alistar","k":12,"n":"Alistar","en":"Alistar","t":"Minotor","cls":["Tank","Support"],"d":3,"res":"Mana","b":{"hp":685,"hpL":120,"ar":40,"arL":4.7,"mr":32,"mrL":2.05,"ad":62,"adL":3.75,"as":0.625,"asR":0.625,"asL":2.125,"rng":125,"ms":335,"t":"M"},"ab":[["Zafer Narası","P","Alistar rakip şampiyonları sersemlettiğinde, onların yerini değiştirdiğinde veya yakınındaki rakipler katledildiğinde kükremesi için güç toplar. Gücünü tamamen topladığında kendisini ve yakınındaki tüm takım arkadaşlarını iyileştirir.","img/abil/alistar-p.png"],["Unufak Et","Q","Alistar yere şiddetli bir darbe indirerek yakınındaki rakiplere hasar verir ve onları havaya savurur.","img/abil/alistar-q.png",[14,13,12,11,10]],["Tos","W","Alistar koşup hedefine tos vurarak hasar verir ve hedefi geri savurur.","img/abil/alistar-w.png",[14,13,12,11,10]],["Ezgeç","E","Alistar yakındaki rakip birimleri dümdüz eder, birimlerin içinden geçebilir ve bir rakip şampiyona hasar verirse yük kazanır. Alistar'ın yükleri tamamen dolduktan sonra bir rakip şampiyona yönelik ilk normal saldırısı ilave büyü hasarı verir ve hedefini sersemletir.","img/abil/alistar-e.png",[12,11.5,11,10.5,10]],["Kırılmaz İrade","R","Alistar vahşi bir kükremeyle üstündeki tüm kitle kontrolü etkilerinden kurtulur. Ayrıca kükremenin etki süresi boyunca daha az fiziksel hasar ve büyü hasarı alır.","img/abil/alistar-r.png",[120,100,80]]],"wk":"Alistar","p":"img/champ/alistar.png","tip":[["Unufak Et'i kullanmak, Tos için daha uygun bir yere geçmeni sağlayabilir.","Hareket hızı Alistar için çok önemlidir. Hangi çizmeleri satın alacağını iyi düşün.","Sıçra yeteneğini kullanarak rakibini gafil avlayabilir ve Unufak Et ile Tos'u kullanarak onu takım arkadaşlarının ortasına savurabilirsin."],["Alistar epey sıkıntı yaratır ama çok da dayanıklıdır, daha zayıf hedeflere yönelmeye çalış.","Kulelerin etrafında Unufak Et - Tos kombolarına dikkat et.","Alistar ultisini kullandığında, ona saldırmadan önce geriye çekilmek ve etkisinin geçmesini beklemek genellikle daha iyi olur."]]},"ambessa":{"id":"Ambessa","k":799,"n":"Ambessa","en":"Ambessa","t":"Savaş Maderşahı","cls":["Fighter","Assassin"],"d":3,"res":"Enerji","b":{"hp":630,"hpL":110,"ar":35,"arL":4.9,"mr":32,"mrL":2.05,"ad":63,"adL":3,"as":0.625,"asR":0.625,"asL":2.5,"rng":125,"ms":335,"t":"P"},"ab":[["Ejderan Adımı","P","Bir yetenek kullanırken saldırı veya hareket komutu vermek, yetenek kullanıldığında Ambessa'nın kısa bir mesafe atılmasını sağlar. Ayrıca bir sonraki saldırısı hem ilave menzil, hasar ve saldırı hızı kazanır hem de enerji iade eder.","img/abil/ambessa-p.png"],["Kurnaz Hücum / Sarsan Vuruş","Q","Ambessa ikiz ejderanlarını önündeki yarım daire şeklindeki alana doğru savurarak isabet alan rakiplere ilave hasar verir. Bu yeteneği bir rakibe isabet ettirmek kısa süreliğine bir sonraki kullanımını dönüştürerek ikiz ejderanlarını önündeki bir hat üstünde yere vurmasını sağlar. İsabet alan ilk rakip ilave hasar alır.","img/abil/ambessa-q.png",[14,13,12,11,10]],["İnkâr","W","Ambessa bir kalkan kazanır, kısa süreliğine kendisini hazırlar ve ardından yere vurarak yakınındaki rakiplere hasar verir. Kendisini hazırlarken minyonlar dışındaki birimlerden gelen bir hasarı engellerse bu yetenek fazladan hasar verir.","img/abil/ambessa-w.png",[18,17,16,15,14]],["Paramparça","E","Ambessa ikiz ejderanlarını etrafında kırbaç gibi savurarak yakınındaki rakiplere hasar verir ve onları yavaşlatır. Bu yetenekle Ejderan Adımı'nı kullanmak atılmanın sonunda bu yeteneğin bir daha tetiklenmesini sağlar.","img/abil/ambessa-e.png",[13,12,11,10,9]],["Mutlak İnfaz","R","Ambessa seçtiği bir hat üstündeki en uzak rakip şampiyona ışınlanır ve hedefine ulaştığında onu sindirir. Ardından rakibi yere çarparak sersemletir ve ona hasar verir.","img/abil/ambessa-r.png",[130,115,100]]],"wk":"Ambessa","p":"img/champ/ambessa.png","tip":[[],[]]},"amumu":{"id":"Amumu","k":32,"n":"Amumu","en":"Amumu","t":"Hüzünlü Mumya","cls":["Tank","Support"],"d":1,"res":"Mana","b":{"hp":685,"hpL":94,"ar":33,"arL":4,"mr":32,"mrL":2.05,"ad":57,"adL":3.8,"as":0.736,"asR":0.638000011444091,"asL":2.18,"rng":125,"ms":335,"t":"M"},"ab":[["Lanetli Dokunuş","P","Amumu'nun normal saldırıları rakiplerini Lanetler ve büyü hasarına maruz kaldıklarında ilave gerçek hasar almalarını sağlar.","img/abil/amumu-p.png"],["Sargı Atışı","Q","Amumu, bir hedefe yapışkan bir sargı fırlatıp kendini ona doğru çeker ve hedefin sersemleyip hasar almasını sağlar.","img/abil/amumu-q.png",[3,3,3,3,3]],["Gözyaşı Seli","W","Yakındaki rakipler acı içinde kalarak her saniye azami canlarının belli bir yüzdesini kaybeder ve üstlerindeki lanetler yenilenir.","img/abil/amumu-w.png",[1,1,1,1,1]],["Sinir Krizi","E","Amumu'nun aldığı fiziksel hasarı kalıcı olarak azaltır. Amumu hiddetini serbest bırakarak yakınındaki rakiplere hasar verebilir. Amumu her isabet aldığında Sinir Krizi'nin bekleme süresi azalır.","img/abil/amumu-e.png",[9,8,7,6,5]],["Hüzünlü Mumya'nın Laneti","R","Amumu çevresindeki rakip birimleri sargıya dolayarak lanetler, sersemletir ve onlara hasar verir.","img/abil/amumu-r.png",[150,125,100]]],"wk":"Amumu","p":"img/champ/amumu.png","tip":[["Amumu takım arkadaşlarına çok bağımlıdır. Bu yüzden, en fazla verimi elde etmek için dostlarınla birlikte aynı koridorda ilerlemeye çalış.","Bekleme Süresinde Azalma, Amumu'da çok etkilidir; ama bunu sağlayacak eşyaları toplamak genellikle zordur. Niteliklerinden ödün vermeden Bekleme Süresinde Azalma elde etmek için, her fırsatta Mavi Gözcü güçlendirmesini almaya çalış.","Gözyaşı Seli, diğer tanklara karşı çok etkili bir yetenektir. Bu yüzden rakiplerinin karşısına çıktığında olabildiğince yüksek Can sahibi olmaya bak."],["Amumu'nun ultisi kullanılabilir olduğunda takım arkadaşlarına yakın durmaktan kaçın.","Değişken hareketler ya da minyon dalgalarının arkasına saklanmak, Amumu'nun Sargı Atışı'yla bir kavga başlatmasını zorlaştıracaktır.","Amumu'nun Gözyaşı Seli, ilk başta Can veren eşyaları satın almayı riskli bir plan haline getirir."]]},"anivia":{"id":"Anivia","k":34,"n":"Anivia","en":"Anivia","t":"Buz Ankası","cls":["Mage"],"d":3,"res":"Mana","b":{"hp":550,"hpL":92,"ar":19,"arL":4.1,"mr":30,"mrL":1.3,"ad":51,"adL":3.2,"as":0.658,"asR":0.625,"asL":1.68,"rng":600,"ms":325,"t":"M"},"ab":[["Yeniden Doğuş","P","Anivia ölümcül hasar aldığında yumurtaya dönüşür ve tam canla yeniden doğar.","img/abil/anivia-p.png"],["Buz Kütlesi","Q","Anivia kanatlarını kavuşturarak, rakiplerine doğru ilerleyen, yoluna çıkan herkesin donmasına ve hasar görmesine neden olan bir buz kütlesi ortaya çıkarır. Buz kütlesi patladığında belli bir alana orta derecede hasar vererek bölgedeki herkesi sersemletir.","img/abil/anivia-q.png",[11,10,9,8,7]],["Buz Duvarı","W","Anivia havadaki nemi yoğunlaştırarak, her tür hareketi engelleyen, geçilmez bir buz duvarına dönüştürür. Duvar, kısa bir süre sonra eriyerek yok olur.","img/abil/anivia-w.png",[17,17,17,17,17]],["Ayaz Yanığı","E","Anivia, kanatlarını çırparak hedefine dondurucu bir rüzgâr gönderir ve ona hasar verir. Hedef, kısa süre önce Buz Kütlesi'nden isabet almış ya da tamamen gelişmiş bir Buzul Fırtınası'ndan hasar almışsa iki kat hasar alır.","img/abil/anivia-e.png",[4,4,4,4,4]],["Buzul Fırtınası","R","Anivia şiddetli bir buz ve dolu sağanağı başlatarak rakiplerine hasar verir ve ilerleyişlerini yavaşlatır.","img/abil/anivia-r.png",[4,3,2]]],"wk":"Anivia","p":"img/champ/anivia.png","tip":[["Buz Kütlesi ile Ayaz Yanığı'nın zamanlamasını tutturmak, yıkıcı kombinasyonlar ortaya çıkarabilir.","Anivia Buzul Fırtınası için Mana'ya muhtaçtır. Mana veren eşyalar seçmeye ya da Sihirdar Vadisi'ndeki Mavi Gözcü güçlendirmesini edinmeye çalış.","Rakip şampiyonların Anivia'nın yumurtasını oyunun başlarında öldürmesi oldukça zor olabilir. Saldırgan oynayarak bu fırsattan faydalan."],["Anivia koridorda ilerlerken saldırmaya çalış. Birkaç kişiyle beraber saldırmak, yumurtasının öldüğünden emin olmanı kolaylaştırır.","Eğer menzilli saldıran bir şampiyon kullanıyorsan, yeterince uzakta dur; böylece Buz Kütlesi'ni daha kolay savuşturabilirsin.","Anivia ile koridorda dövüşmeye çalış. Ormanda, düşük kademeli Buz Duvarı ile yolunu tıkayabilir."]]},"annie":{"id":"Annie","k":1,"n":"Annie","en":"Annie","t":"Şeytan Çekici","cls":["Mage","Support"],"d":2,"res":"Mana","b":{"hp":560,"hpL":96,"ar":23,"arL":4,"mr":30,"mrL":1.3,"ad":50,"adL":2.65,"as":0.61,"asR":0.625,"asL":1.36,"rng":625,"ms":335,"t":"M"},"ab":[["Kundakçı","P","Annie 4 yetenek kullandıktan sonra, saldırıya yönelik bir sonraki yeteneği hedefi sersemletir. Annie oyuna başladığında veya dirildiğinde Kundakçı etkinleşir.","img/abil/annie-p.png"],["Yok Et","Q","Annie, içi Mana dolu bir ateş topu yollar; top hedefi yok ederse, Mana bedelini geri kazanır.","img/abil/annie-q.png",[4,4,4,4,4]],["Ateşle","W","Annie'nin püskürttüğü kavurucu ateş, koni şeklindeki bir alanda bulunan bütün hedeflere hasar verir.","img/abil/annie-w.png",[7,7,7,7,7]],["Alev Kalkanı","E","Annie'ye veya bir takım arkadaşına kalkan ve hareket hızı artışı sağlar. Ayrıca ona normal saldırı veya yetenek isabet ettiren rakiplere hasar verir.","img/abil/annie-e.png",[10,10,10,10,10]],["Çağır: Tibbers","R","Annie ayısı Tibbers'a ete bürünmesini buyurur ve bölgedeki birimlere hasar verir. Tibbers yakınında duran birimlere saldırırken, onları yakabilir.","img/abil/annie-r.png",[130,115,100]]],"wk":"Annie","p":"img/champ/annie.png","tip":[["Sersemletmeyi ulti yeteneğiyle kullanmak için saklamak takım dövüşlerinde her şeyi değiştirebilir.","Minyonlara, Yok Et yeteneğiyle son vuruşu yapmak; Annie'nin oyunun başlarındaki minyon biçme potansiyelini güçlendirir.","Alev Kalkanı, Annie'nin sersemletmesini doldurmak için çok iyi bir büyüdür. Bu yüzden, oyunun başında bu büyüye en az 1 kademe vermek faydalı olabilir."],["Annie'nin ayısı Tibbers, çağrıldığında etrafındaki rakip birimleri yakar. Çağrıldıktan sonra onunla arandaki mesafeyi korumaya çalış.","Sihirdar Büyüsü Çarp, Tibbers'ı alt etmek için kullanılabilir.","Annie'nin çevresinde dönen, beyaz güce dikkat et. Bu, sersemletme yeteneğini kullanmaya hazır olduğu anlamına gelmektedir."]]},"aphelios":{"id":"Aphelios","k":523,"n":"Aphelios","en":"Aphelios","t":"İtikatın Silahı","cls":["Marksman"],"d":3,"res":"Mana","b":{"hp":600,"hpL":102,"ar":26,"arL":4.2,"mr":33,"mrL":1.1,"ad":55,"adL":2.3,"as":0.665,"asR":0.658,"asL":2.1,"rng":550,"ms":325,"t":"P"},"ab":[["Tetikçi ve Kâhin","P","Aphelios, kız kardeşi Alune'nin oluşturduğu 5 Lunari silahını kullanır. Aynı anda biri birincil diğeri de ikincil olmak üzere iki silaha erişimi bulunur. Her silahın özgün bir normal saldırısı ve yeteneği vardır. Saldırılar ve yetenekler, silahın cephanesini tüketir. Aphelios cephanesi biten silahı bırakır ve Alune 5 silahtan bir sonrakini oluşturur.","img/abil/aphelios-p.png"],["Silah Yetenekleri","Q","Aphelios'un, birincil silahına bağlı olarak değişen 5 farklı aktif yeteneği bulunur: Calibrum (Tüfek): Uzun menzilli atışıyla hedefini işaretleyerek Aphelios'un uzun menzilli ikinci bir saldırı yapmasını sağlar. Severum (Tırpan Tabanca): İki silahıyla da yakındaki rakiplere saldırırken Aphelios'un hızla koşmasını sağlar. Gravitum (Top): Bu silahla yavaşlatılan tüm rakipleri sabitler. Infernum (Alev Silahı): Koni şeklindeki bir alanda duran rakiplere alev atar ve Aphelios'un ikincil silahıyla onlara saldırmasını sağlar. Crescendum (Çakram): İkincil silahını ateşleyen bir Gözcü Taret bırakır.","img/abil/aphelios-q.png",[9,9,9,9,9,9]],["Dönüştür","W","Aphelios birincil silahıyla ikincil silahını değiştirerek normal saldırılarını ve aktif yeteneğini değiştirir.","img/abil/aphelios-w.png",[0.8,0.8,0.8,0.8,0.8,0.8]],["Silah Sırası Sistemi","E","Aphelios'un üçüncü bir yeteneği yok. Bu yuvada Alune'nin ona vereceği bir sonraki silah görünür. Silahların sırası ilk başta bellidir ama zamanla değişebilir. Cephanesi biten bir silah, sıranın sonuna geçer.","img/abil/aphelios-e.png",[0,0,0,0,0,0]],["Ay Işığı Nöbeti","R","Bir rakip şampiyona isabet ettiğinde patlayan yoğun bir ay ışığı gönderir. Aphelios'un birincil silahının özel etkisini uygular.","img/abil/aphelios-r.png",[120,110,100]]],"wk":"Aphelios","p":"img/champ/aphelios.png","tip":[["Aphelios'un her bir silahının farklı güçlü yönleri var. Mevcut silahlarını kullanabileceğin en uygun durumu bulmaya çalış."],["Aphelios'un her bir silahının farklı zayıf noktaları var. Şampiyonun için en verimli olandan faydalanmaya çalış. Mor yerçekimi silahına dikkat et. Seni sabitleyebilir."]]},"ashe":{"id":"Ashe","k":22,"n":"Ashe","en":"Ashe","t":"Ayaz Okçu","cls":["Marksman","Support"],"d":2,"res":"Mana","b":{"hp":610,"hpL":101,"ar":26,"arL":4.6,"mr":33,"mrL":1.1,"ad":59,"adL":3,"as":0.658,"asR":0.657999992370605,"asL":3,"rng":600,"ms":325,"t":"P"},"ab":[["Buz Atışı","P","Ashe, saldırılarıyla hedefleri yavaşlatarak bu hedeflere daha fazla hasar verir. Ashe'in kritik vuruşları ilave hasar vermez ama hedefe güçlü bir yavaşlatma etkisi uygular.","img/abil/ashe-p.png"],["Pürdikkat","Q","Ashe saldırı yaptıkça Odak biriktirir. Azami Odak yüküne ulaştığında, Ashe Pürdikkat yeteneğini kullanarak bütün Odak yüklerini harcayabilir. Bu yetenek Ashe'e bir süreliğine Saldırı Hızı verir ve bu süre boyunca Ashe'in normal saldırısı güçlü bir ok yağmuruna dönüşür.","img/abil/ashe-q.png",[0,0,0,0,0]],["Yaylım Ateşi","W","Ashe, ilerledikçe yayılan ve fazladan hasar veren oklar fırlatır. Ayrıca Buz Atışı etkisi uygular.","img/abil/ashe-w.png",[18,14.5,11,7.5,4]],["Şahin Atışı","E","Ashe, Şahin Ruhu'nu haritanın herhangi bir yerine keşif görevine gönderebilir.","img/abil/ashe-e.png",[5,5,5,5,5]],["Büyülü Kristal Ok","R","Ashe düz bir hatta buzdan bir ok atar. Ok rakip bir şampiyona çarparsa hasar verir ve şampiyonun sersemlemesine neden olur. Sersemletme süresi, okun kat ettiği mesafe arttıkça artar. Ayrıca hedefin çevresindeki birimler de hasar alarak yavaşlar.","img/abil/ashe-r.png",[100,80,60]]],"wk":"Ashe","p":"img/champ/ashe.png","tip":[["Büyülü Kristal Ok'u rakiplerin hareket ettiği doğrultuda fırlatmaya çalışırsan vurma ihtimalin daha da artar.","Yaylım Ateşi ile fırlatılan oklar isabet ettiği ilk rakip tarafından engellenebilir; attığın bütün okların rakibin fedaileri tarafından yutulmaması için mesafeni korumaya özen göster.","Şahin Atışı çalılıktaki birimleri görmeni sağlar. Ormanda bir takım çatışması gerçekleşiyorsa bu yetenek büyük avantaj sağlayabilir."],["Ashe'in savunmaya yönelik çok az seçeneği vardır ve bu yüzden, baskın için iyi bir hedeftir.","Ashe bir süredir Büyülü Kristal Ok yeteneğini kullanmadıysa haritada tek başına dolaşırken dikkatli ol."]]},"aurelionsol":{"id":"AurelionSol","k":136,"n":"Aurelion Sol","en":"Aurelion Sol","t":"Yıldızların Hâkimi","cls":["Mage"],"d":3,"res":"Mana","b":{"hp":600,"hpL":90,"ar":22,"arL":4,"mr":30,"mrL":1.3,"ad":58,"adL":3.2,"as":0.625,"asR":0.625,"asL":1.5,"rng":550,"ms":340,"t":"M"},"ab":[["Kozmik Hâkim","P","Aurelion Sol'ün hasar veren yetenekleri rakipleri Yıldız Tozu'na dönüştürür ve bu, Aurelion Sol'ün her bir yeteneğini kalıcı olarak güçlendirir.","img/abil/aurelionsol-p.png"],["Işığın Nefesi","Q","Aurelion Sol'ün birkaç saniyeliğine yoğunlaşarak püskürttüğü ejder nefesi, isabet ettiği ilk rakibe normal miktarda, onun yakınındaki rakiplereyse biraz daha az miktarda hasar verir. Ejder nefesi, doğrudan bir rakibin üstüne yönlendirildiği her saniye ilave hasar verir. Bu ilave, toplanan Yıldız Tozu miktarına bağlı olarak artar. Ayrıca hedef bir şampiyonsa bu yetenek Yıldız Tozu toplar.","img/abil/aurelionsol-q.png",[3,3,3,3,3]],["Astral Seyahat","W","Aurelion Sol yüzey şekillerinin üstünden geçerek hedef yöne doğru uçar. Bu haldeyken diğer yeteneklerini kullanabilir. Aurelion Sol uçarken Işığın Nefesi'nin hem bekleme süresi hem de azami yoğunlaşma süresi kaldırılır ve hasarı artar. Astral Seyahat'in kalan bekleme süresi, Aurelion Sol'den hasar aldıktan sonra kısa bir süre içinde katledilen rakip şampiyon başına azalır. Yıldız Tozu, Astral Seyahat'in azami menzilini arttırır.","img/abil/aurelionsol-w.png",[22,20,18,16,14]],["Çekim Kuvveti","E","Aurelion Sol, rakiplere hasar veren ve onları yavaşça merkezine doğru çeken bir kara delik oluşturur. Bu yetenek, kara delik içinde katledilen rakip ve rakip şampiyonların kara delik içinde geçirdiği saniye başına Yıldız Tozu kazandırır. Kara deliğin merkezi, azami canı belli bir yüzdenin altındaki rakipleri infaz eder. Yıldız Tozu, Çekim Kuvveti'nin etki alanını ve infaz eşiğini arttırır.","img/abil/aurelionsol-e.png",[12,12,12,12,12]],["Yıldız Kayması / Gök Yıkılırken","R","Yıldız Kayması: Aurelion Sol, gökten bir yıldız indirir. Bu yetenek çarpışma alanındaki rakiplere büyü hasarı verir, onları sersemletir ve isabet alan rakip şampiyon başına Yıldız Tozu kazandırır. Yeterince Yıldız Tozu toplandığında Aurelion Sol'ün bir sonraki Yıldız Kayması yeteneği Gök Yıkılırken'e dönüşür. Gök Yıkılırken: Aurelion Sol gökten devasa bir yıldız indirerek daha büyük bir alana daha fazla hasar verir ve rakipleri sersemletmek yerine havaya savurur. Çarpışma alanının kenarından yayılan şok dalgası isabet ettiği rakiplere hasar verir ve onları yavaşlatır. Yıldız Tozu hem Yıldız Kayması hem de Gök Yıkılırken yeteneklerinin çarpışma alanını genişletir.","img/abil/aurelionsol-r.png",[120,110,100]]],"wk":"Aurelion Sol","p":"img/champ/aurelionsol.png","tip":[[],[]]},"aurora":{"id":"Aurora","k":893,"n":"Aurora","en":"Aurora","t":"Dünyalar Arasındaki Cadı","cls":["Mage","Assassin"],"d":2,"res":"Mana","b":{"hp":607,"hpL":110,"ar":23,"arL":4.5,"mr":32,"mrL":1.3,"ad":53,"adL":3,"as":0.668,"asR":0.668,"asL":2,"rng":550,"ms":335,"t":"M"},"ab":[["Ruhsal Feragat","P","Aurora'nın yetenekleri ve saldırıları, hasar verdikleri rakiplerden ruh çıkarır. Çıkarılmış ruhlar Aurora'yı takip eder ve iyileştirir.","img/abil/aurora-p.png"],["Çifte Nazar","Q","Aurora, isabet alan rakiplere nazar değdiren bir atış yapar. Yeteneği yeniden kullanarak etkin nazarları kendine doğru geri çekebilir ve onun temas ettiği rakiplere hasar verir.","img/abil/aurora-q.png",[9,8.5,8,7.5,7]],["Perdenin Arkası","W","Aurora seçili yöne doğru zıplayarak yere indiğinde ruhlar âlemine girer ve kısa süreliğine görünmez olup hareket hızı kazanır.","img/abil/aurora-w.png",[22,21,20,19,18]],["Acayiplik","E","Aurora âlemleri birleştirerek isabet alan rakiplere büyü hasarı veren ve onları yavaşlatan bir ruh sihri patlaması gönderir ve hemen ardından geriye zıplar.","img/abil/aurora-e.png",[15,14,13,12,11]],["Dünyalar Arasında","R","Aurora seçili yöne doğru zıplayarak isabet alan rakiplere hasar veren ve onları yavaşlatan bir şok dalgası yayar. Daha sonra içindeki rakipleri yavaşlatan ve Aurora'nın bir ucundan diğerine ışınlanabilmesini sağlayan bir alan oluşturur.","img/abil/aurora-r.png",[140,120,100]]],"wk":"Aurora","p":"img/champ/aurora.png","tip":[[],[]]},"azir":{"id":"Azir","k":268,"n":"Azir","en":"Azir","t":"Kumların İmparatoru","cls":["Mage","Marksman"],"d":3,"res":"Mana","b":{"hp":575,"hpL":108,"ar":25,"arL":5,"mr":30,"mrL":1.3,"ad":56,"adL":3.5,"as":0.625,"asR":0.694,"asL":5,"rng":550,"ms":330,"t":"M"},"ab":[["Shurima'nın Mirası","P","Azir yok edilen dost ya da rakip kulelerin kalıntılarından Güneş Kursu oluşturabilir.","img/abil/azir-p.png"],["Kumların Fatihi","Q","Azir, tüm Kumdan Askerlere belli bir konuma gitme emri verir. Kumdan Askerler koşarlarken çarpıp içinden geçtikleri bütün hedeflere büyü hasarı verir ve 1 saniyeliğine yavaşlatma etkisi uygular.","img/abil/azir-q.png",[14,12,10,8,6]],["İleri!","W","Azir, menzili içindeki hedeflere onun yerine normal saldırı yapması için bir Kumdan Asker çağırır. Bu saldırılar bir hat üstündeki rakiplere büyü hasarı verir.","img/abil/azir-w.png",[1.5,1.5,1.5,1.5,1.5]],["Kayan Kumlar","E","Azir kısa süreliğine kalkana bürünür ve Kumdan Askerlerinden birine doğru atılarak rakiplere hasar verir. Bir rakip şampiyonla çarpışırsa anında yeni bir Kumdan Asker hazırlar ve hareketine son verir.","img/abil/azir-e.png",[22,20.5,19,17.5,16]],["İmparatorluk Muhafızları","R","Azir'in çağırdığı askerler, yan yana dizilerek ileriye doğru atılır ve rakipleri geriye savurarak, onlara hasar verir.","img/abil/azir-r.png",[120,105,90]]],"wk":"Azir","p":"img/champ/azir.png","tip":[["İleri!'de biriken askerlerin hepsini kullanmamaya çalış. Topyekun saldırılar harici, askerlerden birini cepte tut. Kaçman gerektiğinde veya ilkini yanlış yere koyduğunda ikincisini kullanırsın.","Askerleri koridorda rakibin şampiyonları ile minyonları arasına koy. Böylece, askerleri hem son vuruş yapmada kullanabilir, hem de koridor rakibine karşı tehdit oluşturmada kullanabilirsin.","İmparatorluk Muhafızları'nı öncelikle savunmaya yönelik bir yetenek olarak düşün. Rakip sana veya takım arkadaşlarına saldırdığında bu yeteneği kullan. Takım arkadaşların çağrılan askerlerin arasından geçip gidebilir, rakibin yakın dövüş şampiyonlarına karşı yeteneğin bu yönünü avantaja çevirebilirsin.","Her kuşun eti yenmez!"],["Azir hasar vermek için askerlerini kullanır ama yerlerini çok sık değiştiremez. Askerlerin hareketsiz kaldıkları süreleri kendi menfaatine çevirmeye bak.","Azir'in uzun bir zaman aralığına yayılmış muazzam hasar potansiyeli vardır ancak diğer büyücüler gibi öyle birden uygulayabileceği ani hasara sahip değildir. Azir karşılaşmayı kendi lehine çevirmeden önce ani hasarla onu etkisiz hale getirmeye çalış.","Kumdan Askerleri kızgın közler gibi düşün. Közün üstünde durma."]]},"bard":{"id":"Bard","k":432,"n":"Bard","en":"Bard","t":"Kozmik Koruyucu","cls":["Support","Mage"],"d":3,"res":"Mana","b":{"hp":630,"hpL":103,"ar":32,"arL":4.7,"mr":30,"mrL":1.3,"ad":52,"adL":3,"as":0.658,"asR":0.658,"asL":2,"rng":500,"ms":335,"t":"M"},"ab":[["Gezginin Çağrısı","P","Micinler: Bard'ın kendine çektiği küçük ruhlar normal saldırılara yardım ederek ilave büyü hasarı verir. Bard yeterli sayıda tını topladığında, micinleri alan etkili hasar verir ve isabet alan rakipleri yavaşlatır. Tınılar: Bard'ın toplayacağı kadim tınılar rasgele ortaya çıkar. Bunlar deneyim kazandırır, mana yeniler ve çatışma dışında etkili hareket hızı sağlar.","img/abil/bard-p.png"],["Kozmik Bağ","Q","Bard'ın yaptığı büyü atışı, isabet ettiği ilk rakibi yavaşlattıktan sonra yoluna devam eder. Duvara çarparsa isabet ettiği ilk rakibi sersemletir, başka bir rakibe isabet ederse ikisini birden sersemletir.","img/abil/bard-q.png",[11,10,9,8,7]],["Koruyucunun Mabedi","W","Ortaya çıkardığı can mabedi, kısa bir süre sonra güçlenir ve ona ilk temas eden takım arkadaşını iyileştirip hızlandırdıktan sonra ortadan kaybolur.","img/abil/bard-w.png",[0,0,0,0,0]],["Sihirli Yolculuk","E","Bard yakındaki duvar veya arazi üzerinde bir kapı açar. Dost ve rakip şampiyonlar kapının girişine doğru hareket ederek tek yönlü olarak kapının çıkışına seyahat edebilir.","img/abil/bard-e.png",[22,20.5,19,17.5,16]],["Kader Birliği","R","Bard, hedef konuma yolladığı ruh enerjisi ile etki alanı içindeki bütün şampiyonları, minyonları, canavarları ve kuleleri kısa süreliğine dondurur.","img/abil/bard-r.png",[110,95,80]]],"wk":"Bard","p":"img/champ/bard.png","tip":[["Micin saldırılarını güçlendirmek için tını toplamak elbette önemli, ama koridordaki arkadaşını ihmal etme sakın! Sihirli Yolculuk ile koridora dönerken yanında takımından birini de getir, dönüşün muhteşem olsun.","Koruyucunun Mabedi tam güce ulaştığında daha fazla iyileştirir, kullandıktan sonra biraz beklemen iyi olur.","Sihirli Yolculuk geçitlerinden rakiplerin de faydalanabildiğini ve ulti yeteneğinin dost düşman herkes üzerinde etkili olduğunu unutma!"],["Bard'ın açtığı Sihirli Yolculuk geçitlerini rakipleri de kullanabilir. Güvenli olduğuna inanıyorsan peşinden gidebilirsin.","Bard'ın iyileştirme mabetlerini üzerinden geçerek yok edebilirsin. Bard'ın takım arkadaşlarının bunlardan faydalanmasına izin vermemeye çalış.","Bard'ın ulti yeteneği olan Kader Birliği; takım arkadaşları, rakipler, canavarlar ve kuleler üstünde etkilidir. Bazı durumlarda senin de etkisine girmen avantajlı olabilir!"]]},"belveth":{"id":"Belveth","k":200,"n":"Bel'Veth","en":"Bel'Veth","t":"Hiçlik'in İmparatoriçesi","cls":["Fighter"],"d":3,"res":"","b":{"hp":580,"hpL":105,"ar":28,"arL":5,"mr":32,"mrL":2.05,"ad":55,"adL":1.5,"as":0.67,"asR":0.67,"asL":0,"rng":150,"ms":340,"t":"P"},"ab":[["Mor Ölüm ","P","Bel'Veth büyük minyonları veya canavarları ve şampiyonları alt ettikten sonra kalıcı saldırı hızı yükleri kazanır. Ayrıca bir yetenek kullandıktan sonra geçici olarak ilave saldırı hızı da kazanır.","img/abil/belveth-p.png"],["Hiçlik Akını","Q","Bel'Veth seçili yönde atılır ve deşip geçtiği tüm rakiplere hasar verir.","img/abil/belveth-q.png",[4,3.25,2.5,1.75,1]],["Gökte ve Yerde","W","Bel'Veth kuyruğunu yere savurarak rakiplere hasar verir, onları havaya savurur ve yavaşlatır.","img/abil/belveth-w.png",[12,11,10,9,8]],["Asil Girdap","E","Bel'Veth sabitlenip yoğunlaşarak etrafına saldırmaya başlar ve bu sırada en düşük cana sahip rakibi hedef alır. Ayrıca can çalma ve hasar azaltma kazanır.","img/abil/belveth-e.png",[24,21,18,15,12]],["Ebedi Şölen","R","Bel'Veth, Hiçlik Mercanı kalıntılarını tüketerek Gerçek Suret'ine bürünür ve azami canını, saldırı menzilini ve saldırı hızını arttırır. Destansı Hiçlik canavarlarının Hiçlik Mercanı kalıntılarını tüketmek ona bir Hiçlik Yüzgeçlisi çağırma gücü kazandırır.","img/abil/belveth-r.png",[1,1,1]]],"wk":"Bel'Veth","p":"img/champ/belveth.png","tip":[[],[]]},"blitzcrank":{"id":"Blitzcrank","k":53,"n":"Blitzcrank","en":"Blitzcrank","t":"Büyük Buharlı Golem","cls":["Tank","Support"],"d":2,"res":"Mana","b":{"hp":600,"hpL":109,"ar":37,"arL":4.7,"mr":32,"mrL":2.05,"ad":62,"adL":3.5,"as":0.625,"asR":0.625,"asL":1.13,"rng":125,"ms":325,"t":"P"},"ab":[["Mana Bariyeri","P","Blitzcrank canı azaldığında manasına bağlı olarak bir kalkan kazanır.","img/abil/blitzcrank-p.png"],["Roket El","Q","Blitzcrank'in ateşlediği sağ eli, yoluna çıkan ilk rakibe hasar verir ve onu Blitzcrank'e doğru çeker.","img/abil/blitzcrank-q.png",[20,19,18,17,16]],["Gazla","W","Blitzcrank kendini aşırı yükleyerek büyük oranda hareket ve saldırı hızı kazanır. Etki sona erdikten sonra geçici olarak yavaşlar.","img/abil/blitzcrank-w.png",[15,15,15,15,15]],["Güç Yumruğu","E","Blitzcrank yumruğunu güçlendirerek bir sonraki saldırısının iki kat hasar vermesini ve hedefini havaya savurmasını sağlar.","img/abil/blitzcrank-e.png",[7,6.5,6,5.5,5]],["Statik Alan","R","Blitzcrank'in saldırdığı rakipler, işaretlenerek 1 saniyenin ardından yıldırım hasarı alır. Ayrıca Blitzcrank bu yeteneği etkinleştirdiğinde yakınındaki rakiplerin kalkanlarını kaldırır, onlara hasar verir ve kısa süreliğine onları susturur.","img/abil/blitzcrank-r.png",[60,40,20]]],"wk":"Blitzcrank","p":"img/champ/blitzcrank.png","tip":[["Roket El, Güç Yumruğu ve Statik Alan sırasıyla yapacağın üçlü kombinasyon, tek bir rakibi mahvedebilir.","Blitzcrank'ın tutuşuyla rakibi kule menziline çektikten sonra Güç Yumruğu kullanarak, kulenin rakibe birkaç vuruş yapmasını sağlayabilirsin."],["Blitzcrank'in pasif özelliği olan Mana Bariyeri, can değeri azaldığında bir kalkan görevi görür.","Minyonların arkasında durarak Roket El'den korunabilirsin. Blitzcrank'in Roket El'i, yalnızca karşılaştığı ilk hedefi çeker."]]},"brand":{"id":"Brand","k":63,"n":"Brand","en":"Brand","t":"İntikam Ateşi","cls":["Mage","Support"],"d":2,"res":"Mana","b":{"hp":570,"hpL":105,"ar":24,"arL":4.2,"mr":30,"mrL":1.3,"ad":57,"adL":3,"as":0.681,"asR":0.625,"asL":2,"rng":550,"ms":340,"t":"M"},"ab":[["Alev","P","Brand'in yetenekleri, hedeflerinin alev alarak 4 saniye boyunca hasar almalarını sağlar. Bu etki 3 defaya kadar birikebilir. Brand alev almış bir rakibi katlederse mana geri kazanır. Alev, herhangi bir şampiyon ya da büyük canavar üzerinde azami yüke ulaştığında kararsız hale gelir ve 2 saniye sonra yetenek etkileri uygulayıp kurbanının etrafındaki devasa bir alana hasar vererek patlar.","img/abil/brand-p.png"],["Ateş Topu","Q","Brand büyü hasarı veren bir ateş topu fırlatır. Hedef önceden alev almışsa Ateş Topu hedefi sersemletir.","img/abil/brand-q.png",[8,7.5,7,6.5,6]],["Alev Sütunu","W","Brand kısa bir gecikmenin ardından hedef bölgede bir Alev Sütunu oluşturarak bölgedeki rakip birimlere büyü hasarı verir. Önceden alev almış birimler %25 ek hasar alır.","img/abil/brand-w.png",[10,9.5,9,8.5,8]],["Yangın","E","Brand'in hedefine gönderdiği güçlü patlama yakınındaki rakiplere yayılarak büyü hasarı verir. Hedef alev almışsa, Yangın'ın yayılması iki katına çıkar.","img/abil/brand-e.png",[13,12,11,10,9]],["Volkan","R","Brand'in ortaya çıkardığı yıkıcı ateş seli, Brand veya yakınındaki rakiplerden en fazla 5 defa sekerek her sekmesinde rakiplere büyü hasarı verir. Sekmeler şampiyonların üstündeki Alev etkisini azami yüke ulaştırmaya öncelik verir. Hedefler önceden alev almışsa, Volkan onları kısa süreliğine yavaşlatır.","img/abil/brand-r.png",[100,90,80]]],"wk":"Brand","p":"img/champ/brand.png","tip":[["Yangın büyüsüyle rakiplerinin alev almasını sağlayarak, minyonlarının yanında durmalarını engelleyebilirsin.","Brand'in farklı durumlarda verdiği hasarı en üst düzeye çıkarmak için, yeteneklerini farklı kombinasyonlar halinde kullanabilirsin.","Kundakçılık rakipler arasında gelişigüzel sıçrar. Bu yüzden aynı hedefe birden çok vuruş yapmak istiyorsan, onu küçük rakip grupları üzerinde kullan."],["Brand'in kombosunun başlayabilmesi için bir yeteneğinin hedefini bulması gerekir. Ateş Topu ya da Alev Sütunu'nu savuşturmak, ritmini bozacaktır.","Brand, Volkan'ı kullanırken takım arkadaşlarından uzaklaşmaya çalış. Atış, başta yavaş ilerlediği için takımın kaçmaya fırsat bulabilir.","Brand'in pasifi, sıkışık takımlara karşı avantaj sağlar. Brand'e karşı takım arkadaşlarından uzak durmaya çalış."]]},"braum":{"id":"Braum","k":201,"n":"Braum","en":"Braum","t":"Freljord'un Yüreği","cls":["Tank","Support"],"d":1,"res":"Mana","b":{"hp":610,"hpL":112,"ar":35,"arL":5,"mr":32,"mrL":2.05,"ad":55,"adL":3.2,"as":0.644,"asR":0.643999993801116,"asL":3.5,"rng":125,"ms":335,"t":"M"},"ab":[["Meydan Dayağı","P","Braum'un normal saldırıları rakibin üzerinde Meydan Dayağı yükleri birikmesine neden olur. İlk yükün birikmesiyle birlikte, takım arkadaşlarının isabet eden normal saldırıları da Meydan Dayağı yükü biriktirir. Üstünde 4 yük biriken hedef sersemler ve büyü hasarı alır. Meydan Dayağı yiyen hedef üzerinde bir süre yeni yük birikmez ama rakip Braum'un saldırılarından ilave büyü hasarı alır.","img/abil/braum-p.png"],["Buz Yanığı","Q","Braum kalkanından buz parçaları fırlatarak, rakiplerini yavaşlatıp onlara büyü hasarı verir. Bir adet Meydan Dayağı yükü uygular.","img/abil/braum-q.png",[8,7.5,7,6.5,6]],["Yettim Gari","W","Braum dost bir şampiyona ya da minyona doğru atılır. Hedefine ulaştığında, hem Braum hem de dost birim birkaç saniyeliğine zırh ve büyü direnci kazanır.","img/abil/braum-w.png",[12,11,10,9,8]],["Kapı Gibi","E","Braum birkaç saniye boyunca kalkanını belli bir yöne doğru tutarak ona yönelen tüm atışların yolunu keser. Bu atışlar Braum'a isabet ederek yok olur. Braum bu yönden gelen ilk saldırının tüm hasarını ortadan kaldırır, sonrakilerin de hasarını azaltır.","img/abil/braum-e.png",[16,14,12,10,8]],["Freljord Karşılaması","R","Braum kalkanını yere vurur. Önündeki hattın üstünde ve yakınında duran rakipler havaya savrulur. Yetenek yerde, rakipleri yavaşlatan bir çatlak bırakır.","img/abil/braum-r.png",[130,115,100]]],"wk":"Braum","p":"img/champ/braum.png","tip":[["Takım arkadaşlarınla birlikte çalışarak rakiplerde Meydan Dayağı yükü biriktir, onları işaretli hedeflere normal saldırılar yapmaya teşvik et.","Kapı Gibi ile kırılgan arkadaşlarının önüne atlayarak onları gelen atışlardan korumaya bak.","Freljord Karşılaması ardında etkili bir yavaşlatma alanı bırakır, takım savaşlarını bölmek ve yaklaşan rakipleri yavaşlatmak için doğru konumlandırmaya dikkat göster."],["Meydan Dayağı'nı başlatmak için Braum'un Buz Yanığı veya bir normal saldırı isabet ettirmesi gerekir. İşaretlenirsen 3 isabet daha almadan savaş menzilinden çıkıp sersemletmeden kurtulabilirsin.","Braum'un ultisi uzun bir kullanım süresine sahip; bu arada ondan sıvışabilirsin. Ultinin ardından yerde kalan buz kaplı alan seni yavaşlatır; üzerinden geçmemeye çalış.","Kapı Gibi, Braum'a belli bir yönde müthiş savunma gücü verir; yetenek geçene kadar bekle ya da etrafından dolaş."]]},"briar":{"id":"Briar","k":233,"n":"Briar","en":"Briar","t":"Bastırılmış Açlık","cls":["Fighter","Assassin"],"d":1,"res":"Öfke","b":{"hp":625,"hpL":95,"ar":30,"arL":4.5,"mr":32,"mrL":2.05,"ad":60,"adL":2.5,"as":0.644,"asR":0.669,"asL":2,"rng":125,"ms":340,"t":"P"},"ab":[["Kızıl Lanet","P","Briar'ın saldırı ve yetenekleri biriken bir kanama etkisi uygular ve Briar kanama hasarının belli bir kısmı kadar iyileşir. Doymak bilmeyen Briar, eksik canına bağlı olarak iyileştirme artışı kazanır ancak karakteristik bir can yenilemesi yoktur.","img/abil/briar-p.png"],["Kudurtan Açlık","Q","Briar bir birime doğru atlayıp onu tekmeler, sersemletir ve onun zırhını eksiltir.","img/abil/briar-q.png",[13,12,11,10,9]],["Kan Cinneti / Hapur Hupur","W","Briar ileri doğru atılarak boyunduruğunu parçalar ve Kan Cinneti'ne girerek şampiyonlara öncelik verecek şekilde en yakınındaki rakibin peşine düşer. Cinnet halindeyken saldırı hızıyla hareket hızı kazanır ve saldırıları hedefinin etrafındaki alana hasar verir. Briar cinnet halindeyken bu yeteneği tekrar etkinleştirirse bir sonraki saldırısında hedefinden koca bir ısırık alarak onun eksik canına bağlı olarak ilave hasar verir ve verdiği hasara bağlı olarak iyileşir.","img/abil/briar-w.png",[14,13,12,11,10]],["Dehşet Çığlığı","E","Briar kendine gelerek Kan Cinneti'nden çıkar ve yoğunlaşarak rakiplere hasar veren ve onları yavaşlatan güçlü bir çığlık atar. Yoğunlaşma sırasında gelen hasarı azaltır ve azami canının belli bir bölümüne eşdeğer miktarda iyileşir. Tam güce ulaşmış çığlıklar rakipleri geri savurur, onlara fazladan hasar verir ve duvara çarpanları sersemletir.","img/abil/briar-e.png",[16,16,16,16,16]],["Mezara Kadar","R","Briar boyunduruğunun kan taşını bir tekmeyle fırlatarak taşın isabet ettiği ilk şampiyonu avı olarak işaretler. Ardından avının yanında bitiverir, etraftaki diğer rakipleri korkutur ve gözünü iyice kan hırsı bürür. Briar, avını katledene veya bu uğurda katledilene dek onun peşinden ayrılmaz. Ayrıca Kan Cinneti ilavelerinin yanı sıra fazladan zırh, büyü direnci, can çalma ve hareket hızı kazanır.","img/abil/briar-r.png",[120,100,80]]],"wk":"Briar","p":"img/champ/briar.png","tip":[[],[]]},"caitlyn":{"id":"Caitlyn","k":51,"n":"Caitlyn","en":"Caitlyn","t":"Piltover Şerifi","cls":["Marksman"],"d":2,"res":"Mana","b":{"hp":580,"hpL":107,"ar":27,"arL":4.7,"mr":33,"mrL":1.1,"ad":62,"adL":3.8,"as":0.681,"asR":0.625,"asL":4,"rng":650,"ms":325,"t":"P"},"ab":[["Tam Kafadan","P","Caitlyn her birkaç normal saldırıda bir ya da kapana veya ağa yakalanan hedeflere saldırırken hedefini Tam Kafadan vurur. Tam Kafadan vurmak, hedefe kritik vuruş ihtimali ile orantılı ilave hasar verir. Kapana veya ağa takılan rakiplere karşı Caitlyn'in Tam Kafadan vurma menzili iki katına çıkar.","img/abil/caitlyn-p.png"],["Piltover Silahı","Q","Caitlyn silahını 1 saniye kurarak, fiziksel hasar veren ve önündekileri delip geçen bir atış yapar. (İlk hedeften sonraki hedeflere daha az hasar verir.)","img/abil/caitlyn-q.png",[10,9,8,7,6]],["Yordle Kapanı","W","Caitlyn, üstüne basan rakip şampiyonu açığa çıkaran ve 1,5 saniyeliğine hareketsiz bırakan bir kapan kurar. Ayrıca Caitlyn'e güçlendirilmiş bir Tam Kafadan atışı sağlar.","img/abil/caitlyn-w.png",[0.5,0.5,0.5,0.5,0.5]],["90 Kalibrelik Ağ","E","Caitlyn hedefini yavaşlatan ağır bir ağ fırlatır. Tüfeğinin tepmesiyle, Caitlyn geri savrulur.","img/abil/caitlyn-e.png",[16,14,12,10,8]],["Son Koz","R","Caitlyn sabırla mükemmel atış için nişan alır ve olağanüstü bir menzildeki bir tek hedefe muazzam hasar verir. Rakip şampiyonlar, takım arkadaşlarını korumak için kurşunun önüne atlayabilir.","img/abil/caitlyn-r.png",[90,90,90]]],"wk":"Caitlyn","p":"img/champ/caitlyn.png","tip":[["Çatışma sırasında bekleme süresinden çıkmış olmasını sağlamak için Yordle Kapanlarını önceden yerleştirmeye özen göster.","İstemediğin bir hedef tarafından durdurulmasını önlemek için, Son Koz'u büyük yakın dövüşçü grupları üzerinde kullanmaktan kaçın.","90 Kalibrelik Ağ'ı rakipten uzağa ateşleyerek aradaki mesafeyi kapatabilir ya da duvarların üstünden atlayabilirsin."],["Caitlyn seni Piltover Silahı ile taciz ediyorsa takımının minyonlarının arkasına saklan (başka hedeflere isabet ettikçe verdiği hasar azalır).","Son Koz yeteneğini kullanırken önünde durursan, takım arkadaşına isabet etmesini engelleyebilirsin."]]},"camille":{"id":"Camille","k":164,"n":"Camille","en":"Camille","t":"Çelik Gölge","cls":["Fighter","Assassin"],"d":2,"res":"Mana","b":{"hp":650,"hpL":99,"ar":35,"arL":4.5,"mr":32,"mrL":2.05,"ad":68,"adL":3.8,"as":0.644,"asR":0.643999993801116,"asL":2.5,"rng":125,"ms":340,"t":"P"},"ab":[["Değişken Savunma","P","Şampiyonlara yönelik normal saldırılar, kısa süreliğine hedefin hasar türüne (fiziksel hasar veya büyü hasarı) karşı Camille'in azami canının yüzdelik bir bölümüne eşdeğer bir kalkan sağlar.","img/abil/camille-p.png"],["İmha Protokolü","Q","Camille'in bir sonraki saldırısı ilave hasar verir ve ilave hareket hızı sağlar. Bu yetenek kısa bir süre içinde yeniden kullanılabilir ve Camille iki saldırısı arasında beklerse büyük oranda ilave hasar verir.","img/abil/camille-q.png",[9,8,7,6,5]],["Keskin Çelme","W","Camille kısa bir aranın ardından koni şeklindeki bir alana saldırarak hasar verir. Koninin dış yarısında kalan rakipler yavaşlar, fazladan hasar alır ve Camille'i iyileştirir.","img/abil/camille-w.png",[12,11.5,11,10.5,10]],["Kanca Atışı","E","Camille kendini bir duvara doğru çeker ve vardıktan sonra duvardan uzağa atılarak rakip şampiyonları havaya savurur.","img/abil/camille-e.png",[16,15,14,13,12]],["Hextech Ültimatomu","R","Camille hedef şampiyona doğru fırlayarak hedefini belli bir alana hapseder. Bu esnada normal saldırılarıyla hedefe ilave büyü hasarı verir.","img/abil/camille-r.png",[140,115,90]]],"wk":"Camille","p":"img/champ/camille.png","tip":[["Rakip takım kendini senin takımınla dövüşmeye kaptırana kadar beklemeye çalış ve savunmasız rakipleri ayıklamak için Kanca Atışı'nı kullan.","Yeteneklerinin sağladığı kitle kontrolünü kullanarak İmha Protokolü saldırılarının ikisini de rakiplere tutturmaya çalış."],["Camille'in kalkanı sadece bir hasar türüne karşı etkilidir; bu yüzden senin hasar türüne karşı savunmasız olduğunda ona saldır.","Hextech Ültimatomu'nun çok düşük bir kullanım menzili olduğu için, Camille sana yaklaşmadan önce uzağa sıçramaya çalış."]]},"cassiopeia":{"id":"Cassiopeia","k":69,"n":"Cassiopeia","en":"Cassiopeia","t":"Yılanın Şefkati","cls":["Mage"],"d":3,"res":"Mana","b":{"hp":610,"hpL":98,"ar":18,"arL":4.7,"mr":32,"mrL":1.3,"ad":53,"adL":3,"as":0.647,"asR":0.647000014781951,"asL":1.5,"rng":550,"ms":335,"t":"M"},"ab":[["Yılanın Lütfu","P","Cassiopeia'nın üstündeki tüm hareket hızı ilaveleri daha etkili hale gelir.","img/abil/cassiopeia-p.png"],["Zehirli Patlama","Q","Cassiopeia kısa bir gecikmenin ardından belli bir alanda Zehir patlaması oluşturur ve bir rakip şampiyonu vurduğunda hareket hızı artar.","img/abil/cassiopeia-q.png",[3.5,3.5,3.5,3.5,3.5]],["Zehir","W","Cassiopeia'nın ortaya çıkardığı bir dizi zehir bulutu rakiplerin yavaşlamalarına, yere saplanmalarına ve bir miktar hasar almalarına neden olur. Yere saplanan rakipler, hareket yeteneklerini kullanamaz.","img/abil/cassiopeia-w.png",[24,22,20,18,16]],["İkiz Diş","E","Cassiopeia verdiği hasarın bir miktarı kadar iyileşmesini sağlayan ve zehirlenmiş hedeflere fazladan hasar veren bir saldırı gerçekleştirir. Eğer bu saldırı hedefi katlederse, Cassiopeia belli bir miktar mana geri kazanır.","img/abil/cassiopeia-e.png",[0.75,0.75,0.75,0.75,0.75]],["Taşlaştıran Bakış","R","Cassiopeia gözlerinden büyülü bir enerji dalgası saçarak yüzü ona dönük olan bütün rakipleri sersemletir ve sırtı dönük olan rakipleri yavaşlatır.","img/abil/cassiopeia-r.png",[120,100,80]]],"wk":"Cassiopeia","p":"img/champ/cassiopeia.png","tip":[["En fazla hasarı vermek için İkiz Diş'i, Taşlaştıran Bakış'la sersemletilmiş birimler ya da canavarlar gibi sabit hedefler üzerinde kullan.","Vuruşu garantilemek için Zehirli Patlama'yla hedef alırken rakibe yönel."],["Seni zehirlediğinde, Cassiopeia'nın İkiz Diş'le verebileceği zarardan kaçın.","Sersemlemek yerine yavaşlamak için, Cassiopeia Taşlaştıran Bakışı yapmaya başladığında başka yöne dön."]]},"chogath":{"id":"Chogath","k":31,"n":"Cho'Gath","en":"Cho'Gath","t":"Hiçlik'in Dehşeti","cls":["Tank","Mage"],"d":2,"res":"Mana","b":{"hp":644,"hpL":94,"ar":38,"arL":4.5,"mr":32,"mrL":2.05,"ad":69,"adL":4.2,"as":0.658,"asR":0.625,"asL":1.44,"rng":125,"ms":345,"t":"M"},"ab":[["Etobur","P","Cho'Gath bir birim öldürdüğünde, Can ve Mana geri kazanır. Cho'Gath'ın seviyesinin yükselmesiyle kazandığı Can ve Mana miktarı da artar.","img/abil/chogath-p.png"],["Kazıklı Zemin","Q","Hedef konumda yerden kazıklar çıkararak rakip birimlerini havaya savurur ve hasar alarak yavaşlamalarına neden olur.","img/abil/chogath-q.png",[6,6,6,6,6]],["Yabani Çığlık","W","Cho'Gath'ın attığı korkunç çığlık, koni şeklinde bir alandaki rakiplere büyü hasarı verir ve onları birkaç saniyeliğine susturur.","img/abil/chogath-w.png",[11,10.5,10,9.5,9]],["Cani Dikenler","E","Cho'Gath'ın saldırıları önündeki bütün rakiplere hasar verip onları yavaşlatan ölümcül dikenler gönderir.","img/abil/chogath-e.png",[8,7,6,5,4]],["Ziyafet","R","Bir rakip birimi yutarak yüksek miktarda gerçek hasar verir. Hedef katledilirse Cho'Gath büyür ve azami can artışı kazanır.","img/abil/chogath-r.png",[80,70,60]]],"wk":"Cho'Gath","p":"img/champ/chogath.png","tip":[["Saldırılarını arada Cani Dikenler kullanarak zenginleştir, böylece aynı anda hem minyon öldürür hem de rakip şampiyonları taciz edersin.","Şampiyonlarla Ziyafet çekmekte zorlanıyorsan, büyüyene kadar minyon yemeyi dene.","Kazıklı Zemin'i Etobur'la birlikte yaratıklar üstünde kullanmak, Can ve Mana kazanmak için iyi bir yoldur."],["Can veren birkaç eşya satın almak, Cho'Gath'ın seni kolayca öldürme ihtimalini düşürür.","Cho'Gath'ın en büyük boyutuna gelmesini engellemeye odaklan.","Kazıklı Zemin'in oluşacağı yer daha önceden bir sis bulutuyla belli olur. Cho'Gath'ın yetenekleriyle kombo yapmasını engellemek için buna dikkat etmeye çalış."]]},"corki":{"id":"Corki","k":42,"n":"Corki","en":"Corki","t":"Gözüpek Bombacı","cls":["Marksman","Mage"],"d":2,"res":"Mana","b":{"hp":610,"hpL":100,"ar":27,"arL":4.5,"mr":33,"mrL":1.1,"ad":52,"adL":2.5,"as":0.644,"asR":0.644,"asL":2.8,"rng":550,"ms":325,"t":"P"},"ab":[["Hextech Mühimmatı","P","Corki'nin normal saldırı hasarının yüzdelik bir kısmı ilave gerçek hasar olarak verilir.","img/abil/corki-p.png"],["Fosfor Bombası","Q","Corki hedef konuma bir aydınlatma bombası atar ve bölgedeki rakiplere büyü hasarı verir. Bu saldırı, patlama bölgesinin çevresindeki birimleri bir süreliğine açığa çıkarır.","img/abil/corki-q.png",[9,8.5,8,7.5,7]],["Valkyrie","W","Corki'nin kısa bir mesafe uçarak attığı bombalar, ardında bir yıkım bölgesi bırakır ve ateş içinde kalan rakipler hasar alır.","img/abil/corki-w.png",[20,18,16,14,12]],["Makineli Tüfek","E","Corki'nin makineli tüfeği, önündeki koni şeklinde bir alanı yaylım ateşine tutar ve rakiplere hasar vererek zırh ve büyü direnci değerlerini azaltır.","img/abil/corki-e.png",[12,12,12,12,12]],["Füze Salvosu","R","Corki hedef konuma, çarpışma anında patlayan ve bölgedeki rakiplere hasar veren bir füze ateşler. Corki bir tavan değere ulaşana dek zamanla füze biriktirir. Her 3. füzesi İri Kıyım'a dönüşür ve fazladan hasar verir.","img/abil/corki-r.png",[2,2,2]]],"wk":"Corki","p":"img/champ/corki.png","tip":[["Fosfor Bombası civardaki çalılıklarda saklanmaya kalkan rakip birimlerini ortaya çıkarmakta kullanılabilir.","Valkyrie savunma amaçlı olarak da kullanılabilir. Bu yüzden, hızla kaçmak için kulanmayı deneyebilirsin.","Corki Makineli Tüfek'i kullanırken saldırmaya devam edebilir. Makineli Tüfek'i en üst düzeye çıkarmak, Corki'yle başarılı olmanın anahtarıdır."],["Corki'nin Füze Salvosu'na dikkat et. Saçılma hasarı verirler; böylece minyonların arkasına saklansan bile zarar görebilirsin.","Corki, Valkyrie veya Özel Teslimat'ı kullandıktan sonra savunmasız kalır; çatışmaya bunları kullanarak girerse Corki'ye odaklanmaya çalış."]]},"darius":{"id":"Darius","k":122,"n":"Darius","en":"Darius","t":"Noxus'un Eli","cls":["Fighter","Tank"],"d":1,"res":"Mana","b":{"hp":652,"hpL":114,"ar":37,"arL":5.2,"mr":32,"mrL":2.05,"ad":64,"adL":5,"as":0.625,"asR":0.625,"asL":1,"rng":175,"ms":340,"t":"P"},"ab":[["Kanama","P","Darius'un saldırıları ve hasar veren yetenekleri, rakiplerin 5 saniye boyunca kanayarak fiziksel hasar almalarına neden olur. Kanama 5 defaya kadar birikebilir. Hedefi azami yüke ulaştığında Darius öfkelenerek yüksek miktarda saldırı gücü kazanır.","img/abil/darius-p.png"],["Biçen Balta","Q","Darius baltasını geniş bir çember halinde savurur. Baltanın keskin tarafının isabet ettiği rakipler, balta sapının isabet ettiği rakiplere göre daha fazla hasar alır. Darius, baltasının keskin tarafının isabet ettiği rakip şampiyonlara ve canavarlara bağlı olarak iyileşir.","img/abil/darius-q.png",[9,7.75,6.5,5.25,4]],["Kemik Kıran","W","Darius'un bir sonraki saldırısı rakibin atardamarına isabet eder. Rakip kanadıkça daha yavaş hareket eder.","img/abil/darius-w.png",[5,5,5,5,5]],["Tut Çek","E","Darius baltasını bileyerek verdiği fiziksel hasarın hedefin zırhının belli bir yüzdesini yok saymasını sağlar. Etkinleştirildiğinde, Darius baltasının kancasıyla rakipleri bir araya toplar ve kendine doğru çeker.","img/abil/darius-e.png",[26,23.5,21,18.5,16]],["Noxus Giyotini","R","Darius bir rakip şampiyona doğru zıplar ve gerçek hasar veren ölümcül bir darbe indirir. Bu hasar, hedefte birikmiş Kanama yükü sayısına bağlı olarak artar. Darius, Noxus Giyotini ile öldürücü darbe yaparsa yeteneğin bekleme süresi kısa süreliğine sıfırlanır.","img/abil/darius-r.png",[120,100,80]]],"wk":"Darius","p":"img/champ/darius.png","tip":[["Biçen Balta güçlü bir rahatsız etme yeteneğidir. En büyük etkiyi yaratması için rakibe en uzak menzilden saldır.","Noxus Giyotini, öncesinde ne kadar çok hedefe vurabilirsen o kadar fazla hasar verir. Noxus Kudreti'ni kullanarak hasarı azamiye çıkarabilirsin.","Darius gelişmiş hayatta kalma içgüdüsünden çok yararlanır. Dövüşü uzattığın sürece daha da güçlü hale gelir."],["Darius, Tut Çek özelliği bekleme süresine girdiğinde saldırılara açık hale gelir.","Darius'un savaştan kaçma yeteneği sınırlıdır. Ona karşı avantajlıysan, bastırmaya devam et."]]},"diana":{"id":"Diana","k":131,"n":"Diana","en":"Diana","t":"Ay'ın Hiddeti","cls":["Fighter","Assassin"],"d":2,"res":"Mana","b":{"hp":640,"hpL":109,"ar":31,"arL":4.3,"mr":32,"mrL":2.05,"ad":57,"adL":3,"as":0.625,"asR":0.694,"asL":2,"rng":150,"ms":345,"t":"M"},"ab":[["Gümüşay Bıçağı","P","Her üçüncü saldırı yakındaki rakipleri biçerek fazladan büyü hasarı verir. Diana bir yetenek kullandıktan sonraki 5 saniyeliğine saldırı hızı kazanır.","img/abil/diana-p.png"],["Hilal Saldırısı","Q","Ortaya çıkan Ay enerjisi bir alana büyü hasarı verir. Ay Işığı'yla vurulmuş rakipleri etkileyerek gizlenmiş halde değillerse onları 3 saniyeliğine açığa çıkarır.","img/abil/diana-q.png",[8,7.5,7,6.5,6]],["Solgun Kamer","W","Diana'nın oluşturduğu üç küre, etrafında döner ve rakiplere temas ettiğinde patlayarak alan etkili hasar verir. Ayrıca Diana hasarı emen geçici bir kalkan elde eder. Üçüncü küre de patlarsa, kalkan ilave güç kazanır.","img/abil/diana-w.png",[15,13.5,12,10.5,9]],["Ay Koşusu","E","Ay'ın intikamcı yüzünün canlı sureti haline gelerek bir rakibin üstüne atılır ve büyü hasarı verir. Ay Işığı'ndan etkilenmiş bir rakibe atılmak için kullanıldığında, Ay Koşusu'nun bekleme süresi olmaz. Ay Koşusu'nun hedefi olsun veya olmasın, diğer tüm rakiplerin üzerindeki Ay Işığı zayıflatması kalkar.","img/abil/diana-e.png",[22,20,18,16,14]],["Ay Düşüşü","R","Diana yakındaki bütün rakipleri açığa çıkarıp kendine çekerek yavaşlatır. Eğer Diana bir veya daha fazla rakip şampiyonu çekerse, ay ışığı kısa bir gecikme sonrasında üstüne çökerek etrafındaki alana büyü hasarı verir. Verilen hasar ilkinden sonra çekilen her bir hedef için artar.","img/abil/diana-r.png",[100,90,80]]],"wk":"Diana","p":"img/champ/diana.png","tip":[["Hilal Saldırısı'nı isabet ettirmek çok önemlidir; ama ıskalamaktan korkma; kısa bekleme süresine ve düşük mana bedeline sahiptir.","Ay Koşusu'nu Ay Işığı'yla birlikte gerçekleştireceğin ve bir başka Hilal Saldırısı için bekleyeceğin zamanı iyi kolla.","Ay Düşüşü'nü ve Ay Koşusu'nu kullanarak hedefte kal, fazladan hasar için de Gümüşay Bıçağını kullan."],["Ay Işığı'ndan etkilendiysen Hilal Saldırısı'nı savuştur veya güvenli bir yere kaç.","Solgun Kamer küreleri sadece birkaç saniye kalır. Diana'yla karşılaşmaktan kaçın ve kalkanı dağıldıktan sonra onunla yüzleş.","Diana, Ay Işığı olmadan Ay Koşusu'nu kullanırsa çok saldırgan oynayabilir; ama yerine dönmesi mümkün olmadığında yavaşlatarak veya sersemleterek onu cezalandırabilirsin."]]},"draven":{"id":"Draven","k":119,"n":"Draven","en":"Draven","t":"Görkemli Cellat","cls":["Marksman"],"d":3,"res":"Mana","b":{"hp":675,"hpL":104,"ar":29,"arL":4.5,"mr":33,"mrL":1.1,"ad":64,"adL":3.4,"as":0.679,"asR":0.67900002002716,"asL":2.7,"rng":550,"ms":330,"t":"P"},"ab":[["Draven Ligi","P","Draven bir Dönen Balta yakaladığında, minyon ya da canavar kestiğinde veya kule yıktığında izleyenlerin Hayranlığını kazanır. Rakip şampiyon katletmek, Draven'a sahip olduğu Hayranlık miktarına göre ilave altın verir.","img/abil/draven-p.png"],["Dönen Balta","Q","Draven'ın bir sonraki saldırısı fiziksel hasar verir. Bu balta hedefin üzerinden havaya seker. Draven baltayı havada yakalarsa, otomatik olarak bir başka Dönen Balta hazırlar. Draven aynı anda iki Dönen Balta taşıyabilir.","img/abil/draven-q.png",[12,11,10,9,8]],["Adrenalin Seli","W","Draven'ın hareket hızı ve saldırı hızı artar. Kazanılan fazladan hareket hızı, zaman geçtikçe azalır. Dönen Balta'yı yakalamak Adrenalin Seli'nin bekleme süresini sıfırlar.","img/abil/draven-w.png",[12,12,12,12,12]],["Geri Dur","E","Draven baltalarını fırlatarak hedeflere fiziksel hasar verir ve onları kenara savurur. İsabet alan hedefler yavaşlar.","img/abil/draven-e.png",[16,15,14,13,12]],["Ölüm Pervanesi","R","Draven, isabet ettiği her hedefe fiziksel hasar veren iki devasa balta fırlatır. Ölüm Pervanesi, bir rakip şampiyona isabet ettikten sonra yavaşça yönünü tersine döndürür ve Draven'a döner. Ayrıca Draven bu yeteneği baltalar havadayken kendisine daha çabuk dönmesi için de etkinleştirebilir. İsabet ettiği her ek birime daha az hasar verir ve balta ters yöne döndüğünde sıfırlanır. Canı Draven'ın sahip olduğu Hayranlık yükü sayısından az olan rakipleri infaz eder.","img/abil/draven-r.png",[100,90,80]]],"wk":"Draven","p":"img/champ/draven.png","tip":[["Draven hareket etmiyorsa, Dönen Balta o an bulunduğu konumun yakınlarına inecektir.","Draven saldırdıktan sonra hareket ederse, Dönen Balta hareket ettiği yöne doğru gider. Bunu Dönen Balta'nın nereye gideceğini belirlemek için kullan."],["Draven'ın Dönen Baltalarının ineceği yöne doğru tahmini atışlar yap.","Draven'a sataşarak baltalarını düşürmesini sağlamaya çalış. Düşürürse, gücü büyük ölçüde azalacaktır."]]},"drmundo":{"id":"DrMundo","k":36,"n":"Dr. Mundo","en":"Dr. Mundo","t":"Zaun'un Delisi","cls":["Tank","Fighter"],"d":2,"res":"Yok","b":{"hp":640,"hpL":103,"ar":32,"arL":4.5,"mr":29,"mrL":2.3,"ad":61,"adL":2.5,"as":0.67,"asR":0.625,"asL":3.3,"rng":125,"ms":345,"t":"P"},"ab":[["Nereye İsterse Oraya Gider","P","Dr. Mundo kendisine isabet eden ilk hareketsiz bırakma etkisine direnir. Bunun yerine can kaybeder ve yakınındaki bir konuma bir kimyasal haznesi bırakır. Dr. Mundo haznenin üstünden geçip onu alarak canını yenileyebilir ve bu yeteneğin bekleme süresini azaltabilir. Ayrıca Dr. Mundo yüksek miktarda can yenilenmesine sahiptir.","img/abil/drmundo-p.png"],["Mikroplu Testere","Q","Dr. Mundo isabet ettiği ilk rakibe mevcut canına bağlı olarak hasar veren ve onu yavaşlatan mikroplu bir testere fırlatır.","img/abil/drmundo-q.png",[4,4,4,4,4]],["Şok Terapisi","W","Dr. Mundo kendisini çarparak yakınındaki rakiplere sürekli hasar verir ve aldığı hasarın belli bir kısmını biriktirir. Dr. Mundo sürenin sonunda veya yeteneği yeniden kullandığında yakınındaki rakiplere anlık hasar verir. Ayrıca anlık hasar bir rakibe isabet ederse biriken hasarın yüzdelik bir bölümüne eşdeğer miktarda iyileşir.","img/abil/drmundo-w.png",[17,16.5,16,15.5,15]],["Beyin Sarsıntısı","E","Pasif - Dr. Mundo azami canına bağlı olarak artacak şekilde ilave saldırı gücü kazanır. Aktif - Dr. Mundo ''sağlık'' çantasını bir rakibin kafasına geçirerek ona eksik canına bağlı olarak fiziksel hasar verir. Rakip katledilirse uzağa savrularak temas ettiği rakiplere hasar verir.","img/abil/drmundo-e.png",[9,8.25,7.5,6.75,6]],["Doz Aşımı","R","Dr. Mundo vücuduna kimyasal pompalayarak anlık olarak eksik canının yüzdelik bir bölümüne eşdeğer miktarda iyileşir. Daha sonra hareket hızı kazanır ve azami canının belli bir bölümünü uzun bir süre boyunca yeniler.","img/abil/drmundo-r.png",[120,120,120]]],"wk":"Dr. Mundo","p":"img/champ/drmundo.png","tip":[["Zamanlaması iyi yapılmış bir Sadizm, rakip şampiyonları kandırarak, işini bitirecek hasarları olmasa da, sana saldırmalarını sağlayabilir.","Ruh Gömleği ulti yeteneğinin iyileştirme etkisini yükseltirken, bütün yeteneklerinin bekleme sürelerini azaltır.","Satırlar, tarafsız canavarları öldürmekte güçlü birer araçtır. Üsse dönmektense, ulti yeteneğin seni iyileştirene kadar tarafsız canavar öldür."],["Dr. Mundo ultisini kullandıktan sonra, takım arkadaşlarınla beraber yüksek hasar veren özelliklerinizi beraber kullanmaya çalışın; ancak bu şekilde çabucak onu öldüremezsen, hasar sayesinde iyileşmeye başlayacaktır.","Dr. Mundo Sadizm'i kullandığında iyileşmesinin büyük bir bölümünü engellemek için Tutuştur büyüsünü kullanmaya çalış."]]},"ekko":{"id":"Ekko","k":245,"n":"Ekko","en":"Ekko","t":"Zamanı Kıran Çocuk","cls":["Assassin","Mage"],"d":3,"res":"Mana","b":{"hp":655,"hpL":99,"ar":32,"arL":4.2,"mr":32,"mrL":2.05,"ad":58,"adL":3,"as":0.688,"asR":0.625,"asL":3.3,"rng":125,"ms":340,"t":"M"},"ab":[["Z-Kapsülü Rezonansı","P","Aynı hedefe yönelik her üçüncü saldırı veya hasar veren yetenek, ilave büyü hasarı verir ve hedef bir şampiyonsa Ekko'ya hız artışı sağlar.","img/abil/ekko-p.png"],["Kurmalı Kapan","Q","Ekko'nun fırlattığı zaman bombası bir rakip şampiyona isabet ederse, zamanın bozulmaya uğradığı bir alan oluşturur ve alan içindeki herkesi yavaşlatarak hasar verir. Bir süre sonra yoluna çıkanlara hasar vererek Ekko'ya geri döner.","img/abil/ekko-q.png",[9,8.5,8,7.5,7]],["Paralel Yakınsama","W","Ekko'nun normal saldırıları düşük cana sahip rakiplere ilave büyü hasarı verir. Ekko, Paralel Yakınsama kullanıp zamanın akışını yardığında bir anomali oluşur ve bu anomali birkaç saniye sonra içinde kalan rakipleri yavaşlatır. Ekko bu alanın içine girerse bir kalkan kazanır ve rakipleri zamanda dondurarak sersemleten bir patlamaya yol açar.","img/abil/ekko-w.png",[22,20,18,16,14]],["Zaman Sıçraması","E","Ekko gelecek saldırılardan kaçınmak üzere yuvarlanırken Zaman Kapsülü'nü çalıştırır. Bir sonraki saldırısı ilave hasar verir ve gerçekliği bükerek Ekko'yu hedefinin yanına gönderir.","img/abil/ekko-e.png",[9,8.5,8,7.5,7]],["Kronokırılma","R","Ekko zamanın akışını kırarak hedef alınamaz hale gelir ve zamanda daha elverişli bir ana geri gider. Birkaç saniye önce nerede duruyorsa oraya döner ve bu süre esnasında aldığı hasarın belli bir oranı kadar kendini iyileştirir. Ekko'nun ortaya çıktığı alandaki rakipler muazzam hasar alır.","img/abil/ekko-r.png",[110,80,50]]],"wk":"Ekko","p":"img/champ/ekko.png","tip":[["Kronokırılma kaçmak için oldukça faydalı bir araçtır ama saldırıya yönelik kullanıldığında da bir hayli etkili olabilir. Hasar potansiyelini sakın yabana atma.","Bir rakip şampiyon üzerinde Z-Kapsülü Rezonansı'nı tetikleyebilirsen, Kronokırılma ile risk alarak bunu değerlendirebilirsin. Gelen ilave hareket hızı kaçmayı kolaylaştırır.","Zaman Sıçraması'nın atılma özelliği, Ekko'nun diğer yeteneklerini kullanma fırsatı yaratmak için idealdir. Kurmalı Kapan'la tek vurup çift saymak için veya Paralel Yakınsama'yı patlatmak üzere konum almak için kullanabilirsin."],["Ultisi devre dışıyken Ekko bir hayli zayıf kalır. Kronokırılma'nın ne durumda olduğunu kestirmek için Ekko'nun arkasında bıraktığı ize dikkat et.","Ekko'nun sersemletme alanının oluşması 3 saniye sürer. Büyü yapmaya başladığında Ekko'da beliren görsele bakıp, alanın nerede çıkacağını tahmin etmeye çalış.","Kurmalı Kapan'dan isabet eden ikinci saldırı daha fazla hasar verir, sakınman iyi olur."]]},"elise":{"id":"Elise","k":60,"n":"Elise","en":"Elise","t":"Örümcek Kraliçe","cls":["Assassin","Mage"],"d":3,"res":"Mana","b":{"hp":620,"hpL":109,"ar":30,"arL":4.5,"mr":30,"mrL":1.3,"ad":55,"adL":3,"as":0.625,"asR":0.625,"asL":1.75,"rng":550,"ms":330,"t":"M"},"ab":[["Örümcek Kraliçe","P","İnsan Hali: Elise'in yetenekleri bir rakibe isabet ettiğinde ona bir adet atıl örümcek yavrusu verir. Örümcek Hali: Normal saldırılar ilave büyü hasarı verir ve Elise'in can yenilemesini sağlar.","img/abil/elise-p.png"],["Nörotoksin / Zehirli Isırık","Q","İnsan Hali: Rakibin canı ne kadar çoksa ona orantılı olarak hasar verir. Örümcek Hali: Rakibe doğru atılır ve canı ne kadar azsa ona orantılı olarak hasar verir.","img/abil/elise-q.png",[6,6,6,6,6]],["İntihar Örümceği / Eklembacaklı İstilası","W","İnsan Hali: Hedefe yaklaştığında patlayan, içi zehir dolu bir örümcek yavrusu salar. Örümcek Hali: Elise ile örümcek yavrularının saldırı hızı artar.","img/abil/elise-w.png",[12,12,12,12,12]],["Koza / Örümcek İnişi","E","İnsan Hali: İsabet ettiği ilk rakip birimi sersemletir ve gizlenmemiş olanları açığa çıkarır. Örümcek Hali: Elise, örümcek yavrularıyla beraber havaya sıçrayıp hedeflenen rakibin üstüne düşer. Bir rakip hedefin üstüne düşmesinin ardından, Elise'in Örümcek Kraliçe'den kazandığı ilave hasar ve iyileştirme artar.","img/abil/elise-e.png",[12,11.5,11,10.5,10]],["Örümcek Hali","R","Elise korkunç bir örümceğe dönüşür. Saldırı menzili azalır ve bunun yerine hareket hızı kazanır. Yeni yeteneklere kavuşur ve örümcek yavrusu sürüsü rakiplerine saldırır.","img/abil/elise-r.png",[3,3,3,3]]],"wk":"Elise","p":"img/champ/elise.png","tip":[["Örümcek Hali, can değerleri düşük rakiplerin işini bitirmekte çok etkilidir; İnsan Hali'nin Nörotoksin'i can değeri yüksek rakiplere daha çok hasar verir.","Elise Örümcek Hali'ndeyken, Örümcek Yavruları Elise'in Zehirli Isırık kullandığı hedeflere saldırır.","Elise'in Örümcek Hali ve Örümcek Hali yetenekleri manaya mal olmaz ve mana tasarruf etmek istediğinde önceliği ayarlanabilir."],["Elise'in Örümcek Hali, canın düşükken daha tehlikelidir; İnsan Hali ise canın yüksekken daha güçlüdür.","Örümcek İnişi, bir rakip birim üzerine inmediği takdirde Elise'in sadece dümdüz aşağı ve yukarı hareket etmesini sağlar.","Örümcek İnişi'nin bekleme süresi uzundur. Elise bu gücü kullandıktan sonra savunmasız kalır."]]},"evelynn":{"id":"Evelynn","k":28,"n":"Evelynn","en":"Evelynn","t":"Azabın Kucağı","cls":["Assassin","Mage"],"d":3,"res":"Mana","b":{"hp":642,"hpL":98,"ar":37,"arL":4.7,"mr":32,"mrL":2.05,"ad":61,"adL":3,"as":0.667,"asR":0.666999995708465,"asL":2.1,"rng":125,"ms":335,"t":"M"},"ab":[["İblis Gölge","P","Evelynn çatışma dışında İblis Gölge'ye bürünür. İblis Gölge, canı azaldığında Evelynn'i iyileştirir ve 6. seviyeden sonra kamuflaj etkisi sağlar.","img/abil/evelynn-p.png"],["Nefret Dikeni","Q","Evelynn kırbacıyla saldırır ve isabet alan ilk birime hasar verir. Ardından birkaç defalığına yakındaki rakiplere düz bir hatta ilerleyen dikenler gönderebilir.","img/abil/evelynn-q.png",[4,4,4,4,4]],["Yürek Yakan","W","Evelynn hedefini lanetler ve bir sonraki saldırı veya yeteneği, bir aranın ardından hedefi ayartıp hedefin büyü direncini azaltır.","img/abil/evelynn-w.png",[15,14,13,12,11]],["Kırbaç","E","Evelynn hedefini kırbaçlayarak hasar verir. Ardından kısa süreliğine hareket hızı kazanır.","img/abil/evelynn-e.png",[8,8,8,8,8]],["Dul Bırakan","R","Evelynn kısa süreliğine hedef alınamaz hale gelir ve önündeki alanı kırıp geçirdikten sonra uzak bir konuma gerileyerek yeniden belirir.","img/abil/evelynn-r.png",[120,100,80]]],"wk":"Evelynn","p":"img/champ/evelynn.png","tip":[["Yürek Yakan'ın hazırlık süresi uzun görünebilir ama ayartma ve büyü direnci eksiltme etkileri Evelynn'e olağanüstü avantaj sağladığı için beklemeye değer.","Gizli haldeyken rakip şampiyonların seni tespit etmesine çok yaklaştığın noktalara dikkat et. Bunu rakip şampiyonların üzerinde sarı ve kırmızı parlayan gözlerden anlayabilirsin.","Canın azaldığında İblis Gölge'nin iyileştirme etkisinden faydalanabilir ve kamuflaj sayesinde çatışmaya dönüp rakiplerini gafil avlayabilirsin."],["Kontrol Totemi satın almak, Evelynn'in yerini saptamana ve böylece kurduğu pusulara karşı hazırlıklı olmana yardım edebilir.","Evelynn, ortaya koyduğu tehdidin büyük bölümünü Yürek Yakan'ın ayartma etkisine borçludur. Yürek Yakan'la işaretlenen takım arkadaşlarını korumaya çalış veya sen işaretlenmişsen Evelynn'in saldırabileceği noktalarla arana takım arkadaşlarını almaya özen göster.","Evelynn'in takım arkadaşlarından birine pusu kurduğundan şüpheleniyorsan, haritada sinyal verip sohbet kutusuna mesaj yazarak takım arkadaşını uyar."]]},"ezreal":{"id":"Ezreal","k":81,"n":"Ezreal","en":"Ezreal","t":"Dahi Kâşif","cls":["Marksman","Mage"],"d":3,"res":"Mana","b":{"hp":600,"hpL":102,"ar":24,"arL":4.2,"mr":33,"mrL":1.1,"ad":60,"adL":3.75,"as":0.625,"asR":0.625,"asL":2.5,"rng":550,"ms":325,"t":"P"},"ab":[["Büyü Gücü Yükselişi","P","Ezreal her yetenek isabet ettirdiğinde 5 defaya kadar birikecek şekilde saldırı hızı artışı kazanır.","img/abil/ezreal-p.png"],["Gizemli Atış","Q","Ezreal bir rakip birime isabet etmesi halinde bütün bekleme sürelerini düşük miktarda azaltan bir enerji oku atar.","img/abil/ezreal-q.png",[5.5,5.25,5,4.75,4.5]],["Özüt Akışı","W","Ezreal, isabet ettiği ilk şampiyon veya harita hedefine yapışan bir küre fırlatır. Eğer Ezreal kürenin etkisi altındaki bir rakibe vurursa küre patlayarak hasar verir.","img/abil/ezreal-w.png",[8,8,8,8,8]],["Sihir Geçişi","E","Ezreal yakındaki bir hedef konuma ışınlanır ve ateşlediği güdümlü ışınla en yakındaki rakip birime saldırır. Özüt Akışı etkisi altındaki rakiplere öncelik verir.","img/abil/ezreal-e.png",[26,23,20,17,14]],["İsabet Dalgası","R","Ezreal güç toplar ve içinden geçtiği her bir rakibe yüksek miktarda hasar veren kuvvetli bir enerji dalgası gönderir (dalga, minyon ve destansı olmayan canavarlara daha az hasar verir).","img/abil/ezreal-r.png",[120,105,90]]],"wk":"Ezreal","p":"img/champ/ezreal.png","tip":[["Diğer yetenek atışlarını geliştirmek için Sihir Geçişi'ni kullan.","Ezreal'ı geliştirme biçimine bağlı olarak Saldırı Gücü veren ya da Yetenek Gücü kullanan bir taşıyıcı olarak oynayabilirsin.","İsabet Dalgası'nı kullanarak çoklu minyon gruplarını ve hatta canavarları bile vurabilirsin."],["Ezreal çok narin bir şampiyondur; bu yüzden onun sana gelmesini beklemeden mücadeleyi ona götür.","Ezreal tamamen atış becerisi üzerine kuruludur; bu yüzden minyonları onunla aranda tutmaya çalış.","Gizemli Atış, Közden Sorguç'un dahil olduğu isabet halinde devreye giren etkileri uygular."]]},"fiddlesticks":{"id":"Fiddlesticks","k":9,"n":"Fiddlesticks","en":"Fiddlesticks","t":"Kadim Dehşet","cls":["Mage","Support"],"d":3,"res":"Mana","b":{"hp":650,"hpL":106,"ar":34,"arL":4.7,"mr":30,"mrL":1.3,"ad":55,"adL":2.65,"as":0.625,"asR":0.625,"asL":2.11,"rng":480,"ms":335,"t":"M"},"ab":[["Zararsız Korkuluk","P","Fiddlesticks'in ziynetleri korkuluklarla değiştirilir.","img/abil/fiddlesticks-p.png"],["Dehşet Sal","Q","Fiddlesticks görünmüyorken yetenekleriyle bir rakibe hasar verirse veya ona Dehşet Sal'ın aktifini isabet ettirirse o birimi korkutarak belli bir süre dehşet içinde kaçmasına neden olur.","img/abil/fiddlesticks-q.png",[15,14.5,14,13.5,13]],["Kan Hasadı","W","Fiddlesticks yakındaki rakiplerden can çalarak sürenin sonunda onlara ilave infaz hasarı verir.","img/abil/fiddlesticks-w.png",[10,9.5,9,8.5,8]],["Biçen Tırpan","E","Fiddlesticks tırpanını belli bir alana savurarak saldırısının merkezinde yer alan tüm rakipleri yavaşlatır ve susturur.","img/abil/fiddlesticks-e.png",[10,9,8,7,6]],["Karga Sürüsü","R","Fiddlesticks'in etrafında dönmeye başlayan vahşi bir karga sürüsü, bölgedeki bütün rakip birimlere saniye başına hasar verir.","img/abil/fiddlesticks-r.png",[140,110,80]]],"wk":"Fiddlesticks","p":"img/champ/fiddlesticks.png","tip":[[],[]]},"fiora":{"id":"Fiora","k":114,"n":"Fiora","en":"Fiora","t":"Büyük Düellocu","cls":["Fighter","Assassin"],"d":1,"res":"Mana","b":{"hp":620,"hpL":105,"ar":33,"arL":4.7,"mr":32,"mrL":2.05,"ad":66,"adL":3.3,"as":0.69,"asR":0.689999997615814,"asL":3.2,"rng":150,"ms":345,"t":"P"},"ab":[["Düellocunun Dansı","P","Fiora bu şampiyonun bir zayıf noktasını açığa çıkardı. Bu zayıf noktaya saldırırsa can yeniler ve hareket hızı kazanır.","img/abil/fiora-p.png"],["Hamle","Q","Fiora bir yöne hamle yapıp yakındaki bir rakibi deşer ve fiziksel hasar vererek vuruş etkisi uygular.","img/abil/fiora-q.png",[13,11.25,9.5,7.75,6]],["Karşı Hamle","W","Fiora gelen bütün hasar ve engellemeleri kısa süreliğine savuşturur. Ardından bir yöne saldırır. Bu saldırı, isabet alan ilk şampiyonu yavaşlatır. Fiora bu yetenekle hareketsiz bırakan bir etkiyi savuşturduysa rakip şampiyon sersemler.","img/abil/fiora-w.png",[24,22,20,18,16]],["Kılıç Sanatı","E","Sonraki iki saldırı için Fiora saldırı hızını arttırır. İlk saldırı hedefi yavaşlatırken ikincisi kritik vuruş gerçekleştirir.","img/abil/fiora-e.png",[11,10,9,8,7]],["Büyük Mücadele","R","Fiora bir rakip şampiyonun zayıf noktalarının dördünü birden açığa çıkarır ve onun yakınındayken hareket hızı kazanır. Fiora dört zayıf noktaya birden saldırır ya da en az bir zayıf noktaya saldırdıktan sonra hedef katledilirse kendisi ve bölgedeki takım arkadaşları sonraki birkaç saniye boyunca iyileşir.","img/abil/fiora-r.png",[110,90,70]]],"wk":"Fiora","p":"img/champ/fiora.png","tip":[["Düellocu'nun Dansı sayesinde Fiora seri kapışmalarda üstünlük kazanır. Zayıf noktaya vurduğunda kazandığın hız takviyesini kaçmak ya da sonraki vuruşa hazırlanmak için kullan.","Büyük Mücadele, Fiora'nın en dayanıklı rakipleri bile alt etmesini ve ardından başarılı olursa iyileşmesini sağlar. Bu yüzden rakibin ön saflarına bodoslama saldırmaktan çekinme."],["Düellocunun Dansı, Fiora'nın nereden saldırmaya çalışacağını gösterir. Denediği zaman ağzının payını vermeye hazır ol.","Fiora'ya hareketsiz bırakan engelleme etkileri uygulamadan önce iki kere düşün. Hamlesi hazırsa gücünü sana karşı kullanabilir."]]},"fizz":{"id":"Fizz","k":105,"n":"Fizz","en":"Fizz","t":"Dalgaların Dümencisi","cls":["Assassin","Fighter"],"d":2,"res":"Mana","b":{"hp":640,"hpL":106,"ar":26,"arL":4.6,"mr":32,"mrL":2.05,"ad":58,"adL":3,"as":0.658,"asR":0.657999992370605,"asL":3.1,"rng":175,"ms":335,"t":"M"},"ab":[["Çevik Dövüşçü","P","Fizz birimlerin içinden geçebilir ve şampiyonun tüm kaynaklardan aldığı hasar belli bir miktarda azalır.","img/abil/fizz-p.png"],["Zıpkın Saldırısı","Q","Fizz atılarak hedefini deşip geçerken büyü hasarı verir ve hedefine isabet etkileri uygular.","img/abil/fizz-q.png",[8,7.5,7,6.5,6]],["Deniztaşı Zıpkın","W","Fizz'in saldırıları rakiplerinde kanamaya yol açarak birkaç saniye boyunca büyü hasarı verir. Fizz sıradaki saldırısını ilave hasar verecek şekilde güçlendirebilir ve kısa süreliğine sonraki saldırılarının gücünü arttırabilir.","img/abil/fizz-w.png",[7,6,5,4,3]],["Oyunbaz / Düzenbaz","E","Fizz havaya sıçrar ve zarafetle zıpkınının üstüne konarak hedef alınamaz hale gelir. Fizz bunun ardından zemine darbe indirmeyi ya da tekrar sıçrayarak sert bir iniş yapmayı seçebilir.","img/abil/fizz-e.png",[16,14,12,10,8]],["Denizin Dişleri","R","Fizz'in hedef yönde attığı balık, kendisine temas eden herhangi bir şampiyona yapışarak hedefi yavaşlatır. Kısa bir aranın ardından zeminden fırlayan bir köpekbalığı hedefi havaya, yakındaki rakipleri de yana savurur. İsabet ettiği bütün rakipler büyü hasarı alarak yavaşlar.","img/abil/fizz-r.png",[120,100,80]]],"wk":"Fizz","p":"img/champ/fizz.png","tip":[["Fizz birimlerin içinden geçebildiğinden, koridorda minyonların arasından ilerleyip Deniztaşı Zıpkın'ın pasifini kullanabileceğin fırsatlar kolla ve birkaç saniye sonra yeteneğin aktifiyle devam et.","Fizz'in ulti yeteneği olan Denizin Dişleri hem bir rakibin üzerinde hem de hedefin gideceğini tahmin ettiğin yerde kullanılabilir.","Fizz'in yetenekleri, yetenek gücüne bağlı olarak güçlenir. Bu yüzden anlık hasar verme ihtimali yüksek takımlara karşı Zhonya'nın Kumsaati veya Banshee'nin Duvağı gibi eşyalar almayı düşün. Fazla canın olmadan da hayatta kalabileceğini düşünüyorsan Lich Boğan veya Rabadon'un Şapkası gibi eşyaları da tercih edebilirsin."],["Fizz'in saldırıları, güçlendirilmiş saldırısını kullandıktan sonra birkaç saniyeliğine daha ölümcül hale gelir; eğer zıpkını parlıyorsa ondan uzak durmaya çalış!","Yetenekleri bekleme süresinde değilken Fizz ele avuca sığmaz bir hedef haline gelir. Onu yemleyip yeteneklerini erken kullanmasını sağla, sonra da kitle kontrolü ve can yakan saldırılarla işini bitir!"]]},"galio":{"id":"Galio","k":3,"n":"Galio","en":"Galio","t":"Heybetli Muhafız","cls":["Tank","Mage"],"d":2,"res":"Mana","b":{"hp":600,"hpL":126,"ar":24,"arL":4.7,"mr":32,"mrL":2.05,"ad":59,"adL":3.5,"as":0.625,"asR":0.625,"asL":1.5,"rng":150,"ms":340,"t":"M"},"ab":[["Ezen Darbe","P","Birkaç saniyede bir Galio'nun sıradaki normal saldırısı belli bir alana ilave büyü hasarı verir.","img/abil/galio-p.png"],["Savaş Yelleri","Q","Galio iki rüzgâr öbeği savurur ve öbekler birleştiğinde zaman içinde hasar veren bir hortuma dönüşür.","img/abil/galio-q.png",[11,10,9,8,7]],["Durand Kalkanı","W","Galio savunma için güç toplayıp yavaş hareket etmeye başlar. Topladığı gücü serbest bıraktığında yakındaki rakipleri kışkırtır ve onlara hasar verir.","img/abil/galio-w.png",[18,17,16,15,14]],["Adalet Yumruğu","E","Galio kısa süreliğine gerilip hücuma geçer ve karşısına çıkan ilk rakip şampiyonu havaya savurur.","img/abil/galio-e.png",[11,10,9,8,7]],["Kahraman Dalışı","R","Galio bir takım arkadaşının konumunu iniş noktası olarak belirleyerek bölgedeki tüm takım arkadaşlarına büyü kalkanı kazandırır. Kısa bir gecikmenin ardından Galio bu konuma şiddetle inip yakınındaki rakipleri havaya savurur.","img/abil/galio-r.png",[180,160,140]]],"wk":"Galio","p":"img/champ/galio.png","tip":[["Kitle kontrol etkisindeyken bile Durand Kalkanı'nı serbest bırakabilirsin.","Kahraman Dalışı için mini haritadaki takım arkadaşlarının simgelerini de hedef alabilirsin.","Rakibin yeteneklerinden sıyrılmak için Adalet Yumruğu'nun gerilme hareketinden faydalanabilirsin."],["Galio, Durand Kalkanı için güç topladığı sırada daha yavaş hareket eder.","Kahraman Dalışı, Galio havaya sıçramadan önce engellenebilir.","Galio, Adalet Yumruğu'yla duvarlardan geçemez."]]},"gangplank":{"id":"Gangplank","k":41,"n":"Gangplank","en":"Gangplank","t":"Okyanus Şeytanı","cls":["Fighter"],"d":3,"res":"Mana","b":{"hp":630,"hpL":114,"ar":31,"arL":4.7,"mr":32,"mrL":2.05,"ad":64,"adL":4.2,"as":0.658,"asR":0.69,"asL":3.2,"rng":125,"ms":345,"t":"P"},"ab":[["Ateşle İmtihan","P","Gangplank'in yakın dövüş saldırısı birkaç saniyede bir rakibi ateşe verir.","img/abil/gangplank-p.png"],["Çakaralmaz","Q","Hedefe ateş eder, katledilen her rakip birim başına altın yağmalar.","img/abil/gangplank-q.png",[4.5,4.5,4.5,4.5,4.5]],["İskorbüte Çare","W","Turunç yiyerek kitle kontrol etkilerini tedavi eder ve can yeniler.","img/abil/gangplank-w.png",[22,20,18,16,14]],["Barut Fıçısı","E","Gangplank hedef konumda bir barut fıçısı ortaya çıkarır. Saldırdığında patlayarak saldırının verdiği hasarı bölge içinde kalan rakiplere yayar ve onları yavaşlatır.","img/abil/gangplank-e.png",[0,0,0,0,0]],["Top Salvosu","R","Gangplank gemisine gönderdiği işaretle bir bölgeyi bombardımana tutarak rakipleri yavaşlatır ve onlara hasar verir.","img/abil/gangplank-r.png",[160,140,120]]],"wk":"Gangplank","p":"img/champ/gangplank.png","tip":[["Çakaralmaz, Donmuş Balyoz ya da Kara Balta gibi Vuruş Anı etkileri yaratır.","Haritadaki düşük canlı rakiplere dikkat edersen Top Salvosu yeteneğinle sürpriz skorları cebe indirebilirsin.","Kaçan rakiplerin önlerini kesmek için Top Salvosu'nu kaçış yollarına indirmeye çalış."],["Çakaralmaz yüksek miktarda fiziksel hasar verir. Rakip Gangplank iyi gidiyorsa, Zırh veren eşyaların yardımı olabilir.","Gangplank 6. seviyeye ulaştığında global menzilli ultisi, Top Salvosu'ndan uzak durmaya bakın."]]},"garen":{"id":"Garen","k":86,"n":"Garen","en":"Garen","t":"Demacia'nın Kudreti","cls":["Fighter","Tank"],"d":2,"res":"Yok","b":{"hp":690,"hpL":98,"ar":38,"arL":4.2,"mr":32,"mrL":1.55,"ad":69,"adL":4.5,"as":0.625,"asR":0.625,"asL":3.65,"rng":175,"ms":340,"t":"P"},"ab":[["Metanet","P","Garen bir süre hasar görmez veya rakiplerin yeteneklerinden isabet almazsa, her saniye toplam canının yüzdelik bir kısmını geri kazanır.","img/abil/garen-p.png"],["Amansız Hücum","Q","Garen'in hareket hızında artış meydana gelir ve kendisini etkileyen tüm yavaşlatma etkilerinden kurtulur. Bir sonraki saldırısı rakibinin hayati bir organına denk gelerek ek hasar verir ve rakibi susturur.","img/abil/garen-q.png",[8,8,8,8,8]],["Cesaret","W","Garen rakiplerini katlettikçe zırh ve büyü direncini pasif olarak arttırır. Ek olarak bu yeteneği etkinleştirdiğinde kısa süreliğine kalkan ve sıvışma kazanır. Ardından daha uzun bir süre etkili olan daha az miktarda hasar azaltma elde eder.","img/abil/garen-w.png",[22,19.5,17,14.5,12]],["Yargı","E","Garen kılıcını hızla çevirerek yakındaki rakiplere fiziksel hasar verir.","img/abil/garen-e.png",[9,8.25,7.5,6.75,6]],["Demacia'nın Adaleti","R","Garen bir rakip şampiyonu infaz etmek için Demacia'dan güç alır.","img/abil/garen-r.png",[120,100,80]]],"wk":"Garen","p":"img/champ/garen.png","tip":[["Garen birkaç saniye hasar almaktan sakınabilirse, yenilenme değerleri büyük oranda artar.","Yargı, sadece tek hedefe isabet ettiğinde azami hasar verir. Mücadelelerde etkinlik kazanmak için bir tek rakip şampiyonun isabet alacağı şekilde konum almaya çalış.","Garen'i sadece bekleme süreleri kısıtlar; Kara Balta gibi eşyalar Garen için çok etkilidir."],["Garen'in verdiği yüksek miktardaki fiziksel hasarı düşürmek için zırh veren eşyalar topla.","Demacia'nın Adaleti'yle seni çabucak öldürebileceği için, can değerin azaldıysa Garen'den kaçmaya çalış.","Garen'e öylesine saldırırken dikkatli ol. Genellikle çarpışma senin Yargı'dan tam hasar almana neden olacaktır.","Yargı sadece tek hedefe isabet ettiğinde azami hasar verir. Etki alanından çıkma şansın yoksa aldığın hasarı azaltmak için kendi minyonlarının arasına gir."]]},"gnar":{"id":"Gnar","k":150,"n":"Gnar","en":"Gnar","t":"Kayıp Halka","cls":["Fighter","Tank"],"d":3,"res":"Hiddet","b":{"hp":540,"hpL":79,"ar":32,"arL":3.7,"mr":30,"mrL":1.3,"ad":60,"adL":3.2,"as":0.625,"asR":0.625,"asL":6,"rng":175,"ms":335,"t":"P"},"ab":[["Hiddet Geni","P","Gnar çatışmadayken Hiddet biriktirir. Hiddet en üst seviyeye ulaştığında, kullandığı bir sonraki yetenek onu Mega Gnar'a dönüştürerek daha dayanıklı hale getirir ve Gnar'ın yeni yetenekler kullanabilmesini sağlar.","img/abil/gnar-p.png"],["Bumerang At / Kaya Fırlat","Q","Gnar'ın fırlattığı bumerang, isabet ettiği rakiplere hasar vererek onları yavaşlatır ve ardından Gnar'a geri döner. Gnar, bumerangı yakalarsa bekleme süresi azalır. Mega Gnar ise koca bir kaya fırlatır. Bu kaya isabet ettiği ilk hedefte durur ve yakınlarda bulunan her şeye hasar verip, onları yavaşlatır. Gnar kayayı yerden alırsa, bekleme süresi azalır.","img/abil/gnar-q.png",[16,14.5,13,11.5,10]],["Hiper / Göçert","W","Gnar saldırı yapıp, büyü kullandıkça heyecanı artar ve ilave hasar vererek, Hareket Hızı kazanır. Mega Gnar hiddetinden dolayı heyecanlanmaz, onun yerine arka ayakları üzerinde kalkıp, önünde bulunan alanı yumruklar ve yakınlardaki rakipleri sersemletir.","img/abil/gnar-w.png",[7,7,7,7,7]],["Hop / Güm","E","Gnar bir noktaya zıplar ve kafasına indiği herhangi bir birimden sekerek ilerler. Mega Gnar sekemeyecek kadar büyük olduğundan daha yıkıcı bir güçle inerek, çevresine hasar verir.","img/abil/gnar-e.png",[22,19.5,17,14.5,12]],["GNAR!","R","Mega Gnar etrafındaki her şeyi seçilen bir yöne fırlatarak hasar almalarına ve yavaşlamalarına yol açar. Bir duvara çarpan rakipler sersemler ve ilave hasar alır.","img/abil/gnar-r.png",[90,60,30]]],"wk":"Gnar","p":"img/champ/gnar.png","tip":[["Hiddet'ini kontrollü bir biçimde kullanmaya çalış. Dönüşümleri doğru zamana denk getirerek her iki biçiminden azami fayda sağlayabilirsin.","Ultini kullanarak rakiplerini sersemletmek için kendini duvarlara yakın yerlere konumla.","Güçlü yönlerini iyi öğren! Mini Gnar hızlı ve kırılgandır; ayrıca sürekli hasarı fazladır. Mega Gnar ise yavaş, dayanıklı ve fazla ani hasara sahiptir."],["Gnar, Mini Gnar haline geri döndükten sonra 15 saniye boyunca Hiddet biriktiremez. Takımına karşı saldırı başlatacaksan, bu fırsatı değerlendir.","Gnar dönüşmeye yaklaştıkça, animasyonları ve kaynak göstergesi değişir.","Gnar ultisi ile seni duvara çarparsa sersemletme etkisi olur. Duvar yakınında Gnar ile savaşırken dikkatli ol."]]},"gragas":{"id":"Gragas","k":79,"n":"Gragas","en":"Gragas","t":"Kavgacı Ayyaş","cls":["Fighter","Mage"],"d":2,"res":"Mana","b":{"hp":640,"hpL":115,"ar":38,"arL":5,"mr":32,"mrL":2.05,"ad":64,"adL":3.5,"as":0.675,"asR":0.625,"asL":2.05,"rng":125,"ms":330,"t":"M"},"ab":[["İçelim Güzelleşelim","P","Gragas yetenek kullandığında belli aralıklarla iyileşir.","img/abil/gragas-p.png"],["Fıçı Yuvarla","Q","Gragas fıçısını belli bir konuma yuvarlar. Fıçı etkinleştirilerek patlatılabileceği gibi, 4 saniye sonra kendi kendine de patlayabilir. Patlamanın şiddeti zamanla artar. Patlamaya yakalanan rakipler yavaşlar.","img/abil/gragas-q.png",[10,9,8,7,6]],["Ayyaş Hiddeti","W","Gragas 1 saniyeliğine fıçısından içer. İçtikten sonra saldırganlaşıp coşarak bir sonraki normal saldırısında yakındaki bütün rakiplere büyü hasarı verirken, aldığı hasar da azalır.","img/abil/gragas-w.png",[5,5,5,5,5]],["Vücut Darbesi","E","Gragas belli bir konuma hücum ederek, karşılaştığı ilk birime çarpar ve yakındaki bütün birimlere hasar verir ve onları sersemletir.","img/abil/gragas-e.png",[14,13.5,13,12.5,12]],["Patlayan Fıçı","R","Gragas fıçısını belli bir alana savurur. Fıçının patlama alanı içinde kalan rakiplere hasar vererek onları geri savurur.","img/abil/gragas-r.png",[100,85,70]]],"wk":"Gragas","p":"img/champ/gragas.png","tip":[["Ayyaş Hiddeti'nden gelen hasar indirgeme, etkisini içmeye başladığında gösterir. Hasar alacağından emin olduğunda önceden kullanmaya çalış.","Patlayan Fıçı ile rakiplerini kendi kulelerinin altına doğru savurmaya bak.","Takımının skor alması için Vücut Darbesi ile Patlayan Fıçı kombinasyonlarını dene."],["Gragas ultisiyle herkesi uzağa uçurabilir. Ona doğru, ya da daha kötüsü bir rakip kulesine doğru uçmamaya dikkat et.","Vücut Darbesinin bekleme süresi çok azdır ve Gragas'ı takip etmeyi zorlaştırır. Onu kovalayacağım diye kendini fazla zorlama."]]},"graves":{"id":"Graves","k":104,"n":"Graves","en":"Graves","t":"Kanun Kaçağı","cls":["Marksman"],"d":1,"res":"Mana","b":{"hp":625,"hpL":106,"ar":33,"arL":4.6,"mr":33,"mrL":1.1,"ad":66,"adL":4,"as":0.475,"asR":0.490000009536743,"asL":3,"rng":425,"ms":340,"t":"P"},"ab":[["Yeni Kader","P","Graves'in tüfeği özgün niteliklere sahip. Cephanesi bitince tüfeğini yeniden doldurması gerekir. Saldırılar birimlerin içinden geçemeyen 4 mermi ateşler. Birden fazla merminin isabet ettiği şampiyon dışındaki birimler geri savrulur.","img/abil/graves-p.png"],["Yolun Sonu","Q","Graves, 1 saniye sonra veya yüzey şekline temas ettiğinde infilak eden bir patlayıcı kovan ateşler.","img/abil/graves-q.png",[13,11.25,9.5,7.75,6]],["Sis Perdesi","W","Graves hedef alana sis bombası atarak, görüş menzilini azaltan bir sis bulutu oluşturur. Bomba, patlama anında isabet ettiği rakiplere büyü hasarı verir ve bu rakiplerin hareket hızını kısa süreliğine azaltır.","img/abil/graves-w.png",[26,24,22,20,18]],["Hızlı Tetik","E","Graves ileri atılarak birkaç saniyeliğine zırh ve büyü direnci artışı kazanır. Graves bir rakip şampiyona doğru atılırsa iki Gerçek Hırs yükü kazanır. Rakiplere normal saldırı isabet ettirdiğinde bu yeteneğin bekleme süresi azalır ve direnç artışı yenilenir.","img/abil/graves-e.png",[16,15,14,13,12]],["Parça Tesiri","R","Graves, vurduğu ilk şampiyona ağır hasar veren, patlayıcı bir fişek ateşler. Fişek bir şampiyona çarptıktan ya da azami menziline ulaştıktan sonra patlayarak, koni şeklinde bir alana hasar verir.","img/abil/graves-r.png",[100,80,60]]],"wk":"Graves","p":"img/champ/graves.png","tip":[["Sis Perdesi hem kaçmak için hem de bir rakip şampiyonunu öldürmek için kullanılabilir.","Hızlı Tetik'le menzile girip, Dağınık Atış'la sıfır mesafeden çok fazla hasar verilebilir."],["Graves çoğunlukla fiziksel zarar verir; haliyle onu karşılamada Zırh bir hayli etkilidir.","Sis Perdesi'nin etki alanının dışına çıkmak zararlı etkiyi anında ortadan kaldırır."]]},"gwen":{"id":"Gwen","k":887,"n":"Gwen","en":"Gwen","t":"Kutlu Terzi","cls":["Fighter"],"d":2,"res":"Mana","b":{"hp":620,"hpL":115,"ar":39,"arL":4.9,"mr":32,"mrL":2.05,"ad":63,"adL":3,"as":0.69,"asR":0.69,"asL":2.25,"rng":150,"ms":340,"t":"M"},"ab":[["Bin Kesik","P","Gwen'in saldırıları hedefin canına bağlı olarak ilave büyü hasarı verir. Gwen bu etkiyle şampiyonlara verdiği hasarın belli bir kısmına eşdeğer miktarda iyileşir.","img/abil/gwen-p.png"],["Kırt Kırt!","Q","Gwen makasını koni şeklindeki bir alanda en fazla 6 defa kullanarak büyü hasarı verir. Gwen alanın merkezindeki birimlere gerçek hasar verir ve her bir makas darbesinde onlara pasifin etkisini uygular.","img/abil/gwen-q.png",[6.5,5.75,5,4.25,3.5]],["Kutlu Sis","W","Gwen'in çağırdığı sis, onu bölgenin dışındaki rakiplerden korur. Gwen yalnızca sise giren rakipler tarafından hedef alınabilir.","img/abil/gwen-w.png",[22,21,20,19,18]],["Pens At","E","Gwen kısa bir mesafe boyunca atılır ve birkaç saniyeliğine saldırı hızı, saldırı menzili ve isabet halinde büyü hasarı kazanır. Bu sırada bir rakibe saldırı isabet ettirirse, bu yeteneğin bekleme süresi kısmen iade edilir.","img/abil/gwen-e.png",[13,12.5,12,11.5,11]],["İlmek İlmek","R","Gwen isabet alan rakipleri yavaşlatan, onlara büyü hasarı veren ve isabet alan şampiyonlara Bin Kesik etkisi uygulayan bir iğne fırlatır. Bu yetenek en fazla iki defa daha kullanılabilir ve her bir kullanım fazladan iğne fırlatır ve daha fazla hasar verir.","img/abil/gwen-r.png",[120,100,80]]],"wk":"Gwen","p":"img/champ/gwen.png","tip":[["Saldırıya Devam - Gwen'in saldırıları ilave hasar vermenin yanı sıra çoğu yeteneğini güçlendirir veya sıfırlar.","Gwen özellikle de yüksek menzilli ultisiyle Kutlu Sis'in dışındaki rakiplere hasar verebilir.","Gwen'in bazı yetenekleri pasifinin etkisini birden fazla rakibe uygulayabilir, bu yüzden azami miktarda hasar vermek ve iyileşmek için onları bir arada duran grupların üstünde kullan."],["Gwen'in Kutlu Sis perdesi onu yalnızca bir defa takip eder, bundan sonra Gwen alandan ayrıldığında sis dağılır.","Gwen'in ultisini yeniden kullanabilmesi için bir hedefe saldırması gerekir, kullanımlar arasında saldırılarından kaçınmaya çalış.","Gwen'in yüksek miktarda hasar vermeden önce hedefe birkaç kez saldırması gerekir, bu yüzden ondan önce davran."]]},"hecarim":{"id":"Hecarim","k":120,"n":"Hecarim","en":"Hecarim","t":"Savaşın Gölgesi","cls":["Fighter","Tank"],"d":2,"res":"Mana","b":{"hp":625,"hpL":106,"ar":32,"arL":5.45,"mr":32,"mrL":2.05,"ad":66,"adL":3.7,"as":0.67,"asR":0.6700000166893,"asL":2.5,"rng":175,"ms":345,"t":"P"},"ab":[["Savaş Yolu","P","Hecarim, ilave hareket hızının belli bir yüzdesine eşdeğer saldırı gücü kazanır.","img/abil/hecarim-p.png"],["Galeyan","Q","Hecarim yakındaki rakipleri biçerek onlara fiziksel hasar verir. Hecarim bu saldırıyla en az bir rakibe hasar verirse, sonraki Galeyan kullanımlarının hasarını arttırır ve bekleme süresini kısaltır.","img/abil/hecarim-q.png",[4,4,4,4,4]],["Dehşetin Ruhu","W","Hecarim zırh ve büyü direnci kazanır. Hecarim yakınındaki rakiplere büyü hasarı verir ve rakiplerinin aldığı hasarın yüzdelik bir bölümüne eşdeğer miktarda can kazanır.","img/abil/hecarim-w.png",[14,14,14,14,14]],["Yıkıcı Saldırı","E","Hecarim kısa süreliğine hareket hızı artışı elde eder ve birimlerin içinden geçebilir. İlk saldırısı hedefi geri savurur ve Hecarim, yeteneği etkinleştirdiğinden beri kat ettiği mesafeye bağlı olarak fazladan fiziksel hasar verir.","img/abil/hecarim-e.png",[20,19,18,17,16]],["Gölgelerin Hücumu","R","Hecarim hayalet süvariler çağırarak ileri hücum eder ve düz bir hat boyunca büyü hasarı verir. Hücumu bittiğinde, yakındaki rakiplerin dehşet içinde kaçmalarına sebep olan bir şok dalgası yaratır.","img/abil/hecarim-r.png",[140,120,100]]],"wk":"Hecarim","p":"img/champ/hecarim.png","tip":[["Dehşetin Ruhu yakındaki rakipler hasar alırken Can değerini yeniler; buna, dostlarının verdiği hasarlar da dahildir.","Yıkıcı Saldırı, alınan mesafe arttıkça fazla hasar verir. Hasarı en yüksek düzeye çıkarmak için Hayalet veya Sıçra gibi Sihirdar Büyülerini ya da Gölgelerin Hücumu'nu kullanmayı dene."],["Hecarim Dehşetin Ruhu'yla yakınındaki rakiplerden can kazanır; ama devamlılığı yoktur, ani hasar vermeye çalış.","Hecarim'in ultisi rakiplerinin korku içinde kaçmasına neden olur. Savaşlarda gücünü azaltmak için dağınık durun."]]},"heimerdinger":{"id":"Heimerdinger","k":74,"n":"Heimerdinger","en":"Heimerdinger","t":"Saygın Mucit","cls":["Mage","Support"],"d":3,"res":"Mana","b":{"hp":558,"hpL":105,"ar":19,"arL":4.2,"mr":30,"mrL":1.3,"ad":56,"adL":2.7,"as":0.658,"asR":0.625,"asL":1.36,"rng":550,"ms":340,"t":"M"},"ab":[["Hextech Takviyesi","P","Takımının kuleleri ve Heimerdinger'in kurduğu taretlerin yakınında hareket hızı kazandırır.","img/abil/heimerdinger-p.png"],["H-28G Evrim Tareti","Q","Heimerdinger seri ateş etme özelliğine sahip bir top tareti kurar. Taret ayrıca, ikincil olarak engellerin içinden geçebilen bir ışın saldırısı ile donatılmıştır (taretler, kulelere normalin yarısı hasar verir).","img/abil/heimerdinger-q.png",[1,1,1,1,1]],["Hextech Mikro Roketler","W","Heimerdinger, imlece doğru giden uzun menzilli füzeler ateşler.","img/abil/heimerdinger-w.png",[11,10,9,8,7]],["CH-2 Elektron Bombası","E","Heimerdinger'in belli bir bölgeye attığı bomba, rakip birimlere hasar verir ve doğrudan vurduğu birimleri sersemletirken, çevresindeki birimleri de yavaşlatır.","img/abil/heimerdinger-e.png",[11,11,11,11,11]],["GELİŞTİR!!!","R","Heimerdinger'ın bulduğu geliştirme, bir sonraki büyüsünün etkisinin artmasını sağlar.","img/abil/heimerdinger-r.png",[100,85,70]]],"wk":"Heimerdinger","p":"img/champ/heimerdinger.png","tip":[["Taretlerini yerleştirme şeklin savaşın gidişatını belirleyen bir etken olabilir. Çift yerleştirilmiş taretler çoğu rakibe karşı en iyi yöntem olabilir; ama rakiplerin alan etkili yetenekleri ağırlıktaysa, taretler çabucak yok olabilir. Taretleri çalıya yerleştirmek, lehine sonuçlanacak bir sürpriz saldırıya yol açabilir.","Elektron Bombası'nın iyi kullanılması, Heimerdinger'ın hayatta kalması için çok önemlidir. Yavaşlatma ve sersemletme etkisi rakiplerin işini bitirmene yetecek kadar yerlerine mıhlanmalarını sağlar, ayrıca beklenmedik bir saldırıya karşı ilk savunma hattıdır.","Hextech Mikro-Roketleri yaymak, çoklu hedeflere karşı daha iyi ve daha etkin hasar sağlar; ancak tek noktaya odaklamak en büyük hasarı verir."],["Heimerdinger'ın taretleriyle teker teker savaşmak yerine minyonların yardımıyla hepsini birden yok etmek daha iyi olur.","Heimerdinger'ın pek çok sıkıntılı durumdan kurtulmasını sağlayan Geliştir!!! yeteneğine dikkat et. Ultisi devre dışı kaldığında, harekete geç!"]]},"hwei":{"id":"Hwei","k":910,"n":"Hwei","en":"Hwei","t":"Vizyoner","cls":["Mage","Support"],"d":3,"res":"Mana","b":{"hp":580,"hpL":109,"ar":21,"arL":4.7,"mr":30,"mrL":1.3,"ad":54,"adL":3.3,"as":0.69,"asR":0.658,"asL":2.5,"rng":550,"ms":330,"t":"M"},"ab":[["Vizyonerin İmzası","P","Hwei, yetenekleriyle hasar verdiği rakip şampiyonları kendi imzası olan bitirici dokunuşuna hazırlar. Bir rakibe hasar veren ikinci bir yetenek isabet ettirmek imzasının tamamlanarak onun altında kalmasını sağlar. Kısa bir gecikmenin ardından imza patlayarak menzili içindeki tüm rakiplere büyü hasarı verir.","img/abil/hwei-p.png"],["Öz: Facia","Q","Hwei, zihninde yıkıcı bir darbe resmedebilmesini sağlayan facialar canlandırır. Bu yetenek Hwei'in yeteneklerini şu hasar yetenekleriyle değiştirir: Mahveden Alev, Sinsi Yıldırım ve Püsküren Yarık.","img/abil/hwei-q.png",[10,9,8,7,6]],["Öz: Huzur","W","Hwei, zihninde dinçleştiren manzaralar resmedebilmesini sağlayan huzurlu anlar canlandırır. Bu yetenek Hwei'in yeteneklerini şu işlevsel yeteneklerle değiştirir: Tez Akıntı, Yansıma Havuzu ve Kıpırtılı Işıklar.","img/abil/hwei-w.png",[18,17.5,17,16.5,16]],["Öz: Istırap","E","Hwei, zihninde kontrol edici manzaralar resmedebilmesini sağlayan ıstıraplar canlandırır. Bu yetenek Hwei'in yeteneklerini şu kitle kontrolü yetenekleriyle değiştirir: Zulmün Çehresi, Karanlığın Gözü ve Şiddetli Isırık.","img/abil/hwei-e.png",[12,11.5,11,10.5,10]],["Umutsuzluğun Tablosu","R","Hwei, saf umutsuzluğun resmini çizer. İsabet alan ilk rakip şampiyon, gittikçe genişleyerek yakındaki rakipleri yavaşlatan ve onlara hasar veren bir resmin merkezi haline gelir. Bu resim azami boyutuna ulaştığında veya söz konusu şampiyon katledildiğinde patlar.","img/abil/hwei-r.png",[120,100,80]]],"wk":"Hwei","p":"img/champ/hwei.png","tip":[["Sakinleş, nefes al ve odaklan.","Her fırça darbesi bir amaç doğrultusunda hassaslıkla atılmalı."],["Hwei kullanması zaman alan yetenekleri için senin konumunu tahmin etmek zorunda. Onu hazırlıksız yakala.","Hwei'in ölümcül ama yavaş olan Sinsi Yıldırım yeteneği, sen yalnız kaldığında veya sabitlendiğinde daha çok hasar verir.","Hwei bir Istırap yeteneği resmettikten sonra saldırıya açık hale gelir."]]},"illaoi":{"id":"Illaoi","k":420,"n":"Illaoi","en":"Illaoi","t":"Ruhani Rehber","cls":["Fighter","Tank"],"d":2,"res":"Mana","b":{"hp":656,"hpL":115,"ar":35,"arL":5,"mr":32,"mrL":2.05,"ad":65,"adL":5,"as":0.625,"asR":0.625,"asL":2.5,"rng":125,"ms":350,"t":"P"},"ab":[["Yaşlı Tanrının Elçisi","P","Illaoi ve meydana getirdiği Kabuklar, çevredeki geçilmez yüzeylerde Dokunaçlar ortaya çıkarır. Dokunaçlar ruhlara, Kabuklara ve Illaoi'nin Sille Tokat yeteneğinin kurbanlarına vurur. Dokunaçlar vuruş isabet ettirdikleri rakiplere fiziksel hasar verir ve şampiyonlara hasar verirlerse Illaoi'yi iyileştirirler.","img/abil/illaoi-p.png"],["Dokunaç Darbesi","Q","Dokunaçların verdiği hasarı arttırır. Etkinleştirildiğinde, Illaoi fiziksel hasar veren bir Dokunaç ile darbe indirir.","img/abil/illaoi-q.png",[10,9,8,7,6]],["Sille Tokat","W","Illaoi hedefinin üstüne atılarak fiziksel hasar verir ve yakındaki Dokunaçların da hedefe vurmalarını sağlar.","img/abil/illaoi-w.png",[4,4,4,4,4]],["Ruh Sınavı","E","Illaoi rakibinin bedeninden söküp aldığı ruhu, önünde durmaya zorlar. Ruhlar, aldıkları hasarın belli bir oranını asıl hedefe yansıtır. Ruh katledilir ya da asıl hedef ruhtan fazla uzaklaşırsa, asıl hedef Kabuk haline gelir ve Dokunaçlar ortaya çıkarmaya başlar.","img/abil/illaoi-e.png",[16,15,14,13,12]],["İlahi Ders","R","Illaoi idolünü yere vurur ve yakındaki rakiplere fiziksel hasar verir. İsabet alan her şampiyon başına bir Dokunaç ortaya çıkar.","img/abil/illaoi-r.png",[120,95,70]]],"wk":"Illaoi","p":"img/champ/illaoi.png","tip":[["Dokunaçlar muazzam birer güç kaynağıdır. Onlar olmadan çatışmaya girme.","Ruhlar, hedeflerinin mevcut can miktarını devralır. Amacın","Kabuk","ortaya çıkarmaksa, ruhu katletmeyi kolaylaştırmak için önce rakibinin canını biraz azaltmaya çalış.","İlahi Ders'i, rakibe yönelik güçlü bir çatışma başlatma hamlesinden sonra veya saldırıya uğradığında kullanmak daha çok işine yarayacaktır. Çatışmaya ilk giren olma konusunda temkinli davran."],["Dokunaçları her fırsatta kesmek, Illaoi'yi alt etmeyi çok daha kolaylaştırır.","Ruhun çekildiğinde, mücadele edebiliyorsan etmeye bak. Illaoi'ye hasar vermek ruhun süresini kısaltır.","Illaoi'nin çağırabileceği Dokunaç sayısını azaltmak için İlahi Ders gerçekleştirdiği sırada takım arkadaşlarınla toplu halde bulunmaktan sakın."]]},"irelia":{"id":"Irelia","k":39,"n":"Irelia","en":"Irelia","t":"Bıçakların Dansı","cls":["Fighter","Assassin"],"d":2,"res":"Mana","b":{"hp":630,"hpL":115,"ar":36,"arL":4.7,"mr":30,"mrL":2.05,"ad":65,"adL":3.5,"as":0.656,"asR":0.656000018119812,"asL":2.5,"rng":200,"ms":335,"t":"P"},"ab":[["Ionia Azmi","P","Irelia rakiplerine yetenek isabet ettirdiğinde yük halinde biriken ilave Saldırı Hızı kazanır. Irelia azami yüke ulaştığında ayrıca isabet halinde ilave hasar verir.","img/abil/irelia-p.png"],["Uçarbıçak","Q","Irelia rakibine saldırmak için ileri atılır ve kendini iyileştirir. Eğer hedef işaretliyse veya Uçarbıçak tarafından katledilirse bekleme süresi sıfırlanır.","img/abil/irelia-q.png",[10,9,8,7,6]],["Direniş Dansı","W","Irelia, yoğunlaştıkça hasarı artan bir saldırıya başlar. Yoğunlaşması esnasında aldığı fiziksel hasar azalır.","img/abil/irelia-w.png",[20,18,16,14,12]],["Ölümcül Ahenk","E","Irelia birbirine doğru hareket eden iki bıçak gönderir. Bıçakların arasında kalan rakipler hasar alır, sersemler ve işaretlenir.","img/abil/irelia-e.png",[16,14.5,13,11.5,10]],["Keskin Hapis","R","Irelia bir rakip şampiyona çarptıklarında dışarı doğru açılan çok sayıda bıçak fırlatır. Bıçaklardan isabet alan rakipler hasar alır ve işaretlenir. Ardından bıçaklar, içinden geçen rakiplere hasar veren ve onları yavaşlatan bir duvar oluşturur.","img/abil/irelia-r.png",[125,105,85]]],"wk":"Irelia","p":"img/champ/irelia.png","tip":[["Uçarbıçak'la can değeri düşük minyonları hedefleyerek rakip şampiyonlarla arandaki uzun mesafeleri kapatabilirsin.","Direniş Dansı kitle kontrolleri tarafından engellenemediğinden, yeteneği bunları durdurmak için kullanmaya çalış.","Ölümcül Ahenk azami seyahat menziline sahip değil; onu yaratıcı şekillerde kullanmayı dene."],["Ionia Azmi yüklerine dikkat et ve Irelia'ya yükler devre dışıyken saldırmaya çalış.","Minyon dalgaları Irelia'nın hareketliliğini önemli ölçüde geliştirdiğinden, bunların içindeyken ona karşı savaşmaktan kaçın.","Önemli yeteneklerini Direniş Dansı üzerinde harcamamaya dikkat et."]]},"ivern":{"id":"Ivern","k":427,"n":"Ivern","en":"Ivern","t":"Doğasever Baba","cls":["Support","Mage"],"d":3,"res":"Mana","b":{"hp":630,"hpL":99,"ar":27,"arL":4.7,"mr":30,"mrL":1.3,"ad":50,"adL":3,"as":0.644,"asR":0.643999993801116,"asL":3.4,"rng":475,"ms":330,"t":"M"},"ab":[["Ormanın Dostu","P","Ivern destansı olmayan canavarlara saldıramaz, destansı olmayan canavarlar da Ivern'e saldıramaz. Ivern orman kamplarına zamanla büyüyen fundalıklar kurabilir. Fundalık tamamen büyüdüğünde Ivern canavarları serbest bırakarak altın ve deneyim kazanabilir.","img/abil/ivern-p.png"],["Kök Sal","Q","Ivern'ün ortaya çıkardığı sarmaşık, isabet alan hedeflere hasar vererek onları yerlerine sabitler. Ivern'ün takım arkadaşları sabitlenen hedefe doğru atılabilir.","img/abil/ivern-q.png",[14,13,12,11,10]],["Yeşert","W","Çalıdayken Ivern ve yakınındaki takım arkadaşlarının saldırıları ilave büyü hasarı verir. Ivern bu yeteneği etkinleştirerek bir çalılık ortaya çıkarabilir.","img/abil/ivern-w.png",[0.5,0.5,0.5,0.5,0.5]],["Patlartohum","E","Ivern takım arkadaşlarından birine kısa süre sonra patlayarak rakiplerin yavaşlayıp hasar görmesini sağlayan bir kalkan verir. Bu patlama bir rakibe isabet etmezse kalkan yenilenir.","img/abil/ivern-e.png",[11,10,9,8,7]],["Daisy!","R","Ivern gözcü dostu Daisy'yi onunla birlikte savaşması için çağırır. Yeteneği yeniden kullanarak Daisy'ye saldırması veya hareket etmesi için emir verebilirsin.","img/abil/ivern-r.png",[140,130,120]]],"wk":"Ivern","p":"img/champ/ivern.png","tip":[["Kök Sal yeteneğini rakibe isabet ettirdiğinde Patlartohum'la kendi takım arkadaşlarına yardımcı olmaya çalış!","Yeşert yeteneğinle ileride pusu için kullanabileceğin noktalar kur!","Daisy yetenek atışlarını engelleyebilir ve rakipleri yavaşlatabilir. Daisy'nin yıpratıcı etkisini takım arkadaşlarına yardım etmek için kullan!"],["Ivern kandırmaca konusunda usta olduğu için avucundan kolayca kaçabilir. Onu uzun süre takip edeceksen dikkatli ol.","Ivern'ün çalısı uzun süre varlığını korur. Pusulara dikkat et!","Daisy'yi yardıma çağırmaya hazırsa Ivern'le yalnız dövüşürken dikkatli ol!"]]},"janna":{"id":"Janna","k":40,"n":"Janna","en":"Janna","t":"Fırtınanın Hiddeti","cls":["Support","Mage"],"d":3,"res":"Mana","b":{"hp":570,"hpL":90,"ar":28,"arL":4.5,"mr":30,"mrL":1.3,"ad":47,"adL":2.5,"as":0.625,"asR":0.625,"asL":3,"rng":550,"ms":325,"t":"M"},"ab":[["Pupa Yeli","P","Janna'nın takım arkadaşları ona doğru ilerlerken hareket hızı kazanır. Janna isabet halinde ve Meltem yeteneğini kullandığında ilave hareket hızının bir kısmına eşdeğer miktarda ilave büyü hasarı verir.","img/abil/janna-p.png"],["Uğultulu Kasırga","Q","Janna basınç ve sıcaklığı bölgesel olarak değiştirerek zamanla büyüyen, küçük bir hortum oluşturabilir. Yeteneği tekrar kullanarak hortumu serbest bırakabilir. Hortum serbest kaldığında, oluşturulduğu yönde ilerler ve yoluna çıkan rakiplere hasar vererek onları havaya savurur.","img/abil/janna-q.png",[14,14,14,14,14]],["Meltem","W","Janna pasif olarak hareket hızını arttıran ve diğer birimlerin üstünden geçmesini sağlayan bir hava elementali çağırır. Bu yeteneği etkinleştirerek bir rakibine hasar verip onun hareket hızını da azaltabilir.","img/abil/janna-w.png",[8,7.5,7,6.5,6]],["Fırtınanın Gözü","E","Janna bir takım arkadaşına veya kuleye rüzgâr kalkanı vererek hedefini gelen hasara karşı korur ve onun saldırı gücünü arttırır.","img/abil/janna-e.png",[16,15,14,13,12]],["Muson","R","Janna etrafını rakipleri geri savuran büyülü bir fırtınayla kuşatır. Fırtına dindiğinde geriye kalan ferahlatıcı esintiler, yetenek etkin olduğu sürece yakındaki takım arkadaşlarını iyileştirir.","img/abil/janna-r.png",[130,115,100]]],"wk":"Janna","p":"img/champ/janna.png","tip":[["Fırtınanın Gözü dost kulelerde kullanılabilir.","Uğultulu Kasırga'yı enerjisi dolmadan çabucak fırlatmak, karşı takımı büyük ölçüde etkisiz hale getirebilir.","Janna'nın ultisini iyi zamanlamak, rakipleri yaralı bir dost şampiyondan uzaklaştırabilir hatta rakipleri birbirinden ayırabilir."],["Bir engelleme yeteneğini Janna'nın ultisi için sakla.","Uğultulu Kasırga'nın yüklenme sesini dinle; Janna seni onunla ekranın dışından ya da çalılıktan vurmayı deneyebilir.","Janna başka bir dostunu desteklerken en güçlü halindedir. Dostuna sataşabilirsen, bu onun seninle dövüşme yetisini azaltacaktır."]]},"jarvaniv":{"id":"JarvanIV","k":59,"n":"Jarvan IV","en":"Jarvan IV","t":"Demacia'nın Simgesi","cls":["Fighter","Tank"],"d":2,"res":"Mana","b":{"hp":640,"hpL":104,"ar":36,"arL":4.6,"mr":32,"mrL":2.05,"ad":64,"adL":3,"as":0.658,"asR":0.657999992370605,"asL":2.5,"rng":175,"ms":340,"t":"P"},"ab":[["Ordu Marşı","P","Jarvan'ın bir rakibe yönelik ilk normal saldırısı, rakibin mevcut canına bağlı olarak ilave fiziksel hasar verir. Bu etki, birkaç saniye boyunca aynı hedef üstünde ortaya çıkmaz.","img/abil/jarvaniv-p.png"],["Ejderha Saldırısı","Q","Jarvan IV kargısını uzatır ve karşısına çıkan rakiplere hasar vererek zırhlarını azaltır. Ayrıca, bu hareket Jarvan'ı Demacia Sancağı'na çekerken yoluna çıkan bütün rakipleri havaya savurmasını sağlar.","img/abil/jarvaniv-q.png",[10,9,8,7,6]],["Altın Kalkan","W","Jarvan IV Demacia'nın kadim krallarını çağırarak onu zarardan korumalarını ve çevredeki rakipleri yavaşlatmalarını sağlar.","img/abil/jarvaniv-w.png",[9,9,9,9,9]],["Demacia Sancağı","E","Jarvan IV, sahip olduğu Demacia gururu sayesinde pasif olarak fazladan Saldırı Hızı kazanır. Demacia Sancağı etkinleştirildiğinde, Jarvan IV bir Demacia bayrağı dikerek, büyü hasarı ve yakındaki dost şampiyonlara Saldırı Hızı verir.","img/abil/jarvaniv-e.png",[12,11.5,11,10.5,10]],["Afet","R","Jarvan IV kahramanca savaşa atılırken hedefine öyle bir güçle saldırır ki, zeminde bir deprem yaratarak hedefle kendini bir arena içine hapseder. Yakındaki rakipler darbe anında hasar alır.","img/abil/jarvaniv-r.png",[120,105,90]]],"wk":"Jarvan IV","p":"img/champ/jarvaniv.png","tip":[["Ejderha Saldırısı / Demacia Sancağı kombosunu kendi Afet bölgelerinden çıkmak için kullanabilirsin.","Dövüşlerin başında hasarını en yüksek seviyeye çekmek için normal saldırılarını farklı şampiyonlara yönelt.","Demacia Sancağı'nı, rakiplerin gelip gelmediğini görebilmek için bir keşif aracı olarak kullan."],["Havaya savrulmak istemiyorsan Jarvan IV ve Demacia Sancağı arasında durma.","Afet'in arazisi, korkutucu bir güçtür ama hareket yetenekleri üstesinden gelebilir."]]},"jax":{"id":"Jax","k":24,"n":"Jax","en":"Jax","t":"Silah Ustası","cls":["Fighter"],"d":2,"res":"Mana","b":{"hp":650,"hpL":103,"ar":36,"arL":4.2,"mr":32,"mrL":2.05,"ad":68,"adL":4.25,"as":0.638,"asR":0.638000011444091,"asL":3.4,"rng":125,"ms":350,"t":"P"},"ab":[["Amansız Saldırı","P","Jax'in arka arkaya yaptığı normal saldırılar saldırı hızını devamlı olarak arttırır.","img/abil/jax-p.png"],["Sıçrama Saldırısı","Q","Jax bir birime doğru sıçrar. Birimin rakip birim olması halinde, Jax silahıyla darbe indirir.","img/abil/jax-q.png",[8,7.5,7,6.5,6]],["Güçlendir","W","Jax silahını enerjiyle yükler ve bir sonraki saldırısının ek hasar vermesini sağlar.","img/abil/jax-w.png",[7,6,5,4,3]],["Karşı Saldırı","E","Jax'in savaştaki hüneri, kısa süreliğine gelen tüm fiziksel saldırılardan sıyrılmasını ve ardından hızla karşı saldırıya geçerek çevresindeki bütün rakipleri sersemletmesini sağlar.","img/abil/jax-e.png",[17,15,13,11,9]],["Silah Ustası","R","Peş peşe gerçekleştirilen her üçüncü saldırı fazladan büyü hasarı verir. Ayrıca Jax bu yeteneği etkinleştirdiğinde çevresindeki birimlere hasar verebilir ve azmini pekiştirerek zırhıyla büyü direncini kısa süreliğine arttırabilir.","img/abil/jax-r.png",[110,100,90]]],"wk":"Jax","p":"img/champ/jax.png","tip":[["Jax, Sıçrama Saldırısı'nı totemler dahil olmak üzere dost birimler üzerinde de kullanabilir.","Jax, Guinsoo'nun Hiddeti ve Hextech Silahkılıç gibi hem Yetenek Gücü hem de Saldırı Gücü veren eşyalardan büyük ölçüde yararlanır."],["Onunla yumruk yumruğa kapışmaktansa kısa aralıklarla saldır. Art arda saldırmasını engellemek verdiği hasarı büyük ölçüde azaltır.","Jax çok kısa bir süre için uzaktan gelen bütün saldırıları savuşturabilir ve etkisi bittiğinde yakın mesafedeki rakipleri afallatabilir. Ona saldırmak için sıyrılma gücü bitene kadar bekle."]]},"jayce":{"id":"Jayce","k":126,"n":"Jayce","en":"Jayce","t":"Yarınların Koruyucusu","cls":["Fighter","Marksman"],"d":3,"res":"Mana","b":{"hp":590,"hpL":109,"ar":22,"arL":5,"mr":30,"mrL":1.3,"ad":59,"adL":4.25,"as":0.658,"asR":0.657999992370605,"asL":3,"rng":125,"ms":335,"t":"P"},"ab":[["Hextech Kapasitör","P","Jayce silah değiştirdiğinde kısa süreliğine hareket hızı kazanır.","img/abil/jayce-p.png"],["Göklere! / Şok Patlaması","Q","Çekiç Hali: Rakibin üzerine sıçrar ve fiziksel hasar vererek onu yavaşlatır. Top Hali: Rakibin üzerinde (ya da menzili bittiğinde) patlayan ve isabet alan tüm rakiplere fiziksel hasar veren bir elektrik topu ateşler.","img/abil/jayce-q.png",[16,14,12,10,8,6]],["Şimşek Sahası / Hiper Yük","W","Çekiç Hali: Pasif: Her vuruşta Mana yeniler. Aktif: Birkaç saniyeliğine etraftaki rakiplere zarar veren bir elektrik alanı yaratır. Top Hali: Birkaç saldırı boyunca Saldırı Hızını azami değere yükselten bir enerji patlaması kazandırır.","img/abil/jayce-w.png",[10,10,10,10,10,10]],["Gürleyen Darbe / Hızlandırma Geçidi","E","Çekiç Hali: Bir rakibe büyü hasarı verir ve onu kısa bir mesafe geri savurur. Top Hali: İçinden geçen tüm takım arkadaşlarının hareket hızlarını arttıran bir Hızlandırma Geçidi ortaya çıkartır. Şok Patlaması geçidin içerisinden ateşlendiğinde atışın hızı, menzili ve hasarı artar.","img/abil/jayce-e.png",[20,18,16,14,12,10]],["Merkür Topu / Merkür Çekici","R","Çekiç Hali: Merkür Çekici'ni Merkür Topu'na dönüştürüp, yeni yetenekler ve menzil verir. Bu formdaki ilk saldırı, hedefin Zırhını ve Büyü Direncini düşürür. Top Formu: Merkür Topu'nu Merkür Çekici'ne dönüştürerek yeni yetenekler, Zırh ve Büyü Direnci verir. Bu formda yapılan ilk saldırı ilave büyü hasarı verir.","img/abil/jayce-r.png",[6]]],"wk":"Jayce","p":"img/champ/jayce.png","tip":[["Silahlarını sıklıkla değiştirdiğinden emin ol. Saldırılarını güçlendirecek ve çabucak hız patlamaları kazanmanı sağlayacaktır.","Kendini çok fazla hasar alırken bulursan, daha fazla savunma için Jayce'in Çekiç Hali'ni kullanmayı dene.","Daha fazla menzil ve hasar için Şok Patlaması'nı Hızlandırma Geçidi'nden geçirerek yap."],["Jayce hem menzilli olarak hem de yakından saldırabilir. Nasıl saldıracağını bilebilmek için duruşuna ve silahının rengine dikkat et.","Jayce Hızlandırma Geçidi'ni devreye sokarsa dikkatli ol; muhtemelen Şok Patlaması yapmaya hazırlanıyordur.","Jayce oyunun başlarında güçlüdür. Avantaj yakalarsa savunma ağırlıklı oyna."]]},"jhin":{"id":"Jhin","k":202,"n":"Jhin","en":"Jhin","t":"Virtüöz","cls":["Marksman","Mage"],"d":2,"res":"Mana","b":{"hp":655,"hpL":107,"ar":24,"arL":4.7,"mr":33,"mrL":1.1,"ad":61,"adL":4.4,"as":0.625,"asR":0.625,"asL":3,"rng":550,"ms":330,"t":"P"},"ab":[["Suflör","P","Jhin'in Suflör adlı silahı, olağanüstü hasar vermek için tasarlanmış hassas bir araçtır. Sabit bir hızla atış yapar ve haznesinde sadece dört mermi taşır. Jhin, karanlık büyüyle donattığı dördüncü merminin kritik vuruş yapmasını ve ilave infaz hasarı vermesini sağlar. Suflör her kritik vuruş yaptığında Jhin'e ilham vererek kısa süreliğine hareket hızı kazandırır.","img/abil/jhin-p.png"],["İlham Ateşi","Q","Jhin rakibine büyülü bir fişek atar. Fişek en fazla dört hedefe isabet eder ve verdiği hasar, katlettiği her hedef başına artar.","img/abil/jhin-q.png",[7,6.5,6,5.5,5]],["Trajedi","W","Jhin bastonunu savurarak muazzam menzile sahip bir atış yapar. Atışı minyon ve canavarları deşip geçse de isabet ettiği ilk şampiyonda durur. Kısa süre önce Jhin'in takım arkadaşlarının saldırısına uğrayan, Nilüfer Kapanlarına yakalanan veya Jhin'den hasar alan hedefler yere sabitlenir.","img/abil/jhin-w.png",[12,12,12,12,12]],["Esaret Çiçeği","E","Jhin, üzerine basıldığında filizlenen, görünmez bir Nilüfer Kapanı kurar. Filizlenen kapan yakınındaki rakipleri yavaşlatır, ardından keskin taçyaprakları saçarak patlar ve hasar verir. Ölümün Güzelliği - Jhin bir rakip şampiyonu katlettiğinde, katledilen bedenin üzerinde bir nilüfer kapanı filizlenir.","img/abil/jhin-e.png",[2,2,2,2,2]],["Son Perde","R","Jhin yoğunlaşarak Suflör'ü omuzdan ateşlenen bir mega topa dönüştürür. Suflör bu haliyle olağanüstü menzile sahip dört süper atış yapabilir. Süper atışlar, minyon ve canavarları deşip geçse de isabet ettikleri ilk şampiyonda durur. Suflör, isabet alan rakipleri sakatlar ve onların yavaşlayarak infaz hasarı almalarını sağlar. Mükemmel hazırlanan, dillere destan bir güçle bezeli 4. atışın kritik vuruş yapması garantidir.","img/abil/jhin-r.png",[120,105,90]]],"wk":"Jhin","p":"img/champ/jhin.png","tip":[["Trajedi atışının muazzam bir menzili vardır. Bir çatışmaya yaklaşırken geniş bir alanı tarayıp, yerine sabitlenmiş rakipler ara.","Ulti yeteneğin, canı dolu olan rakiplere daha az hasar verir. Canı azalıp kaçan hedefleri avlamaya çalış.","Silahını doldururken de yeteneklerini kullanabilirsin. Normal saldırı gerçekleştiremeden geçirdiğin zamanı, yeteneklerini kullanarak değerlendir."],["Trajedi sadece son dört saniye içinde Jhin'in normal saldırıları, kapanları veya takım arkadaşlarından isabet alan birimleri yerine sabitler.","Jhin, haritanın dört bir yanına görünmez kapanlar yerleştirir. O yüzden adımını attığın yere dikkat et!","Jhin'in saldırıları oldukça güçlüdür ama 4. atışından sonra cephanesi biter. Silahını yeniden doldurduğu sırada geçen süreyi üzerine atılıp, ona hızla hasar vermek için kullan."]]},"jinx":{"id":"Jinx","k":222,"n":"Jinx","en":"Jinx","t":"Delifişek","cls":["Marksman"],"d":2,"res":"Mana","b":{"hp":610,"hpL":105,"ar":26,"arL":4.2,"mr":33,"mrL":1.1,"ad":59,"adL":3,"as":0.625,"asR":0.625,"asL":1,"rng":525,"ms":325,"t":"P"},"ab":[["Ay Çok Heyecanlı!","P","Jinx bir rakip şampiyonun, destansı orman canavarının veya yapının katledilmesine, kesilmesine veya yıkılmasına yardım ettiğinde büyük bir hareket hızı ve saldırı hızı artışı kazanır.","img/abil/jinx-p.png"],["Değiştir!","Q","Jinx, makinelisi Dan Dan ve roketatarı Kılçık arasında geçiş yaparak normal saldırılarına farklı özellikler kazandırır. Dan Dan'la yapılan saldırılar saldırı hızı sağlarken, Kılçık'la yapılan saldırılar alan etkili hasar ile menzil artışı verir; fakat mana tüketir ve daha yavaştır.","img/abil/jinx-q.png",[0.9,0.9,0.9,0.9,0.9]],["Cızzt!","W","Jinx, şok tabancası Cızbız'la ateş ettiği ilk rakip şampiyona hasar verir, şampiyonu yavaşlatır ve açığa çıkarır.","img/abil/jinx-w.png",[8,7,6,5,4]],["Patlangaç!","E","Jinx'in bir hat üzerinde attığı bombalı kapanlar 5 saniye sonra patlayarak rakipleri ateşe verir. Patlangaçlar, üzerlerinden geçen rakip şampiyonları sabitler.","img/abil/jinx-e.png",[24,20.5,17,13.5,10]],["Manyak Güçlü Ölüm Roketi!","R","Jinx'in ateşlediği süper roket harita boyunca yol alırken hasar elde eder. Roket bir rakip şampiyona çarptığında patlayarak ona ve çevredeki rakiplere eksik Can değerlerine göre hasar verir.","img/abil/jinx-r.png",[85,65,45]]],"wk":"Jinx","p":"img/champ/jinx.png","tip":[["Roketler her zaman en iyi çözüm değildir! Jinx'in makinelisi tam kapasiteye ulaştığında inanılmaz derecede güçlüdür. Bir rakip şampiyon çok yaklaştığında makineliye geç.","Jinx'in roketleri, patlama içindeki tüm rakiplere tam hasar verir. Koridorda minyonların üzerinde kullanarak, minyonların saldırısını çekmeden yakındaki rakip şampiyonları vurabilirsin.","Çatışma başladığında kenarda kalıp roketlerle ve Czzt!'la taciz etmeye çalış. Güvenli olduğunu hissetmediğin sürece çatışmaya dalıp makineliyle saydırma."],["Jinx'in makinelisinin güçlenmesi zaman alır. Roketlerle seni taciz ettiğini görürsen üzerine atlayıp indirmeye çalış.","Jinx'e ne kadar yakınsan ultisi sana o kadar az hasar verir.","Jinx'in bombalı kapanlarının bekleme süresi uzundur; Jinx bunları ana olarak kendini korumak için kullanır. Eğer bombaları ıskalarsa, kaçmakta zorlanacaktır."]]},"kaisa":{"id":"Kaisa","k":145,"n":"Kai'Sa","en":"Kai'Sa","t":"Hiçlik'in Kızı","cls":["Marksman","Mage"],"d":2,"res":"Mana","b":{"hp":640,"hpL":102,"ar":25,"arL":4.2,"mr":33,"mrL":1.1,"ad":59,"adL":2.6,"as":0.644,"asR":0.643999993801116,"asL":1.8,"rng":525,"ms":335,"t":"M"},"ab":[["İkinci Deri","P","Kai'Sa'nın normal saldırıları Plazma yükü biriktirerek artan ilave büyü hasarı verir. Takım arkadaşlarının hareketsiz bırakma etkileri de Plazma yükü biriktirmeye yardımcı olur. Ayrıca Kai'Sa'nın aldığı eşyalar, şampiyonun temel yeteneklerini daha güçlü özelliklere sahip olacak şekilde güçlendirir.","img/abil/kaisa-p.png"],["Icathia Yaylımı","Q","Kai'Sa yakınındaki hedeflere güdümlü çok sayıda atış yapar. Yaşayan Silah: Icathia Yaylımı daha fazla atış yapacak şekilde geliştirilir.","img/abil/kaisa-q.png",[10,9,8,7,6]],["Hiçlik Topu","W","Kai'Sa rakiplerini pasifiyle işaretleyen uzun menzilli bir atış yapar. Yaşayan Silah: Hiçlik Topu daha fazla pasif işareti uygulayacak ve şampiyonlara isabet etmesi halinde bekleme süresini azaltacak şekilde geliştirilir.","img/abil/kaisa-w.png",[20,18.5,17,15.5,14]],["Gücün Sınırı","E","Kai'Sa kısa süreliğine hareket hızını ve ardından saldırı hızını arttırır. Yaşayan Silah: Gücün Sınırı kısa süreliğine görünmezlik sağlayacak şekilde geliştirilir.","img/abil/kaisa-e.png",[16,14.5,13,11.5,10]],["Ölümcül Dürtü","R","Kai'Sa bir rakip şampiyonun yakınına atılır.","img/abil/kaisa-r.png",[130,100,70]]],"wk":"Kai'Sa","p":"img/champ/kaisa.png","tip":[["Rakibin taşıyıcılarını yalnız başlarına yakalamaya ve onları Icathia Yaylımı'yla alaşağı etmeye çalış.","Takım arkadaşlarınla işbirliği yaparak ultini en iyi şekilde kullan ve pasifinden azami fayda kazan.","En azından bir veya iki yeteneğini evrimleştirecek eşyalar almaya özen göster."],["Kai'Sa tek başına kalan rakipleri ortadan kaldırma konusunda çok iyidir. Ona karşı oynarken takım arkadaşlarınla birlikte hareket etmeye çalış.","Kai'Sa büyücüler veya uzun menzilli taşıyıcılar tarafından uzaktan avlanmaya gerçekten müsait bir şampiyon.","Kör noktalara totem yerleştirerek Kai'Sa'nın gelişini önceden fark edebilirsin."]]},"kalista":{"id":"Kalista","k":429,"n":"Kalista","en":"Kalista","t":"İntikam Mızrağı","cls":["Marksman"],"d":3,"res":"Mana","b":{"hp":560,"hpL":114,"ar":24,"arL":5.2,"mr":33,"mrL":1.1,"ad":57,"adL":4.75,"as":0.694,"asR":0.694000005722045,"asL":4.5,"rng":525,"ms":330,"t":"P"},"ab":[["Üstün Denge","P","Kalista, normal saldırı veya Delici için hazırlanırken hareket komutu verilirse, saldırısını yaptığında o yöne doğru kısa bir mesafeyi atılarak geçer.","img/abil/kalista-p.png"],["Delici","Q","Kalista'nın fırlattığı mızrak, hızla ilerleyerek katlettiği rakiplerin içinden geçer.","img/abil/kalista-q.png",[9,9,9,9,9]],["Gözcü","W","Kalista, Yeminli takım arkadaşıyla aynı hedefe saldırdığında ilave hasar kazanır. Etkinleştirerek, bir hat boyunca devriye gezen ve önündeki alanı açığa çıkaran bir ruh gönderebilirsin.","img/abil/kalista-w.png",[30,30,30,30,30]],["Ciğerini Sök","E","Saldırılar, fırlatılan mızrakların hedefe saplanıp kalmasına neden olur. Etkinleştirerek mızrakları rakibinden sökebilirsin. Bu esnada rakip yavaşlatılır ve artan hasara maruz kalır.","img/abil/kalista-e.png",[0,0,0,0,0]],["Ecelin Çağrısı","R","Kalista, Yeminli takım arkadaşını yanına ışınlar. Işınlanan şampiyon, bir konuma doğru atılarak rakip şampiyonları geriye savurabilir.","img/abil/kalista-r.png",[160,140,120]]],"wk":"Kalista","p":"img/champ/kalista.png","tip":[["Bir hedefi katlettiğinde bekleme süresi sıfırlandığından, Ciğerini Sök iyi bir son vuruş aracıdır.","Üstün Denge'yi tetiklemek için bir kereliğine hareket komutu vermek, Kalista'nın normal saldırı hedefini değiştirmez.","Kalista'nın Hareket Hızı, pasifi sayesinde Saldırı Hızına bağlı olarak büyük oranda artar."],["Kalista'nın hareket becerisi saldırmasına bağlıdır. Yani Kalista saldırı menzilinin dışındayken hareket düzeyi düşüktür ve saldırı hızı azaltan etkiler, çatışmada alabildiği mesafeyi düşürür.","Kalista normal saldırı hazırlığını iptal edemez. Bu sayede saldırıya başlayacağı anı kestirebilirsen ona yetenek atma fırsatı yakalabilirsin.","Kalista'nın görüş açısından çıkmayı başarırsan (mesela çalıya girdiğinde) normal saldırıları sana isabet etmeden yere düşer."]]},"karma":{"id":"Karma","k":43,"n":"Karma","en":"Karma","t":"Bilgelik Ateşi","cls":["Mage","Support"],"d":2,"res":"Mana","b":{"hp":630,"hpL":109,"ar":28,"arL":5,"mr":30,"mrL":1.3,"ad":49,"adL":3,"as":0.625,"asR":0.625,"asL":2.3,"rng":525,"ms":335,"t":"M"},"ab":[["Güçlenen Ateş","P","Karma'nın hasar veren yetenekleri Mantra'nın bekleme süresini azaltır.","img/abil/karma-p.png"],["İçindeki Alev","Q","Karma'nın gönderdiği küre şeklindeki ruh enerjisi, bir rakip birime isabet ettiğinde patlayarak hasar verir. Mantra Avantajı: Patlamaya ek olarak, Mantra İçindeki Alev'in yıkıcı gücünü arttırarak kısa bir süre sonra tekrar hasar verir.","img/abil/karma-q.png",[9,8,7,6,5]],["Değişmez Karar","W","Karma kendisiyle hedeflediği rakip arasında bir bağ kurarak rakibin hasar almasına ve açığa çıkmasına yol açar. Bağ kopmazsa, rakip yere sabitlenir ve yeniden hasar alır. Mantra Avantajı: Karma bağı güçlendirerek kendini iyileştirir ve yere sabitlenme süresini uzatır.","img/abil/karma-w.png",[12,12,12,12,12]],["Esin","E","Karma'nın oluşturduğu koruyucu kalkan, gelen hasarı emer ve korunan takım arkadaşının hareket hızını arttırır. Mantra Avantajı: Hedeften yayılan enerji, başta verilen kalkanı güçlendirir ve yakındaki dost şampiyonlara da Esin verir.","img/abil/karma-e.png",[10,9.5,9,8.5,8]],["Mantra","R","Karma bir sonraki yeteneğini güçlendirerek yeteneğe ilave bir etki kazandırır. Mantra 1. seviyeden itibaren kullanılabilir ve yetenek puanı gerektirmez.","img/abil/karma-r.png",[40,38,36,34]]],"wk":"Karma","p":"img/champ/karma.png","tip":[["Güçlenen Ateş, saldırgan oyun tarzını ödüllendirir. Yeteneklerini ve normal saldırılarını rakibe isabet ettirerek Mantra'nın bekleme süresini düşürmeye ve saldırgan oynamaya çalış.","Değişmez Karar'ı kullanırken, hedefi yakalamakta zorlanıyorsan rakiplerini İçindeki Alev'le yavaşlat veya Esin'le kendini hızlandır.","Mantra'yı kullanırken cimri davranma. Güçlenen Ateş takım savaşlarında çok güçlüdür, bu da Mantra'yı birkaç kez doldurmayı kolaylaştırır."],["Karma'nın pasifi, yetenekleri ve normal saldırıları ile rakip şampiyonlara vurduğunda Mantra'sının bekleme süresini düşürür. Sana, zarar almadan vuruş yapmasına izin verme.","Karma'nın Ruhyalazı, yerleştirildiği alanda patlayarak ilave hasar verir. Çabucak çemberden kaçarak ağır hasar almaktan kurtulmaya çalış.","Değişmez Karar, güçlü bir ayırma aracıdır. Sabitlenmekten kaçmak için aranıza mesafe koy ve sonra çatışmaya girmeye çalış."]]},"karthus":{"id":"Karthus","k":30,"n":"Karthus","en":"Karthus","t":"Ölümşakıyan","cls":["Mage"],"d":3,"res":"Mana","b":{"hp":620,"hpL":110,"ar":21,"arL":4.7,"mr":30,"mrL":1.3,"ad":46,"adL":3.25,"as":0.625,"asR":0.625,"asL":2.11,"rng":450,"ms":335,"t":"M"},"ab":[["Ölüm Tanımaz","P","Karthus, katledildikten sonra yetenek kullanmaya devam edebildiği bir hayalet biçimine girer.","img/abil/karthus-p.png"],["Hortlak Mayın","Q","Karthus belli bir konumda gecikmeli bir patlama meydana getirerek, çevredeki rakiplere hasar verir. Ayrı düşmüş rakiplere daha fazla hasar verir.","img/abil/karthus-q.png",[0,0,0,0,0]],["Acı Duvarı","W","Karthus sömürü enerjisinden bir perde oluşturur. Perdenin içinden geçen rakip birimlerin Hareket Hızı ve Büyü Direnci belirli bir süreliğine azalır.","img/abil/karthus-w.png",[15,15,15,15,15]],["Çürüt","E","Karthus pasif olarak kurbanlarından enerji çalarak, öldürdüğü her kurbandan Mana kazanır. Alternatif olarak, Karthus kendini avlarının ruhlarıyla kuşatarak kendi Manasını hızla tüketirken, yakındaki rakiplere de hasar verebilir.","img/abil/karthus-e.png",[0.5,0.5,0.5,0.5,0.5]],["Ağıt","R","Karthus 3 saniye odaklandıktan sonra bütün rakip şampiyonlara hasar verir.","img/abil/karthus-r.png",[200,180,160]]],"wk":"Karthus","p":"img/champ/karthus.png","tip":[["Farklı koridorlardaki rakipleri öldürebilmek için Ağıt'ı ne zaman kullanabileceğini takım arkadaşlarına sor.","Hortlak Mayın, minyonları biçmek ve rakip şampiyonlara zarar vermekte çok güçlüdür."],["Karthus öldürüldükten sonra kısa bir süre için büyü yapabilir. Güvenliğin için cesedinden uzaklaş.","İyileşmek için üsse daha sık gitmek zorunda kalsan da, Ağıt'tan kurtulacak kadar cana sahip olduğundan sürekli emin ol."]]},"kassadin":{"id":"Kassadin","k":38,"n":"Kassadin","en":"Kassadin","t":"Hiçlik Gezgini","cls":["Assassin","Mage"],"d":3,"res":"Mana","b":{"hp":646,"hpL":113,"ar":21,"arL":4,"mr":30,"mrL":1.3,"ad":59,"adL":3.9,"as":0.64,"asR":0.639999985694885,"asL":3.7,"rng":150,"ms":335,"t":"M"},"ab":[["Hiçlik Taşı","P","Kassadin daha az büyü hasarı alır ve birimlerin içinden geçebilir.","img/abil/kassadin-p.png"],["Hiçlik Küresi","Q","Kassadin hiçlik enerjisinden oluşan bir küreyi hedefe yollayarak hasar verir ve onun yoğunlaşmasını engeller. Kalan enerji etrafında toplanarak, büyü hasarını soğuran geçici bir kalkan oluşturur.","img/abil/kassadin-q.png",[9,8.5,8,7.5,7]],["Cehennem Kılıcı","W","Pasif: Kassadin'in normal saldırıları ilave büyü hasarı verir. Aktif: Kassadin'in bir sonraki normal saldırısı büyük miktarda ilave büyü hasarı verir ve manasını yeniler.","img/abil/kassadin-w.png",[7,7,7,7,7]],["Güç Darbesi","E","Kassadin, çevresinde kullanılan yeteneklerden enerji çeker. Tam güce ulaştığında, Kassadin Güç Darbesi'ni koni şeklindeki bir alana göndererek önündeki rakiplere hasar verebilir ve onları yavaşlatabilir.","img/abil/kassadin-e.png",[21,20,19,18,17]],["Boşluk Geçişi","R","Kassadin, yakın bir konuma ışınlanarak etrafındaki birimlere hasar verir. Kısa zaman aralığında gerçekleştirilen birden fazla Boşluk Geçişi fazladan manaya mal olur ama ilave hasar verir.","img/abil/kassadin-r.png",[5,3.5,2]]],"wk":"Kassadin","p":"img/champ/kassadin.png","tip":[["Kassadin'in birden fazla eşya donanım yolu vardır; Mana ve Yetenek Gücü eşyaları üzerinden büyücü olma yolundan gidebilir ya da Bekleme Süresinde Azalma ve Büyü Direnci özelliği olan eşyalarla büyücülere karşı avantajlı hale gelebilir.","Kassadin'in ultisinin birçok kullanımı vardır ve bekleme süresi çoğunluğa kıyasla daha kısadır, bol bol kullan.","Boşluk Geçişi'nin artan Mana giderinin önüne geçebilmek için Mavi Gözcü güçlendirmesini almaya çalış."],["Kassadin çoğunlukla büyü hasarı verir. İyi gidiyorsa, Merkür'ün Adımları ve Banshee'nin Duvağı gibi Büyü Direnci veren eşyaları almayı düşün.","Kassadin art arda Boşluk Geçişi'ni kullanırsa, her seferinde daha fazla mana harcar. Onu kovalarken bu aklında olsun.","Kassadin'in yavaşlatma etkisi olan Güç Darbesi'nin kullanılabilir olması için 6 büyü yapması gerekmektedir. Yeteneğinin seviyesini arttırırsa, onunla aynı koridorda mücadele ederken yeteneklerini akıllıca kullan."]]},"katarina":{"id":"Katarina","k":55,"n":"Katarina","en":"Katarina","t":"Sinsi Bıçak","cls":["Assassin","Mage"],"d":3,"res":"Yok","b":{"hp":672,"hpL":108,"ar":32,"arL":4.7,"mr":32,"mrL":2.05,"ad":58,"adL":3.2,"as":0.658,"asR":0.657999992370605,"asL":2.74,"rng":125,"ms":335,"t":"M"},"ab":[["Açgözlü","P","Katarina'nın kısa süre önce hasar verdiği bir şampiyon katledilirse, Katarina'nın yeteneklerinin bekleme süreleri önemli ölçüde azalır. Katarina yerden bir hançer alırsa, bunu kullanarak yakınındaki tüm rakipleri biçer ve onlara büyü hasarı verir.","img/abil/katarina-p.png"],["Sıçrayan Bıçak","Q","Katarina'nın hedefine attığı hançer yakındaki rakiplere sektikten sonra yere saplanır.","img/abil/katarina-q.png",[11,10,9,8,7]],["Ölümcül Çeviklik","W","Katarina kısa süreliğine hareket hızında artış kazanır ve bulunduğu noktadan havaya bir hançer savurur.","img/abil/katarina-w.png",[15,14,13,12,11]],["Shunpo","E","Katarina bir anda hedefine ışınlanır ve bu hedef rakipse ona, değilse en yakındaki rakibe saldırır.","img/abil/katarina-e.png",[12,11,10,9,8]],["Ölüm Çiçeği","R","Katarina bıçaklarını benzersiz bir hızla savurarak en yakındaki 3 şampiyona yoğunlaşır ve yüksek miktarda büyü hasarı verir.","img/abil/katarina-r.png",[75,60,45]]],"wk":"Katarina","p":"img/champ/katarina.png","tip":[["Yerden hançer aldığında Shunpo'nun bekleme süresi büyük oranda azalır.","Karşı takım, takımının diğer üyeleriyle meşgulken, Shunpo'yu kullanarak çatışmanın içine ışınlan ve Ölüm Çiçeği'nin yıkıcı etkisinden yararlan.","Shunpo'yu dost bir şampiyon, minyon veya totem üzerinde kullanmak, harika bir kaçış yöntemi olabilir."],["Katarina'nın yetenekleri büyü hasarı verir; yani Saldırı Gücü veren eşyalar topluyorsa bile, ona karşı büyü direnci topla.","Katarina'nın Ölüm Çiçeği'ni kullandığı an için bir engelleme saklamaya çalış."]]},"kayle":{"id":"Kayle","k":10,"n":"Kayle","en":"Kayle","t":"Adaletin Kılıcı","cls":["Marksman","Mage"],"d":3,"res":"Mana","b":{"hp":670,"hpL":92,"ar":26,"arL":4.2,"mr":22,"mrL":1.3,"ad":50,"adL":2.5,"as":0.625,"asR":0.666999995708465,"asL":1.5,"rng":175,"ms":335,"t":"P"},"ab":[["İlahi Yükseliş","P","Kayle seviye atlayıp yetenek puanı harcadıkça saldırıları da göklerden güç alır. Kanatları alev alan Kayle, zamanla saldırı hızı, hareket hızı, saldırı menzili ve saldırıları için ateş dalgaları kazanır.","img/abil/kayle-p.png"],["Işığın Hükmü","Q","Kayle'ın çağırdığı semavi kılıç rakipleri delip geçerek isabet ettiği bütün hedefleri yavaşlatır, onlara hasar verir ve dirençlerini azaltır.","img/abil/kayle-q.png",[10,9.5,9,8.5,8]],["Semavi Lütuf","W","İlahi güçler tarafından kutsanan Kayle, kendine ve en yakınındaki takım arkadaşına iyileştirme ve hareket hızı sağlar.","img/abil/kayle-w.png",[15,15,15,15,15]],["Yıldızateşi Kılıcı","E","Pasif: Kayle'ın semavi kılıcı Erdem, şampiyonun saldırdığı rakiplere ilave büyü hasarı verir. Aktif: Kayle'ın bir sonraki saldırısı hedefini semavi ateşle çarparak hedefin eksik canıyla orantılı ilave hasar verir.","img/abil/kayle-e.png",[8,7.5,7,6.5,6]],["Yüce Adalet","R","Kayle bir takım arkadaşını hasar görmez hale getirir ve hedefin etrafındaki bölgeyi ilahi bir kılıç yağmuruna tutmaları için eski Adaletin Suretlerini çağırır.","img/abil/kayle-r.png",[140,110,80]]],"wk":"Kayle","p":"img/champ/kayle.png","tip":[["Yüce Adalet'i yüksek hasar veren bir takım arkadaşının üzerinde kullanarak savaşın seyrini değiştirebilirsin.","Kayle, İlahi Yükseliş'le saldırı menzili kazandığında, saldırıları müthiş derecede güçlenir. O zamana kadar güvende kalmaya çalış.","Kayle, hem saldırı gücü hem de yetenek gücünden muazzam şekilde faydalanabilir. Dolayısıyla Nashor'un Dişi ve Hextech Silahkılıç gibi karma eşyalar Kayle için son derece etkilidir."],["Yüce Adalet, Kayle'ın veya takım arkadaşlarının sadece hasara karşı bağışıklık kazanmasını sağlar. Yavaşlatma ve sersemletme yetenekleri hâlâ uygulanabilir. O nedenle, aşırıya kaçıyorlarsa onları kapana kıstır.","Kayle genellikle narin bir hedeftir. Ultisini bir takım arkadaşının üstünde kullandığını gördüğün anda ona saldırmaya çalış.","Kayle, oyuna görece olarak zayıf bir yakın dövüşçü olarak başlar. Menzilli biçimine yükselmeden önce onu geride bırakmaya çalış."]]},"kayn":{"id":"Kayn","k":141,"n":"Kayn","en":"Kayn","t":"Gölge Cellat","cls":["Fighter","Assassin"],"d":3,"res":"Mana","b":{"hp":655,"hpL":103,"ar":38,"arL":4.5,"mr":32,"mrL":2.05,"ad":68,"adL":3.3,"as":0.669,"asR":0.669000029563903,"asL":2.7,"rng":175,"ms":340,"t":"P"},"ab":[["Darkin Tırpan","P","Kayn elinde kadim bir silah taşır ve bu silahın içindeki Darkin Rhaast'la hâkimiyet mücadelesi verir. Ya Darkin galip gelir ya da Kayn Rhaast'ı alt ederek Gölge Suikastçı olur. Darkin: Şampiyonlara verilen yetenek hasarının belli bir yüzdesi kadar iyileşir. Gölge Suikastçı: Rakip şampiyonlarla girilen çatışmaların ilk birkaç saniyesinde ilave hasar verir.","img/abil/kayn-p.png"],["Karanlık Hasat","Q","Kayn ileri atılıp rakiplerini biçer. İki hamle de hasar verir.","img/abil/kayn-q.png",[7,6.5,6,5.5,5]],["Kasvet Dalgası","W","Kayn bir hat üstündeki hedeflere hasar verip onları yavaşlatır.","img/abil/kayn-w.png",[13,12,11,10,9]],["Gölge Yolu","E","Kayn yüzey şekillerinin içinden geçebilir.","img/abil/kayn-e.png",[21,19,17,15,13]],["Davetsiz Misafir","R","Kayn bir rakibin bedeninde saklanır ve dışarı çıkarken büyük miktarda hasar verir.","img/abil/kayn-r.png",[120,100,80]]],"wk":"Kayn","p":"img/champ/kayn.png","tip":[["Biçimini seçerken hem kendi takımının hem de rakibinin kadrosunu göz önünde bulundur.","Yakındaki rakiplerin hangi duvarın içinde olduğunu görebildiğini unutma."],["Davetsiz Misafir için önce Kayn'in bir hedefe hasar vermesi gerekir. Davetsiz Misafir'i uzaktan kullanmasına engel olmak istiyorsan Kasvet Dalgası'ndan sıyrılmaya çalış.","Kayn yakınındaki bir yüzey şeklinin içindeyken söz konusu yüzey şeklinin kıyısında görsel bir uyarı alırsın.","Gölge Yolu'ndayken Kayn'e hasar vererek bu yeteneği kısaltabilir veya yoğun kitle kontrolü (sersemletme, ayartma, havaya savurma gibi) uygulayarak Gölge Yolu'na anında son verebilirsin."]]},"kennen":{"id":"Kennen","k":85,"n":"Kennen","en":"Kennen","t":"Fırtınanın Kalbi","cls":["Mage"],"d":2,"res":"Enerji","b":{"hp":580,"hpL":98,"ar":29,"arL":4.95,"mr":30,"mrL":1.3,"ad":48,"adL":3.75,"as":0.625,"asR":0.689999997615814,"asL":3.4,"rng":550,"ms":335,"t":"M"},"ab":[["Fırtına İşareti","P","Kennen, yeteneklerini 3 defa isabet ettirdiği rakipleri sersemletir.","img/abil/kennen-p.png"],["Gürleyen Yıldız","Q","Kennen belli bir konuma hızla ilerleyen bir yıldız atar ve yıldız vurduğu rakibe hasar verirken, bir de Fırtına İşareti koyar.","img/abil/kennen-q.png",[7,6.25,5.5,4.75,4]],["Elektrik Dalgası","W","Kennen pasif olarak birkaç saldırıda bir fazladan hasar verir ve hedefini Fırtına İşareti ile damgalar. Bu yeteneği aktifleştirerek, önceden Fırtına İşareti taşıyan hedeflere hasar verip bir Fırtına İşareti daha ekleyebilir.","img/abil/kennen-w.png",[13,11.25,9.5,7.75,6]],["Şimşek Gibi","E","Kennen şimşek suretine bürünür ve birimlerin içinden geçebilir. İçinden geçtiği rakip birimlere Fırtına İşareti uygular. Kennen bu surete büründüğünde hareket hızı, suretten çıktığında saldırı hızı kazanır.","img/abil/kennen-e.png",[10,9,8,7,6]],["Yıldırım Yağmuru","R","Kennen'in çağırdığı fırtına, yakındaki rakip şampiyonlara vurarak büyü hasarı verir.","img/abil/kennen-r.png",[120,120,120]]],"wk":"Kennen","p":"img/champ/kennen.png","tip":[["Rakiplerine 3 tane Fırtına İşareti atarak onları sersemletebilirsin.","Şimşek Gibi, daha sonra başka yetenekleri kullanmaya izin veren Enerjiyi geri döndürmesiyle dövüş başlatmak için kullanılabilir.","Gürleyen Yıldız'la bir rakibe Fırtına İşareti atabilir, daha sonra üzerine Elektrik Dalgası'nı ekleyebilirsin."],["Fırtına İşareti dezavantajının etkisi altındaysan, Kennen'ın yakınındayken biraz daha dikkatli ol. Sana 3 adet Fırtına İşareti'yle vurursa, sersemlersin.","Kennen doğası gereği dayanıksızdır. Şimşek Gibi'yle dikkatsiz davranırsa dön ve ona saldır."]]},"khazix":{"id":"Khazix","k":121,"n":"Kha'Zix","en":"Kha'Zix","t":"Hiçlik Yağmacısı","cls":["Assassin"],"d":2,"res":"Mana","b":{"hp":643,"hpL":99,"ar":32,"arL":4.2,"mr":32,"mrL":2.05,"ad":60,"adL":3.1,"as":0.668,"asR":0.667999982833862,"asL":2.7,"rng":125,"ms":345,"t":"P"},"ab":[["Görünmez Tehdit","P","Takım arkadaşlarından ayrı düşen yakın rakipleri işaretler. Kha'Zix'in yetenekleri, ayrı düşmüş hedeflerle özel etkileşimler ortaya çıkarır. Kha'Zix rakip takım tarafından görülemediğinde Görünmez Tehdit oluşturur; bir rakip şampiyona yaptığı ilk normal saldırısı ilave büyü hasarı verir ve hedefini birkaç saniyeliğine yavaşlatır.","img/abil/khazix-p.png"],["Korkularından Beslen","Q","Hedefe fiziksel hasar verir. Bu hasar, takım arkadaşlarından ayrı düşmüş hedeflere karşı artar. Kha'Zix Biçen Pençe Geliştirmeyi seçerse takım arkadaşlarından ayrı düşmüş hedeflere karşı bekleme süresinin bir kısmını geri kazanır. Kha'Zix ayrıca normal saldırılarında ve Korkularından Beslen'de ek menzil elde eder.","img/abil/khazix-q.png",[4,4,4,4,4]],["Hiçlik Dikenleri","W","Kha'Zix, patlayarak isabet alan rakiplerin fiziksel hasar almalarına yol açan dikenler atar. Patlamanın menzili içindeyse Kha'Zix de iyileşir. Diken Dizisi Geliştirmeyi seçerse, Hiçlik Dikenleri koni biçiminde bir alana üç diken atar, isabet ettikleri rakipleri yavaşlatır ve rakip şampiyonları 2 saniyeliğine görünür kılar. Takım arkadaşlarından ayrı düşmüş rakipler fazladan yavaşlar.","img/abil/khazix-w.png",[9,9,9,9,9]],["Çullan","E","Kha'Zix bir alana zıplayarak indiği bölgeye fiziksel hasar verir. Kanat geliştirmeyi seçerse Çullan'ın menzili artar ve şampiyon katlettiğinde ya da asist yaptığında bekleme süresi sıfırlanır.","img/abil/khazix-e.png",[20,18,16,14,12]],["Hiçlik Saldırısı","R","Her yetenek seviyesi, Kha'Zix'in yeteneklerinden birini geliştirerek o yeteneğe ek bir özel etki kazandırmasını sağlar. Etkinleştirildiğinde, Kha'Zix görünmez hale gelerek Görünmez Tehdit'i tetikler ve hareket hızında artış elde eder. Kha'Zix, Aktif Gizlenme Geliştir'i seçerse Hiçlik Saldırısı'nın görünmezlik süresi artar ve yetenek bir kullanım daha kazanır.","img/abil/khazix-r.png",[100,85,70]]],"wk":"Kha'Zix","p":"img/champ/khazix.png","tip":[["Kısa mesafe içinde takım arkadaşı bulunmayan rakipler, tek başına kalmış sayılır. Bu hedeflere Korkularından Beslen ile saldırıldığında hasar epey artar.","Kha'Zix rakip tarafından görülemediğinde, Görünmez Tehdit devreye girer. Yeniden etkinleştirmek için çalılara gir ya da Hiçlik Saldırısı kullan. Rakip şampiyonlara normal saldırı yaparak Görünmez Tehdit açmayı unutma.","Kha'Zix nerede ve ne zaman dövüşeceğini seçmek konusunda oldukça özgürdür. Başarılı olmak için dövüşlerini dikkatli seç."],["Korkularından Beslen, yalnız yakaladığı hedeflere ek hasar verir. Dost minyonların, şampiyonların veya kulelerin yakınında dövüşerek avantaj elde et.","Çullan ve Hiçlik Saldırısı uzun bekleme sürelerine sahiptir. Bunlar kullanılabilir halde değilken Kha'Zix gayet savunmasızdır."]]},"kindred":{"id":"Kindred","k":203,"n":"Kindred","en":"Kindred","t":"Madalyonun İki Yüzü","cls":["Marksman"],"d":2,"res":"Mana","b":{"hp":595,"hpL":104,"ar":29,"arL":4.7,"mr":33,"mrL":1.1,"ad":65,"adL":3.25,"as":0.625,"asR":0.625,"asL":3.5,"rng":500,"ms":325,"t":"P"},"ab":[["Avcının Damgası","P","Kindred hedeflerini av için damgalayabilir. Av başarıyla tamamlandığında Kindred'ın temel yetenekleri kalıcı olarak güçlenir. Başarıyla tamamlanan her 4 av ayrıca Kindred'ın normal saldırı menzilini arttırır.","img/abil/kindred-p.png"],["Okların Dansı","Q","Kindred belli bir yöne atılır ve yakındaki hedeflere en fazla üç ok atışı yapar.","img/abil/kindred-q.png",[9,9,9,9,9]],["Kurdun Hiddeti","W","Kurt hiddete kapılır ve çevresindeki düşmanlara saldırır. Kuzu hareket ederek ve saldırarak pasif şekilde yük biriktirir. Yükler tamamen dolduğunda, Kuzu'nun bir sonraki saldırısı can yeniler.","img/abil/kindred-w.png",[18,17,16,15,14]],["Karabasan","E","Kuzu dikkatli bir atış yaparak hedefi yavaşlatır. Kuzu hedefe iki defa daha saldırı isabet ettirirse, üçüncü saldırısında Kurt hedefin üzerine çullanır ve hırpaladığı hedefe büyük miktarda hasar verir.","img/abil/kindred-e.png",[14,12.5,11,9.5,8]],["Kuzunun Şefkati","R","Kuzu, belli bir alandaki bütün canlıların ölümünü erteler. Etki sona erene kadar, canlıların hiçbiri ölemez. Sonunda, birimler iyileştirilir.","img/abil/kindred-r.png",[160,140,120]]],"wk":"Kindred","p":"img/champ/kindred.png","tip":[["Ormanda canavarlarla savaşırken saldırılar arasında hareket etmek hem hasardan kaçınmanı hem de Kurdun Hiddeti'nden daha fazla iyileştirme etkisi kazanmanı sağlar.","Hangi avların peşine düşeceğine dikkatli karar ver; olabildiğince çok hedef avlamak, oyunun ilerleyen safhalarında başarının sırrıdır.","Büyük takım çatışmalarına ilk girişen olma. Çatışmaları başlatmayı takım arkadaşlarına bırak."],["Kindred hassas bir şampiyondur. Üzerinde baskı kurarsan temkinli oynamaya mecbur kalır.","Kindred'in verdiği hasar miktarının hızla artmasını önlemek için, Kurt'un orman kamplarında başlattığı Avları temizle.","Kindred Kuzunun Şefkati kullandığı zaman etki alanına gir, bu yetenek bütün şampiyonları ölmekten korur."]]},"kled":{"id":"Kled","k":240,"n":"Kled","en":"Kled","t":"Deli Bozuk Süvari","cls":["Fighter"],"d":3,"res":"Cesaret","b":{"hp":410,"hpL":84,"ar":35,"arL":5.2,"mr":28,"mrL":2.05,"ad":65,"adL":3.5,"as":0.625,"asR":0.625,"asL":3.5,"rng":250,"ms":305,"t":"P"},"ab":[["Ödlek Kertenkele, Skaarl","P","Kled kendisinin yerine hasar alan güvenilir bineği Skaarl'ın tepesinde hareket eder. Skaarl'ın canı tükendiği zaman Kled yere iner. Bineksiz hâldeyken Kled'in yetenekleri değişir ve Deli Bozuk Süvari şampiyonlara daha az hasar verir. Kled rakipleriyle savaşarak Skaarl'ın cesaretini yenileyebilir. Azami cesarete ulaştığında Kled Skaarl'ın canının bir miktarıyla bineğinin sırtına atlar.","img/abil/kled-p.png"],["Ayı Oltası","Q","Kled bir rakip şampiyona hasar verip ona takılan bir ayı tuzağı atar. Hedefi kısa bir süre bağlı kalırsa fazladan fiziksel hasar alır ve Kled'e doğru çekilir. Kled bineğinden ayrı düştüğünde bu yeteneğin yerini Cep Piştovu alır. Cep Piştovu ile yapılan atış Kled'i geri savurur ve cesaret yeniler.","img/abil/kled-q.png",[11,10,9,8,7]],["Vahşet Sevdası","W","Kled dört saldırı boyunca muazzam bir saldırı hızı kazanır. Dördüncü saldırı fazladan hasar verir.","img/abil/kled-w.png",[13,12,11,10,9]],["Yardır","E","Kled fiziksel hasar verecek şekilde atılır ve kısa süreliğine hız artışı kazanır. Kled bu yeteneği yeniden kullanarak ilk hedefinin üzerinden tekrar atılıp ilk verdiği hasarı yeniden verebilir.","img/abil/kled-e.png",[13,12,11,10,9]],["Hücuuuuuuuum!!!!!","R","Kled ve Skaarl bir konuma hücum ederek arkalarında hız sağlayan bir iz bırakır ve bir kalkan kazanır. Skaarl karşılarına çıkan ilk rakip şampiyona kilitlenir ve ona çarpar.","img/abil/kled-r.png",[140,125,110]]],"wk":"Kled","p":"img/champ/kled.png","tip":[["Kled minyon biçerek bir miktar cesaret üretse de şampiyonlarla savaştığında bu miktar daha da artar.","Vahşet Sevdası'nın son vuruşu, diğer üç vuruştan daha fazla hasar verir; bu yüzden ıskalamamaya dikkat et!","Hücuuuuuuuum!!! çok uzak bir mesafeden kullanılabilir. Yanlarına ulaştığında rakiplerinin nerede olacağını tahmin etmeye çalış."],["Kled Cep Piştovu ve normal saldırılarıyla rakiplerine hasar vererek, minyon biçerek ve yapılar ya da destansı canavarlara saldırarak cesaret üretir.","Bineğinden indiği zaman Kled'in cesaret göstergesine dikkat et. Cesaret miktarı %100'e ulaştığında Kled yeniden bineğinin üstüne atlayıp büyük miktarda can kazanır.","Vahşet Sevdası hazır olduğunda Kled çok daha tehditkâr olur."]]},"kogmaw":{"id":"KogMaw","k":96,"n":"Kog'Maw","en":"Kog'Maw","t":"Cehennemin Dişleri","cls":["Marksman","Mage"],"d":2,"res":"Mana","b":{"hp":635,"hpL":99,"ar":24,"arL":4.45,"mr":33,"mrL":1.1,"ad":61,"adL":3.1,"as":0.665,"asR":0.665000021457672,"asL":2.65,"rng":500,"ms":330,"t":"P"},"ab":[["Icathia Sürprizi","P","Kog'Maw katledildikten 4 saniye sonra patlayarak çevresindeki rakiplere gerçek hasar verir.","img/abil/kogmaw-p.png"],["Ölümün Salyaları","Q","Kog'Maw büyü hasarı verdiği hedefin zırh ve büyü direncini kısa süreliğine düşüren, çürütme etkisine sahip bir salgı fırlatır. Ayrıca Kog'Maw ilave saldırı hızı kazanır.","img/abil/kogmaw-q.png",[7,7,7,7,7]],["Biyo-Büyü Salvosu","W","Kog'Maw'ın saldırılarının menzili artar ve %i:OnHit% isabet halinde hedefin azami can değerinin belirli bir oranına eşdeğer büyü hasarı verir.","img/abil/kogmaw-w.png",[17,17,17,17,17]],["Hiçlikten Sızan","E","Kog'Maw üstünden geçtiği rakiplere hasar veren ve üstünde duran rakipleri yavaşlatacak şekilde bir iz bırakan, tuhaf bir salya bırakır.","img/abil/kogmaw-e.png",[12,12,12,12,12]],["Canlı Havan","R","Kog'Maw çok uzun menzilli bir havan atışı yaparak büyü hasarı verir (bu hasar, Can miktarı düşük rakiplere karşı büyük ölçüde artar) ve gizli olanlar haricindeki hedeflerin görünür olmasını sağlar. Ayrıca kısa aralıklarla atılan birden fazla Canlı Havan, fazladan Manaya mal olur.","img/abil/kogmaw-r.png",[2,1.5,1]]],"wk":"Kog'Maw","p":"img/champ/kogmaw.png","tip":[["Kog'Maw Biyo-Büyü Salvosu yeteneğiyle çoğu şampiyonu uzaktan avlayabilir.","Hiçlikten Sızan'ı kusursuz bir Canlı Havan kurmak için kullan.","Icathia Sürprizi'ni en iyi şekilde kullan."],["Kog'Maw'ın iyi bir kaçış yeteneği yoktur, yani özellikle toplu saldırılara açıktır.","Kog'Maw öldükten sonra ondan kaç!!!!","Canlı Havan'ın menzili her seviyede artar.","Biyo-Büyü Salvosu Kog'Maw'ın Baron Nashor'u çok erken öldürmesini sağlar. Kog'Maw Mahvolmuş Kralın Kılıcı'nı tamamlarken Nashor'a totem yerleştirmek önemli olabilir."]]},"ksante":{"id":"KSante","k":897,"n":"K'Sante","en":"K'Sante","t":"Nazumah'nın Gururu","cls":["Tank","Fighter"],"d":3,"res":"Mana","b":{"hp":625,"hpL":120,"ar":36,"arL":5.2,"mr":30,"mrL":2.1,"ad":64,"adL":3.5,"as":0.688,"asR":0.625,"asL":2.5,"rng":150,"ms":330,"t":"P"},"ab":[["Cesur Yürek","P","K'Sante'nin yetenekleri, hedefleri işaretleyerek onların bir sonraki saldırısından daha fazla hasar almalarını sağlar. Hodri Meydan etkisindeyken K'Sante tüm saldırıları ve yetenekleriyle daha fazla hasar verir.","img/abil/ksante-p.png"],["Ntofo Darbeleri","Q","K'Sante kısa bir hat üstündeki rakiplere saldırarak hasar verir ve onları yavaşlatır. İsabet halinde bir Ntofo Darbeleri yükü kazanır. İki yük biriktiğinde K'Sante rakipleri çeken bir şok dalgası gönderir. Hodri Meydan etkisindeyken bekleme süresi azalır.","img/abil/ksante-q.png",[3.5,3.5,3.5,3.5,3.5]],["Yolaçan","W","K'Sante güç toplar, daha az hasar alır ve ardından atılarak rakipleri geri savurup sersemletir. Hodri Meydan etkisindeyken fazladan hasar verir ama hedefleri geri savurmaz veya sersemletmez.","img/abil/ksante-w.png",[14,13,12,11,10]],["Koşar Adım","E","K'Sante atılır ve bir kalkan kazanır. Bir takım arkadaşını hedef alırsa yeteneğin menzili artar ve K'Sante ona atıldığında ikisi de kalkan kazanır. Hodri Meydan etkisindeyken bekleme süresi azalır ve hızı artar.","img/abil/ksante-e.png",[10,9.5,9,8.5,8]],["Hodri Meydan","R","K'Sante bir rakibi geri savurur ve yoluna çıkan herhangi bir duvarın içinden fırlatır. Ardından K'Sante Hodri Meydan etkisine girer, rakibin peşinden atılır ve savunmasını azaltmanın karşılığında hasar ile iyileştirme artışı kazanıp yeteneklerini dönüştürür.","img/abil/ksante-r.png",[120,100,80]]],"wk":"K'Sante","p":"img/champ/ksante.png","tip":[["Ses Dalgası'nı Ejderhanın Gazabı'ndan önce kullan, böylece Titreşim Darbesi'yle hedefini kovalayabilirsin.","Yetenek kullandıktan sonra normal saldırı yaparak Artçı Rüzgâr'dan faydalan. Bu, hasarı en yükseğe çıkarır ve enerji kaybını da en aza indirir.","Koruma Güdüsü'nü kendi üstünde kullanman ve ardından Demir İrade'den faydalanman orman canavarlarını keserken epey işine yarar."],["Lee Sin'in ultisi Ejderha'nın Gazabı'nın etkisini en aza indirmek için takımca dağınık durun.","Lee Sin fiziksel hasar veren rakiplere karşı Demir İrade ve Sakatla gibi güçlü araçlara sahip olsa da büyü hasarına açıktır.","Lee Sin yeteneklerini art arda kullanmasına bel bağlar. Engelleyici yeteneklerini kullanarak Lee Sin'in zincirleme yetenekleri ve saldırılarını önle."]]},"leblanc":{"id":"Leblanc","k":7,"n":"LeBlanc","en":"LeBlanc","t":"Hilekâr","cls":["Assassin","Mage"],"d":3,"res":"Mana","b":{"hp":598,"hpL":108,"ar":22,"arL":4.2,"mr":30,"mrL":1.3,"ad":55,"adL":2.2,"as":0.658,"asR":0.625,"asL":1.5,"rng":525,"ms":340,"t":"M"},"ab":[["Ayna Görüntüsü","P","LeBlanc, azami canı %40'ın altına düştüğünde 1 saniyeliğine görünmez olarak hasar vermeyen ve 8 saniyeye kadar varlığını koruyabilen bir Ayna Görüntüsü oluşturur.","img/abil/leblanc-p.png"],["Şer Mührü","Q","LeBlanc bir mühür yansıtarak hasar verir ve hedefini 3,5 saniyeliğine işaretler. İşaretli hedefe bir yetenekle hasar vermek mührü patlatarak fazladan hasar uygular. Yeteneğin iki bölümünden biri hedefi katlederse mana bedelini ve kalan bekleme süresinin bir kısmını iade eder.","img/abil/leblanc-q.png",[6,6,6,6,6]],["Vurkaç","W","LeBlanc bir konuma atılarak hedefinin yakınlarındaki rakiplere hasar verir. Vurkaç, sonraki 4 saniye boyunca LeBlanc'ı başlangıç noktasına döndürmek için yeniden kullanılabilir.","img/abil/leblanc-w.png",[15,13.75,12.5,11.25,10]],["Hayali Zincir","E","LeBlanc, isabet ettiği ilk rakibi bağlayan bir zincir fırlatır. Hedef 1,5 saniye boyunca zincirli kalırsa LeBlanc tarafından yere sabitlenir ve fazladan hasar alır.","img/abil/leblanc-e.png",[14,13.25,12.5,11.75,11]],["Taklit","R","LeBlanc temel yeteneklerinden birinin taklit halini kullanır.","img/abil/leblanc-r.png",[45,35,25]]],"wk":"LeBlanc","p":"img/champ/leblanc.png","tip":[["Vurkaç, diğer büyülerle saldırırken güvenli bir yere kaçmana olanak sağlar.","Vurkaç'ı kullanmak, Hayali Zincir'i isabet ettirmene yardımcı olabilir.","Şer Mührü ile Hayali Zincir'i art arda kullanarak, ışınlanma özelliğine sahip karakterlerin kaçmasını 4 saniyeye kadar önleyebilirsin."],["LeBlanc ultisi sayesinde yetenek kullandığı sırada veya nadiren de olsa uzak bir noktada kendisinin sahtelerini ortaya çıkarabilir.","Uzakta ortaya çıkan sahte LeBlanc her zaman en yakın şampiyona doğru koşar, zararsız bir yetenek kullanır ve ardından hemen yok olur.","LeBlanc'a önce sen saldırırsan düzenbazlıklarının çoğundan, özellikle de atılmasına yarayan Vurkaç yeteneğinden sakınabilirsin.","LeBlanc'ı sersemletmek yada susturmak, Vurkaç yeteneğinin dönüş ayağını etkinleştirmesini engeller."]]},"leesin":{"id":"LeeSin","k":64,"n":"Lee Sin","en":"Lee Sin","t":"Kör Keşiş","cls":["Fighter","Assassin"],"d":2,"res":"Enerji","b":{"hp":645,"hpL":108,"ar":36,"arL":4.5,"mr":32,"mrL":2.05,"ad":66,"adL":3.4,"as":0.651,"asR":0.651000022888183,"asL":3,"rng":125,"ms":345,"t":"P"},"ab":[["Artçı Rüzgâr","P","Lee Sin'in bir yetenek kullandıktan sonraki 2 normal saldırısı, saldırı hızı kazandırır ve enerji iade eder.","img/abil/leesin-p.png"],["Ses Dalgası / Titreşim Darbesi","Q","Ses Dalgası: Lee Sin'in rakiplerinin yerini tespit etmek için yolladığı ses dalgası, çarptığı ilk rakibe fiziksel hasar verir. Ses Dalgası bir rakibe isabet ederse Lee Sin sonraki 3 saniye boyunca Titreşim Darbesi gerçekleştirebilir. Titreşim Darbesi: Lee Sin, Ses Dalgası'nın isabet ettiği rakibin üstüne atılıp rakibin eksik can miktarına bağlı olarak fiziksel hasar verir.","img/abil/leesin-q.png",[10,9,8,7,6]],["Koruma Güdüsü / Demir İrade","W","Koruma Güdüsü: Lee Sin hedef dost birime atılarak kalkan kazanır. Bu birim bir şampiyonsa o da kalkan kazanır. Lee Sin, Koruma Güdüsü'nü kullandıktan sonra Demir İrade'yi kullanabilir. Demir İrade: Lee Sin'in yoğun eğitimi, savaşta avantaj sağlar. Lee Sin mutlak sömürü kazanır.","img/abil/leesin-w.png",[8,8,8,8,8]],["Fırtına / Sakatla","E","Fırtına: Lee Sin yere vurarak büyü hasarı veren ve isabet ettiği rakip birimleri açığa çıkaran bir şok dalgası oluşturur. Fırtına bir rakibe isabet ederse Lee Sin, Sakatla yeteneğini kullanabilir. Sakatla: Lee Sin, Fırtına'dan hasar alan yakındaki rakipleri sakatlayarak onların hareket hızını azaltır. Hareket hızı, etki süresi boyunca yavaş yavaş normale döner.","img/abil/leesin-e.png",[8,8,8,8,8]],["Ejderhanın Gazabı","R","Lee Sin güçlü bir döner tekmeyle hedefini geri savururarak, hedefe ve çarptığı bütün rakiplere fiziksel hasar verir. Hedefin çarpıştığı hedefler de kısa süreliğine havaya savrulur. Lee Sin oyuncuları harita dışına tekmelemese de, bu tekniği Jesse Perring'den öğrenmiştir.","img/abil/leesin-r.png",[110,85,60]]],"wk":"Lee Sin","p":"img/champ/leesin.png","tip":[["Ses Dalgası'nı Ejderhanın Gazabı'ndan önce kullan, böylece Titreşim Darbesi'yle hedefini kovalayabilirsin.","Büyüler arasında geçiş yaparak Artçı Rüzgâr'ın avantajını kullan. Bu, hasarı en yükseğe çıkarır ve Enerji kaybını da en aza indirir.","Koruma Güdüsü'nü kendine yapmak ve Demir İrade'yi kullanmak, ormandaki tarafsız yaratıkları öldürmek için güçlü bir araçtır."],["Lee Sin'in ultisi Ejderha'nın Gazabı'nın etkisini en aza indirmek için dağınık durun.","Lee Sin, Demir İrade ve Sakatla gibi fiziksel hasarla savaşabilen, güçlü araçlara sahip olsa da, büyü hasarına açıktır.","Lee Sin büyük ölçüde yeteneklerini art arda kullanmasına bel bağlar. Engelleyici yeteneklerini kullanarak, yeteneklerini ve saldırılarını arka arkaya yapmasını engelle."]]},"leona":{"id":"Leona","k":89,"n":"Leona","en":"Leona","t":"Seher Işığı","cls":["Tank","Support"],"d":2,"res":"Mana","b":{"hp":646,"hpL":101,"ar":43,"arL":4.8,"mr":32,"mrL":2.05,"ad":60,"adL":3,"as":0.625,"asR":0.625,"asL":2.9,"rng":125,"ms":335,"t":"P"},"ab":[["Güneş Işığı","P","Hasar veren yetenekler 1,5 saniyeliğine hedefi Günışığı etkisine maruz bırakır. Leona'nın takım arkadaşları bu hedeflere hasar verdiğinde Günışığı'nı tüketerek fazladan büyü hasarı da verirler.","img/abil/leona-p.png"],["Şafak Kalkanı","Q","Leona bir sonraki normal saldırısında kalkanını kullanarak, fazladan büyü hasarı verir ve hedefi sersemletir.","img/abil/leona-q.png",[5,5,5,5,5]],["Tutulma","W","Leona kalkanını kaldırarak hasar azaltma, zırh ve büyü direnci kazanır. Yeteneğin süresi ilk sona erdiğinde yakında rakip varsa, Leona onlara büyü hasarı verir ve yeteneğin etki süresi uzar.","img/abil/leona-w.png",[14,13,12,11,10]],["Ufuk Kılıcı","E","Leona güneş ışığından kılıcının bir görüntüsünü yaratır ve düz bir hattaki bütün rakiplere büyü hasarı verir. Görüntü kaybolduğunda, darbe alan son rakip kısa süreliğine hareketsiz kalır ve Leona onun üstüne atılır.","img/abil/leona-e.png",[12,10.5,9,7.5,6]],["Güneş Patlaması","R","Leona güneş enerjisi yüklü bir ışın indirerek belli bir alandaki rakiplere hasar verir. Alanın ortasında kalan rakipler sersemlerken, dışında kalanlar yavaşlar.","img/abil/leona-r.png",[90,75,60]]],"wk":"Leona","p":"img/champ/leona.png","tip":[["Saldırıya önderlik et ve dostların hasar vermeye başlamadan önce rakipleri Günışığı ile işaretle.","Şafak Kalkanı ve Ufuk Kılıcı güçlü bir saldırı kombosu oluşturur.","Tutulma'yı kullanarak büyük ölçüde hasar emebilirsin ama daha fazla süreli etkili olabilmesi için rakiplerin yakınında durmak zorundasın."],["Leona, Tutulma'yı etkinleştirdiğinde, hasar görmeden uzaklaşman için üç saniyen var.","Yalnızca Güneş Patlaması'nın merkezinde olan rakipler sersemler; yani çabuk davranırsan bundan kurtulabilirsin."]]},"lillia":{"id":"Lillia","k":876,"n":"Lillia","en":"Lillia","t":"Narin Gonca","cls":["Fighter","Mage"],"d":3,"res":"Mana","b":{"hp":605,"hpL":105,"ar":24,"arL":4.5,"mr":32,"mrL":1.55,"ad":61,"adL":3.1,"as":0.625,"asR":0.625,"asL":2.7,"rng":325,"ms":330,"t":"M"},"ab":[["Düş Dalı","P","Bir şampiyona veya canavara yetenek isabet ettirmek, ona zamanla azami canına bağlı olarak fazladan hasar verir.","img/abil/lillia-p.png"],["Çiçek Açtıran","Q","Lillia yeteneklerini rakiplere isabet ettirdiğinde biriken bir hareket hızı ilavesi kazanır. Bunu etkinleştirerek yakınındaki rakiplere büyü hasarı verebilir. Alanın dış kısmındaki rakipler ilave gerçek hasar alır.","img/abil/lillia-q.png",[6,5.5,5,4.5,4]],["Dikkat Et! İik!","W","Lillia yakınındaki bir alana hasar verir. Alanın merkezindeki rakipler daha fazla hasar alır.","img/abil/lillia-w.png",[14,13,12,11,10]],["Dönertohum","E","Lillia isabet ettiği hedeflere hasar veren ve onları yavaşlatan bir tohum fırlatır. Eğer tohum hiçbir şeye isabet etmezse, bir duvara veya hedefe çarpana dek yuvarlanmaya devam eder.","img/abil/lillia-e.png",[12,12,12,12,12]],["Mışıl Mışıl","R","Lillia, Düş Tozu bulaşmış tüm rakipleri uyuşuk hale getirdikten sonra onları uyutur. Bu rakipler zorla uyandırıldığında ilave hasar alır.","img/abil/lillia-r.png",[150,130,110]]],"wk":"Lillia","p":"img/champ/lillia.png","tip":[[],[]]},"lissandra":{"id":"Lissandra","k":127,"n":"Lissandra","en":"Lissandra","t":"Buz Cadısı","cls":["Mage"],"d":2,"res":"Mana","b":{"hp":620,"hpL":110,"ar":22,"arL":4.2,"mr":30,"mrL":1.3,"ad":55,"adL":2.7,"as":0.656,"asR":0.625,"asL":1.5,"rng":550,"ms":325,"t":"M"},"ab":[["Buzdoğan İtaati","P","Lissandra'nın yakınında katledilen şampiyonlar Donmuş Köle'ye dönüşür. Donmuş Köleler yakındaki rakipleri yavaşlatır ve bir gecikmenin ardından aşırı soğuktan parçalanarak yakındaki hedeflere büyü hasarı verir.","img/abil/lissandra-p.png"],["Keskin Buz","Q","Attığı buzdan mızrak, isabet ettiğinde parçalanarak rakibin büyü hasarı almasına ve Hareket Hızı değerinin düşmesine yol açar. Parçalar hedefi delip geçerek, isabet alan diğer rakiplere aynı hasarı verir.","img/abil/lissandra-q.png",[7,6,5,4,3]],["Kırağı Çemberi","W","Yakındaki rakipleri dondurarak büyü hasarı verir ve onları sabitler.","img/abil/lissandra-w.png",[10,9.5,9,8.5,8]],["Buzul Pençe","E","Lissandra'nın oluşturduğu buzdan pençe büyü hasarı verir. Bu yeteneği tekrar etkinleştirmek, Lissandra'yı pençenin o anki konumuna taşır.","img/abil/lissandra-e.png",[24,21,18,15,12]],["Donmuş Mezar","R","Bir rakip şampiyon üzerinde kullanılırsa hedef donarak sersemler. Lissandra üzerinde kullanılırsa Lissandra kendini kara buz içine hapseder; bir yandan iyileşirken bir yandan da hedef alınamaz ve zarar görmez hale gelir. Kara buz hedeften fışkırarak rakiplerin büyü hasarı almalarına ve hareket hızı değerlerinin azalmasına yol açar.","img/abil/lissandra-r.png",[120,100,80]]],"wk":"Lissandra","p":"img/champ/lissandra.png","tip":[["Aynı anda kendi üzerinde gerçekleştirme ve ulti tuşuna (varsayılan alt+R) basarak, ultini kendi üzerinde anında kullanabilirsin.","Buzul Pençe'yi gerçekleştirmek ve ardından ters yöne kaçmak, rakiplerinin hangi yöne gideceğin konusunda şaşkınlığa düşmesine yol açar.","Lissandra'nın yetenekleri, pek çok büyücüye kıyasla daha kısa menzile sahiptir. Bundan ötürü, Zhonya'nın Kumsaati ve Banshee'nin Duvağı gibi hem yetenek gücü hem de savunma özelliği veren eşyalar, hayatta kalması ve hasar vermesi için çok yararlı olabilir."],["Lissandra'nın Buzul Pençe ile hareket etmesini önlemek için, yeteneği tekrar kullanmadan onu hareketsiz bırak.","Kırağı Çemberi'nin bekleme süresi, ilk kademelerde uzundur; hâlâ bekleme süresindeyken saldır.","Lissandra'nın Keskin Buz'u sadece isabet ettiği ilk birimi yavaşlatır. Lissandra'ya yaklaşırken takımının minyonlarının arkasında durarak yavaşlatılmaktan kurtulabilirsin."]]},"locke":{"id":"Locke","k":805,"n":"Locke","en":"Locke","t":"Kefaretin Külleri","cls":["Assassin","Mage"],"d":2,"res":"Mana","b":{"hp":620,"hpL":109,"ar":32,"arL":4.2,"mr":32,"mrL":2.05,"ad":58,"adL":3,"as":0.688,"asR":0.625,"asL":3.3,"rng":125,"ms":340,"t":"M"},"ab":[["Gümüş Kazık","P","Locke'un saldırıları isabet halinde rakibin eksik canına bağlı olarak artacak şekilde ilave büyü hasarı verir.","img/abil/locke-p.png"],["Ayin Çivisi","Q","Locke fırlatmak üzere bir dizi Ruh Çivisi hazırlar. Çiviler büyü hasarı verir ve isabet alan rakipleri işaretler. Locke işaretleri tüketerek saldırıyla ilave hasar verebilir.","img/abil/locke-q.png",[10,9,8,7,6]],["Ruh Yangını","W","Locke ruhunu tutuşturarak saldırı hızı ile hareket hızı kazanır ve kendine hasar verir. Sürenin sonunda Locke, etki boyunca aldığı hasarın bir kısmına eşdeğer miktarda can yeniler.","img/abil/locke-w.png",[18,17,16,15,14]],["Külgezen","E","Locke bir konuma ışınlanır ve ardından sıradaki hedefine saldırmak için atılarak deşip geçtiği rakiplere hasar verir.","img/abil/locke-e.png",[10,10,10,10,10]],["Araf","R","Locke, hasar veren ve isabet ettiği rakipleri infaz edebilen bir yadigâr fırlatır. Locke rakip şampiyonları mühürleyerek ilave güç kazanır.","img/abil/locke-r.png",[120,100,80]]],"wk":"Locke","p":"img/champ/locke.png","tip":[[],[]]},"lucian":{"id":"Lucian","k":236,"n":"Lucian","en":"Lucian","t":"İnfazcı","cls":["Marksman","Assassin"],"d":2,"res":"Mana","b":{"hp":641,"hpL":100,"ar":28,"arL":4.2,"mr":33,"mrL":1.1,"ad":60,"adL":2.9,"as":0.638,"asR":0.638000011444091,"asL":2.5,"rng":500,"ms":335,"t":"P"},"ab":[["Işık Silahşoru","P","Lucian bir yetenek kullandığında, sonraki saldırısı çift vuruş olur. Bir takım arkadaşından kalkan veya iyileştirme edindiğinde ya da yakınındaki bir rakip şampiyon hareketsiz bırakıldığında sonraki 2 normal saldırısıyla ilave büyü hasarı verir.","img/abil/lucian-p.png"],["Işık Atışı","Q","Lucian, hedefini delip geçen bir ışık huzmesi fırlatır.","img/abil/lucian-q.png",[9,8,7,6,5]],["İntikam Ateşi","W","Lucian'ın yaptığı atış, yıldız şeklinde bir patlama yaratarak rakipleri işaretler ve kısa süreliğine açığa çıkarır. Lucian işaretli rakiplere saldırdığında hareket hızı kazanır.","img/abil/lucian-w.png",[14,13,12,11,10]],["Amansız Takip","E","Lucian hızlıca atılarak kısa bir mesafeyi geçer. Işık Silahşoru saldırıları, Amansız Takip'in bekleme süresini azaltır.","img/abil/lucian-e.png",[16,15.5,15,14.5,14]],["İnfaz","R","Lucian, silahlarıyla bir saldırı yağmuru gerçekleştirir.","img/abil/lucian-r.png",[110,100,90]]],"wk":"Lucian","p":"img/champ/lucian.png","tip":[["Hasarı üst düzeye çıkarmak için, Amansız Takip'le Işık Atışı'nı birleştirmeye çalış.","İntikam Ateşi yıldız şeklinde patlar. Yıldızı, kenarları rakip şampiyonlara isabet edecek şekilde hizalamaya çalış.","İnfaz için bir açı seçtiğinde, değiştiremezsin. O yüzden doğru anı kolla!","Lucian, Işık Silahşoru sayesinde Saldırı Gücü'nden, Saldırı Hızı'ndan yararlandığından daha fazla yararlanır."],["Lucian'ın ani hasarı güçlüdür; ama sürekli hasarı azdır.","Lucian İnfaz yeteneğinin hedefini değiştiremez. Atış doğrultusundan kaçarak bundan yararlan.","Işık Atışı, Lucian'a fazladan Saldırı Menzili kazandırmaz. Lucian'ın atışını hizalamak için bir hedef bulması gerekir. Lucian'ın seçeceği açıyı tahmin ederek Işık Atışı'ndan kaçın."]]},"lulu":{"id":"Lulu","k":117,"n":"Lulu","en":"Lulu","t":"Peri Sihirbaz","cls":["Support","Mage"],"d":2,"res":"Mana","b":{"hp":565,"hpL":92,"ar":26,"arL":4.6,"mr":30,"mrL":1.3,"ad":47,"adL":2.6,"as":0.625,"asR":0.625,"asL":2.25,"rng":550,"ms":330,"t":"M"},"ab":[["Peri Yoldaş, Pix","P","Takip ettiği şampiyon her rakip birime saldırdığında, Pix de enerji yüklü büyülü oklar atar. Bu oklar güdümlüdür ama başka birimler tarafından önlerine geçilebilir.","img/abil/lulu-p.png"],["Işıltılı Ok","Q","Pix ve Lulu isabet ettiği bütün rakiplere hasar veren ve onları büyük ölçüde yavaşlatan büyü enerjisi yüklü birer ok gönderir.","img/abil/lulu-q.png",[7,7,7,7,7]],["Kapris","W","Bir takım arkadaşı hedef seçilirse, ona kısa süreliğine Saldırı Hızı ve Hareket Hızı kazandırır. Bir rakip hedef seçilirse, onu saldıramayan ya da yetenek ve büyü kullanamayan sevimli bir yaratığa çevirir.","img/abil/lulu-w.png",[18,18,18,18,18]],["Yetiş, Pix!","E","Bir takım arkadaşı hedef seçilirse, Pix'e bu takım arkadaşına kalkan olmasını emreder. Ardından Pix bu takım arkadaşını takip ederek, saldırılarına destek olur. Bir rakibin hedef seçilmesi halinde, Pix'e rakibin üstüne atlayarak hasar vermesini emreder. Ardından, Pix bu rakibi takip ederek, gözden kaybolmamasını sağlar.","img/abil/lulu-e.png",[10,9.5,9,8.5,8]],["Vahşi Büyüme","R","Lulu, bir takım arkadaşının boyutlarını büyütürek büyük miktarda ilave can kazanmasına ve yakındaki rakiplerin havaya savrulmalarına yol açar. Sonraki birkaç saniye boyunca, Lulu'nun takım arkadaşı yakındaki rakipleri yavaşlatan bir hareye sahip olur.","img/abil/lulu-r.png",[120,100,80]]],"wk":"Lulu","p":"img/champ/lulu.png","tip":[["Işıltılı Ok, imlecinin nerede durduğuna bağlı olarak değişik açılardan ateşlenebilir. İmlecini Pix ve Lulu'ya yaklaştırmak etki alanını belirgin ölçüde değiştirecektir.","Yetiş, Pix'i menzilli saldırganlara yaparak Pix takviyesi, Vahşi Büyüme'yi Tanklara ya da Dövüşçülere yaparak ilave başlangıç gücü elde edebilirsin."],["Lulu'nun perisinden gelen atışlar engellenebilir. Fazladan Peri saldırılarından kurtulmak için minyonların arkasına saklan.","Rakipleri meşgulken Lulu üstünlük kazanır, ona bu şansı verme! Aman vermeyen ağır taktiklerle Lulu'yu ve dostunu koridor dışına çıkmaya zorla."]]},"lux":{"id":"Lux","k":99,"n":"Lux","en":"Lux","t":"Işık Leydisi","cls":["Mage","Support"],"d":2,"res":"Mana","b":{"hp":580,"hpL":99,"ar":21,"arL":5.2,"mr":30,"mrL":1.3,"ad":54,"adL":3.3,"as":0.669,"asR":0.625,"asL":3,"rng":550,"ms":330,"t":"M"},"ab":[["Aydınlanma","P","Lux'ın hasar veren yetenekleri birkaç saniyeliğine hedefi enerjiyle yükler. Lux'ın bir sonraki saldırısı enerjiyi ateşler ve (Lux'ın seviyesine bağlı olarak) ilave büyü hasarı verir.","img/abil/lux-p.png"],["Işık Bağı","Q","Lux en fazla iki rakip birimini bağlayan ve onlara hasar veren bir ışık küresi gönderir.","img/abil/lux-q.png",[10,10,10,10,10]],["Prizmatik Bariyer","W","Lux değneğini fırlatır ve dokunduğu bütün dost hedeflerin etrafındaki ışığı bükerek, onların rakip hasarından korunmalarını sağlar.","img/abil/lux-w.png",[12,11.5,11,10.5,10]],["Işık Patlaması","E","Belli bir bölgeye, yakındaki rakipleri yavaşlatan tuhaf bir ışık gönderir. Lux ışığın patlamasını sağlayarak etki alanındaki rakiplere hasar verebilir.","img/abil/lux-e.png",[10,9.5,9,8.5,8]],["Son Parıltı","R","Lux enerji topladıktan sonra, etki alanında yakalanan bütün rakiplere hasar veren bir ışık huzmesi yollar. Bu, ayrıca Lux'ın pasif yeteneğini de tetikleyerek Aydınlanma dezavantajının süresini de yeniler.","img/abil/lux-r.png",[60,50,40]]],"wk":"Lux","p":"img/champ/lux.png","tip":[["Lux'ın çok iyi alan kontrol yetenekleri vardır. Işık Patlaması'nı bir rakibin kaçmasını ya da üstüne gelmesini önlemek için kullanmayı dene.","Prizmatik Bariyer'i tutturmakta zorluk çekiyorsan, en uzak menzile gittikten sonra sana geri döndüğünü unutma. Dönüşünde dostlarını vurabilmek için durduğun yeri iyi seçmeye çalış.","Işık Patlaması müthiş bir keşif aracıdır. Pusu kontrolü için çalılığa girmeden önce Işık Patlaması'nı çalılığa fırlatmayı dene."],["Lux güçlü alan kontrol yeteneklerine sahiptir. Dağılıp farklı yönlerden saldır; böylece belirli bir alana kilitlenemez.","Düşük can değeriyle geri çekilirken Lux'ın Son Parıltı'sını savuşturmaya hazır ol. Ana ışından önce kırmızı bir hedefleme ışını ateşlenir; mümkünse yana kaçmaya çalış."]]},"malphite":{"id":"Malphite","k":54,"n":"Malphite","en":"Malphite","t":"Yektaş'tan Kopan Parça","cls":["Tank","Mage"],"d":1,"res":"Mana","b":{"hp":665,"hpL":104,"ar":40,"arL":4.95,"mr":28,"mrL":2.05,"ad":62,"adL":4,"as":0.736,"asR":0.638000011444091,"asL":3.4,"rng":125,"ms":335,"t":"M"},"ab":[["Granit Kalkan","P","Malphite azami canının en fazla %10'una eşdeğer miktarda hasar soğuran bir kaya katmanıyla korunur. Malphite birkaç saniye boyunca hasar almazsa, bu etki yenilenir.","img/abil/malphite-p.png"],["Sismik Parça","Q","Malphite rakibine yerden bir kaya parçası gönderir. Parça rakibe çarptığında hasar vererek 3 saniye boyunca hedeften hareket hızı çalar.","img/abil/malphite-q.png",[8,8,8,8,8]],["Gök Gürültüsü","W","Malphite'ın gerçekleştirdiği muazzam saldırı bir ses patlamasına sebep olur. Sonraki birkaç saniye boyunca gerçekleştirdiği saldırılar, şampiyonun önünde artçı şoklar gerçekleştirir.","img/abil/malphite-w.png",[10,9.5,9,8.5,8]],["Yeri Sars","E","Malphite'ın yere vurarak gönderdiği şok dalgası, zırhına eşdeğer miktarda büyü hasarı verir ve rakiplerin saldırı hızını kısa süreliğine azaltır.","img/abil/malphite-e.png",[7,7,7,7,7]],["Önlenemez Güç","R","Malphite belli bir konuma yüksek hızla hücum ederek rakiplere hasar verir ve onları havaya savurur.","img/abil/malphite-r.png",[130,115,100]]],"wk":"Malphite","p":"img/champ/malphite.png","tip":[["Zırh, Granit Kalkan'ın içinden geçen saldırıların oranını doğal olarak azaltır, böylece Gaddar Darbe kalkanı fiziksel hasara karşı güçlendirir.","Zırh'ı arttırabilceği yeteneklerinden başka, bazı oyunlar Malphite'ın Büyü Direnci kazanmasını gerektirir. Böyle oyunlar olduğunda Ordu Kalkanı, Merkür'ün Adımları ve Koruyucu Melek almayı dene."],["Fiziksel hasara dayalı bir karaktersen, Malphite'la dövüşürken dostlarının arkasında kal. Yeri Sars, vereceğin hasar potansiyelini büyük ölçüde azaltabilir.","Malphite ormancılık yapabilen birkaç tanktan biridir. Çarp'ı alırsa dikkat et."]]},"malzahar":{"id":"Malzahar","k":90,"n":"Malzahar","en":"Malzahar","t":"Hiçlik'in Habercisi","cls":["Mage"],"d":2,"res":"Mana","b":{"hp":580,"hpL":101,"ar":18,"arL":4.7,"mr":30,"mrL":1.3,"ad":55,"adL":3,"as":0.625,"asR":0.625,"asL":1.5,"rng":500,"ms":335,"t":"M"},"ab":[["Hiçlik Geçişi","P","Malzahar bir süre hasar almaz veya kitle kontrolü altına girmezse, büyük oranda hasar azaltma kazanır ve kitle kontrolünden etkilenmez. Hasar aldıktan veya bir kitle kontrol etkisini engelledikten sonra, kısa süre daha bu avantajı korur.","img/abil/malzahar-p.png"],["Hiçlik'in Çağrısı","Q","Malzahar Hiçlik'e açılan iki geçit oluşturur. Kısa bir aradan sonra geçitler büyü hasarı veren ve rakip şampiyonları susturan atışlar yapar.","img/abil/malzahar-q.png",[6,6,6,6,6]],["Hiçlik Sürüsü","W","Malzahar, yakındaki rakiplere saldıran Hiçlik Haşereleri çağırır.","img/abil/malzahar-w.png",[8,8,8,8,8]],["Lanetli Kehanet","E","Malzahar hedefinin zihninde, uğrayacağı felaketi gösteren korkunç kehanetler canlandırır ve hedefin zamanla hasar almasını sağlar. Malzahar hedef üzerinde diğer yeteneklerini kullandığında kehanetler yenilenir. Hedef, kehanetlerin etkisi altındayken katledilirse, kehanetler yakındaki bir başka rakip birime geçer ve Malzahar'a mana kazandırır. Malzahar'ın Hiçlik Haşereleri, kehanetlerin etkisi altındaki birimleri kovalar.","img/abil/malzahar-e.png",[11,10,9,8,7]],["Ölümün Pençesi","R","Malzahar Hiçlik'in özünü, hasar veren bir negatif enerji alanında yoğunlaştırarak rakip şampiyonu sindirir.","img/abil/malzahar-r.png",[140,110,80]]],"wk":"Malzahar","p":"img/champ/malzahar.png","tip":[["Hiçlik Sürüsü yeteneğini kullanmadan önce yakınlarında Hiçlik Haşeresi'nin saldırabileceği veya katledebileceği rakipler bulunduğundan emin ol.","Hiçlik'in Çağrısı ve Ölümün Pençesi yeteneklerini, rakiplerin üzerindeki Lanetli Kehanet süresini arttırmak için kullan.","Koridordayken hasar almaktan kaçınmak, Hiçlik Geçişi'nin etkin olduğu süreyi en üst düzeye çıkararak Malzahar'ın daha güvende olmasını sağlar."],["Malzahar, Lanetli Kehanet etkisi altındaki rakiplerine büyü isabet ettirdiğinde kehanetler yenilenir.","Lanetli Kehanet etkisi altındaki minyon dalgalarından uzak durmaya çalış. Ne zaman katledilip kehanetleri sana bulaştıracakları belli olmaz.","Malzahar, Hiçlik Sürüsü'nü büyüttüğünde özellikle tehlikeli olur."]]},"maokai":{"id":"Maokai","k":57,"n":"Maokai","en":"Maokai","t":"Çarpık Treant","cls":["Tank","Support"],"d":1,"res":"Mana","b":{"hp":665,"hpL":109,"ar":35,"arL":5.2,"mr":32,"mrL":2.05,"ad":64,"adL":3.3,"as":0.8,"asR":0.694999992847442,"asL":2.125,"rng":125,"ms":335,"t":"M"},"ab":[["Öz Büyüsü","P","Maokai'nin normal saldırısı onu orta karar bir bekleme süresiyle iyileştirir ve rakiplere fazladan hasar verir. Maokai her yetenek kullandığında ya da bir yetenekten isabet aldığında bu bekleme süresi azalır.","img/abil/maokai-p.png"],["Diken Vuruşu","Q","Maokai bir şok dalgasıyla yakındaki rakiplere büyü hasarı verir ve onları geri savurarak yavaşlatır.","img/abil/maokai-q.png",[7,6.5,6,5.5,5]],["Uğursuz İlerleyiş","W","Maokai bir kök öbeğine dönüşerek hedef alınamaz hale gelir ve hedefe doğru atılır. Vardığında hedefini yerine sabitler.","img/abil/maokai-w.png",[14,13,12,11,10]],["Fide Atışı","E","Maokai hedef bölgeyi gözetmesi için bir fide gönderir. Fideler çalıda daha etkili olur.","img/abil/maokai-e.png",[18,17,16,15,14]],["Doğanın Hükmü","R","Maokai yavaş yavaş ilerleyip önüne çıkan rakipleri yerine sabitleyerek onlara hasar veren, diken ve köklerden oluşan devasa bir duvar ortaya çıkarır.","img/abil/maokai-r.png",[130,110,90]]],"wk":"Maokai","p":"img/champ/maokai.png","tip":[["Fideler çalıya atıldıklarında etkileri artar ama fazla birikmezler.","Doğanın Hükmü'nden kaçmanın çok zor olacağı ya da rakiplerin bu yeteneğe gafil avlanacağı yandan hamlelere odaklan.","Maokai'nin pasifi, bir şeylere saldırabildiği sürece kendisi üzerine odaklanan yeteneklere karşı olağanüstü dayanıklı olmasını sağlar."],["Fideler kendilerine fazla yaklaşan ilk rakibin peşine düşer ve birkaç saniye sonra ya da başka rakiplerle çarpıştıklarında patlar. Çalıdaki fidelerin yakınlarında özellikle dikkatli ol çünkü çalıdaki fideler çok daha tehlikeli olur.","Maokai'nin kendisini iyileştirme etkisinin bekleme süresi, yeteneklerini ona kaç defa isabet ettirdiğine bağlı olarak büyük oranda değişir. Ona karşı boş yere yetenek kullanmamaya dikkat et.","Maokai Uğursuz İlerleyiş'i kullanırken hasardan etkilenmez, o yüzden yeteneklerini hiç boşa harcama."]]},"masteryi":{"id":"MasterYi","k":11,"n":"Master Yi","en":"Master Yi","t":"Wuju Üstadı","cls":["Fighter","Assassin"],"d":2,"res":"Mana","b":{"hp":640,"hpL":105,"ar":33,"arL":5,"mr":32,"mrL":2.05,"ad":65,"adL":2.5,"as":0.679,"asR":0.67900002002716,"asL":2.5,"rng":175,"ms":355,"t":"P"},"ab":[["Çift Saldırı","P","Master Yi art arda gerçekleştirdiği her birkaç normal saldırıda bir iki kere vurur.","img/abil/masteryi-p.png"],["Alfa Vuruşu","Q","Master Yi savaş alanına gözle görülmeyecek bir hızla ışınlanarak, yoluna çıkan birden fazla birime fiziksel hasar verir ve bu esnada hedef alınamaz hale gelir. Alfa Vuruşu kritik vuruş gerçekleştirebilir ve canavarlara ilave fiziksel hasar verir. Normal saldırılar Alfa Vuruşu'nun bekleme süresini azaltır.","img/abil/masteryi-q.png",[20,19.5,19,18.5,18]],["Meditasyon","W","Master Yi zihnen odaklanarak bedenini dinçleştirir ve can yenilerken, kısa süreliğine daha az hasar alır. Ayrıca Master Yi, Çift Saldırı yükleri biriktirirken odaklandığı her saniye Wuju Stili ile Gözükara'nın kalan sürelerini duraklatır.","img/abil/masteryi-w.png",[10,10,10,10,10]],["Wuju Stili","E","Normal saldırılara ilave gerçek hasar ekler.","img/abil/masteryi-e.png",[14,14,14,14,14]],["Gözükara","R","Master Yi eşi benzeri olmayan bir çevikliğe kavuşur. Hareket ve saldırı hızını geçici olarak arttırır ve tüm yavaşlatma etkilerine karşı bağışıklık kazanır. Yetenek etkinken şampiyon katletmek veya asist almak Gözükara'nın süresini uzatır. Katletme veya asist halinde diğer yeteneklerinin bekleme süresini pasif olarak azaltır.","img/abil/masteryi-r.png",[85,85,85]]],"wk":"Master Yi","p":"img/champ/masteryi.png","tip":[["Menzilli bir karakterle aynı koridordaysan, Meditasyon'un kademesini arttırmak koridorda onlardan daha fazla kalmanı ve daha hızlı seviye atlamanı sağlar.","Wuju Stili oyunun başlarında minyonlara son vuruşu yapmakta çok güçlüdür.","Alfa Vuruşu'yla rakip şampiyonunun önündeki bir minyonu hedeflemeyi dene; böylece büyünün sonunda güvenli bir mesafede olmuş olursun."],["Meditasyon zaman içerisinde alınan hasarı iyileştirmek için etkili bir yöntemdir ama Master Yi oyunun başında koordineli takım baskınlarına karşı savunmasızdır.","Master Yi, Alfa Vuruşu ile minyon biçmeye kalkıştığında ona birkaç kere vur, böylece Meditasyon'la iyileşmek için mana kullanmak zorunda kalacaktır.","Master Yi, Gözükara'yı kullanırken yavaşlatılamaz, ancak diğer zayıflatma etkileri onu durdurabilir."]]},"mel":{"id":"Mel","k":800,"n":"Mel","en":"Mel","t":"Ruhun Yansıması","cls":["Mage","Support"],"d":2,"res":"Mana","b":{"hp":590,"hpL":107,"ar":21,"arL":5.4,"mr":30,"mrL":1.3,"ad":52,"adL":3.3,"as":0.625,"asR":0.625,"asL":2.75,"rng":550,"ms":330,"t":"M"},"ab":[["Parlak Zekâ","P","Mel her yetenek kullandığında bir sonraki saldırısı için üç ilave atış kazanır. En fazla dokuz atış biriktirebilir. Mel bir yetenek veya saldırıyla hasar verdiğinde sınırsız kez birikecek şekilde Baskı yükü uygular. Mel rakibe yeteri kadar Baskı hasarı verirse yükler tüketilerek hedef infaz edilir.","img/abil/mel-p.png"],["Pırıltılı Salvo","Q","Mel, büyü hasarı veren bir atış salvosu gönderir. Bir rakip şampiyona isabet ettirmek bu yeteneğin bekleme süresini azaltır.","img/abil/mel-q.png",[10,9,8,7,6]],["Ret","W","Mel, çarpıştığı rakip atışlarını yok eden ve karşılığında büyü atışları gönderen bir kırılma novası oluşturur. Nova ayrıca Mel ve takım arkadaşlarına kalkan ve hareket hızı sağlar.","img/abil/mel-w.png",[30,28.5,27,25.5,24]],["Güneş Kapanı","E","Mel ileriye parıldayan bir küre gönderir. Kürenin merkezinde kalan rakipler sabitlenirken etrafındaki alanda yer alanlar yavaşlar ve zamanla hasar alır.","img/abil/mel-e.png",[11,10.5,10,9.5,9]],["Altın Tutulma","R","Mel, Baskı yüküyle işaretlenmiş tüm rakiplere kendisine olan mesafeleri fark etmeksizin saldırır ve Baskı yükü başına fazladan hasar verir. Altın Tutulma'nın her bir seviyesi Baskı'nın hasarını arttırır.","img/abil/mel-r.png",[120,90,60]]],"wk":"Mel","p":"img/champ/mel.png","tip":[["Mel, güçlü yetenekler de dahil rakip atışlarını yok edebilir. Ona güçlü atışlar göndermek için Ret yeteneğini kullanmasını bekle.","Mel yetenek veya saldırı isabet ettirdikçe daha fazla Baskı yükü uygular. Canın fazla azalırsa bir sonraki saldırısı seni katledeceği için birkaç saniyeliğine geri çekil ve Baskı yüklerinin süresinin bitmesini bekle."],["Mel, güçlü yetenekler de dahil rakip atışlarını yok edebilir. Ona güçlü atışlar göndermek için Ret yeteneğini kullanmasını bekle.","Mel yetenek veya saldırı isabet ettirdikçe daha fazla Baskı yükü uygular. Canın fazla azalırsa bir sonraki saldırısı seni katledeceği için birkaç saniyeliğine geri çekil ve Baskı yüklerinin süresinin bitmesini bekle."]]},"milio":{"id":"Milio","k":902,"n":"Milio","en":"Milio","t":"Alevin Şefkati","cls":["Support","Mage"],"d":2,"res":"Mana","b":{"hp":560,"hpL":88,"ar":26,"arL":4.6,"mr":30,"mrL":1.3,"ad":48,"adL":3.2,"as":0.625,"asR":0.625,"asL":3,"rng":525,"ms":330,"t":"M"},"ab":[["Ateş Parçası!","P","Milio'nun yetenekleri temas ettiği takım arkadaşlarını efsunlayarak onların bir sonraki hasar veren saldırılarının ilave anlık hasar vermesini ve hedefi yakmasını sağlar.","img/abil/milio-p.png"],["Süper Güçlü Ateş Şutu","Q","Milio bir topu tekmeleyerek rakibini geri savurur. Top hedefine isabet ettikten sonra havaya yükselir ve rakibe doğru yere düşer. Topun etki alanındaki rakipler hasar alır ve yavaşlar.","img/abil/milio-q.png",[10,10,10,10,10]],["Sıcacık Kamp Ateşi","W","Milio takım arkadaşlarını iyileştiren ve onların saldırı menzilini arttıran bir güçlendirme alanı oluşturur. Alan, kullanım noktasına en yakın takım arkadaşını takip eder.","img/abil/milio-w.png",[29,27,25,23,21]],["Kor Kucak","E","Milio bir takım arkadaşına kalkan vererek ona geçici olarak hareket hızı kazandırır. Bu yetenek 2 yüke sahiptir.","img/abil/milio-e.png",[0.5,0.5,0.5,0.5,0.5]],["Hayat Alevi","R","Milio yaraları saran bir alev dalgası göndererek menzildeki takım arkadaşlarını iyileştirir ve onların üstlerindeki kitle kontrolü etkilerini kaldırır.","img/abil/milio-r.png",[160,145,130]]],"wk":"Milio","p":"img/champ/milio.png","tip":[["Milio elinin altındaki araçlardan en iyi şekilde yararlanmak için çevresinde takım arkadaşlarının olmasına ihtiyaç duyar.","Milio'nun atılma hızı, hareket hızına bağlı olarak artar. Fazladan hızını rakiplerini şaşırtmakta kullan!","Eğlendikten sonra tehlike olsa kaç yazar?"],["Milio'nun hareket yetenekleri, ikilinin nereye gideceğini önceden belirler. Bundan faydalanmaya çalış.","Çabuk kitle kontrolü uygulayabilen şampiyonlar Milio'ya karşı son derece başarılı olur.","Milio çevresinde takım arkadaşı olmadan yakalandığında hareket becerisinden büyük oranda mahrum kalır. Onu yalnız yakalamaya çalış."]]},"missfortune":{"id":"MissFortune","k":21,"n":"Miss Fortune","en":"Miss Fortune","t":"Ödül Avcısı","cls":["Marksman","Mage"],"d":1,"res":"Mana","b":{"hp":625,"hpL":100,"ar":25,"arL":4,"mr":33,"mrL":1.1,"ad":55,"adL":2.4,"as":0.656,"asR":0.656000018119812,"asL":3,"rng":550,"ms":325,"t":"P"},"ab":[["Şıpsevdi","P","Miss Fortune her yeni rakibe normal saldırı yaptığında ilave fiziksel hasar verir.","img/abil/missfortune-p.png"],["Çifte Vuruş","Q","Miss Fortune'un rakibine yaptığı atış hem rakibe, hem de rakibin arkasındaki bir hedefe hasar verir. İki isabet de Şıpsevdi etkisi ortaya çıkarabilir.","img/abil/missfortune-q.png",[7,6,5,4,3]],["Caka","W","Miss Fortune saldırıya uğramadığı sürece pasif olarak hareket hızı kazanır. Bu yetenek etkinleştirildiğinde kısa süreliğine ilave saldırı hızı sağlar. Bekleme süresindeyken yapılan Şıpsevdi kullanımları, Caka'nın kalan bekleme süresini azaltır.","img/abil/missfortune-w.png",[12,12,12,12,12]],["Kurşun Yağmuru","E","Miss Fortune kurşun yağdırdığı belli bir alanı açığa çıkarır, rakiplerine dalga dalga hasar verir ve onları yavaşlatır.","img/abil/missfortune-e.png",[18,17,16,15,14]],["Mermi Manyağı","R","Miss Fortune, ilerledikçe genişleyen bir yaylım ateşine başlar ve rakiplerine büyük miktarda hasar verir. Her Mermi Manyağı dalgası kritik vuruş yapabilir.","img/abil/missfortune-r.png",[120,110,100]]],"wk":"Miss Fortune","p":"img/champ/missfortune.png","tip":[["Miss Fortune'un hızı, yakınlarda hasar almadıysa artar. Çok hızlı ilerlemek için isabet almamaya çalış.","Rakip şampiyonlar geride saklanıyorsa, Çifte Vuruş'u en uzaktaki rakip minyon üzerinde kullan; onlara doğru sekerek çok fazla hasar verecektir.","Caka bekleme süresindeyken aktifi en verimli şekilde kullanabilmek için Şıpsevdi'den faydalanmayı unutma."],["Miss Fortune'nun hız takviyesi, bir rakipten hasar aldığında ortadan kalkar.","Miss Fortune'a ulaşabilirsen katletmesi kolaydır; takım savaşlarında öncelikle onu hedef al."]]},"monkeyking":{"id":"MonkeyKing","k":62,"n":"Wukong","en":"Wukong","t":"Maymun Kral","cls":["Fighter","Tank"],"d":1,"res":"Mana","b":{"hp":610,"hpL":99,"ar":31,"arL":4.7,"mr":28,"mrL":2.05,"ad":66,"adL":3.5,"as":0.69,"asR":0.657999992370605,"asL":3,"rng":175,"ms":340,"t":"P"},"ab":[["Taş Deri","P","Wukong şampiyonlar ve canavarlara karşı savaşırken birikebilen zırh ve azami can yenilenmesi kazanır.","img/abil/monkeyking-p.png"],["Yıkıcı Vuruş","Q","Wukong'un bir sonraki saldırısı fazladan menzil kazanır, ilave hasar verir ve birkaç saniyeliğine hedefin zırhını azaltır.","img/abil/monkeyking-q.png",[8,7.5,7,6.5,6]],["Oyunbaz Savaşçı","W","Wukong görünmez olup belli bir yöne atılarak yakınındaki rakiplere saldıran bir kopya bırakır.","img/abil/monkeyking-w.png",[22,21,20,19,18]],["Bulut Saldırısı","E","Wukong hedef rakibin üstüne atılır ve hedefin yanındaki rakiplere saldırarak isabet alan rakiplerin her birine hasar veren yansımalar ortaya çıkarır.","img/abil/monkeyking-e.png",[10,9.25,8.5,7.75,7]],["Burgaç","R","Wukong sopasını uzatıp çevirerek hareket hızı kazanır. İsabet alan rakipler hasar alır ve havaya savrulur.","img/abil/monkeyking-r.png",[130,110,90]]],"wk":"Wukong","p":"img/champ/monkeyking.png","tip":[["Rakibine çabucak saldırıp kendisine gelemeden oradan kaçabilmek için Yem ve Bulut Saldırısı beraber iyi iş görür.","Yem'i çalılığa yakın bir yerde kullanmayı dene, böylece rakip hareketine daha fazla tepki verecektir."],["Wukong genellikle Bulut Saldırısı'ndan sonra Yem'i kullanacaktır. Gerçek Wukong'a vurduğundan emin olmak için, kısa süreliğine yeteneklerini kullanmayı ertelemeye çalış.","Etrafı rakipleri tarafından sarıldığında Wukong'u öldürmek zorlaşır. Avantaj sağlamak için tek başına yakalamaya çalış."]]},"mordekaiser":{"id":"Mordekaiser","k":82,"n":"Mordekaiser","en":"Mordekaiser","t":"Demir Hortlak","cls":["Fighter","Mage"],"d":2,"res":"Kalkan","b":{"hp":645,"hpL":104,"ar":37,"arL":4.2,"mr":32,"mrL":2.05,"ad":61,"adL":4,"as":0.625,"asR":0.625,"asL":1,"rng":175,"ms":335,"t":"M"},"ab":[["Karanlık Azap","P","Mordekaiser şampiyonlara veya canavarlara 3 saldırı veya yetenek isabet ettirmesinin ardından güçlü bir hasar haresi ve hareket hızı kazanır.","img/abil/mordekaiser-p.png"],["Mahvet","Q","Mordekaiser gürzüyle yere bir darbe indirerek isabet alan rakiplere hasar verir. Yetenek tek bir rakibe isabet ettiğinde hasar artar.","img/abil/mordekaiser-q.png",[8,7,6,5,4]],["Yıkılmaz","W","Mordekaiser bir kalkan oluşturmak için verdiği ve aldığı hasarı biriktirir. İyileşmek için kalkanı tüketebilir.","img/abil/mordekaiser-w.png",[12,11,10,9,8]],["Ecelin Eli","E","Mordekaiser bir alandaki bütün rakipleri çeker.","img/abil/mordekaiser-e.png",[16,14,12,10,8]],["Ölüler Âlemi","R","Mordekaiser kurbanını farklı bir boyuta sürükleyerek niteliklerinin bir bölümünü çalar. Eğer kurbanını katlederse, hedef yeniden doğana kadar nitelikleri korur.","img/abil/mordekaiser-r.png",[120,110,100]]],"wk":"Mordekaiser","p":"img/champ/mordekaiser.png","tip":[["Senin için savunma, saldırı üstüne kurulu. Daha güçlü Yıkılmaz kalkanları oluşturmak için savaşmaya devam et.","Aynı yeteneği birden fazla rakibe isabet ettirmek, Karanlık Azap'ı çabucak etkinleştirmeni sağlar.","Ölüler Âlemi'ni canı az olan rakipler üstünde kullanarak onları katletmeyi garantile ve kazandığın nitelikleri takım savaşının geri kalanı boyunca koru."],["Mordekaiser şampiyonlara karşı savaşırken güçlü bir hasar haresi oluşturur. Ondan uzak durmaya çalış.","Şampiyonun verdiği hasar büyük bir kalkana dönüştürülebilir ve can kazanmak için tüketilebilir.","Ölüler Âlemi, seni takım arkadaşlarından tamamen ayırır. Hareketliliğe yönelik yeteneklerini saklayarak onları bu âlemde Mordekaiser'dan kaçmak için kullan."]]},"morgana":{"id":"Morgana","k":25,"n":"Morgana","en":"Morgana","t":"Istırabın Kanatları","cls":["Support","Mage"],"d":1,"res":"Mana","b":{"hp":630,"hpL":104,"ar":25,"arL":4.2,"mr":30,"mrL":1.3,"ad":56,"adL":3.5,"as":0.625,"asR":0.625,"asL":1.53,"rng":450,"ms":335,"t":"M"},"ab":[["Ruh Sömürüsü","P","Morgana rakiplerinin ruhlarını sömürerek şampiyonlara, büyük minyonlara; orta ve büyük boy orman canavarlarına verdiği hasarla kendini iyileştirir.","img/abil/morgana-p.png"],["Karanlık Esaret","Q","Morgana, kara büyüyle bir rakibi olduğu yere sabitler. Hedefinin başkalarına yaşattığı acıları tatması için ona büyü hasarı verir.","img/abil/morgana-q.png",[10,10,10,10,10]],["Zulüm Gölgesi","W","Morgana bir alana lanetli bir gölge göndererek karanlık çemberinin içinde kalmaya cüret eden rakiplere hasar verir. Çember zaman içinde büyü hasarı verir ve bu hasar hedefin canı azaldıkça artar.","img/abil/morgana-w.png",[12,12,12,12,12]],["Kara Kalkan","E","Morgana, bir takım arkadaşını yıldızateşinden oluşan koruyucu bir kalkanla kutsar. Bu kalkan, kırılana dek büyü hasarını ve kitle kontrolü etkilerini engeller.","img/abil/morgana-e.png",[26,23.5,21,18.5,16]],["Ruh Prangası","R","Morgana, semavi gücünü tamamen serbest bırakarak kanatlarını açar ve süzülmeye başlar. Yakınındaki şampiyonlara karanlık ve acı dolu zincirler geçirerek hareket hızı kazanır. Zincirler hedefleri yavaşlatır ve isabet anında hasar verir. Ayrıca bir süre sonra zincirleri kıramayan rakipleri sersemletir.","img/abil/morgana-r.png",[120,110,100]]],"wk":"Morgana","p":"img/champ/morgana.png","tip":[["Kara Kalkan'ın akıllıca kullanımı takım savaşlarının sonucunu belirleyebilir.","Hayatta kalmaya yönelik eşyalar, Kara Kalkan ve Ruh Prangası ile birlikte kullanıldığında Morgana katledilmesi çok güç bir rakibe dönüşür.","Koridorda tek başınaysan Zulüm Gölgesi çok iyi bir minyon biçme aracıdır."],["Zulüm Gölgesi, çok düşük cana sahip birimlere yüklü hasar verir. Canın azken, Morgana'nın seni Zulüm Gölgesi'nin menzilinde kıstırma çabalarına dikkat et.","Morgana genellikle saldırılarını hazırlayabilmek için Karanlık Esaret'in hedefini bulmasına ihtiyaç duyacaktır. Minyonlarını, Karanlık Esaret'e karşı kalkan olarak kullan.","Kara Kalkan, Morgana'yı kitle kontrol etkilerinden etkilenmez hale getirse de büyü hasarıyla kırılması mümkün."]]},"naafiri":{"id":"Naafiri","k":950,"n":"Naafiri","en":"Naafiri","t":"Yüz Çeneli Tazı","cls":["Assassin","Fighter"],"d":1,"res":"Mana","b":{"hp":610,"hpL":105,"ar":28,"arL":4.2,"mr":32,"mrL":2.05,"ad":55,"adL":2,"as":0.663,"asR":0.625,"asL":2.1,"rng":125,"ms":340,"t":"P"},"ab":[["Tazılar Sofrası","P","Naafiri saldırı ve yeteneklerinin hedeflerine saldıran tazılar çağırır.","img/abil/naafiri-p.png"],["Darkin Hançerleri","Q","Naafiri her biri kanamaya neden olan veya hedef zaten kanama etkisi altındaysa ilave hasar veren en fazla iki hançer fırlatır. Tazılar bu yetenekten isabet alan ilk şampiyona veya canavara saldırmak için atılır.","img/abil/naafiri-q.png",[9,8.5,8,7.5,7]],["Sürünün Çağrısı","W","Naafiri hedef alınamaz hale gelir, sürüsünü güçlendirir, fazladan tazı çağırır ve hareket hızı ile saldırı gücü kazanır.","img/abil/naafiri-w.png",[26,24,22,20,18]],["Karnını Deş","E","Naafiri atılarak etrafındaki rakiplere hasar verir ve tazılarını çağırarak canlarını tamamen yeniler.","img/abil/naafiri-e.png",[11,10,9,8,7]],["Tazıların İzinden","R","Naafiri ve tazıları bir şampiyona atılarak hasar verir. Naafiri bir şampiyonu alt ederse yakındaki rakipleri açığa çıkarır ve bu yeteneği bir kere daha kullanabilir. Yeteneğin ikinci kullanımı kalkan kazandırır.","img/abil/naafiri-r.png",[110,95,80]]],"wk":"Naafiri","p":"img/champ/naafiri.png","tip":[["Shurima çöllerinin dört bucağında ulumalar yankılanır durur. Sürüler halinde dolaşan ve bu çorak topraklarda durmaksızın av peşinde koşan açgözlü yırtıcıların, çöl tazılarının çağrısıdır bu. Bu sürülerden bir tanesi köpek içgüdüleriyle değil, bir darkinin kadim gücüyle hareket etmesiyle meşhurdur."],[]]},"nami":{"id":"Nami","k":267,"n":"Nami","en":"Nami","t":"Dalga Çağıran","cls":["Support","Mage"],"d":2,"res":"Mana","b":{"hp":560,"hpL":88,"ar":29,"arL":5.2,"mr":30,"mrL":1.3,"ad":54,"adL":3.1,"as":0.644,"asR":0.643999993801116,"asL":2.61,"rng":550,"ms":335,"t":"M"},"ab":[["Vahşi Dalgalar","P","Nami'nin yeteneklerinin isabet ettiği dost şampiyonlar, kısa süreliğine Hareket Hızı kazanır.","img/abil/nami-p.png"],["Suya Hapis","Q","Hedef bölgeye fırlattığı kabarcık, isabet ettiği tüm hedeflerin hasar alıp sersemlemesine yol açar.","img/abil/nami-q.png",[12,11,10,9,8]],["Med Cezir","W","Ortaya çıkardığı akıntı takım arkadaşlarıyla rakip şampiyonlar arasında sekerken takım arkadaşlarını iyileştirir, rakip şampiyonlara hasar verir.","img/abil/nami-w.png",[10,10,10,10,10]],["Dalga Çağıran'ın Hediyesi","E","Bir takım arkadaşını kısa süreliğine güçlendirir. Takım arkadaşının normal saldırıları ve yetenekleri ilave büyü hasarı verir ve hedefi yavaşlatır.","img/abil/nami-e.png",[11,11,11,11,11]],["Gelgit Dalgası","R","Çağırdığı devasa Gelgit Dalgası rakipleri havaya savurur, yavaşlatır ve onlara hasar verir. Dalgaya kapılan takım arkadaşlarının üzerindeki Vahşi Dalgalar etkisi ikiye katlanır.","img/abil/nami-r.png",[120,110,100]]],"wk":"Nami","p":"img/champ/nami.png","tip":[["Suya Hapis'in bekleme süresi uzundur; doğru anda kullandığından emin ol.","Med Cezir'i rakip şampiyonlarla çatışmaya girdiğinde kullanmak, savaşın gidişatını lehine çevirebilir.","Nami'nin ultisi, uzaktaki rakiplerle çatışma başlatmak için işe yarayabilir."],["Suya Hapis çok uzun bekleme süresine sahip ama çok güçlü bir yetenektir; Nami bu yeteneği ıskalarsa durumdan yararlan.","Gelgit Dalgası'nın menzili çok uzundur ama yavaş yol alır; sana doğru gelirken dikkatli ol çünkü yolundan sapabilir.","Dalga Çağıran'ın Hediyesi'nden etkilenen bir rakiple dövüşmekten kaçınmaya çalış; bu yetenek kısa sürer, o yüzden bitmesini beklemenin büyük yardımı dokunur."]]},"nasus":{"id":"Nasus","k":75,"n":"Nasus","en":"Nasus","t":"Kumların Efendisi","cls":["Fighter","Tank"],"d":2,"res":"Mana","b":{"hp":650,"hpL":104,"ar":34,"arL":4.7,"mr":32,"mrL":2.05,"ad":67,"adL":4,"as":0.638,"asR":0.638000011444091,"asL":3.48,"rng":125,"ms":350,"t":"P"},"ab":[["Ruhyiyen","P","Nasus, rakibinin ruh enerjisini sömürerek ilave can çalma kazanır.","img/abil/nasus-p.png"],["Sömürü Darbesi","Q","Nasus rakibine vurarak hasar verir ve hedefin katledilmesi halinde sonraki Sömürü Darbelerinin gücü artar.","img/abil/nasus-q.png",[7.5,6.5,5.5,4.5,3.5]],["Çürü","W","Nasus rakip bir şampiyonu yaşlandırarak hedefin hareket ve saldırı hızını zamanla azaltır.","img/abil/nasus-w.png",[15,14,13,12,11]],["Ruh Ateşi","E","Nasus bir bölgeye yolladığı Ruh Ateşi ile bölgedeki rakiplerin hasar görmesini ve Zırh miktarlarının düşmesini sağlar.","img/abil/nasus-e.png",[12,12,12,12,12]],["Kumların Hiddeti","R","Nasus yakınındaki rakipleri hırpalayan güçlü bir kum fırtınası çıkarır. Fırtına hiddetlendikçe Nasus fazladan can ve saldırı menzili kazanır, yakınındaki rakiplere hasar verir, Sömürü Darbesi'nin bekleme süresinde azalma kazanır ve hem ilave zırh hem de büyü direnci elde eder.","img/abil/nasus-r.png",[120,100,80]]],"wk":"Nasus","p":"img/champ/nasus.png","tip":[["Sömürü Darbesi'yle son vuruşları yapmaya dikkat etmek, oyunun sonuna büyük etki yapacaktır.","Yalnızsan, Ruh Ateşi bir koridordaki minyonları biçmek için çok iyi bir yöntemdir. Aynı koridorda 2 kişiyle karşı karşıyaysan ve çok ileri bastırırsan kötü olabilir. Sömürü Darbesi'yle vurulan son darbelerle alan etkili biçme arasında doğru dengeyi bul.","Savunman düşükse, rakipler ultin açık olsa bile seni yere sermeye çalışacaklardır. Saniye Başına Hasar donanımında bile hayatta kalmayı kolaylaştıracak eşyalar satın almaya çalış."],["Nasus ultisiyle dönüşüme uğradığında, Lig'deki çoğu şampiyondan daha güçlü hale gelir. Bariz bir avantajın olmadan karşısına çıkma.","En yüksek seviye Çürü, Saldırı Gücü tabanlı karakterler için çok etkin bir karşılıktır; bu yüzden ona yalnız yakalanmamaya çalış.","Onunla Can değeri tamken karşılaşmamaya çalış."]]},"nautilus":{"id":"Nautilus","k":111,"n":"Nautilus","en":"Nautilus","t":"Derinliklerin Devi","cls":["Tank","Support"],"d":2,"res":"Mana","b":{"hp":646,"hpL":100,"ar":39,"arL":4.95,"mr":32,"mrL":2.05,"ad":58,"adL":3.3,"as":0.706,"asR":0.611999988555908,"asL":1,"rng":175,"ms":325,"t":"M"},"ab":[["Afallatan Vuruş","P","Nautilus'ün bir hedefe yönelik ilk saldırısı ona fazladan fiziksel hasar verir ve onu kısa süreliğine sabitler.","img/abil/nautilus-p.png"],["Demir At","Q","Nautilus çapasını ileri savurur. Çapa bir rakibe çarparsa, rakiple Nautilus birbirine çekilir ve hedef büyü hasarı alır. Çapa bir yüzey şekline çarparsa, Nautilus ona doğru çekilir.","img/abil/nautilus-q.png",[14,13,12,11,10]],["Titan'ın Gazabı","W","Nautilus geçici bir kalkan kazanır. Kalkan etkinken, Nautilus'ün saldırıları hedefine ve çevresindeki rakiplere zamanla hasar verir.","img/abil/nautilus-w.png",[12,12,12,12,12]],["Gelgit","E","Nautilus çevresinde patlayan üç dalga oluşturur. Her bir patlama rakiplere hasar verir ve onları yavaşlatır.","img/abil/nautilus-e.png",[7,6.5,6,5.5,5]],["Derin Darbe","R","Nautilus bir rakibini yeraltından takip eden bir şok dalgası gönderir. Bu şok dalgası, üstündeki yerkabuğunu parçalayarak ilerlerken yoluna çıkan rakipleri de havaya savurur. Dalga rakibe ulaştığında patlayarak yüzeye çıkar ve hedefini havaya savurarak sersemletir.","img/abil/nautilus-r.png",[120,100,80]]],"wk":"Nautilus","p":"img/champ/nautilus.png","tip":[["Bir anda saldırı yaparken Demir At'ı yakındaki bir alana hedeflemeyi ve daha yüksek vuruş yüzdesi için de peşinden Gelgit'i kullanmayı düşün.","Gelgit'in patlaması, aktifleştirildikten bir süre sonra gerçekleşir; caydırıcı olarak kaçarken ya da rakip üzerine gelirken kullanabilirsin."],["Nautilus yanında Gelgit'i kullanırsa, koşmadan önce yerinde kalıp dalga efektinin bitmesini bekle. Erken koşmak fazladan hasar alacağın ve yavaşlayacağın ikinci patlamalara maruz kalmana neden olacaktır.","Nautilus'ün kalkanları açıkken, normal saldırılarıyla büyük ölçüde alan etkili hasar verebilir. Zamanın varsa kalkanı yok etmeyi düşün."]]},"neeko":{"id":"Neeko","k":518,"n":"Neeko","en":"Neeko","t":"Meraklı Bukalemun","cls":["Mage","Support"],"d":2,"res":"Mana","b":{"hp":610,"hpL":104,"ar":21,"arL":5.2,"mr":30,"mrL":1.3,"ad":48,"adL":2.5,"as":0.625,"asR":0.67,"asL":3.5,"rng":550,"ms":340,"t":"M"},"ab":[["Binbir Surat","P","Neeko bir takım arkadaşının veya haritadaki başka bir birimin şekline bürünebilir. Hareketsiz bırakan bir kitle kontrolü etkisinden isabet aldığında, hasar veren bir yetenek kullandığında, şampiyon harici bir birimken rakip kulelere hasar verdiğinde veya şekline büründüğün birim can göstergesine eşdeğer miktarda hasar aldığında gerçek biçimine geri dönersin.","img/abil/neeko-p.png"],["Tohum Tuzağı","Q","Neeko büyü hasarı veren bir tohum fırlatır. Tohum, şampiyonlara isabet ettiğinde veya birimleri katlettiğinde yeniden gelişir.","img/abil/neeko-q.png",[9,8.5,8,7.5,7]],["Kandırıkçı","W","Neeko'nun her üçüncü normal saldırısı pasif olarak ilave büyü hasarı verir ve kısa süreliğine hareket hızı kazandırır. Neeko bu yeteneği etkinleştirerek belli bir doğrultuda bir kopya gönderebilir ve yeniden etkinleştirerek kopyanın yönünü değiştirebilir.","img/abil/neeko-w.png",[16,15,14,13,12]],["Dolaşık Dikenler","E","Neeko, içinden geçtiği her şeye hasar veren ve onları sabitleyen bir diken öbeği fırlatır. Dikenler bir rakibi katlettiğinde veya bir şampiyonun içinden geçtiğinde büyür, hızlanır ve daha uzun süreliğine sabitler.","img/abil/neeko-e.png",[12,11.5,11,10.5,10]],["Ruh Çiçeği","R","Neeko kısa bir hazırlığın ardından havaya sıçrar ve yakınındaki tüm rakipleri havaya savurur. Yere indiğinde yakınındaki rakiplere hasar verir ve onları sersemletir. Neeko şekil değiştirmişse gizli bir şekilde hazırlanabilir.","img/abil/neeko-r.png",[120,105,90]]],"wk":"Neeko","p":"img/champ/neeko.png","tip":[["Seçenekler menüsünden pasifi için tuş atayabilirsin. Varsayılan tuşlar Shift+F1-F5 şeklindedir.","Binbir Surat'ı az ve öz kullanmaya çalış. Etkisiz kullanımlar rakibi alarma geçirebilir."],["Neeko'ya karşı oynarken minyonların arkasında durmak çok tehlikelidir; çünkü bu durumda Dolaşık Dikenler güçlenir.","Neeko şekil değiştirdiğinde Ruh Çiçeği'nin uyarı görselleri görünmez olur."]]},"nidalee":{"id":"Nidalee","k":76,"n":"Nidalee","en":"Nidalee","t":"Yabani Avcı","cls":["Assassin","Mage"],"d":3,"res":"Mana","b":{"hp":610,"hpL":109,"ar":32,"arL":5,"mr":30,"mrL":1.45,"ad":58,"adL":3.5,"as":0.638,"asR":0.638000011444091,"asL":3.22,"rng":525,"ms":335,"t":"M"},"ab":[["Kolaçan","P","Nidalee çalı içindeyken hareket hızı 2 saniyeliğine %10 artar, bu etki 1400 menzil içerisindeki görünür rakip şampiyonlara karşı %30'a çıkar. Mızrak Atışı ile Vahşi Pusu saldırılarından isabet alan şampiyonlar ve canavarlar Avlandı olarak işaretlenir ve 4 saniyeliğine Gerçek Görüş etkisine girer. Bu süre içinde, Nidalee'nin hareket hızı %10 artar, Avlandı ile işaretlenen hedeflere karşı bu etki %30'a çıkar ve bu hedeflere karşı kullanacağı Yere Ser ile Atıl yetenekleri güçlenir.","img/abil/nidalee-p.png"],["Mızrak Atışı / Yere Ser","Q","Nidalee insan suretindeyken, kat ettiği mesafeyle doğru orantılı hasar veren bir mızrak atar. Puma suretindeyken, bir sonraki saldırısıyla hedefinde ölümcül bir yara açar; hedefin canı ne kadar azsa, o kadar çok hasar alır.","img/abil/nidalee-q.png",[6,6,6,6,6]],["Vahşi Pusu / Atıl","W","İnsan suretindeyken, Nidalee bir kapan kurar. Gafil avlanıp kapana takılan hedefler hasar alır ve görünür hale gelir. Puma suretindeyken, Nidalee belli bir yöne doğru atlar ve indiği alana hasar verir.","img/abil/nidalee-w.png",[13,12,11,10,9]],["İlkel Güdü / Pençele","E","İnsan suretindeyken, Nidalee pumanın ruhunu çağırarak takım arkadaşlarını iyileştirir ve onlara kısa süreliğine Saldırı Hızı kazandırır. Puma suretindeyken; belli bir yöne doğru pençe atarak, önündeki rakiplere hasar verir.","img/abil/nidalee-e.png",[12,12,12,12,12]],["Puma Sureti","R","Nidalee pumaya dönüşerek yeni yetenekler kazanır.","img/abil/nidalee-r.png",[3,3,3,3]]],"wk":"Nidalee","p":"img/champ/nidalee.png","tip":[["Avantaj elde etmek için çalıları kullan! Çalılığın içine ve dışına çıkmak savaştaki etkini büyük ölçüde değiştirebilir.","Takım savaşlarına, Mızrak Atışı'yla rakibini taciz ederek başla ve daha sonra puma suretine geçip Avlanan hedefleri kovala.","Vahşi Pusu kapanları, kapana yakalanan hedeflerin o anki Can değerine bağlı olarak hasar verir. Kuşatmalarda savaş başlamadan önce takımının cephe arkasına kapan kurarak rakibin ön saflarına hasar verebilirsin."],["Nidalee'nin Av zayıflatması yalnızca Mızrak Atışı ve Vahşi Pusu ile yapılır. Bu yeteneklerden kaçınarak, daha fazla hasar verme ihtimalinin önüne geçebilirsin.","Nidalee'nin Mızrak Atışı, hedefine ne kadar uzaksa o kadar fazla zarar verir. Çok uzaktaysa, mutlaka savuşturmalısın.","Nidalee, Avlanan hedeflere Yere Ser ile büyük miktarda hasar verir ama bunun için yakınlaşması gerekir. Kitle kontrol veya savunmaya yönelik yeteneklerini idareli kullan, son vuruşu yapmak için yanına geldiğinde lazım olur."]]},"nilah":{"id":"Nilah","k":895,"n":"Nilah","en":"Nilah","t":"Dizginsiz Mutluluk","cls":["Fighter","Assassin"],"d":3,"res":"Mana","b":{"hp":570,"hpL":101,"ar":27,"arL":4.2,"mr":32,"mrL":2.05,"ad":58,"adL":2,"as":0.697,"asR":0.67,"asL":1.25,"rng":225,"ms":340,"t":"P"},"ab":[["Daimi Mutluluk","P","Nilah'nın son vuruş yaptığı minyonlardan kazandığı deneyim artar. Ayrıca yakınındaki takım arkadaşlarının iyileştirme ve kalkan etkilerini güçlendirir ve paylaştırır.","img/abil/nilah-p.png"],["Şekilsiz Kılıç","Q","Nilah kırbaç kılıcını seçilen yöne doğru düz bir hat üstünde savurarak isabet alan tüm rakiplere hasar verir. Bu eylem Nilah'nın saldırı menzilini kısa süreliğine arttırır.","img/abil/nilah-q.png",[4,4,4,4,4]],["Neşe Örtüsü","W","Nilah kendisini su buharıyla çevreleyerek hareket hızını arttırır ve gelen tüm saldırılardan zarifçe kaçınır. Buhar varlığını koruduğu sürece Nilah'nın temas ettiği takım arkadaşları da bu etkiden faydalanır.","img/abil/nilah-w.png",[26,25,24,23,22]],["Akışkan","E","Nilah şevkle hedef birime doğru atılır ve deşip geçtiği tüm rakiplere hasar verir.","img/abil/nilah-e.png",[0.5,0.5,0.5,0.5,0.5]],["Ulvi İdeal","R","Nilah kırbaç kılıcını coşkuyla döndürerek etrafındaki rakiplere hasar verir ve daha sonra silahıyla onları kendisine doğru çeker.","img/abil/nilah-r.png",[110,95,80]]],"wk":"Nilah","p":"img/champ/nilah.png","tip":[[],[]]},"nocturne":{"id":"Nocturne","k":56,"n":"Nocturne","en":"Nocturne","t":"Ebedi Kâbus","cls":["Fighter","Assassin"],"d":2,"res":"Mana","b":{"hp":640,"hpL":109,"ar":36,"arL":4.2,"mr":32,"mrL":1.55,"ad":62,"adL":2.6,"as":0.721,"asR":0.721,"asL":2.7,"rng":125,"ms":345,"t":"P"},"ab":[["Umbra Bıçakları","P","Her birkaç saniyede bir, Nocturne'ün sonraki saldırısı çevredeki rakiplere ilave fiziksel hasar verir ve şampiyonu iyileştirir. Nocturne'ün normal saldırıları, bu bekleme süresini azaltır.","img/abil/nocturne-p.png"],["Karanlığın Eli","Q","Nocturne hasar veren ve şampiyonların ardında Karanlık Yol bırakmalarına neden olan bir gölge bıçak fırlatır. Nocturne yol üstündeyken birimlerin içinden geçebilir ve hareket hızı ile saldırı gücü değerlerinde artış elde eder.","img/abil/nocturne-q.png",[8,8,8,8,8]],["Karanlık Örtüsü","W","Nocturne bıçaklarını güçlendirir ve pasif olarak saldırı hızı kazanır. Karanlık Örtüsü'nü etkinleştirince, bir tek rakip yeteneğini engelleyen ve başarılı olursa pasif saldırı hızını ikiye katlayan büyülü bir bariyer yaratarak gölgeler arasında kaybolabilir.","img/abil/nocturne-w.png",[20,18,16,14,12]],["Tarifsiz Dehşet","E","Nocturne hedefinin zihnine bir kâbus işler ve her saniye hasar verir. Hedef, sürenin sonuna kadar menzil dışına çıkmazsa korkuya kapılır.","img/abil/nocturne-e.png",[15,14,13,12,11]],["Paranoya","R","Nocturne bütün rakip şampiyonların görüş mesafesini azaltır ve bu arada takım arkadaşlarını görememelerine neden olur. Ardından, Nocturne bu fırsattan istifade yakındaki bir rakibin üstüne atılabilir.","img/abil/nocturne-r.png",[160,130,100]]],"wk":"Nocturne","p":"img/champ/nocturne.png","tip":[["Rakibe doğru atılmasan bile kritik bir anda Paranoya'yı kullanmak işe yarar.","Karanlığın Eli yalnızca bir saldırı yeteneği değildir. Savaş dışında uzun mesafeleri kısa zamanda almakta ya da ölmek üzereyken kaçmakta da kullanılabilir.","Paranoya'nın fırlayışıyla Karanlık Örtüsü'nü art arda kullan. Rakiplerin panikleyebilir ve kritik bir zayıflatmayı büyü kalkanının üzerinde harcayabilir."],["Paranoya yapıldığında takım arkadaşlarına yakın dur. Unutma, birlikten kuvvet doğar!","Nocturne'un Tarifsiz Dehşet'i menzilden kötü etkilenir; bu yüzden hareket yeteneklerini onu aktif hale getirdiği zamana saklamaya çalış."]]},"nunu":{"id":"Nunu","k":20,"n":"Nunu ve Willump","en":"Nunu & Willump","t":"Ayrılmaz İkili","cls":["Tank","Mage"],"d":2,"res":"Mana","b":{"hp":610,"hpL":90,"ar":29,"arL":4.2,"mr":32,"mrL":2.05,"ad":61,"adL":3,"as":0.625,"asR":0.625,"asL":2.25,"rng":125,"ms":345,"t":"M"},"ab":[["Freljord'un Çağrısı","P","Nunu, Willump'ın ve yakınındaki bir takım arkadaşının saldırı ve hareket hızlarını arttırır. Ayrıca Willump'ın normal saldırılarının hedefin etrafındaki rakiplere hasar vermesini sağlar.","img/abil/nunu-p.png"],["Tüket","Q","Willump bir minyon, canavar veya rakip şampiyondan ısırık alarak ona hasar verirken, kendini iyileştirir.","img/abil/nunu-q.png",[13,12,11,10,9]],["Büsbüyük Kartopu","W","Willump, yuvarladıkça boyutu ve hızı artan bir kartopu oluşturur. Bu kartopu rakiplere hasar verir ve onları havaya savurur.","img/abil/nunu-w.png",[14,14,14,14,14]],["Kartopu Yağmuru","E","Nunu birden fazla kartopu fırlatarak rakiplerine hasar verir. Nunu kartopu fırlatmayı tamamladığında, Willump kartoplarından isabet almış bütün şampiyon ve büyük canavarları yere sabitler.","img/abil/nunu-e.png",[14,13,12,11,10]],["Mutlak Sıfır","R","Nunu ve Willump belli bir alandaki rakipleri yavaşlatan ve tamamlandığında yüksek miktarda hasar veren, kuvvetli bir kar fırtınası oluşturur.","img/abil/nunu-r.png",[110,100,90]]],"wk":"Nunu & Willump","p":"img/champ/nunu.png","tip":[["Tüket, Nunu'nun menzilli rakiplere karşı koridorda kalmasını sağlar.","Bir rakip menzil dışına çıkmak üzereyse Mutlak Sıfır'ı erkenden kesmeyi seçebilirsin.","Mutlak Sıfır'ı o sıradaki etki kaldıran yetenekler kullanıldıktan sonra yapmak çoğu zaman yararına olacaktır. Bir takım çatışmasına gözü kapalı dalmadan önce geride durmaya çalış."],["Mutlak Sıfır'ın yoğunlaşmasını engellemek takımının alacağı hasarı azaltacaktır.","Sıçra kullanarak Mutlak Sıfır'dan kolayca kurtulmak mümkün.","Büsbüyük Kartopu çok hızlı hareket etse de dönüşlerde daha yavaştır. Dolayısıyla ondan kaçarken düz bir hat boyunca hareket etmek yerine ani ve sert dönüşler yapmaya çalış."]]},"olaf":{"id":"Olaf","k":2,"n":"Olaf","en":"Olaf","t":"Başıbozuk","cls":["Fighter","Tank"],"d":1,"res":"Mana","b":{"hp":645,"hpL":119,"ar":35,"arL":4.2,"mr":32,"mrL":2.05,"ad":68,"adL":4.7,"as":0.72,"asR":0.694,"asL":2.7,"rng":125,"ms":350,"t":"P"},"ab":[["Başıbozuk Hiddeti","P","Olaf eksik canına bağlı olarak saldırı hızı ve can çalma kazanır.","img/abil/olaf-p.png"],["Balta Fırlat","Q","Olaf'ın hedef konuma fırlattığı balta, yolda biçtiği rakiplere hasar vererek bu rakiplerin zırhını ve hareket hızını azaltır. Olaf baltasını yerden alırsa bu yeteneğin bekleme süresi sıfırlanır.","img/abil/olaf-q.png",[9,9,9,9,9]],["Dayan","W","Olaf saldırı hızını arttırır ve bir kalkan kazanır.","img/abil/olaf-w.png",[16,15,14,13,12]],["Pervasız Vuruş","E","Olaf öyle bir hışımla saldırır ki; hem hedefine, hem de kendine gerçek hasar verir ve hedefi yok ederse Can bedelini geri alır.","img/abil/olaf-e.png",[11,10,9,8,7]],["Ragnarok","R","Olaf pasif olarak zırh ve büyü direnci kazanır. Yeteneği kullanarak saldırmaya devam ettiği sürece engellemelere karşı bağışıklık kazanır.","img/abil/olaf-r.png",[100,90,80]]],"wk":"Olaf","p":"img/champ/olaf.png","tip":[["Olaf, canı azalmışken Başıbozuk Hiddeti, Hırçın Saldırı ve Ragnarok'u birleştirerek şaşırtıcı ölçüde güçlenebilir.","Hırçın Saldırı'nın verdiği ilave iyileşme etkisi, tüm kaynaklardan elde ettiğin Can Çalma etkileri ile takım arkadaşlarının yaptığı iyileştirmeleri arttırır."],["Can değeri ne kadar düşükse Olaf o kadar tehlikelidir. Engelleyici yeteneklerini, onun işini bitirmek için sakla.","Olaf'ın baltasına ulaşmasını engellemek, koridorda ilerleme safhasında neden olacağı sıkıntıyı en aza indirecektir.","Ragnarok sırasında zayıflatma etkilerine karşı bağışıklık kazanmasına rağmen, Olaf'ın hasara karşı savunması azalır. Ragnarok sırasında Olaf'tan kaçamazsan, takım arkadaşlarınla birlikte ona hasar vermeye odaklanın."]]},"orianna":{"id":"Orianna","k":61,"n":"Orianna","en":"Orianna","t":"Mekanik Kız","cls":["Mage","Support"],"d":3,"res":"Mana","b":{"hp":565,"hpL":110,"ar":20,"arL":4.2,"mr":26,"mrL":1.3,"ad":44,"adL":2.6,"as":0.658,"asR":0.657999992370605,"asL":3.5,"rng":525,"ms":325,"t":"M"},"ab":[["İşleyen Demir","P","Orianna'nın saldırıları fazladan büyü hasarı verir. Bu hasar, Orianna aynı hedefe saldırdıkça artar.","img/abil/orianna-p.png"],["Komut: Saldır","Q","Orianna, topuna verdiği emirle hedef konuma fırlamasını ve yoluna çıkan hedeflere büyü hasarı vermesini sağlar. (çarptığı her hedefe bir öncekinden az hasar verir). Sonrasında top hedef konumda kalır.","img/abil/orianna-q.png",[7,6,5,4,3]],["Komut: Uyumsuzluk","W","Orianna, topuna verdiği emirle çevresine büyü hasarı veren bir enerji darbesi oluşturur. Bu darbe, ardında takım arkadaşlarını hızlandırırken rakipleri yavaşlatan bir alan bırakır.","img/abil/orianna-w.png",[7,7,7,7,7]],["Komut: Koru","E","Orianna, topuna verdiği emirle bir takım arkadaşına yapışıp ona kalkan olmasını ve şampiyona giderken çarptığı her rakibe büyü hasarı vermesini sağlar. Top, yapıştığı şampiyona fazladan zırh ve büyü direnci sağlar.","img/abil/orianna-e.png",[9,9,9,9,9]],["Komut: Şok Dalgası","R","Orianna, topuna verdiği emirle kısa bir aradan sonra hasar veren bir şok dalgası yaratır ve yakındaki rakiplerin topa doğru çekilmesini sağlar.","img/abil/orianna-r.png",[110,95,80]]],"wk":"Orianna","p":"img/champ/orianna.png","tip":[["Komut: Koru, topu kendine çabucak geri döndürmek için kullanılabilir. Çabucak rahatsız etmek için bunu Komut: Saldır'la birleştirebilirsin.","Komut: Uyumsuzluk, Orianna'nın topu kendindeyse çok güçlü bir kaçış aracıdır. Hız ve yavaşlatan bir engel bırakmak oldukça güçlü bir kombinasyon olabilir.","Komut: Şok Dalgası, topu doğru konumlandırdıysan rakipleri sana doğru ya da senden uzağa doğru sürükleyebilir."],["Orianna yalnızca topun etrafındaki alanı etkileyebilir. Bunu avantaj olarak kullan.","Orianna'nın topu ona geri dönerken bağlantısına karşı dikkatli ol. Bu, beklenmedik durumlara yol açabilir."]]},"ornn":{"id":"Ornn","k":516,"n":"Ornn","en":"Ornn","t":"Dağın Kalbindeki Ateş","cls":["Tank"],"d":2,"res":"Mana","b":{"hp":660,"hpL":109,"ar":33,"arL":5.2,"mr":32,"mrL":2.05,"ad":69,"adL":3.5,"as":0.625,"asR":0.625,"asL":2,"rng":175,"ms":335,"t":"P"},"ab":[["Yaşayan Ocak","P","Ornn tüm kaynaklardan ilave zırh ve büyü direnci kazanır. Ornn altın harcayarak her yerde tek kullanımlık olmayan eşyalar işleyebilir. Ayrıca Ornn kendi ve takım arkadaşları için şaheser eşyalar oluşturabilir.","img/abil/ornn-p.png"],["Volkanik Patlama","Q","Ornn yere vurarak isabet alan rakiplere hasar veren ve onları yavaşlatan bir yarık gönderir. Kısa bir beklemenin ardından yarığın ucunda bir magma sütunu oluşur.","img/abil/ornn-q.png",[9,8.5,8,7.5,7]],["Harlı Ateş","W","Ornn ilerleyerek alev kusar. Son alevlerden isabet alan rakipler Kavruk hale gelir.","img/abil/ornn-w.png",[12,11.5,11,10.5,10]],["Kavuran Hücum","E","Ornn hücum eder ve üzerinden geçtiği rakiplere hasar verir. Eğer Ornn hücumu sırasında yüzey şekilleriyle çarpışırsa çevresinde hasar veren ve rakipleri havaya savuran bir şok dalgası oluşturur.","img/abil/ornn-e.png",[14,13.5,13,12.5,12]],["Ocağın Çağrısı","R","Ornn bölgeye devasa bir elemental çağırır ve elemental giderek artan bir hızla Ornn'a doğru ilerler. Elementalin ezdiği rakipler hasar alır, yavaşlar ve Kavruk hale gelir. Ornn bu yeteneği yeniden kullanarak elementale doğru hücum edip onu vurduğu yöne yönlendirebilir. Yeniden yönlendirilen elementalin ezdiği rakipler havaya savrulur, aynı hasarı yeniden alır ve tekrar Kavruk hale gelir.","img/abil/ornn-r.png",[140,120,100]]],"wk":"Ornn","p":"img/champ/ornn.png","tip":[["Eşyaların tariflerini öğrenmek, koridorda hızlıca geliştirme seçmeye yardımcı olur.","Volkanik Patlama, rakipleri tehdit eden sınırlı bölgeler kurmak için kullanılabilir.","Yeteneklerinin sırası çok önemli! Kavruk'tan en verimli şekilde faydalanmaya çalış."],["Duvarlardan uzak durmaya çalış. Ornn seni sersemletemediği zamanlarda o kadar da güçlü olamaz.","Koridorda eşya üretmesini engellemek için Ornn'a saldırmayı unutma."]]},"pantheon":{"id":"Pantheon","k":80,"n":"Pantheon","en":"Pantheon","t":"Eğilmez Mızrak","cls":["Fighter","Assassin"],"d":2,"res":"Mana","b":{"hp":650,"hpL":109,"ar":40,"arL":4.95,"mr":28,"mrL":2.05,"ad":64,"adL":3.3,"as":0.658,"asR":0.658,"asL":2.95,"rng":175,"ms":345,"t":"P"},"ab":[["Fani Dirayeti","P","Her birkaç yetenek veya saldırının ardından Pantheon'un bir sonraki yeteneği güçlenir.","img/abil/pantheon-p.png"],["Meteor Mızrağı","Q","Pantheon mızrağını ileri doğru saplar ya da hedef doğrultuda fırlatır.","img/abil/pantheon-q.png",[11,10.25,9.5,8.75,8]],["Kalkan Hücumu","W","Pantheon bir hedefe atılarak ona hasar verir ve onu sersemletir.","img/abil/pantheon-w.png",[13,12,11,10,9]],["Siperli Saldırı","E","Pantheon kalkanını kaldırarak önden gelen hasardan etkilenmez hale gelir ve mızrağıyla art arda saldırılar gerçekleştirir.","img/abil/pantheon-e.png",[22,21,20,19,18]],["Gökkubbenin Çöküşü","R","Pantheon hazırlanıp havaya sıçrayarak seçilen bölgeye meteor gibi düşer.","img/abil/pantheon-r.png",[180,165,150]]],"wk":"Pantheon","p":"img/champ/pantheon.png","tip":[["Fani Dirayeti 5 yetenek veya normal saldırıdan sonra etkinleşir. Savaş sırasında birden fazla kez etkinleşmesi için saldırılarını planla.","Rakibin üstüne atlamadan önce Meteor Mızrağı'yla ona hasar ver.","Eğer bir rakip Siperli Saldırı'nın menzilinden çıkmak üzereyse yeteneği yeniden kullanarak hemen kalkan vuruşunu gerçekleştir."],["Pantheon'un Siperli Saldırı'sı, onu önden gelen saldırılara karşı hasar almaz hale getirir. Ya şampiyonun arkasına geç ya da yeteneğin sonlanmasını bekle.","Canın azsa Pantheon'un yakınlarındayken dikkatli ol. Fırlatılan bir Meteor Mızrağı düşük cana sahip rakipleri infaz eder.","Gökkubbenin Çöküşü, Pantheon düşmeden birkaç saniye önce seni uyarır. Bu zamanı bölgeden uzaklaşmak veya onunla başa çıkmak adına bir plan oluşturmak için kullan."]]},"poppy":{"id":"Poppy","k":78,"n":"Poppy","en":"Poppy","t":"Çekicin Muhafızı","cls":["Tank","Fighter"],"d":2,"res":"Mana","b":{"hp":610,"hpL":110,"ar":35,"arL":5,"mr":32,"mrL":2.05,"ad":56,"adL":4,"as":0.658,"asR":0.625,"asL":2.5,"rng":125,"ms":345,"t":"P"},"ab":[["Demir Elçi","P","Poppy'nin fırlattığı kalkanı hedeften seker. Poppy kalkanını yerden alarak geçici bir koruma kazanabilir.","img/abil/poppy-p.png"],["Sarsan Çekiç","Q","Poppy çekicini sallayıp, hasar verir ve rakipleri yavaşlatarak kısa bir süre sonra patlayan bir alan oluşturur.","img/abil/poppy-q.png",[8,7,6,5,4]],["Sağlam Duruş","W","Poppy pasif olarak zırh ve büyü direnci kazanır. Bu ilaveler şampiyonun canı azaldığında artar. Poppy, Sağlam Duruş yeteneğini etkinleştirdiğinde hareket hızı kazanır ve çevresindeki rakiplerin atılma hamlelerini engeller. Atılması engellenen rakipler yavaşlar ve yere saplanır.","img/abil/poppy-w.png",[20,18,16,14,12]],["Kahraman Hücumu","E","Poppy üstüne atıldığı hedefi sürükler. Eğer hedef bir duvara çarptırılırsa sersemler.","img/abil/poppy-e.png",[14,13,12,11,10]],["Muhafızın Hükmü","R","Poppy rakipleri çok uzaklara savuran bir çekiç darbesi için yoğunlaşır.","img/abil/poppy-r.png",[140,120,100]]],"wk":"Poppy","p":"img/champ/poppy.png","tip":[["Demir Elçi ile fırlatılan kalkan, duvarlara yakın yerlere düşme eğilimindedir; Kahraman Hücumu ile bu durumdan faydalanmaya çalış.","Muhafızın Hükmü serbest bırakılarak rakibi anında uçuşa geçirebilir; düellolarda bunu çıkarına kullanmaya çalış."],["Poppy, Sağlam Duruş yeteneğiyle rakiplerin atılmasını engelleyebilir.","Poppy çekicini döndürmeye başladığında Muhafızın Hükmü için güç topluyor demektir.","Kalkanının üstüne basarak Poppy'yi kalkansız bırakabilirsin."]]},"pyke":{"id":"Pyke","k":555,"n":"Pyke","en":"Pyke","t":"Kanlırıhtım'ın Öcü","cls":["Support","Assassin"],"d":3,"res":"Mana","b":{"hp":670,"hpL":110,"ar":37,"arL":4.7,"mr":32,"mrL":2.05,"ad":62,"adL":2,"as":0.667,"asR":0.666999995708465,"asL":2.5,"rng":150,"ms":330,"t":"P"},"ab":[["Boğulmuşların Nefesi","P","Pyke rakiplerinden saklandığında, kısa süre önce şampiyonlardan aldığı hasarı iyileştirir. Ayrıca Pyke hiçbir kaynaktan ilave azami can kazanamaz; bunun yerine ilave SG kazanır.","img/abil/pyke-p.png"],["Kemik Zıpkın","Q","Pyke önündeki bir rakibi yaralar veya bir rakibi kendine doğru çeker.","img/abil/pyke-q.png",[10,9.5,9,8.5,8]],["Hayalet Sular","W","Pyke kamuflaja bürünür ve önemli miktarda hareket hızı kazanır. Bu hareket hızı zamanla azalarak kaybolur.","img/abil/pyke-w.png",[14,13,12,11,10]],["Karanlık Gelgit","E","Pyke ileri atılır ve arkasında, ona geri dönerken yoluna çıkan rakip şampiyonları sersemleten bir hortlak bırakır.","img/abil/pyke-e.png",[15,14,13,12,11]],["Derinlerin İntikamı","R","Pyke düşük cana sahip rakiplerin üstüne atlayarak onları infaz eder. Bu durumda yeteneği yeniden kullanabilir ve asist yapan tüm takım arkadaşlarına ilave altın verir.","img/abil/pyke-r.png",[100,85,70]]],"wk":"Pyke","p":"img/champ/pyke.png","tip":[["Pyke çok kırılgan olduğundan kısa süreliğine çatışmadan kaçmaktan çekinme. Rakiplerin seni göremiyorken Boğulmuşların Nefesi ile önemli miktarda can yenileyebilirsin.","Bir rakibe Kemik Zıpkın'ın basılı tutulmuş halini isabet ettirmek onu her zaman aynı mesafe boyunca çeker. Bunu yakın dövüş mesafesinde kullanarak hedefini arkana fırlatabilirsin.","Kemik Zıpkın'ı tuşa basıp çekerek kullanmak çok daha hızlıdır ve ilave hasar verir.","Saldırıya yönelik birçok yeteneğin ayrıca kaçış için kullanılır. Çatışmadan çıkmak için her zaman bir planının olması gerektiğini unutma."],["Pyke rakip şampiyonlardan aldığı hasarın önemli bir bölümünü iyileştirir. Tabii yalnızca onlar tarafından görülemiyorken!","Eğer Pyke yakınlarında Hayalet Sular kullanarak saklanıyorsa, ayaklarının altında dönüp duran köpekbalıkları görürsün.","Canı düşük seviyelerde olan takım arkadaşlarının yakınında durmamaya çalış; çünkü Pyke Derinlerin İntikamı'nı kulanarak onları infaz ederse listesindeki bir sonraki hedef sen olabilirsin."]]},"qiyana":{"id":"Qiyana","k":246,"n":"Qiyana","en":"Qiyana","t":"Elementlerin İmparatoriçesi","cls":["Assassin"],"d":3,"res":"Mana","b":{"hp":590,"hpL":115,"ar":31,"arL":4.5,"mr":32,"mrL":2.05,"ad":64,"adL":3.1,"as":0.688,"asR":0.625,"asL":2.1,"rng":150,"ms":335,"t":"P"},"ab":[["İmparatoriçenin Hakkı","P","Qiyana'nın her bir rakibe yönelik ilk normal saldırısı veya yeteneği ilave hasar verir.","img/abil/qiyana-p.png"],["Elementlerin Öfkesi / Ixtal Bıçağı","Q","Qiyana silahını savurur ve elementine bağlı olarak ilave bir etkiyle birlikte hasar verir.","img/abil/qiyana-q.png",[7,7,7,7,7]],["Diyarın Hâkimi","W","Qiyana bir noktaya atılır ve silahını bir elementle efsunlar. Silahı efsunlu haldeyken saldırı ve yetenekleri ilave hasar verir.","img/abil/qiyana-w.png",[7,7,7,7,7]],["Cüret","E","Qiyana bir rakibe atılarak ona hasar verir.","img/abil/qiyana-e.png",[11,10,9,8,7]],["Toprağın Öfkesi","R","Qiyana, isabet ettiği elementleri patlatan bir şok dalgası göndererek patlamanın yakınındaki rakipleri sersemletir ve onlara hasar verir.","img/abil/qiyana-r.png",[120,120,120]]],"wk":"Qiyana","p":"img/champ/qiyana.png","tip":[[],[]]},"quinn":{"id":"Quinn","k":133,"n":"Quinn","en":"Quinn","t":"Demacia'nın Kanatları ","cls":["Marksman","Assassin"],"d":2,"res":"Mana","b":{"hp":565,"hpL":107,"ar":28,"arL":4.7,"mr":33,"mrL":1.1,"ad":59,"adL":3.2,"as":0.668,"asR":0.667999982833862,"asL":3.1,"rng":525,"ms":330,"t":"P"},"ab":[["Alıcı Kuş","P","Quinn'in Demacia kartalı Valor, rakipleri belli aralıklarla Alıcı Kuş ile işaretler. Quinn'in Alıcı Kuş ile işaretlenmiş hedeflere karşı yaptığı ilk normal saldırı ilave fiziksel hasar verir.","img/abil/quinn-p.png"],["Kör Eden Saldırı","Q","Quinn, Valor'ı çağırarak bir rakibi işaretleyip onun görüşünü engellemesini ve sonra yakınındaki bütün rakiplere hasar vermesini sağlar.","img/abil/quinn-q.png",[11,10.5,10,9.5,9]],["Keskin Duyular","W","Quinn, Alıcı Kuş ile işaretlenmiş bir hedefe saldırdıktan sonra pasif olarak saldırı hızı ve hareket hızı elde eder. Valor'ın yakındaki geniş bir alanı açığa çıkarması için etkinleştir.","img/abil/quinn-w.png",[50,45,40,35,30]],["Pike","E","Quinn bir rakibe atılarak fiziksel hasar verir ve hedefin Hareket Hızı değerini azaltır. Hedefe ulaştığında hedefi kısa süre engelleyip, geri sıçrar ve azami saldırı mesafesinin sınırına yakın bir yere iner.","img/abil/quinn-e.png",[12,11,10,9,8]],["Düşman Hattının Ötesi","R","Quinn ve Valor büyük bir hızla uçmak için güç birliği yapar. Yeteneği sonlandırmak Hava Saldırısı gerçekleştirerek yakındaki rakiplere hasar verir ve şampiyonları Alıcı Kuş ile işaretler.","img/abil/quinn-r.png",[3,3,3]]],"wk":"Quinn","p":"img/champ/quinn.png","tip":[["Valor'ın","Savunmasız","olarak işaretlediği bir hedefe saldırmak, Alıcı Kuş'un bekleme süresine girmesine neden olur. Alıcı Kuş yüklerini ne kadar çabuk tüketirsen, o kadar çabuk yenilersin.","Pike güçlü bir yetenektir ama dikkatli kullanılması gerekir; rakipler, üzerlerine gelen Quinn'e saldırabilir. Sırtın duvara dönükse Pike bazen araziyi geçmek için kullanılabilir.","Düşman Hattının Ötesi'ni uzun mesafeleri kısa sürede katetmek, hızlıca minyon kesmek veya yaralı rakipleri kovalamak için kullanabilirsin."],["İşaretlendiğinde, Quinn'in bu durumdan faydalanmaması için derhal ondan uzaklaş.","Quinn'in konumuna dikkat et. Düşman Hattının Ötesi, Valor'ın haritayı çabucak katetmesine ve seni gafil avlamasına olanak sağlayabilir.","Düşman Hattının Ötesi'ni kullanırken Quinn'in hasar görmesi, ilave hareket hızını geçici olarak devre dışı bırakır."]]},"rakan":{"id":"Rakan","k":497,"n":"Rakan","en":"Rakan","t":"Gönülçelen","cls":["Support"],"d":2,"res":"Mana","b":{"hp":610,"hpL":99,"ar":30,"arL":4.9,"mr":32,"mrL":2.05,"ad":62,"adL":3.5,"as":0.635,"asR":0.634999990463256,"asL":3,"rng":300,"ms":335,"t":"M"},"ab":[["Alımlı Kürk","P","Rakan belli aralıklarla kalkan elde eder.","img/abil/rakan-p.png"],["Göz Alıcı Tüy","Q","Büyü hasarı veren efsunlu bir tüy savurur. Tüy bir rakip şampiyon ya da destansı canavara isabet ederse Rakan kendisini ve takım arkadaşlarını iyileştirebilir.","img/abil/rakan-q.png",[11,10,9,8,7]],["Zarif Uçuş","W","Belli bir konuma atılarak vardığı yerin yakınındaki rakipleri havaya savurur.","img/abil/rakan-w.png",[14,13,12,11,10]],["Savaş Dansı","E","Bir takım arkadaşının yanına uçarak ona kalkan verir. Kısa bir süre bedelsiz olarak yeniden kullanılabilir.","img/abil/rakan-e.png",[0,0,0,0,0]],["Seri Cazibe","R","Hareket hızı kazanarak temas ettiği rakipleri ayartır ve onlara büyü hasarı verir.","img/abil/rakan-r.png",[130,110,90]]],"wk":"Rakan","p":"img/champ/rakan.png","tip":[["Rakan elinin altındaki araçlardan en iyi şekilde yararlanmak için çevresinde takım arkadaşlarının olmasına ihtiyaç duyar.","Rakan'ın atılma hızı, hareket hızına bağlı olarak artar. Fazladan hızını rakiplerini şaşırtmakta kullan!","Eğlendikten sonra tehlike olsa kaç yazar?"],["Rakan'ın hareket yetenekleri, ikilinin nereye gideceğini önceden belirler. Bundan faydalanmaya çalış.","Çabuk kitle kontrolü uygulayabilen şampiyonlar Rakan'a karşı son derece başarılı olur.","Rakan çevresinde takım arkadaşı olmadan yakalandığında hareket becerisinden büyük oranda mahrum kalır. Onu yalnız yakalamaya çalış."]]},"rammus":{"id":"Rammus","k":33,"n":"Rammus","en":"Rammus","t":"Zırhlı Armadillo","cls":["Tank"],"d":2,"res":"Mana","b":{"hp":645,"hpL":100,"ar":35,"arL":4.5,"mr":32,"mrL":2.05,"ad":65,"adL":2.75,"as":0.7,"asR":0.625,"asL":2.215,"rng":125,"ms":335,"t":"P"},"ab":[["Dikenli Kabuk","P","Rammus zırhına ve büyü direncine bağlı olarak artacak şekilde ilave saldırı gücü kazanır.","img/abil/rammus-p.png"],["Güç Topu","Q","Rammus rakiplerine doğru hızlanarak ilerler; darbeden etkilenen hedefler hasar alarak yavaşlar.","img/abil/rammus-q.png",[12,10.5,9,7.5,6]],["Tortop","W","Rammus savunma duruşuna geçerek zırh ve büyü direncini yüksek miktarda arttırır. Ayrıca kendisine saldıran rakiplere hasar yansıtır.","img/abil/rammus-w.png",[7,7,7,7,7]],["Çıldırtan Dikenler","E","Rammus bir rakip şampiyonu veya canavarı kışkırtarak kendisine saldırmaya zorlar.","img/abil/rammus-e.png",[12,12,12,12,12]],["Keskin Gülle","R","Rammus havaya zıplar ve hedef bölgeye sert bir iniş yaparak rakiplere büyü hasarı verir ve onları yavaşlatır. Güç Topu etkinken kullanıldığında Rammus bölgenin merkezine yakın rakipleri de havaya savurur.","img/abil/rammus-r.png",[120,105,90]]],"wk":"Rammus","p":"img/champ/rammus.png","tip":[["Güç Topu etkili bir kaçış mekanizması olarak kullanılabilir.","Kendi kulenin yanındayken rakip şampiyon üzerinde kışkırtma kullanmak, kulenin rakibe saldırmasına neden olabilir.","Sarsıntı ve Tortop oyunun sonlarına doğru kuleleri yok etmek için kullanılabilir. Bir takım savaşında çıkmaza girdiysen, çoğu zaman oradan çıkıp binalara saldırmak daha iyidir."],["Tortop kapalıyken özellikle dikkat etmelisin. Duruşunu kaybettiğinde Rammus'un nitelikleri normal bir tanktan çok daha düşüktür.","Rammus genelde yüksek zırh toplar; bu da Tortop'ta değilken onu büyü yapanların verdiği hasara karşı savunmasız bırakır."]]},"reksai":{"id":"RekSai","k":421,"n":"Rek'Sai","en":"Rek'Sai","t":"Yeraltındaki Dehşet","cls":["Fighter","Tank"],"d":1,"res":"Hiddet","b":{"hp":600,"hpL":99,"ar":35,"arL":4.5,"mr":32,"mrL":2.05,"ad":62,"adL":3,"as":0.667,"asR":0.666999995708465,"asL":2,"rng":175,"ms":340,"t":"P"},"ab":[["Xer'Sai'nin Öfkesi","P","Rek'Sai saldırılarını ve temel yeteneklerini hedeflere isabet ettirerek öfke biriktirir. Gömülü haldeyken bu öfkeyi tüketerek can yeniler.","img/abil/reksai-p.png"],["Kraliçe'nin Gazabı / Avına Güdümlü","Q","Rek'Sai'nin bir sonraki 3 normal saldırısı, yakındaki rakiplere ilave fiziksel hasar verir. Gömülü haldeyken Rek'Sai'nin fırlattığı Hiçlik enerjisi yüklü toprak parçaları, isabet ettikleri rakiplere hasar verir ve onları açığa çıkarır.","img/abil/reksai-q.png",[4,3.5,3,2.5,2]],["Gömül / Yüzeye Çık","W","Rek'Sai yerin altına gömülerek yeni yetenekler elde eder ve hareket hızı kazanır. Görüş menzili azalır ve normal saldırılarını kullanamaz. Gömülü haldeyken Rek'Sai, Yüzeye Çık kullanarak yakınındaki rakipleri havaya savurabilir ve onlara hasar verebilir.","img/abil/reksai-w.png",[4,4,4,4,4]],["Hiddetli Isırık / Tünel Kaz","E","Rek'Sai hedefini ısırarak fiziksel hasar veya azami öfkeye sahipse ilave gerçek hasar verir. Gömülü haldeyken Rek'Sai yeniden kullanılabilen, uzun ömürlü bir tünel kazar. Rakipler bu tüneli, iki girişinden birinin üstünde durarak yok edebilir.","img/abil/reksai-e.png",[6,6,6,6,6]],["Hiçlik Hücumu","R","Rek'Sai hasar verdiği rakip şampiyonları pasif şekilde işaretler. Yeteneği yeniden kullandığında kısa süreliğine hedef alınamaz hale gelip işaretli hedefin üstüne çullanır ve hedefin azami canına bağlı olarak yüksek miktarda hasar verir.","img/abil/reksai-r.png",[120,100,80]]],"wk":"Rek'Sai","p":"img/champ/reksai.png","tip":[["Tünelleri haritaya yaymak, Hiçlik Hücumu kullanmak istediğinde bol bol seçeneğin olmasını sağlar.","Haritada gezinmeye başlamadan önce Gömül kullanarak, Sarsıntı Duyusu'nun sağladığı Hareket Hızı artışından ve emniyetten faydalanabilirsin.","Sarsıntı Duyusu, yaklaşan rakipleri sana bildirebilir ve özellikle rakibinin bölgesine girdiğinde çok faydalıdır."],["Rek'Sai'nin açtığı tünellerden birini görürsen, girişlerinden herhangi biri üstünde kısa süreliğine durarak, o tüneli yok edebilirsin.","Rek'Sai'nin Öfke göstergesi doldukça, Hiddetli Isırık yeteneğinin hasarı da artar. Öfke'si doluyken Rek'Sai'ye yaklaşırken çok dikkatli olmalısın.","Rek'Sai yakınlarındaysa, senin ve takım arkadaşlarının konumunu görebilir. Rek'Sai yalnızca hareket eden birimlerin konumunu bu şekilde görebilir."]]},"rell":{"id":"Rell","k":526,"n":"Rell","en":"Rell","t":"Demir İrade","cls":["Tank","Support"],"d":2,"res":"Mana","b":{"hp":620,"hpL":104,"ar":30,"arL":4,"mr":28,"mrL":1.8,"ad":55,"adL":3,"as":0.625,"asR":0.625,"asL":2,"rng":175,"ms":315,"t":"M"},"ab":[["Kalıpları Kır","P","Rell'in saldırı ve yetenekleri isabet halinde fazladan büyü hasarı verir ve zırh ile büyü direnci çalar.","img/abil/rell-p.png"],["Parçalayan Darbe","Q","Rell bir hat üstündeki birimlere büyü hasarı vererek kalkanlarını yok eder ve onları sersemletir.","img/abil/rell-q.png",[11,10.5,10,9.5,9]],["Demirbazlık: Sert İniş","W","Binek Üstünde: Rell zırhıyla bineğinden sertçe inerek rakipleri havaya savurur ve büyük bir kalkan kazanır. Rell binek üstünde değilken zırh, büyü direnci, saldırı hızı ve saldırı menzili kazanır ancak yavaşlar. Bineksiz: Rell bineğini oluşturarak hareket hızı artışı kazanır ve saldırdığı sonraki rakibi havaya savurur.","img/abil/rell-w.png",[10,10,10,10,10]],["Son Sürat","E","Pasif: Rell çatışma dışında hareket hızı kazanır. Aktif: Rell ve bir takım arkadaşı zamanla artan hareket hızı kazanır. Bu ilave, rakiplere ve birbirlerine doğru ilerlerken ikiye katlanır. Ayrıca bir sonraki saldırısı patlayarak büyü hasarı verir.","img/abil/rell-e.png",[14,13,12,11,10]],["Manyetik Fırtına","R","Rell manyetik öfkesini serbest bırakarak yakınındaki rakipleri şiddetle kendisine doğru çeker. Ardından Rell yakınındaki rakipleri kısa süreliğine kendisine doğru sürüklemeye devam ederek onlara zamanla büyü hasarı verir.","img/abil/rell-r.png",[120,100,80]]],"wk":"Rell","p":"img/champ/rell.png","tip":[[],[]]},"renata":{"id":"Renata","k":888,"n":"Renata Glasc","en":"Renata Glasc","t":"Kimya Baronesi","cls":["Support","Mage"],"d":3,"res":"Mana","b":{"hp":545,"hpL":94,"ar":27,"arL":4.7,"mr":30,"mrL":1.3,"ad":49,"adL":3,"as":0.625,"asR":0.625,"asL":2.11,"rng":550,"ms":330,"t":"M"},"ab":[["Nüfuz","P","Renata'nın saldırıları ilave hasar verir ve rakipleri işaretler. Renata'nın takım arkadaşları işaretli rakiplere saldırarak ilave hasar verebilir.","img/abil/renata-p.png"],["Tokalaşma","Q","Renata isabet ettiği ilk rakibi sabitleyen bir atış yapar ve yeteneği yeniden kullanarak o birimi belli bir yöne savurabilir.","img/abil/renata-q.png",[16,16,16,16,16]],["Kurtarma Paketi","W","Renata bir takım arkadaşını var gücüyle savaşması için güçlendirir, ölümünü geciktirir ve bir rakibi alt etmesi halinde onu kurtarır.","img/abil/renata-w.png",[28,27,26,25,24]],["Avantaj Programı","E","Renata'nın gönderdiği kimyasal roketler, isabet ettiği takım arkadaşlarına kalkan kazandırır ve rakiplere hasar vererek onları yavaşlatır.","img/abil/renata-e.png",[14,13,12,11,10]],["Usulsüz Devralma","R","Renata isabet alan tüm rakipleri delirten bir kimyasal dalgası gönderir.","img/abil/renata-r.png",[150,130,110]]],"wk":"Renata Glasc","p":"img/champ/renata.png","tip":[[],[]]},"renekton":{"id":"Renekton","k":58,"n":"Renekton","en":"Renekton","t":"Kumların Kasabı","cls":["Fighter","Tank"],"d":1,"res":"Öfke","b":{"hp":660,"hpL":111,"ar":35,"arL":5.2,"mr":28,"mrL":2.05,"ad":69,"adL":4.15,"as":0.665,"asR":0.665000021457672,"asL":2.75,"rng":125,"ms":345,"t":"P"},"ab":[["Hiddet Saltanatı","P","Renekton'un saldırıları öfke üretir. Canı azken ürettiği öfke artar. Bu öfke, yeteneklerini ilave etkilerle güçlendirebilir.","img/abil/renekton-p.png"],["Ezik Katili","Q","Renekton bıçağını savurarak çevresindeki bütün hedeflere ortalama hasar verir ve verdiği hasarın küçük bir miktarı kadar iyileşir. Öfke değeri 50'den fazlaysa, verdiği hasar ve iyileşme miktarı artar.","img/abil/renekton-q.png",[7,7,7,7,7]],["İnsafsız Yırtıcı","W","Renekton hedefini iki defa biçerek ortalama fiziksel hasar verir ve onu 0,75 saniyeliğine sersemletir. Renekton'un Öfke değeri 50'nin üstündeyse şampiyon hedefini üç defa biçerek hedefin üstündeki kalkanları yok eder, ona fiziksel hasar verir ve onu 1,5 saniyeliğine sersemletir.","img/abil/renekton-w.png",[16,14,12,10,8]],["Kes Biç","E","Renekton yerinden fırlayarak yoluna çıkan birimlere hasar verir. Renekton güçlendiğinde ek hasar verir ve isabet alan birimlerin Zırh değerini azaltır.","img/abil/renekton-e.png",[16,14.5,13,11.5,10]],["Sahip","R","Renekton Zorba'ya dönüşerek ek Can kazanır ve çevresindeki rakiplere hasar verir. Bu biçimdeyken, Renekton düzenli aralıklarla Öfke kazanır.","img/abil/renekton-r.png",[120,100,80]]],"wk":"Renekton","p":"img/champ/renekton.png","tip":[["Kes Biç, rahatsız edici manevralarda çok üstündür. Önce Kes, başka bir beceri kullan ve Biçerek geri çekilip güvenliğe ulaş.","Çarpışmanın ortasında kullanıldığında Ezik Katili çok büyük ölçüde can emer. Bunu rakiplerine olduğundan daha zayıf görünmek için kullanabilirsin.","Hem çabucak güçlü hale gelmek hem de Öfke'yi kullanmaya izin verdiğinden bekleme süresini azaltmak Renekton için özellikle iyidir."],["Saldırmak üzere olduğunu işaret edeceğinden Renekton'un Öfke ölçeğine dikkat et.","Renekton'a sürekli sataşarak, savaşmasını ve Öfke kazanmasını engellemek, yeteneklerinin etkinliğini düşürecektir."]]},"rengar":{"id":"Rengar","k":107,"n":"Rengar","en":"Rengar","t":"Gölge Avcı","cls":["Assassin","Fighter"],"d":3,"res":"Hırs","b":{"hp":590,"hpL":104,"ar":34,"arL":4.2,"mr":32,"mrL":2.05,"ad":68,"adL":3,"as":0.667,"asR":0.666999995708465,"asL":3,"rng":125,"ms":345,"t":"P"},"ab":[["Görünmez Yırtıcı","P","Rengar çalıdayken normal saldırı gerçekleştirdiğinde hedefinin üzerine atlar. Rengar her yetenek kullandığında Vahşet yükü kazanır. Azami Vahşet yüküne ulaştığında bir sonraki yeteneği güçlenir. Rakip şampiyonları katletmek Rengar'ın Kemikdiş Kolye'sine bir ganimet ekleyerek ilave saldırı gücü sağlar.","img/abil/rengar-p.png"],["Yabani","Q","Rengar'ın bir sonraki saldırısı hedefini acımasızca deşerek ilave hasar verir. Vahşet etkisi: Fazladan hasar verir ve saldırı hızı sağlar.","img/abil/rengar-q.png",[0.25,0.25,0.25,0.25,0.25]],["Savaş Kükremesi","W","Rengar savaş gazabıyla kükreyerek rakiplere hasar verir ve belli bir süre önce aldığı hasarın bir kısmını iyileştirir. Vahşet etkisi: Ayrıca kitle kontrolü etkilerini bozar.","img/abil/rengar-w.png",[0.25,0.25,0.25,0.25,0.25]],["Bola Atışı","E","Rengar'ın fırlattığı bola, ilk isabet ettiği hedefi kısa süreliğine yavaşlatır. Vahşet etkisi: Hedefi yere sabitler.","img/abil/rengar-e.png",[0.25,0.25,0.25,0.25,0.25]],["Av Heyecanı","R","Rengar yırtıcı içgüdülerini harekete geçirerek kamuflaja bürünür ve çevresindeki geniş bir alanda bulunan en yakın rakip şampiyonu görür. Av Heyecanı etkin olduğu sürece Rengar hareket hızı kazanır ve bu esnada çalıda olmasa bile izini sürdüğü hedefin üstüne atlayıp zırhını azaltabilir.","img/abil/rengar-r.png",[100,90,80]]],"wk":"Rengar","p":"img/champ/rengar.png","tip":[["Rengar'ın ulti yeteneğini kullanarak takım dövüşlerinde ve çatışmalarda yüksek öncelikli hedefleri bulup avlayabilirsin.","Rengar'ın gücünün büyük bölümü, güçlendirilmiş yeteneklerini doğru anda kullanmasından kaynaklanır; iyi seçim yap!","Rengar'ın pasif yeteneğinden yararlanmak için, rakipleri kovalarken çalılıklardan geçmeye dikkat et."],["Rengar, Vahşet göstergesi dolduğunda güçlendirilmiş bir yetenek elde eder. Bu gösterge boşken karşısına çıkmaya çalış.","Rengar, pasif yeteneği sayesinde çalılığın içinden atlayabilir; onunla çalılığın yakınında savaşmaktan kaçın.","Rengar, ultisi sırasında kamuflaja büründüğünde en yakın rakip şampiyonun üstünde bir gösterge belirir."]]},"riven":{"id":"Riven","k":92,"n":"Riven","en":"Riven","t":"Sürgün","cls":["Fighter","Assassin"],"d":3,"res":"Yok","b":{"hp":630,"hpL":100,"ar":33,"arL":4.4,"mr":32,"mrL":2.05,"ad":64,"adL":3,"as":0.625,"asR":0.625,"asL":3.5,"rng":125,"ms":340,"t":"P"},"ab":[["Rünlü Kılıç","P","Riven'ın yetenekleri, kılıcı için yükler biriktirir. Şampiyonun normal saldırıları yükleri tüketerek fazladan hasar verir.","img/abil/riven-p.png"],["Kırık Kanatlar","Q","Riven bir dizi saldırıya geçer. Bu yetenek kısa süre içinde üç kez aktifleştirilebilir ve üçüncü darbe, yakındaki rakipleri geri savurur.","img/abil/riven-q.png",[13,13,13,13,13]],["Ki Patlaması","W","Riven bir Ki Patlaması yaratarak, yakınındaki rakiplerin hasar alıp sersemlemelerine neden olur.","img/abil/riven-w.png",[11,10,9,8,7]],["Yiğitlik","E","Riven kısa bir mesafe ileri sıçrayarak, gelen hasarı engeller.","img/abil/riven-e.png",[10,9,8,7,6]],["Sürgün Kılıcı","R","Riven yadigâr silahını enerjiyle yükler ve Saldırı Gücü ile Menzil kazanır. Ayrıca, bu süre boyunca güçlü bir menzilli saldırı olan Rüzgâr Darbesi'ni bir defaya mahsus olarak kullanabilir.","img/abil/riven-r.png",[120,90,60]]],"wk":"Riven","p":"img/champ/riven.png","tip":[["Riven'ın Kırık Kanatlar yeteneği, büyünün yapılması sırasında imlecin üzerindeki şampiyona kilitlenir. Rakibini geçip gitmek istiyorsan, imlecin de rakibini geçtiğinden emin ol.","Riven bir iyileşme kaynağı ya da güçlü savunmadan yoksundur ve kombo patlamalarıyla durumu denkleştirmelidir. Yiğitlik'i kaçmak ve karşıdan gelen hasarları emmek için kullanırken, Kırık Kanatlar ve Ki Patlaması ile dövüşlere öncülük edebilirsin."],["Riven'ın hareket kabiliyeti çok yüksektir ama herhangi bir beceriyle çok uzaklara ilerleyemez. Kombosu sırasında onu yerine sabitleyerek ya da susturarak etkinliğini büyük ölçüde düşürebilirsin.","Riven'ın verdiği tüm hasarlar fizikseldir; rakip takımdaki bir Riven kontrolden çıkarsa, Zırh değerini yükseltmeyi öncelik haline getir.","Hepsine neredeyse aynı hasarı vereceğinden, Riven birden fazla rakibiyle yakın dövüşe girerse üstün çıkar. Riven'a karşı iki kişiyseniz, tam kombosunu harcamadan yakın dövüşe girmeyin."]]},"rumble":{"id":"Rumble","k":68,"n":"Rumble","en":"Rumble","t":"Mekanize Bela","cls":["Fighter","Mage"],"d":3,"res":"Isı","b":{"hp":640,"hpL":105,"ar":36,"arL":4.7,"mr":28,"mrL":1.55,"ad":64,"adL":3.2,"as":0.644,"asR":0.643999993801116,"asL":1.85,"rng":125,"ms":345,"t":"M"},"ab":[["Hurdalık Devi","P","Rumble'ın kullandığı her yetenek ona ısı verir. %50 Isıya ulaştığında Tehlike Bölgesi'ne girer ve tüm temel yetenekleri ilave etkiler kazanır. %100 Isıya ulaştığında motoru hararet yapar. Bu, ilave saldırı hızı kazandırır ve normal saldırılarının ilave hasar vermesini sağlar ama Rumble'ın yetenek kullanmasını birkaç saniyeliğine engeller.","img/abil/rumble-p.png"],["Alev Makinesi","Q","Rumble önünde koni şeklinde bir alandaki rakiplerini ateşe verir ve 3 saniyeliğine büyü hasarı almalarına yol açar. Tehlike Bölgesi'ndeyken bu hasar artar.","img/abil/rumble-q.png",[10,9,8,7,6]],["Hurda Kalkan","W","Rumble onu hasara karşı koruyan ve kısa bir hız artışı kazanmasını sağlayan bir kalkan oluşturur. Tehlike Bölgesi'ndeyken, kalkan güç kazanır ve sağladığı ek hız artar.","img/abil/rumble-w.png",[6,6,6,6,6]],["Elektro Zıpkın","E","Rumble'ın fırlattığı zıpkın hedefinin çarpılarak büyü hasarı almasına, yavaşlamasına ve büyü direncinin azalmasına neden olur. Rumble aynı anda 2 zıpkın taşıyabilir. Tehlike Bölgesi'ndeyken söz konusu hasar ve yavaşlatma etkisi artar.","img/abil/rumble-e.png",[0.5,0.5,0.5,0.5,0.5]],["Dengeleyici","R","Rumble hat halinde düşen bir dizi füze ateşleyerek, rakiplerin hasar görmesine ve yavaşlamasına yol açan ateşten bir yüzey yaratır.","img/abil/rumble-r.png",[130,105,80]]],"wk":"Rumble","p":"img/champ/rumble.png","tip":[["Etkisini en yükseğe çıkartabilmek için Tehlike Bölgesi'nin içerisinde kalmaya çalış. Yeteneklerini çok arka arkaya kullanırsan moturunun Hararer yapması kaçınılmazdır.","Hedeflerini Alev Makinesi'nin menzilinde tutmaya çalış. Alev Makinesi zamanla çok fazla hasar verebilir.","Bir dövüşü kazanıyorsan ultini kullanarak rakibin kaçış yolunu tıkayabilirsin."],["Gözün Rumble'ın Isı göstergesinin üzerinde olsun. Motoru Hararet yaptığında Rumble'ın yetenekleri devre dışı olacağından, bu aralık onu katletmek için en iyi fırsattır.","Rumble'ın ultisi, etki alanı içerisindeysen çok büyük hasar verebilir. Füzelerin düştüğünü görürsen, olabildiğince çabuk kaç.","Rumble neredeyse tamamen büyü hasarı verir. Hasarı azaltmak için Büyü Direnci sağlayan eşyalara ağırlık ver."]]},"ryze":{"id":"Ryze","k":13,"n":"Ryze","en":"Ryze","t":"Rün Büyücüsü","cls":["Mage"],"d":3,"res":"Mana","b":{"hp":620,"hpL":124,"ar":22,"arL":4.7,"mr":32,"mrL":1.3,"ad":55,"adL":3,"as":0.658,"asR":0.625,"asL":2.11,"rng":550,"ms":340,"t":"M"},"ab":[["Büyü Ustalığı","P","Ryze'ın yetenekleri ilave mana miktarına bağlı olarak fazladan hasar verir ve Ryze'ın azami manası yetenek gücüne bağlı olarak belli bir oranda artar.","img/abil/ryze-p.png"],["Aşırı Yük","Q","Ryze'ın diğer temel yetenekleri pasif olarak Aşırı Yük'ün bekleme süresini sıfırlar ve bir rün yükler. Ryze, 2 rün yüklüyken Aşırı Yük kullandığında kısa süreliğine hareket hızı kazanır. Aşırı Yük yeteneği kullanıldığında Ryze hedef yöne bir saf enerji atışı yapar ve atış isabet ettiği ilk hedefe hasar verir. Eğer hedef Akı Damgası etkisi altındaysa, Aşırı Yük ilave hasar verir ve yakındaki Akı Damgası ile işaretlenmiş diğer rakiplere sıçrar.","img/abil/ryze-q.png",[5,5,5,5,5]],["Rün Hapsi","W","Ryze, hedefini rünlerden oluşan bir kafese hapseder. Hedef hasar alır ve hareket hızı kaybeder. Eğer hedef Akı Damgası etkisi altındaysa yavaşlamak yerine sabitlenir.","img/abil/ryze-w.png",[11,10.5,10,9.5,9]],["Büyü Akışı","E","Ryze'ın fırlattığı saf büyü gücünden oluşan küre, isabet ettiği rakibin hasar almasına ve çevredeki bütün rakiplerin zayıflamasına yol açar. Ryze'ın yetenekleri, zayıflayan rakibe karşı ek etkiler kazanır.","img/abil/ryze-e.png",[3.5,3.25,3,2.75,2.5]],["Mekân Sapması","R","Aşırı Yük, Akı Damgası etkisi altındaki rakiplere pasif olarak daha fazla hasar verir. Kullanıldığında Ryze yakındaki bir konuma açılan bir geçit oluşturur. Birkaç saniye sonra geçidin yakınındaki takım arkadaşları hedef konuma ışınlanır.","img/abil/ryze-r.png",[180,160,140]]],"wk":"Ryze","p":"img/champ/ryze.png","tip":[["Aşırı Yük'ün pasifini en yüksek hasarı verecek ya da en fazla hızı sağlayacak şekilde kullanmaya çalış.","Büyü Akışı'nın kısa bekleme süresi, Akı Damgası'nı çok sayıda rakibe yaymaya olanak sağlar.","Ryze, Mekân Sapması güç toplarken hareket edebilir ve başka yetenekler kullanabilir."],["Ryze, Akı Damgası ile işaretlenen rakiplere karşı özellikle tehlikelidir.","Mekân Sapması'nın tamamlanmasına kadar geçen süreyi, geçitten çıkabilecek rakiplerine nasıl karşı koyacağını tasarlamak için kullan.","Mekân Sapması hazırlandığı sırada Ryze kitle kontrol etkisi altına alınırsa geçidin açılması engellenir."]]},"samira":{"id":"Samira","k":360,"n":"Samira","en":"Samira","t":"Çöl Gülü","cls":["Marksman","Assassin"],"d":2,"res":"Mana","b":{"hp":630,"hpL":108,"ar":26,"arL":4.7,"mr":33,"mrL":1.1,"ad":57,"adL":3,"as":0.658,"asR":0.658,"asL":3.3,"rng":500,"ms":335,"t":"P"},"ab":[["Deliduman","P","Samira saldırılarını veya isabet eden bir önceki yeteneğinden farklı olan yeteneklerini isabet ettirerek bir kombo yapar. Samira'nın yakın dövüş menzilinden gerçekleştirdiği saldırılar fazladan büyü hasarı verir. Samira'nın hareketsiz bırakılan rakiplere yönelik saldırıları, onun atılarak rakipleri saldırı menziline sokmasını sağlar. Eğer rakip havaya savrulmuşsa kendisi de onu kısa süreliğine havaya savurur.","img/abil/samira-p.png"],["Gösteriş","Q","Samira ateş ederek veya kılıcını savurarak hasar verir. Yetenek Heyecan Dorukta sırasında kullanılırsa, tamamlandığında yolundaki tüm rakiplere saldırır.","img/abil/samira-q.png",[6,5,4,3,2]],["Kılıç Girdabı","W","Samira kılıcını etrafında savurarak rakiplere hasar verir ve onların atışlarını engeller.","img/abil/samira-w.png",[30,28,26,24,22]],["Heyecan Dorukta","E","Samira bir rakibin üstünden geçer (yapılar dahil). Üstünden geçtiği rakiplere kılıcıyla saldırır ve saldırı hızı kazanır. Bir rakip şampiyonu katletmek bu yeteneğin bekleme süresini sıfırlar.","img/abil/samira-e.png",[20,18,16,14,12]],["Cehennem Tetiği","R","Samira tabancalarıyla art arda ateş ederek çevresindeki tüm rakiplere amansızca saldırır.","img/abil/samira-r.png",[5,5,5]]],"wk":"Samira","p":"img/champ/samira.png","tip":[[],[]]},"sejuani":{"id":"Sejuani","k":113,"n":"Sejuani","en":"Sejuani","t":"Kuzeyin Hiddeti","cls":["Tank"],"d":2,"res":"Mana","b":{"hp":630,"hpL":114,"ar":34,"arL":5.45,"mr":32,"mrL":2.05,"ad":66,"adL":4,"as":0.688,"asR":0.625,"asL":3.5,"rng":150,"ms":340,"t":"M"},"ab":[["Kuzeyin Hiddeti","P","Sejuani çatışmadan çıktıktan sonra ona zırh ve büyü direncinin yanı sıra yavaşlatma etkilerine karşı bağışıklık sağlayan Buz Zırh kazanır. Buz Zırh, Sejuani hasar aldıktan sonra kısa bir süreliğine daha devam eder. Sejuani, sersemlemiş bir rakibe hasar vererek onu parçalayabilir ve hedefin büyük miktarda büyü hasarı almasını sağlar.","img/abil/sejuani-p.png"],["Kutup Saldırısı","Q","Sejuani ileri hücum ederek rakiplerinin havaya savrulmalarını sağlar. Bir rakip şampiyona isabet ettiğinde hücum sona erer.","img/abil/sejuani-q.png",[18,16.5,15,13.5,12]],["Kışın Gazabı","W","Sejuani gürzünü iki defa savurarak hasar verir, rakipleri yavaşlatır ve buz yükü oluşturur.","img/abil/sejuani-w.png",[9,8,7,6,5]],["Yoğun Buz","E","Sejuani en fazla buz yükü taşıyan rakip şampiyonu dondurup sersemletir.","img/abil/sejuani-e.png",[1.5,1.5,1.5,1.5,1.5]],["Buzul Hapsi","R","Sejuani bolasını atarak isabet alan ilk şampiyonu dondurup sersemletir ve diğer rakipleri yavaşlatan bir buz fırtınası ortaya çıkarır.","img/abil/sejuani-r.png",[120,105,90]]],"wk":"Sejuani","p":"img/champ/sejuani.png","tip":[["Kutup Saldırısı'nı kötü durumlardan kaçmak, yoğunlaşılan yetenekleri engellemek ya da kaçanları kovalamak için kullan.","Yakın dövüşçü takım arkadaşların Yoğun Buz yeteneğin için buz yükü biriktirebilir; bu yüzden kime saldırdıklarını iyi takip et.","Buzul Hapsi'ni çevrende takım arkadaşlarının da bulunduğu ve yararlanabileceği karşılaşmalar için sakla."],["Kutup Saldırısı ve Buzul Hapsi'ni savuşturmak sana büyük avantaj sağlayabilir.","Kışın Gazabı'nın ikinci vuruşundan sakınmaya odaklan çünkü hasarın büyük bölümünü bu vuruş verir.","Yakın dövüşçü rakipler de Sejuani için buz yükü biriktirebilir. Yakınlarında onlar varken çok dikkatli ol."]]},"senna":{"id":"Senna","k":235,"n":"Senna","en":"Senna","t":"Arındırıcı","cls":["Support","Marksman"],"d":3,"res":"Mana","b":{"hp":530,"hpL":89,"ar":25,"arL":4,"mr":33,"mrL":1.1,"ad":50,"adL":0,"as":0.625,"asR":0.4,"asL":2.6,"rng":600,"ms":330,"t":"P"},"ab":[["Bağışlama","P","Senna'nın yakınında katledilen birimlerin ruhları düzenli olarak Kara Sis'e hapsolur. Senna bu ruhlara saldırarak onları serbest bırakabilir ve onları ölümde bile tutsak eden sisi soğurabilir. Sis yadigâr topun gücünü arttırarak ona saldırı gücü, saldırı menzili ve kritik vuruş ihtimali kazandırır. Senna'nın yadigâr topu daha uzun sürede ateşlenir, ilave hasar verir ve kısa süreliğine hedefinin hareket hızının bir kısmını kazandırır.","img/abil/senna-p.png"],["Deşen Karanlık","Q","Senna yadigâr topunun çift namlusundan ışık ile gölgeden oluşan ve hedefin içinden geçen bir ışın ateşler. Bu ışın isabet ettiği takım arkadaşlarını iyileştirir ve rakiplere hasar verir.","img/abil/senna-q.png",[15,15,15,15,15]],["Son Kavuşma","W","Senna ileri doğru bir Kara Sis dalgası gönderir. Bir rakibe isabet ettiğinde ona yapışır. Kısa bir gecikmenin ardından onu ve yakındaki diğer tüm hedefleri sabitler.","img/abil/senna-w.png",[11,11,11,11,11]],["Kara Sis'in Laneti","E","Senna silahında biriktirdiği sisi kendi etrafındaki bir fırtınaya dönüştürerek karanlığı benimser ve hayalete dönüşür. Alana giren takım arkadaşları kamuflaja bürünür ve sis onların da hayalet gibi görünmesini sağlar. Hayaletler kimliklerini saklar, hedef alınamaz ve hareket hızı artışı kazanır.","img/abil/senna-e.png",[26,24.5,23,21.5,20]],["Gölgelerin Şafağı","R","Senna ölen Işık Muhafızlarının kullandığı yadigâr taşların gücünü çağırarak yadigâr topunu gölge ve ışıktan oluşan kutsal bir silaha dönüştürür. Daha sonra takım arkadaşlarını koruyan ve merkezinde bulunan rakiplere hasar veren, haritayı baştan başa geçen bir ışın ateşler.","img/abil/senna-r.png",[140,120,100]]],"wk":"Senna","p":"img/champ/senna.png","tip":[[],[]]},"seraphine":{"id":"Seraphine","k":147,"n":"Seraphine","en":"Seraphine","t":"Yükselen Yıldız","cls":["Support","Mage"],"d":2,"res":"Mana","b":{"hp":570,"hpL":95,"ar":26,"arL":4.2,"mr":30,"mrL":1.3,"ad":50,"adL":3,"as":0.669,"asR":0.625,"asL":2,"rng":525,"ms":330,"t":"M"},"ab":[["Sahne Tozu","P","Seraphine'in her üçüncü temel yeteneği iki defa gerçekleşir. Ayrıca takım arkadaşlarının yakınında yetenek kullanmak onların bir sonraki normal saldırılarının ilave büyü hasarı ve menzil kazanmasını sağlar.","img/abil/seraphine-p.png"],["Yüksek Perde","Q","Seraphine bir alana hasar verir.","img/abil/seraphine-q.png",[8,7.5,7,6.5,6]],["Saran Ses","W","Seraphine yakınındaki takım arkadaşlarına kalkan verir ve onları hızlandırır. Kendisi zaten bir kalkana sahipse, yakınındaki takım arkadaşlarını iyileştirir.","img/abil/seraphine-w.png",[22,22,22,22,22]],["Sert Ritim","E","Seraphine bir hat üstündeki rakiplere hasar verir ve onların hareketini kısıtlar.","img/abil/seraphine-e.png",[11,11,11,11,11]],["Bis","R","Seraphine yeteneğin isabet ettiği rakiplere hasar verir ve onları ayartır. Yeteneğin menzil etkisi isabet alan her takım arkadaşı ve rakip şampiyon başına yenilenir.","img/abil/seraphine-r.png",[160,140,120]]],"wk":"Seraphine","p":"img/champ/seraphine.png","tip":[[],[]]},"sett":{"id":"Sett","k":875,"n":"Sett","en":"Sett","t":"Patron","cls":["Fighter","Tank"],"d":1,"res":"İnat","b":{"hp":670,"hpL":114,"ar":33,"arL":4.7,"mr":28,"mrL":2.05,"ad":60,"adL":4,"as":0.625,"asR":0.625,"asL":1.75,"rng":125,"ms":340,"t":"P"},"ab":[["Dövüşçü İnadı","P","Sett normal saldırılarını gerçekleştirirken bir sol, bir de sağıyla vurur. Sağ yumruğu biraz daha güçlü ve hızlıdır. Ayrıca Sett kaybetmekten nefret eder ve eksik canına bağlı olarak fazladan can yenilenmesi kazanır.","img/abil/sett-p.png"],["Yapıştır","Q","Sett'in sonraki iki saldırısı, hedefin azami canına bağlı olarak fazladan hasar verir. Ayrıca Sett rakip şampiyonlara doğru hareket ederken hareket hızı artışı kazanır.","img/abil/sett-q.png",[9,8,7,6,5]],["Balyoz Gibi","W","Sett aldığı hasarı inat olarak biriktirir. Yetenek kullanıldığında Sett biriktirdiği tüm inadı harcayarak bir kalkan kazanır ve belli bir alana yumruğuyla vurur. Orta hat üstündeki rakipler gerçek hasar, yan hatlardaki rakiplerse fiziksel hasar alır.","img/abil/sett-w.png",[18,16.5,15,13.5,12]],["Surat Dağıtan","E","Sett iki yanında duran tüm rakipleri çekerek onlara hasar verir ve onları sersemletir. Eğer rakipler sadece tek bir yandaysa, sersemletilmek yerine yavaşlatılırlar.","img/abil/sett-e.png",[16,14.5,13,11.5,10]],["Yürek Hoplatan","R","Sett bir rakip şampiyonu kavrayarak havaya zıplar ve daha sonra onu yere savurur. Hedef ve hedefin düştüğü konumun yakınındaki tüm rakipler hasar alır ve yavaşlar.","img/abil/sett-r.png",[120,100,80]]],"wk":"Sett","p":"img/champ/sett.png","tip":[[],[]]},"shaco":{"id":"Shaco","k":35,"n":"Shaco","en":"Shaco","t":"İblis Soytarı","cls":["Assassin"],"d":3,"res":"Mana","b":{"hp":630,"hpL":99,"ar":30,"arL":4,"mr":32,"mrL":2.05,"ad":63,"adL":3,"as":0.694,"asR":0.694000005722045,"asL":3,"rng":125,"ms":345,"t":"P"},"ab":[["Arkadan Vuruş","P","Shaco'nun normal saldırıları ve Çift Zehirli Bıçak yeteneği arkadan saldırırken fazladan hasar verir.","img/abil/shaco-p.png"],["Kandırmaca","Q","Shaco görünmez olur ve hedef konuma ışınlanır. Görünmez haldeyken yaptığı ilk normal saldırı güçlenerek ilave hasar verir ve arkadan gerçekleştirildiğinde kritik vuruş yapar.","img/abil/shaco-q.png",[13,12.5,12,11.5,11]],["Soytarı Kutusu","W","Shaco gizli bir canlı Soytarı Kutusu ortaya çıkarır. Soytarı Kutusu tetiklendiğinde yakındaki rakipleri korkutup onlara saldırır.","img/abil/shaco-w.png",[15,15,15,15,15]],["Çift Zehirli Bıçak","E","Shaco'nun bıçakları isabet ettikleri hedefleri pasif olarak zehirleyerek hareket hızlarını düşürür. Shaco bıçaklarını fırlatarak hedefine hasar verebilir ve onu zehirleyebilir. Fırlatılan bıçak, hedefin canı %30'un altındaysa ilave hasar verir.","img/abil/shaco-e.png",[8,8,8,8,8]],["Halüsinasyon","R","Shaco, hemen yanında kendi görüntüsünü içeren bir yanılsama oluşturur. Bu yanılsama, rakiplere saldırabilir (kulelere daha az hasar verir). Yanılsama katledildiğinde patlar ve üç minik Soytarı Kutusu ortaya çıkararak yakındaki rakiplere hasar verir.","img/abil/shaco-r.png",[100,90,80]]],"wk":"Shaco","p":"img/champ/shaco.png","tip":[["Kandırmaca'yı arazide kullanmak temiz bir kaçış yolu sağlayabilir.","Hasar verildiğinde etki bırakan eşyalar satın almaya çalış. Bunlar Halüsinasyon klonuna da yarar sağlayacaktır.","Arkadan Vuruş'un hasarı, Ebedi Kılıç gibi kritik hasarı arttıran etkilerle yükseltilebilir."],["Shaco oyunun başlarında iyi gidiyorsa, orman kamplarının yakınlarına koymak için Görünmez Totem satın almak doğru bir yatırım olacaktır.","Shaco Kandırmaca'yı bir dövüşe girmek için kullanırsa, onu dövüşten kaçmak için hemen kullanamayacaktır. Takımınla onu çabucak alt etmeye odaklan."]]},"shen":{"id":"Shen","k":98,"n":"Shen","en":"Shen","t":"Alacakaranlığın Gözü","cls":["Tank"],"d":2,"res":"Enerji","b":{"hp":610,"hpL":99,"ar":34,"arL":4.2,"mr":32,"mrL":2.05,"ad":64,"adL":3,"as":0.751,"asR":0.651000022888183,"asL":3,"rng":125,"ms":340,"t":"P"},"ab":[["Ki Kalkanı","P","Shen yetenek kullandıktan sonra bir kalkan kazanır. Diğer şampiyonları etkilemek, bu kalkanın bekleme süresini azaltır.","img/abil/shen-p.png"],["Alacakaranlık Saldırısı","Q","Shen ruhani kılıcını saldırılarında kullanmak için geri çağırır ve hedefinin azami can miktarına bağlı olarak hasar verir. Kılıç bir şampiyona çarparsa saldırılar büyük oranda güçlenir ve kılıcın çarptığı bütün şampiyonlar, Shen'den uzaklaşırken yavaşlar.","img/abil/shen-q.png",[8,7.25,6.5,5.75,5]],["Ruh Sığınağı","W","Shen veya ruhani kılıcının çevresindeki takım arkadaşlarına yönelik saldırılar önlenir.","img/abil/shen-w.png",[16,14.5,13,11.5,10]],["Gölge Fırlayışı","E","Shen belli bir yöne atılarak yoluna çıkan rakipleri kışkırtır.","img/abil/shen-e.png",[18,16,14,12,10]],["Birlikten Kuvvet Doğar","R","Shen seçilen takım arkadaşını gelen hasarlara karşı korur ve kısa süre sonra da hedef şampiyonun yanına ışınlanır.","img/abil/shen-r.png",[200,180,160]]],"wk":"Shen","p":"img/champ/shen.png","tip":[["Gözün takım arkadaşlarının üstünde olsun ve ışınlanarak onları kurtarmaya hazır ol.","Enerjini, Mana kullanan şampiyonlara karşı uzun vadede avantaj elde etmeni sağlayan bir koz olarak kullan."],["Shen'in kışkırtmasını savuşturmaya ve ıskalarsa cezasını kesmeye hazır ol.","Shen 6. seviyeye ulaştığı zaman çatışmaların gidişatını bir anda değiştirebilen küresel ultisine dikkat et."]]},"shyvana":{"id":"Shyvana","k":102,"n":"Shyvana","en":"Shyvana","t":"Ejder Kanı","cls":["Fighter","Tank"],"d":2,"res":"Öfke","b":{"hp":625,"hpL":95,"ar":35,"arL":4,"mr":32,"mrL":2.05,"ad":62,"adL":4,"as":0.638,"asR":0.638,"asL":2,"rng":150,"ms":350,"t":"P"},"ab":[["Pulzırh","P","Rakip şampiyon, büyük minyon ve büyük canavar alt etmek Shyvana'ya Pulzırh yükü kazandırarak dirençlerini arttırır.","img/abil/shyvana-p.png"],["Kor Darbesi","Q","Shyvana'nın bir sonraki saldırısı hem hedefine hem de etrafındaki alana hasar verir. Bu yetenek yeniden kullanılabilir. Ejderha biçimindeyken bir hedefe yüksek miktarda hasar veren bir yeniden kullanım daha kazanır.","img/abil/shyvana-q.png",[10,9,8,7,6]],["Ateşten Siper","W","Shyvana kalkan ve hareket hızı kazanır. Ayrıca kısa bir gecikmenin ardından etrafındaki alan infilak eder. Ejderha biçimindeyken bu patlamayı bir rakip şampiyona isabet ettirirse can yeniler.","img/abil/shyvana-w.png",[13,12.25,11.5,10.75,10]],["Magma Topu","E","Shyvana büyük bir hedefe çarpınca patlayan ve onu yavaşlatan bir ateş topu gönderir. Ejderha biçimindeyken bu ateş topu rakip birimlerin içinden geçer, büyük bir rakibe çarpınca patlar ve ardında ateşten bir iz bırakır.","img/abil/shyvana-e.png",[12,11,10,9,8]],["Ejder Dalışı","R","Shyvana bir ejderhaya dönüşür ve ileri atılarak yolundaki rakiplerin kaçmasına neden olur. Ejderha biçimindeyken büyür ve temel yetenekleri güçlenir.","img/abil/shyvana-r.png",[0,0,0]]],"wk":"Shyvana","p":"img/champ/shyvana.png","tip":[["Shyvana'nın yeteneklerinin hepsi saldıran birimlerden yararlanabilir. Sonuç olarak, Saldırı Hızı'nı arttıran eşyalar onun için çoğu şampiyondan daha değerlidir.","Alevli Nefes, zorlu koridor rakiplerine karşı seviye atlamak için çok iyidir.","Ateş Burgacı ormanda dolaşmak için ideal bir seçimdir. Canavarlar etki süresi boyunca hasar alırlar ve hız patlaması da ani saldırı potansiyelini arttırır.","Rakipleri yavaşlatan şu eşyalardan birini satın almak yararlı olabilir: Donmuş Balyoz, Ölü Adamın Zırhı veya Entropi."],["Shyvana'nın gücünün büyük bir bölümü saldırganlıktan gelir, mesafesini koruyan rakiplere karşı zayıf kalır.","Shyvana'nın tüm temel yetenekleri ejderha biçiminde birden fazla rakibe vurur. Onunla savaşırken rakip şampiyonların grup halinde durmaması önemlidir.","Shyvana'nın öfke göstergesi, ultisinin ne zaman etkinleştirilebileceğini gösterir. Öfkesi azken onu hırpalamak çok etkili olabilir."]]},"singed":{"id":"Singed","k":27,"n":"Singed","en":"Singed","t":"Deli Kimyager","cls":["Tank","Mage"],"d":2,"res":"Mana","b":{"hp":650,"hpL":96,"ar":34,"arL":4.2,"mr":32,"mrL":2.05,"ad":63,"adL":3.4,"as":0.7,"asR":0.69,"asL":1.9,"rng":125,"ms":345,"t":"M"},"ab":[["Akışkan Zehir","P","Singed yakınındaki şampiyonlardan hız alarak onları geçerken anlık bir hareket hızı artışı kazanır.","img/abil/singed-p.png"],["Zehirli İz","Q","Singed'in arkasında bıraktığı zehir bulutu, içinde kalan rakiplere hasar verir.","img/abil/singed-q.png",[0,0,0,0,0]],["Kuvvetli Zamk","W","Yere bir şişe kuvvetli zamk atarak üstünden geçen rakiplerin yavaşlamasını ve yere saplanmasını sağlar.","img/abil/singed-w.png",[17,16,15,14,13]],["Tut Savur","E","Hedef birime hasar vererek, onu kaldırıp Singed'in arkasına savurur. Singed'in savurduğu hedef Kuvvetli Zamk'ın üstüne inerse yere sabitlenir.","img/abil/singed-e.png",[10,9.5,9,8.5,8]],["Delilik İksiri","R","Singed'in içtiği güçlü kimyasal karışım, çatışma niteliklerinin artmasını ve Zehirli İz yeteneğinin Ağır Yara açmasını sağlar.","img/abil/singed-r.png",[100,100,100]]],"wk":"Singed","p":"img/champ/singed.png","tip":[["Singed'in bulunduğu koridordaki olaylara egemen olamasına izin verdiği için, Zehirli İz, biçme ve rahatsız etmekte çok etkilidir.","Delilik iksirini kullanarak rakiplerini Zehirli İz'e yönelt.","Kulelere doğru Tut Savur yapmak, rakiplerine büyük hasar verebilir."],["Singed'in dostlarına doğru fırlatılmamak için mesafeni koru.","Singed'in etkili olabilmesi için takımına yakın ilerlemesi gerekir. Takım arkadaşlarına saldırırken kalabalığı kontrol etme etkilerini kullanıp bunu avantaja dönüştürmeye çalış.","Singed'i kovalarken dikkatli ol.Yere sermesi çok zordur ve onu takip ederken hasar görmen için arkasında Zehirli İz'i bırakabilir."]]},"sion":{"id":"Sion","k":14,"n":"Sion","en":"Sion","t":"Ölü Dev","cls":["Tank","Fighter"],"d":2,"res":"Mana","b":{"hp":655,"hpL":95,"ar":36,"arL":4.2,"mr":32,"mrL":2.05,"ad":68,"adL":4,"as":0.679,"asR":0.67900002002716,"asL":1.3,"rng":175,"ms":345,"t":"P"},"ab":[["Ölümün Görkemi","P","Sion katledildikten sonra kendini geçici olarak yeniden canlandırır ama canı hızla azalır. Bu sırada saldırıları büyük oranda hızlanır, onu iyileştirir ve hedefinin azami canına bağlı olarak ilave hasar verir.","img/abil/sion-p.png"],["Kırıp Geçir","Q","Sion önündeki bir alanda güçlü bir vuruş yapmak için hazırlanır, hazırlanması bittiğinde vuruşunu yaparak rakiplere hasar verir. Hazırlanmaya yeteri kadar zaman ayırırsa, isabet alan rakipler ayrıca havaya savrulur ve sersemler.","img/abil/sion-q.png",[10,9,8,7,6]],["Ruh Eriten","W","Sion kalkan kazanır ve yakınındaki rakiplere büyü hasarı vermek için yeteneği 3 saniye sonra yeniden kullanabilir. Sion rakiplerini katlettikçe pasif olarak azami can kazanır.","img/abil/sion-w.png",[15,14,13,12,11]],["İnfazcının Kükremesi","E","Sion'un ateşlediği kısa menzilli şok dalgası, isabet ettiği ilk hedefe hasar verir, onu yavaşlatır ve zırhını azaltır. Şok dalgası bir minyon veya canavara isabet ederse, isabet ettiği birim geriye savrularak içinden geçtiği bütün rakiplere hasar verir, onları yavaşlatır ve zırhlarını azaltır.","img/abil/sion-e.png",[12,11,10,9,8]],["Durdurulamaz Hücum","R","Sion bir yöne doğru hücum eder ve zamanla hızını arttırır. Fare imlecinin konumu aracılığıyla hücum ettiği yönü bir miktar değiştirebilir. Bir rakibe çarptığında ona hasar verir ve hücum ettiği mesafeye bağlı olarak havaya savurur.","img/abil/sion-r.png",[140,100,60]]],"wk":"Sion","p":"img/champ/sion.png","tip":[["Durdurulamaz Hücum esnasında dönüş kabiliyeti oldukça kısıtlıdır, düz bir hat üzerinde kullanmaya gayret göster.","İnfazcının Kükremesi, aşırı güçlü bir Kırıp Geçiren saldırısı yapmak için ideal bir hazırlık yeteneğidir.","Ruh Eriten güçlendirmesi, geriye kalan kalkan gücünü gösterir, bu bilgiyi ne zaman patlayacağını hesaplamada kullan."],["Sion zamanından önce hazırlanmayı bıraktığında, Kırıp Geçiren ile vuruşunu yine de yapar ama saldırının etkisi azalır.","Sion öldüğünde fırsat varken konumunu değiştir ve dönüşü için hazırlan."]]},"sivir":{"id":"Sivir","k":15,"n":"Sivir","en":"Sivir","t":"Savaş Hanımı","cls":["Marksman"],"d":2,"res":"Mana","b":{"hp":600,"hpL":104,"ar":30,"arL":4,"mr":33,"mrL":1.1,"ad":60,"adL":2.5,"as":0.625,"asR":0.625,"asL":1.6,"rng":500,"ms":335,"t":"P"},"ab":[["Tabana Kuvvet","P","Sivir, bir rakip şampiyona saldırdığında kısa süreliğine hareket hızı artar.","img/abil/sivir-p.png"],["Bıçaklı Bumerang","Q","Sivir bıçağını bir bumerang gibi fırlatarak hasar verir.","img/abil/sivir-q.png",[10,9.5,9,8.5,8]],["Seken Atış","W","Sivir'in sonraki birkaç normal saldırısı fazladan saldırı hızı kazanır ve yakındaki hedeflere sekerek daha az hasar verir.","img/abil/sivir-w.png",[12,12,12,12,12]],["Büyü Kalkanı","E","Sivir üstünde kullanılan tek bir rakip yeteneğini engelleyen büyülü bir bariyer oluşturur. Bir yetenek engellenirse Sivir can ve anlık hareket hızı artışı kazanır.","img/abil/sivir-e.png",[24,22.5,21,19.5,18]],["Av Peşinde","R","Sivir takım arkadaşlarına savaşta önderlik ederek onlara bir süreliğine hareket hızı artışı kazandırır. Ayrıca Sivir'in normal saldırıları yeteneklerinin bekleme sürelerini azaltır.","img/abil/sivir-r.png",[120,100,80]]],"wk":"Sivir","p":"img/champ/sivir.png","tip":[["Sivir'in Bıçaklı Bumerang'ı en uzun menziline ulaştıktan sonra ona geri döner, bunun için normalde onu savuşturan rakiplere vurmak için pozisyon değiştirebilirsin.","Seken Atış etkinleştirildiğinde Sivir'in normal saldırısını sıfırlar; bu nedenle, bir normal saldırıdan hemen sonra etkinleştirmek verilecek hasarı en üst düzeye çıkarır.","Büyü Kalkanı'nı sersemletme veya sabitleme gibi seni engelleyebilecek rakip yeteneklerine karşı kullanmak için sakla."],["Bıçaklı Bumerang'ı kullanmak çok fazla mana harcatır; bu yüzden onu savuşturursan Sivir dezavantajlı hale gelir. Giderken vurursa, geri dönerken de onun yoluna çıkmaktan kaçın.","Sivir koridor ilerletmede etkilidir; onu koridorda uzun süre yalnız bırakırsan kulelerini yerle bir edebilir.","Sivir'le aynı koridordaysan, ileri gidermiş gibi yapıp geri çekilerek Sivir'in Büyü Kalkanı zamanlamasını şaşırtabilirsin."]]},"skarner":{"id":"Skarner","k":72,"n":"Skarner","en":"Skarner","t":"Ezeli Hükümdar","cls":["Tank","Fighter"],"d":2,"res":"Mana","b":{"hp":630,"hpL":110,"ar":33,"arL":4.5,"mr":32,"mrL":2.05,"ad":63,"adL":5,"as":0.625,"asR":0.625,"asL":2,"rng":150,"ms":335,"t":"P"},"ab":[["Titreşim Ağı","P","Skarner'ın saldırıları, Tektonik Zemin, Toprağın Başkaldırısı ve Mıhla rakiplere sarsıntı yükü uygular. Azami sarsıntı yükü biriktiğinde rakipler bu yeteneğin süresi boyunca azami canlarına bağlı olarak büyü hasarı alır.","img/abil/skarner-p.png"],["Tektonik Zemin / Toprağın Başkaldırısı","Q","Skarner, topraktan saldırılarını güçlendiren ve daha sonra fırlatabileceği bir kaya söker.","img/abil/skarner-q.png",[8,6.75,5.5,4.25,3]],["Sismik Kalkan","W","Skarner bir kalkan kazanır ve rakiplere hasar verip onları yavaşlatan bir şok dalgası gönderir.","img/abil/skarner-w.png",[10,9,8,7,6]],["Ixtal Hücumu","E","Skarner hücum ederek yüzey şekillerinin içinden geçer. Temas ettiği şampiyon veya büyük canavarı tosladığı sonraki duvara çarptırarak sersemletir ve ona hasar verir.","img/abil/skarner-e.png",[22,21,20,19,18]],["Mıhla","R","Skarner kuyruklarını önüne doğru savurarak rakip şampiyonları sindirir. Sindirilen rakipler Skarner hareket ettikçe onunla birlikte sürüklenir.","img/abil/skarner-r.png",[120,105,90]]],"wk":"Skarner","p":"img/champ/skarner.png","tip":[["Normal saldırılar sarsıntı yükü uygular. Azami miktarda hasar vermek için hedefinin peşinden ayrılma ve pasifini arka arkaya uygula.","Harita hedeflerini almaya veya takım savaşları başlatmadan önce Kristal İğneleri ele geçirmek, çatışmalarda Skarner'ın performansını büyük oranda arttırır.","Mıhla, rakibi takım arkadaşlarının saldırabilmesi için konumlamak amacıyla kullanıldığında çok güçlüdür."],["Ixtal Hücumu herhangi bir sersemletme, sabitleme veya havaya savurma etkisiyle durdurulabilir. Baskına geliyorsa bu yeteneklerden birini hazırda tut!","Mıhla'dan kaçınabilirsin. Menzilinden uzaklaşmak için Sıçra veya farklı bir yetenek kullan.","Skarner'ın sürekli hasarı eninde sonunda seni alt edecektir. Onu görmezden gelme."]]},"smolder":{"id":"Smolder","k":901,"n":"Smolder","en":"Smolder","t":"Yavru Alev","cls":["Marksman","Mage"],"d":2,"res":"Mana","b":{"hp":575,"hpL":100,"ar":24,"arL":4,"mr":33,"mrL":1.1,"ad":58,"adL":2.3,"as":0.638,"asR":0.638,"asL":4,"rng":550,"ms":330,"t":"P"},"ab":[["Ejder Talimi","P","Şampiyonlara yetenek isabet ettirmek veya rakipleri Süper Kavurucu Nefes yeteneğiyle katletmek bir Ejder Talimi yükü kazandırır. Bu yükler Smolder'ın temel yeteneklerinin hasarını arttırır.","img/abil/smolder-p.png"],["Süper Kavurucu Nefes","Q","Smolder bir rakibe doğru alev püskürtür. Yük biriktirdikçe bu yetenek daha da güçlenir.","img/abil/smolder-q.png",[5.5,5,4.5,4,3.5]],["Hapşuu!","W","Smolder tüm sevimliliğiyle hapşırarak rakip şampiyonlara isabet ettiğinde patlayan bir alev topu gönderir.","img/abil/smolder-w.png",[14,13,12,11,10]],["Uç Uç Ejderim","E","Smolder havalanarak yüzey şekillerinin üstünden uçar ve en düşük cana sahip rakibi bombardımana tutar.","img/abil/smolder-e.png",[24,22,20,18,16]],["ANNNEEEE!","R","Smolder yukarıdan alev püskürtmesi için annesini çağırır. Alevin merkezinde kalan rakipler fazladan hasar alır ve yavaşlar.","img/abil/smolder-r.png",[120,110,100]]],"wk":"Smolder","p":"img/champ/smolder.png","tip":[["Smolder erken safhalarda kendisini savunamaz. Pasif için yük biriktirmeye ve ileri safhalarda güçlü bir ejder olmak için hayatta kalmaya bak!","Smolder güvende kalmak için takımına ihtiyaç duyar. Rakip tehditlere karşı sana yardım edebilecek takım arkadaşlarını yanından eksik etme.","Smolder bir arada duran rakiplere yüksek miktarda hasar verebilir. Rakiplerin birbirlerine yakın olduğu anları fırsat bilip saldır."],["Smolder güvende kalmak için takımına ihtiyaç duyar. Ona, takım arkadaşları yanında değilken saldır.","Smolder'a karşı savaşırken takımınla bir arada durma!","Smolder erken safhalarda kendisini savunamaz. O, gerçek bir ejder olmayı öğrenemeden bu zayıflığından faydalanmaya çalış!","Smolder'ın uçuşu ağır kitle kontrolleri tarafından yarıda kesilebilir ve yavaşlatmalardan etkilenir."]]},"sona":{"id":"Sona","k":37,"n":"Sona","en":"Sona","t":"Müzik Dehası","cls":["Support","Mage"],"d":2,"res":"Mana","b":{"hp":550,"hpL":91,"ar":26,"arL":4.2,"mr":30,"mrL":1.3,"ad":49,"adL":3,"as":0.644,"asR":0.643999993801116,"asL":2.3,"rng":550,"ms":325,"t":"M"},"ab":[["Baskın Akor","P","Accelerando: Sona temel yeteneklerini etkili bir şekilde kullandıkça belli bir sınıra kadar kalıcı olarak ulti harici yetenek hızı kazanır. Bu sınırı aştığında sonraki başarılı yetenek kullanımları ultisinin kalan bekleme süresini azaltır. Baskın Akor: Her birkaç yetenek kullanımında bir, Sona'nın bir sonraki saldırısı ilave büyü hasarı vermesinin yanı sıra Sona'nın kullandığı son temel yeteneğe bağlı olarak ek bir etki daha kazanır.","img/abil/sona-p.png"],["Cesaret İlahisi","Q","Sona'nın çaldığı Cesaret İlahisi'nden çıkan ses okları, şampiyon ve canavarlar öncelikli olmak üzere, en yakındaki iki rakibe büyü hasarı verir. Sona'nın sahip olduğu geçici hare, bölge avantajıyla işaretlenen takım arkadaşlarının rakiplere karşı yapacakları ilk saldırıda ilave hasar vermelerini sağlar.","img/abil/sona-q.png",[8,8,8,8,8]],["Metanet Aryası","W","Sona'nın çaldığı Metanet Aryası, etrafına koruyucu melodiler yayarak Sona ile yakınındaki yaralı bir takım arkadaşını iyileştirir. Sona'nın oluşturduğu geçici hare, bölge avantajıyla işaretlenen takım arkadaşlarına geçici bir kalkan verir.","img/abil/sona-w.png",[10,10,10,10,10]],["Sürat Şarkısı","E","Sona'nın çaldığı Sürat Şarkısı, çevresindeki takım arkadaşlarına ilave hareket hızı kazandırır. Sona'nın oluşturduğu geçici hare, bölge avantajıyla işaretlenen takım arkadaşlarının ilave hareket hızı elde etmelerini sağlar.","img/abil/sona-e.png",[14,14,14,14,14]],["Kreşendo","R","Sona en güçlü akorunu basarak rakip şampiyonları sersemletir, dans etmeye zorlar ve onlara büyü hasarı verir.","img/abil/sona-r.png",[140,120,100]]],"wk":"Sona","p":"img/champ/sona.png","tip":[["Sona'nın hareleri etkinken takım arkadaşlarını işaretlemeyi unutma, tabii rakipler tarafından yakalanmamaya da dikkat etmelisin.","Kreşendo'yu oyunun seyrinin değişebileceği özel anlar için sakla.","Sürat Şarkısı ve Metanet Aryası'nın doğru zamanlama ile kullanarak, hayatta kalma ihtimalini en yüksek seviyeye çıkarabilirsin."],["Sona'yı görür görmez hemen dağılın ki tüm takımınızı dans ettiremesin.","Uzun süre yalnız bırakıldığında takımını iyileştireceğinden, önce Sona'yı öldür."]]},"soraka":{"id":"Soraka","k":16,"n":"Soraka","en":"Soraka","t":"Yıldız Çocuk","cls":["Support","Mage"],"d":1,"res":"Mana","b":{"hp":605,"hpL":88,"ar":32,"arL":5,"mr":30,"mrL":1.3,"ad":50,"adL":3,"as":0.625,"asR":0.625,"asL":2.14,"rng":550,"ms":325,"t":"M"},"ab":[["Kurtuluş","P","Soraka düşük cana sahip takım arkadaşlarına doğru daha hızlı koşar.","img/abil/soraka-p.png"],["Yıldız Yağmuru","Q","Gökten hedef konuma düşen yıldız büyü hasarı verir ve rakipleri yavaşlatır. Herhangi bir rakip şampiyon Yıldız Yağmuru'ndan isabet alırsa Soraka can yeniler.","img/abil/soraka-q.png",[8,7,6,5,4]],["Astral İlham","W","Soraka, kendi Can değerinin bir kısmını feda ederek takımından başka bir şampiyonu iyileştirir.","img/abil/soraka-w.png",[6,5,4,3,2]],["Ekinoks","E","Belli bir konumda oluşturduğu alanın içinde kalan bütün rakipleri susturur. Alan ortadan kaybolduğunda hala içinde olan rakipler yere sabitlenir.","img/abil/soraka-e.png",[20,19,18,17,16]],["Dilek","R","Soraka takım arkadaşlarının yüreklerini umutla doldurarak kendinin ve bütün dost şampiyonların can değerini anında yeniler.","img/abil/soraka-r.png",[150,135,120]]],"wk":"Soraka","p":"img/champ/soraka.png","tip":[["Etkili iyileştirme özelliği ile grubunu ileriye taşıyan Soraka, savaşta güçlü bir takım arkadaşıdır.","Haritanın başka köşelerinden Dilek'i kullanarak takım arkadaşlarını ölümcül durumlardan kurtarabilirsin.","Ekinoks, rakipleri uzakta tutmada oldukça güçlü bir alan hakimiyeti yöntemi olarak kullanılabilir."],["Takım arkadaşlarını iyileştirmek için cephe hattına yaklaştığında, saldırını Soraka'ya odakla.","Soraka, taciz etmek için Ekinoks kullanırsa, bu yeteneğin uzun bekleme süresini kendi lehine kullan.","Soraka'ya odaklanmak, iyileştirmekte olduğu takım arkadaşına odaklanmaktan daha kolaydır."]]},"swain":{"id":"Swain","k":50,"n":"Swain","en":"Swain","t":"Yüce Noxus Generali","cls":["Mage","Support"],"d":3,"res":"Mana","b":{"hp":595,"hpL":99,"ar":23,"arL":4.7,"mr":34,"mrL":1.55,"ad":58,"adL":2.7,"as":0.625,"asR":0.625,"asL":2.11,"rng":525,"ms":330,"t":"M"},"ab":[["Kuzgun Sürüsü","P","Swain'in kuzgunları onu iyileştiren ve azami canını kalıcı olarak arttıran tayflar toplar.","img/abil/swain-p.png"],["Ölümün Eli","Q","Swain rakipleri delip geçen birkaç büyü atışı yapar. İsabet alan rakipler, her bir atış için daha fazla hasar alır.","img/abil/swain-q.png",[7,6,5,4,3]],["İmparatorluğun Gözü","W","Swain rakiplerine hasar veren ve onları yavaşlatan bir iblis gözü açar. İsabet ettirdiği şampiyonlar açığa çıkar ve Swain'e bir Tayf kazandırır.","img/abil/swain-w.png",[20,19,18,17,16]],["Kımıldama","E","Swain bir iblis gücü dalgası yollar. Daha sonra dalga Swain'e geri döner ve isabet ettiği rakipleri sabitler. Swain sabitlenen şampiyonları kendine doğru çekebilir. Bu yeteneğin bekleme süresi Karanlığın Zirvesi sırasında azalır.","img/abil/swain-e.png",[12,11.5,11,10.5,10]],["Karanlığın Zirvesi","R","Swain bir iblise dönüşerek yakınındaki rakip şampiyonlardan, minyonlardan ve tarafsız canavarlardan can çalar. Swain, İblis Ateşi'ni kullanarak yakınındaki rakipleri bir tayf ateşi patlamasıyla darmadağın edebilir ve yavaşlatabilir. Swain rakip şampiyonların ruhunu sömürdüğü sürece bu biçimini sonsuza dek koruyabilir.","img/abil/swain-r.png",[120,120,120]]],"wk":"Swain","p":"img/champ/swain.png","tip":[["Kımıldama ile bir rakibi yerine sabitlemekte güçlük çekiyorsan, bunu rakiplerin kendi minyonlarının yakınlarındayken kullanmayı dene. Böylece patlama onları şaşırtacaktır.","Koridorda ilerlerken, Ölümün Eli'nin delip geçme hasarını kullanarak rakiplerine güvenli bir mesafeden hasar vermeye çalış.","İmparatorluğun Gözü'nü tek başına isabet ettirmek epey zor olduğundan, rakiplerin bu sırada başka şeylere odaklandığı veya kitle kontrolü altında olabileceği küçük çatışmaları yakalamak için sürekli haritayı izle.","Karanlığın Zirvesi, Swain'i katletmeyi gerçekten zorlaştırsa da ondan uzaklaşmak epey kolay. Eğer rakiplerinin hareketliliği canına tak ettiyse onları yavaşlatarak menzilinde tutacak eşyalara odaklanmaya çalış."],["Eğer hareketsiz bırakıldıysan Swain'in pasifi gerçekten çok etkili olabiliyor. Etrafta hareketsiz bırakma etkilerine sahip şampiyonlar varsa daha da dikkatli olmaya çalış.","Hareketlilik Swain'in bütün temel yeteneklerine karşı kullanılabilir: Ölümün Eli Swain'in hedefine ne kadar yakın olduğuna göre hasar verir, İmparatorluğun Gözü çok uzun bir gecikmeye sahiptir ve Kımıldama'nın tehlikeli olabilmesi için ona geri dönmeye başlaması gerekir.","Ağır Yara'ya sahip eşyalar almak, Karanlığın Zirvesi sırasında Swain'i katletmeyi çok daha kolaylaştırır."]]},"sylas":{"id":"Sylas","k":517,"n":"Sylas","en":"Sylas","t":"İsyanın Zinciri","cls":["Mage","Assassin"],"d":2,"res":"Mana","b":{"hp":600,"hpL":122,"ar":29,"arL":5.2,"mr":32,"mrL":2.55,"ad":61,"adL":3,"as":0.645,"asR":0.644999980926513,"asL":3.5,"rng":175,"ms":340,"t":"M"},"ab":[["Petrisit Patlaması","P","Sylas, yetenek kullanmasının ardından bir Petrisit Patlaması yükü biriktirir. Sylas'ın normal saldırıları bir yük harcayarak enerji kazanan zincirlerini kendi çevresinde sallamasını sağlar. Zincirler, isabet ettikleri rakiplere ilave büyü hasarı verir. Sylas, Petrisit Patlaması yüküne sahipken saldırı hızı kazanır.","img/abil/sylas-p.png"],["Kırbaç Zincir","Q","Sylas'ın savurduğu zincirler, hedef konumda kesişerek isabet alan rakiplere hasar verir ve onları yavaşlatır. Bir gecikmenin ardından kesişme noktasında rakiplere hasar veren bir büyü patlaması gerçekleşir.","img/abil/sylas-q.png",[10,9,8,7,6]],["Kral Katili","W","Sylas büyü gücüyle bir rakibin üstüne atılarak hasar verir ve yeteneği rakip şampiyonlara karşı kullandığında iyileşir.","img/abil/sylas-w.png",[12,10.5,9,7.5,6]],["Firar / Kaçır","E","Sylas hedef noktaya atılır. Yeteneği yeniden kullandığında zincirlerini fırlatır ve kendini isabet alan ilk rakibe çeker.","img/abil/sylas-e.png",[13,12,11,10,9]],["Gasp","R","Sylas rakibinin ultisini gasp ederek bunu istediği gibi kullanabilir.","img/abil/sylas-r.png",[80,55,30]]],"wk":"Sylas","p":"img/champ/sylas.png","tip":[["Kral Katili'ni kullanmadan önce kendi veya rakibinin canının azalmasını bekleyerek yetenekten azami fayda sağlamaya çalış.","Yetenek kullanımını zamana yayarak Petrisit Patlaması'ndan sonuna kadar yararlan.","Rakiplerin ultilerini zekice kullanmak, takım savaşları için yepyeni yaklaşımların önünü açabilir."],["Sylas'ın can göstergesi yanıltıcı olabilir, Kral Katili'ne dikkat et!","Sylas'la savaşacaksan ultini çalamayacağı anları kovalamaya çalış."]]},"syndra":{"id":"Syndra","k":134,"n":"Syndra","en":"Syndra","t":"Gücün Karanlık Yüzü","cls":["Mage"],"d":3,"res":"Mana","b":{"hp":583,"hpL":100,"ar":25,"arL":4,"mr":30,"mrL":1.3,"ad":54,"adL":2.9,"as":0.658,"asR":0.625,"asL":2,"rng":550,"ms":330,"t":"M"},"ab":[["Sınır Tanımaz","P","Syndra, seviye atlayarak ve rakiplere hasar vererek topladığı Gazap Partikülleriyle yeteneklerini geliştirebilir. Karanlık Küre: Syndra bir yüke daha sahip olabilir. İrade Gücü: İlave gerçek hasar verir. Zayıflara Acıma: Etki alanı genişler ve tüm hedefleri yavaşlatır. Güç Patlaması: Düşük canlı hedefleri infaz eder.","img/abil/syndra-p.png"],["Karanlık Küre","Q","Syndra'nın ortaya çıkardığı Karanlık Küre büyü hasarı verir. Küre, başka güçler aracılığıyla yönlendirilebilir.","img/abil/syndra-q.png",[7,7,7,7,7]],["İrade Gücü","W","Syndra'nın tutup fırlattığı bir Karanlık Küre veya minyon, rakiplere büyü hasarı verir ve onların Hareket Hızını azaltır.","img/abil/syndra-w.png",[13,12,11,10,9]],["Zayıflara Acıma","E","Syndra rakipleri ve Karanlık Küreleri geri savurarak büyü hasarı verir. Karanlık Kürelerin isabet ettiği rakipler sersemler.","img/abil/syndra-e.png",[17,16.5,16,15.5,15]],["Güç Patlaması","R","Syndra, bir rakip şampiyonun üzerine Karanlık Küreler yağdırır.","img/abil/syndra-r.png",[120,100,80]]],"wk":"Syndra","p":"img/champ/syndra.png","tip":[["Ulti yeteneğinin verdiği hasarı en üst düzeye çıkarmak için, karşılaşma alanında birçok küre olduğu zaman kullan.","İrade Gücü'yle bir rakip şampiyona vurduktan sonra Karanlık Küre'yi kullan; böylece yavaşlar ve kaçması zorlaşır.","Büyülerinden birini mümkün olduğunca kısa sürede 5. kademeye getir; en üst kademede güçlü ilave etkiler kazanırlar."],["Syndra'ya karşı oynarken en baştan çizme al; böylece birçok büyüsünden kaçman kolaylaşır.","Syndra'ya saldırmak için, Zayıflara Acıma büyüsünü kullanmasını bekle; bekleme süresi uzun olduğundan, Syndra savunmasız kalacaktır.","En üst kademede Syndra'nın büyüleri değişik bir görünüme ve ilave etkilere sahip olur."]]},"tahmkench":{"id":"TahmKench","k":223,"n":"Tahm Kench","en":"Tahm Kench","t":"Nehrin Kralı","cls":["Tank","Support"],"d":2,"res":"Mana","b":{"hp":640,"hpL":103,"ar":39,"arL":4.7,"mr":32,"mrL":2.05,"ad":56,"adL":3.2,"as":0.658,"asR":0.657999992370605,"asL":2.5,"rng":175,"ms":335,"t":"M"},"ab":[["Tadımlık","P","Tahm Kench saldırılarını devasa cüssesiyle destekleyerek toplam can miktarına bağlı olarak fazladan hasar elde eder. Rakip şampiyonlara hasar vermek Tadımlık yükü biriktirir. Yük sayısı üçe ulaştığında bir rakip şampiyon üzerinde Ham Yap yeteneğini kullanabilir.","img/abil/tahmkench-p.png"],["Dil Yarası","Q","Tahm Kench'in diliyle yaptığı ani saldırı isabet ettiği ilk birime hasar verir ve onu yavaşlatır. Saldırı bir şampiyona isabet ederse kendisini iyileştirir. Rakip şampiyonlara 1 Tadımlık yükü uygular. Üstünde 3 Tadımlık yükü olan şampiyonlar sersemler ve tüm yükler tüketilir.","img/abil/tahmkench-q.png",[7,6.5,6,5.5,5]],["Lezzet Yolculuğu","W","Suya dalıp hedef konumda yeniden ortaya çıkarak bölgedeki tüm rakiplere hasar verir ve onları havaya savurur.","img/abil/tahmkench-w.png",[21,20,19,18,17]],["Kayış Gibi","E","Pasif: Tahm Kench aldığı hasarın yüzdelik bir bölümünü biriktirir ve çatışma dışındayken buna bağlı olarak iyileşir. Aktif: Biriktirilen tüm hasar geçici bir kalkana dönüştürülür.","img/abil/tahmkench-e.png",[3,3,3,3,3]],["Ham Yap","R","Tahm Kench bir şampiyonu birkaç saniyeliğine yutar. Bu şampiyon bir rakipse ona büyü hasarı verir, bir takım arkadaşıysa onu korur.","img/abil/tahmkench-r.png",[0,0,0]]],"wk":"Tahm Kench","p":"img/champ/tahmkench.png","tip":[["Destek olarak en büyük görevin kırılgan takım arkadaşlarının emniyetini sağlamaktır. Ham Yap'ın menzili ile bekleme süresini aklında tutarak doğru konum almaya çalış!","Kayış Gibi'nin aktif özeliğini ne zaman kullanacağını iyi hesapla. Bazen sonradan hasar almamak için kalkanı erkenden açmak iyidir, bazen iyileşme daha avantajlı olur."],["Tahm Kench'in Kayış Gibi yeteneğinin kalkan özelliğini kullanması, Nehrin Kralı'nın iyileşme kapasitesinin büyük bir kısmından vazgeçtiği anlamına gelir. Kayış Gibi'nin bekleme süresi dolana kadar yeni gri can biriktiremez. Bunları kendi lehine kullanmaya çalış!","Tahm Kench'in Lezzet Yolculuğu'na dikkat et! Hareketsiz bırakan kitle kontrolü etkileriyle yoğunlaşmasını iptal edebilirsin."]]},"taliyah":{"id":"Taliyah","k":163,"n":"Taliyah","en":"Taliyah","t":"Taşların Dokuyucusu","cls":["Mage","Support"],"d":2,"res":"Mana","b":{"hp":550,"hpL":104,"ar":18,"arL":4.7,"mr":28,"mrL":1.3,"ad":58,"adL":3.3,"as":0.658,"asR":0.625,"asL":1.36,"rng":525,"ms":330,"t":"M"},"ab":[["Taş Kızak","P","Taliyah duvarların yanında hareket hızı kazanır.","img/abil/taliyah-p.png"],["Taş Hasadı","Q","Taliyah yetenek kullanımı sırasında dilediği gibi hareket ederken hedef yöne taşlar savurur. Bu yetenek Taliyah'nın altında İşlenmiş Zemin oluşturur. Taliyah, Taş Hasadı'nı İşlenmiş Zemin'in üstünde kullanırsa onu tüketir ve rakipleri yavaşlatan daha güçlü bir kaya fırlatır.","img/abil/taliyah-q.png",[7,6,5,4,3]],["Yerden Bitme","W","Taliyah yerden bir kaya parçasının bitmesini ve üstündeki rakipleri seçtiği yöne savurmasını sağlar.","img/abil/taliyah-w.png",[14,12.5,11,9.5,8]],["Toprak Bozumu","E","Taliyah yavaşlatan bir mayın tarlası kurar. Rakipler atılırsa ya da bölgenin içine savrulursa mayınlar patlar ve onları sersemletir.","img/abil/taliyah-e.png",[14,14,14,14,14]],["Örgü Duvar","R","Taliyah çok uzun bir duvar örer ve ardından duvarla birlikte ilerler.","img/abil/taliyah-r.png",[180,150,120]]],"wk":"Taliyah","p":"img/champ/taliyah.png","tip":[["Rakiplerini Yerden Bitme ile Toprak Bozumu'nun ortasına atmaya çalış.","Unutma, her zaman Örgü Duvar'la birlikte hareket etmek zorunda değilsin.","Rylai'nin Kristal Asası'nı aldıktan sonra peşinden koşan rakiplere karşı Taş Hasadı kullandığında onları pişman edebilirsin."],["Taliyah koridorda Toprak Bozumu kullandığında Yerden Bitme'ye karşı gözünü dört aç. Seni mayın tarlasına savurursa hem savrulma hem de üstüne düştüğün taşlar yüzünden kemiklerin çatırdayabilir.","Taliyah, Taş Hasadı kullandığında belli bir yöne kilitlenerek atış yapar. Başka bir deyişle Taliyah sana taş atıyorsa kenara kaç!"]]},"talon":{"id":"Talon","k":91,"n":"Talon","en":"Talon","t":"Bıçağın Gölgesi","cls":["Assassin"],"d":3,"res":"Mana","b":{"hp":658,"hpL":109,"ar":30,"arL":4.7,"mr":36,"mrL":2.05,"ad":68,"adL":3.1,"as":0.625,"asR":0.625,"asL":2.9,"rng":125,"ms":335,"t":"P"},"ab":[["Bıçak Sırtı","P","Talon'un yetenekleri şampiyon ve büyük canavarlarda 3 defaya kadar birikecek şekilde Yara açar. Talon 3 Yara yükü olan bir şampiyona saldırdığında, hedefi zamanla büyük miktarda hasar alarak kanama geçirir.","img/abil/talon-p.png"],["Noxus Diplomasisi","Q","Talon hedef birimi bıçaklar. Eğer hedef birim yakın dövüş menzilindeyse bu saldırı kritik hasar verir. Yakın dövüş menzilinin dışındaysa Talon hedefine atılarak onu bıçaklar. Bu yetenek hedefi katlederse Talon bir miktar can ve bekleme süresi geri kazanır.","img/abil/talon-q.png",[8,7.5,7,6.5,6]],["Biç Çek","W","Talon'un savurup çektiği hançerler, rakipleri her biçtiğinde fiziksel hasar verir. Bıçaklar dönüşleri sırasında ilave hasar verir ve isabet ettikleri birimleri yavaşlatır.","img/abil/talon-w.png",[9,8.5,8,7.5,7]],["Katilin Yolu","E","Talon belli bir mesafe boyunca her tür yüzey şekli veya yapının üzerinden atlayarak ilerler. Bu yeteneğin kısa bir bekleme süresi vardır ama üzerinden atlanan yüzey şeklini uzun bir bekleme süresine sokar.","img/abil/talon-e.png",[0,0,0,0,0]],["Gölge Saldırısı","R","Talon bıçaklarıyla bir çember oluşturur ve görünmez hale gelerek fazladan hareket hızı kazanır. Talon'un görünmezliği sona erdiğinde, bıçaklar onun bulunduğu yere çekilir. Bıçaklar her hareket ettiğinde, Gölge Saldırısı en az bir bıçağın isabet ettiği rakiplere fiziksel hasar verir.","img/abil/talon-r.png",[100,80,60]]],"wk":"Talon","p":"img/champ/talon.png","tip":[["Rakibin arkasına geçip Noxus Diplomasisi'nin yakın dövüş saldırısını kullanmaya hazırlanmak için Katilin Yolu yeteneğini kullanabilirsin.","Gölge Saldırısı güçlü bir kaçış aracıdır ama grup halinde hücum ederken de saldırıya yönelik kullanılabilir.","Dövüşmeden önce hedefini seçmeyi unutma. Talon'un tüm yeteneklerini bir hedef üzerinde odaklamak yararlıdır ama bunları bölüştürmek seni çaresiz bırakabilir."],["Talon'un saldırıları fiziksel hasar verir. Ani hasarlarına karşı koyabilmek için başlarda zırh topla.","Talon bir savaştan kaçmak için büyük ölçüde Gölge Saldırısı'na ihtiyaç duyar. Gölge Saldırısı etkin değilken bariz şekilde daha savunmasızdır.","Haritada gezinme konusunda kimse Talon'un eline su dökemez. Nerede olduğunu sürekli takip etmeye özen göster veya saldırgan bir ilerleme stratejisi güderek Talon'u koridorda kalmaya zorla."]]},"taric":{"id":"Taric","k":44,"n":"Taric","en":"Taric","t":"Valoran'ın Koruyucusu","cls":["Support","Tank"],"d":1,"res":"Mana","b":{"hp":645,"hpL":99,"ar":40,"arL":4.3,"mr":28,"mrL":2.05,"ad":55,"adL":3.5,"as":0.625,"asR":0.625,"asL":2,"rng":150,"ms":340,"t":"P"},"ab":[["Cüretkâr","P","Kullanılan yetenekler, Taric'in sonraki 2 normal saldırısının güçlenerek ilave büyü hasarı vermesini, yetenek bekleme sürelerinin azalmasını ve peş peşe hızlı saldırılar yapmasını sağlar.","img/abil/taric-p.png"],["Yıldız Işıltısı","Q","Biriktirilen yük miktarına bağlı olarak takım arkadaşlarını iyileştirir. Cüretkâr ile güçlenen saldırılar birer Yıldız Işıltısı yükü kazandırır.","img/abil/taric-q.png",[3,3,3,3,3]],["Kristal Siper","W","Taric ve Kristal Siper altında olan takım arkadaşının zırh değerini pasif olarak arttırır. Aktif olarak takım arkadaşlarından birine kalkan sağlar ve bu takım arkadaşı Taric'in yanında olduğu sürece Kristal Siper etkisinde kalır. Taric'in kullandığı büyüler, aynı zamanda Kristal Siper altındaki takım arkadaşı üzerinden de gerçekleştirilir.","img/abil/taric-w.png",[15,15,15,15,15]],["Parıltı","E","Taric'in hazırladığı yıldız ışığı huzmesi, kısa bir gecikmenin ardından rakiplere büyü hasarı verir ve onları sersemletir.","img/abil/taric-e.png",[16,15,14,13,12]],["Kozmik Titreşim","R","Kısa bir gecikmenin ardından yakındaki takım arkadaşlarına kozmik enerji dalgaları gönderir ve etkilenen takım arkadaşlarının kısa bir süre hasar görmez hâle gelmelerini sağlar.","img/abil/taric-r.png",[180,150,120]]],"wk":"Taric","p":"img/champ/taric.png","tip":[["Cüretkâr'ın bekleme süresinde azalma etkisi; Donmuş Yürek, Buzdoğan Eldiven ve Ruh Gömleği gibi bekleme süresinde azalma kazandıran eşyaların Taric üzerinde olağanüstü güçlü olmalarını sağlar.","Düşük yüklerde kullanıldığında, Yıldız Işıltısı'nın iyileştirme etkisi mana açısından verimsiz hâle gelir ama Cüretkâr sayesinde Taric'in uzun vadeli hasarını büyük oranda arttırabilir.","Kozmik Titreşim'i son ana kadar saklayıp gecikmesi yüzünden birilerinin katledilmesini göze almak yerine, bir takım savaşının başlayacağını anlar anlamaz kullanmak daha faydalı olabilir."],["Taric'in ultisi olan Kozmik Titreşim, uzun bir duraklamanın ardından etki gösterir. Bu etki ortaya çıkmadan önce çatışmadan uzaklaşmak veya Taric'in takım arkadaşlarını katletme arasında çabuk seçim yapmaya çalış.","Taric, Cüretkâr pasifi sayesinde rakiplerine normal saldırı yaparak büyülerinin bekleme sürelerini azaltır. Takım savaşlarında onu yemlemeye ve koridordaki minyon dalgalarına yaklaştığında cezalandırmaya çalış."]]},"teemo":{"id":"Teemo","k":17,"n":"Teemo","en":"Teemo","t":"Çevik İzci","cls":["Marksman","Mage"],"d":2,"res":"Mana","b":{"hp":615,"hpL":104,"ar":24,"arL":4.5,"mr":30,"mrL":1.3,"ad":54,"adL":3,"as":0.69,"asR":0.689999997615814,"asL":3.38,"rng":500,"ms":330,"t":"M"},"ab":[["Kaçak Dövüş","P","Teemo olduğu yerde durur ve kısa bir süre hiçbir şey yapmazsa, belirsiz bir süreliğine görünmez hale gelir. Teemo çalı içinde hareket ederken de görünmez hale gelebilir ve görünmezliğini bozmadan dolaşabilir. Teemo görünmezlikten çıktıktan sonra Şaşırtmaca Avantajı kazanır ve saldırı hızını birkaç saniyeliğine arttırır.","img/abil/teemo-p.png"],["Kör Eden Dart","Q","Rakibin görüşünü etkileyen güçlü bir zehirle hedefe hasar verir ve etki süresi boyunca hedefin kör olmasına yol açar.","img/abil/teemo-q.png",[7,7,7,7,7]],["Seri Adım","W","Teemo koşuşturmaya başlar ve rakip bir şampiyon ya da kulenin saldırısına uğrayana kadar hareket hızı pasif olarak artar. Teemo, depara kalkarak kısa süreliğine darbe alsa bile kaybetmeyeceği ilave hareket hızı avantajı elde edebilir.","img/abil/teemo-w.png",[14,14,14,14,14]],["Zehirli Atış","E","Teemo'nun her saldırısı, %i:OnHit% isabet halinde hedefi zehirleyerek anında ve sonraki 4 saniye boyunca hasar verir.","img/abil/teemo-e.png",[0,0,0,0,0]],["Tehlikeli Tuzak","R","Teemo, çantasında sakladığı mantarlardan birini kullanarak patlayıcı bir tuzak atar. Bir rakip tuzağa basarsa rakipleri yavaşlatan ve onların zamanla hasar almasına neden olan bir zehir bulutu yayılır. Teemo yerdeki başka bir mantarın üzerine mantar atarsa attığı mantar sekerek ilave menzil kazanır.","img/abil/teemo-r.png",[0.25,0.25,0.25]]],"wk":"Teemo","p":"img/champ/teemo.png","tip":[["Teemo'nun mantarları, minyon dalgalarını biçmekte çok etkili olarak kullanılabilir.","Mantarlarını Ejderha'yı ya da Baron Nashor'u öldürmeye çalışan rakipleri ortaya çıkartabilmek için onların yakınına koy."],["Teemo'nun Zehirli Atış'ı hem vurulan oyuncuları hem de geride duranları cezalandırır, bu yüzden saldırmadan önce güvenli bir mesafede durun.","Önemli noktalardaki mantarları Kâhinin Merceği'yle (Ziynet) yok etmek çok önemli olabilir."]]},"thresh":{"id":"Thresh","k":412,"n":"Thresh","en":"Thresh","t":"Zincirli Gardiyan","cls":["Support","Tank"],"d":3,"res":"Mana","b":{"hp":620,"hpL":120,"ar":33,"arL":0,"mr":30,"mrL":1.55,"ad":54,"adL":2.2,"as":0.625,"asR":0.625,"asL":3.5,"rng":450,"ms":330,"t":"P"},"ab":[["Felaket","P","Thresh yakınında katledilen rakiplerin ruhlarını toplayarak, kalıcı olarak zırh ve yetenek gücü kazanır.","img/abil/thresh-p.png"],["Ölüm Cezası","Q","Thresh bir rakibi zinciriyle bağlar ve kendine doğru çeker. Bu yeteneğin ikinci kez etkinleştirilmesi, Thresh'in rakibe doğru çekilmesini sağlar.","img/abil/thresh-q.png",[19,16.5,14,11.5,9]],["Karanlık Geçiş","W","Thresh'in fırlattığı fener, yakındaki takım arkadaşlarını hasardan korur. Takım arkadaşları fenere tıklayarak Thresh'e doğru atılabilir.","img/abil/thresh-w.png",[21,20,19,18,17]],["Derisini Yüz","E","Thresh'in saldırıları giderek güçlenerek, saldırılar arasında beklediği süre arttıkça daha fazla hasar verir. Etkinleştirildiğinde, Thresh zincirini sallayarak tüm rakipleri darbe yönünde savurur.","img/abil/thresh-e.png",[13,12.25,11.5,10.75,10]],["Hücre","R","Yıkılması halinde hasar veren ve yavaşlatan duvarlardan oluşan bir hapishane oluşturur.","img/abil/thresh-r.png",[120,100,80]]],"wk":"Thresh","p":"img/champ/thresh.png","tip":[["Thresh'in fenerini kullanırken iletişim kurmak çok önemli. Feneri nasıl kulanmak istediğini takım arkadaşlarına bildir.","Ölüm Cezası ve Derisini Yüz art arda gerçekleştirerek güçlü kombinasyonlar oluşturulabilir.","Thresh, birimler tarafından öldürülmeden ruhları toplayabilir. Haritadaki yerini iyi ayarlayarak gerçekleşen ölümlere yakın olmak, topladığın ruh sayısını en üst düzeye çıkarır."],["Thresh'in Ölüm Cezası kabiliyetini gerçekleştirmesi uzun sürer. Gerçekleştirmeye başladığı zamanı kollayıp kaçınmak için harekete geç.","Hücre'nin bir duvarını bilerek yıkmak, savunmasız bir takım arkadaşının sağ salim kaçmasını sağlayabilir.","Thresh'in savunma gücü ile verdiği hasarın bir kısmını topladığı ruhlar belirler. Ruh toplamak için hamle yaptığında onu cezalandırmaya çalış."]]},"tristana":{"id":"Tristana","k":18,"n":"Tristana","en":"Tristana","t":"Yaman Topçu","cls":["Marksman","Assassin"],"d":2,"res":"Mana","b":{"hp":640,"hpL":102,"ar":30,"arL":4,"mr":33,"mrL":1.1,"ad":60,"adL":3.4,"as":0.656,"asR":0.694,"asL":1.5,"rng":550,"ms":325,"t":"P"},"ab":[["Göz, Gez, Arpacık","P","Tristana'nın saldırı menzili seviye atladıkça artar.","img/abil/tristana-p.png"],["Seri Ateş","Q","Tristana silahını süratle ateşleyerek kısa süreliğine Saldırı Hızını arttırır.","img/abil/tristana-q.png",[20,19,18,17,16]],["Roket Atlayışı","W","Tristana yere ateş edip kendini uzak bir konuma doğru fırlatır. Yere indiğinde etrafındaki birimlere hasar verir ve kısa süreliğine yavaşlamalarına neden olur.","img/abil/tristana-w.png",[22,20,18,16,14]],["Patlayıcı Yük","E","Tristana bir birimi öldürdüğünde, top gülleleri şarapneller halinde dağılarak çevredeki rakiplere hasar verir. Etkinleştirilerek, hedeflenen rakip üzerinde kısa bir süre sonra patlayarak etraftaki birimlere hasar veren bir bomba yerleştirmede kullanılabilir.","img/abil/tristana-e.png",[16,15.5,15,14.5,14]],["Gülle Atışı","R","Tristana silahına kocaman bir gülle yükleyip, rakip bir birime doğru ateşler. Bu atış, büyü hasarı verir ve hedefi geri savurur.","img/abil/tristana-r.png",[100,100,100]]],"wk":"Tristana","p":"img/champ/tristana.png","tip":[["Tristana'nın devasa silahı çok uzaklardan hedefini vurmasına izin verir. Rakipleri kendine yaklaştırmamak için bundan faydalan.","Bir rakip üzerinde Patlayıcı Yük yükü biriktirdiğinde, Roket Atlayışı'nı kullanarak vereceğin tonlarca ani hasarla işini bitirebilirsin.","Seri Ateş kullanmak, rakip şampiyonlar üzerinde Patlayıcı Yük yükü biriktirmeyi kolaylaştırır."],["Bir savaşta Tristana'nın Seri Ateş'i aktif hale getirdiğini görürsen, onu sersemlet ve büyü boşa gidene kadar geride bekle.","Patlayıcı Yük'ten daha az zarar almak için bir koridorda kendi minyonlarından uzakta dur."]]},"trundle":{"id":"Trundle","k":48,"n":"Trundle","en":"Trundle","t":"Trol Kralı","cls":["Fighter","Tank"],"d":2,"res":"Mana","b":{"hp":650,"hpL":110,"ar":37,"arL":4.5,"mr":32,"mrL":2.05,"ad":68,"adL":4.5,"as":0.67,"asR":0.6700000166893,"asL":2.9,"rng":175,"ms":350,"t":"P"},"ab":[["Kralın Hakkı","P","Yakınındaki bir rakip birim katledildiğinde, Trundle birimin azami canının yüzdelik bir kısmını iyileşme olarak kazanır.","img/abil/trundle-p.png"],["Kopar","Q","Trundle rakibini ısırarak hasar almasına ve kısa süreliğine yavaşlamasına yol açar, ayrıca rakibin Saldırı Gücünün bir kısmını sömürür.","img/abil/trundle-q.png",[3.5,3.5,3.5,3.5,3.5]],["Donmuş Krallık","W","Trundle hedef konumda krallığını ilan ederek, burada bulunduğu sürece Saldırı Hızı, Hareket Hızı ve tüm kaynaklardan gelen iyileştirme etkilerinde artış kazanır.","img/abil/trundle-w.png",[18,17,16,15,14]],["Buzdan Sütun","E","Trundle'ın hedef konumda yarattığı buzdan sütun, zemini aşılmaz hale getirerek yakındaki bütün rakip birimleri yavaşlatır.","img/abil/trundle-e.png",[21,19.5,18,16.5,15]],["Dize Getir","R","Trundle anında hedefinin Can, Zırh ve Büyü Direncinin belli bir yüzdesini çalar. Sonraki 4 saniye boyunca çalınan Can, Zırh ve Büyü Direnci miktarı iki katına çıkar.","img/abil/trundle-r.png",[120,100,80]]],"wk":"Trundle","p":"img/champ/trundle.png","tip":[["Trundle Donmuş Krallık alanı içerisindeki dövüşlerde üstünlük sağlar. Rakipleri bu bölgeye çekmeye çalış.","Güçlü bir rakip tankını yumuşatmak veya takımının ateşini odaklayacağı bir hedef yaratmak için Dize Getir'i kullan.","Kopar, rakiplerin fiziksel hasarını düşürmek için iyidir; bunu rakibin fiziksel hasar veren şampiyonlarında kullan."],["Trundle belli mekânlardaki savaşlarda çok güçlüdür. Onu Donmuş Krallık alanının dışına çıkartmaya çalış.","Onun Buzdan Sütun'undan hemen çıkmaya çalış; içerisinde durdukça seni epey yavaşlatır."]]},"tryndamere":{"id":"Tryndamere","k":23,"n":"Tryndamere","en":"Tryndamere","t":"Barbar Kral","cls":["Fighter","Assassin"],"d":2,"res":"Öfke","b":{"hp":696,"hpL":108,"ar":33,"arL":4.8,"mr":32,"mrL":2.05,"ad":66,"adL":4.5,"as":0.67,"asR":0.725,"asL":3.4,"rng":175,"ms":345,"t":"P"},"ab":[["Savaş Gazabı","P","Tryndamere her saldırısı, kritik vuruşu ve öldürücü vuruşu için Öfke kazanır. Öfke pasif olarak Kritik Vuruş İhtimalini arttırır ve Kan Hırsı büyüsüyle tüketilebilir.","img/abil/tryndamere-p.png"],["Kan Hırsı","Q","Tryndamere savaş ateşiyle coşar ve yaraları arttıkça sahip olduğu saldırı gücü de artar. Kan Hırsı yeteneğini kullanarak Öfke tüketip kendini iyileştirebilir.","img/abil/tryndamere-q.png",[12,12,12,12,12]],["Alaycı Nara","W","Tryndamere, küçümseyen bir nara savurarak çevresindeki rakiplerin saldırı gücünü azaltır. Arkası Tryndamere'e dönük rakiplerin hareket hızı da azalır.","img/abil/tryndamere-w.png",[14,14,14,14,14]],["Biçerdöner","E","Tryndamere hedef birime doğru ilerlerken, önüne çıkan rakipleri biçerek onlara hasar verir.","img/abil/tryndamere-e.png",[12,11,10,9,8]],["Ölümsüz Hiddet","R","Tryndamere'in savaş hırsı öylesine güçlenir ki ne kadar yara alırsa alsın katledilemez.","img/abil/tryndamere-r.png",[120,100,80]]],"wk":"Tryndamere","p":"img/champ/tryndamere.png","tip":[["Ölümsüz Hiddet'i etkinleştirmeyi geciktirmek, bir rakip şampiyonun seni öldürmesini gereğinden fazla istemesini sağlamak için etkin bir yoldur.","Kan Hırsı Tryndamere'i iyileştirmek için çok iyi bir yoldur. Etkinleştirmeden önce sönmemesini sağlamaya çalış.","Rakip Zırh biriktirmeye başladyısa, Son Fısıltı veya Youmuu'nun Hayalet Kılıcı gibi eşyaları satın almayı dene."],["Oyunun başlarında Tryndamere'i rahatsız et ki minyonlarını öldürüp Kan Hırsı'yla iyileşemesin.","Unutma; Tryndamere seni yalnızca ondan başka bir yöne bakıyorsan yavaşlatabilir.","Tryndamere'in hasarının çoğu fizikseldir. Çok fazla güçleniyorsa, Çivili Zırh satın almayı düşün."]]},"twistedfate":{"id":"TwistedFate","k":4,"n":"Twisted Fate","en":"Twisted Fate","t":"İskambil Ustası","cls":["Mage","Marksman"],"d":3,"res":"Mana","b":{"hp":604,"hpL":108,"ar":24,"arL":4.35,"mr":30,"mrL":1.3,"ad":52,"adL":2.5,"as":0.625,"asR":0.651000022888183,"asL":2.5,"rng":525,"ms":330,"t":"M"},"ab":[["Hileli Zar","P","Twisted Fate katlettiği her birim için ''şanslı'' zarını atarak fazladan 1 ila 6 altın alır.","img/abil/twistedfate-p.png"],["Koz: Ölüm","Q","Twisted Fate'in attığı üç kart, içinden geçtiği her rakibe hasar verir.","img/abil/twistedfate-q.png",[6,5.75,5.5,5.25,5]],["Bir Kart Seç","W","Twisted Fate destesinden büyülü bir kart seçer ve kullanarak bir sonraki saldırısına ek etkiler kazandırır.","img/abil/twistedfate-w.png",[6,6,6,6,6]],["Şans Destesi","E","Twisted Fate her 4 saldırıda bir ilave hasar verir. Ayrıca, saldırı hızı artar.","img/abil/twistedfate-e.png",[0,0,0,0,0]],["Kader","R","Twisted Fate baktığı fal ile bütün rakiplerinin görünmesine ve Kapı büyüsünün kullanılmasına olanak sağlar. Kapı, Twisted Fate'i 1,5 saniye içinde herhangi bir hedef noktaya ışınlar.","img/abil/twistedfate-r.png",[170,140,110]]],"wk":"Twisted Fate","p":"img/champ/twistedfate.png","tip":[["Kader'i kullanarak rakiplere aniden saldırabilmek için dostlarınla eş zamanlı çalış.","Gizlenen karakterler genellikle savaştan çok düşük can puanıyla kaçarlar. Kader'in gizlenen birimleri ortaya çıkartma yeteneğini kullanarak onlara son darbeyi vur.","Twisted Fate'in Saldırı Gücü ya da Yetenek Gücü'ne de yatkın bir karakter olması, onu farklı takım kompozisyonlarına uydurur."],["Oyunun başlarında, şampiyonun vurulduğunda sağ kalmasına yetecek kadar Can değeri olmadığından, Koz: Ölüm yeteneğinden kaçınmaya bak.","Canın azaldıysa, güvenli bir yere kaçmak için Kader'i gösterge olarak kullan. Bu, olası baskınlardan kaçmak için sana avans verecektir."]]},"twitch":{"id":"Twitch","k":29,"n":"Twitch","en":"Twitch","t":"Veba Getiren","cls":["Marksman","Assassin"],"d":2,"res":"Mana","b":{"hp":630,"hpL":98,"ar":27,"arL":4,"mr":33,"mrL":1.1,"ad":59,"adL":3,"as":0.679,"asR":0.67900002002716,"asL":3,"rng":550,"ms":330,"t":"P"},"ab":[["Ölümcül Zehir","P","Twitch'in normal saldırıları %i:OnHit% isabet halinde hedefine hastalık bulaştırarak saniye başına gerçek hasar verir.","img/abil/twitch-p.png"],["Pusu","Q","Twitch kısa süreliğine kamuflaja bürünür ve hareket hızı kazanır. Kamuflajdan çıktığındaysa kısa süreliğine saldırı hızı kazanır. Ölümcül Zehir etkisindeki bir rakip şampiyon katledildiği zaman Pusu'nun bekleme süresi sıfırlanır.","img/abil/twitch-q.png",[16,16,16,16,16]],["Zehir Şişesi","W","Twitch'in fırlattığı zehir şişesi belli bir alanda patlayarak hedefleri yavaşlatır ve onlara ölümcül zehir uygular.","img/abil/twitch-w.png",[13,12,11,10,9]],["Bulaştır","E","Twitch hastalıklarından oluşturduğu patlama ile zehirlediği rakiplerini kasıp kavurur.","img/abil/twitch-e.png",[12,11,10,9,8]],["Zehir Salvosu","R","Twitch'in tüm gücüyle arbaletini ateşler ve oldukça uzak bir mesafeden fırlattığı oklar, önlerine çıkan tüm rakipleri delik deşik eder.","img/abil/twitch-r.png",[90,90,90]]],"wk":"Twitch","p":"img/champ/twitch.png","tip":[["Twitch, oyundaki en yüksek Saldırı Hızına sahip şampiyonlardan biridir; isabet etkili Kara Balta veya Aklın Sonu gibi eşyalar satın almayı dene.","Bulaştır'ın menzili geniştir; kullanmadan önce biriktirebildiğin kadar Ölümcül Zehir etkisi biriktir.","Zehir Şişesi'yle saldırı menzilinin dışındaki bir rakibe yetişebilirsin."],["Twitch narindir. Kamuflaj altında olmadığı zamanları yakaladığında, takım arkadaşlarınla birlikte ona odaklan.","Büyü Kalkanları Ölümcül Zehir'in hasarını engellemez ama Twitch'in onunla tetikleyeceği etkilerini engelleyecektir.","Twitch'in koridordan çıktığından şüphelenirsen, takım arkadaşlarına ''KAYIP'' olduğunu haber ver."]]},"udyr":{"id":"Udyr","k":77,"n":"Udyr","en":"Udyr","t":"Ruh Gezgini","cls":["Fighter","Tank"],"d":3,"res":"Mana","b":{"hp":664,"hpL":92,"ar":31,"arL":4.7,"mr":32,"mrL":2.05,"ad":62,"adL":4,"as":0.65,"asR":0.6499999761581421,"asL":3,"rng":125,"ms":350,"t":"P"},"ab":[["Ruhani Köprü","P","Udyr, duruşunu değiştiren dört temel yeteneğe sahiptir ve bu yetenekleri yeniden kullanarak duruşunu güçlü etkilerle yenileyebilir. Ayrıca bir yetenek kullandıktan sonraki iki saldırısı için saldırı hızı kazanır.","img/abil/udyr-p.png"],["Yabani Pençe","Q","Udyr saldırı hızı kazanır ve sonraki iki saldırısı ilave fiziksel hasar verir. Yeniden Kullanım: Daha çok saldırı hızı kazanır ve sonraki iki saldırısıyla birlikte hedefine yıldırım çarpar.","img/abil/udyr-q.png",[6,6,6,6,6,6]],["Demir Post","W","Udyr bir kalkan kazanır ve sonraki iki saldırısı kendisini iyileştirir. Yeniden Kullanım: Udyr daha büyük bir kalkan kazanır ve sonraki birkaç saniyeliğine azami canına bağlı olarak iyileşir.","img/abil/udyr-w.png",[6,6,6,6,6,6]],["Alaz Hücum","E","Udyr hareket hızı kazanır ve her bir hedefe yönelik ilk saldırısı rakibi sersemletir. Yeniden Kullanım: Daha fazla hareket hızı ve hareketsiz bırakan etkilere karşı birkaç saniyeliğine bağışıklık kazanır.","img/abil/udyr-e.png",[6,6,6,6,6,6]],["Kanatlı Kasırga","R","Udyr kendisini bir buzul kasırgasıyla kuşatarak yakınındaki rakiplere hasar verir ve onları yavaşlatır. Yeniden Kullanım: Udyr kasırgayı güçlendirip serbest bırakarak onun rakiplerini takip etmesini ve ilave hasar vermesini sağlar.","img/abil/udyr-r.png",[6,6,6,6,6,6]]],"wk":"Udyr","p":"img/champ/udyr.png","tip":[["Hasar hafifledikten sonra kaplumbağa kalkanına gelir. Bu yüzden savunma eşyaları satın almak hayatta kalabilirliğini büyük ölçüde arttırabilir.","Udyr oyundaki en iyi ormanda gezebilenlerden biridir. Bunun avantajını kullanabilmek takımına büyük Tecrübe Puanı avantajı ve harita kontrolü sağlar."],["Udyr'in menzilli saldırı seçenekleri kısıtlı, bu yüzden mesafeni korumaya çalış.","Udyr bir yeteneğin daha güçlü olan Uyanmış versiyonunu kullandıktan sonra diğer yeteneklerin Uyanmış versiyonlarını bir süreliğine kullanamaz."]]},"urgot":{"id":"Urgot","k":6,"n":"Urgot","en":"Urgot","t":"Dehşet Makinesi","cls":["Fighter","Tank"],"d":3,"res":"Mana","b":{"hp":655,"hpL":102,"ar":36,"arL":5,"mr":32,"mrL":2.05,"ad":63,"adL":4,"as":0.625,"asR":0.625,"asL":3.75,"rng":350,"ms":330,"t":"P"},"ab":[["Dehşet Saçar","P","Urgot'un normal saldırıları ve İmha yeteneği, bacaklarının düzenli olarak alev saçarak fiziksel hasar vermesini sağlar.","img/abil/urgot-p.png"],["Çürüten Bomba","Q","Hedeflenen noktaya, fiziksel hasar veren ve patlama alanında kalan rakipleri yavaşlatan bir bomba fırlatır.","img/abil/urgot-q.png",[10,9.5,9,8.5,8]],["İmha","W","Urgot yavaşlayarak silahını yakındaki rakiplerin üzerine boşaltır. Yetenek, Urgot'un kısa süre önce diğer yeteneklerini isabet ettirdiği rakip şampiyonlara öncelik verir ve Dehşet Saçar'ı tetikler.","img/abil/urgot-w.png",[12,9,6,3,0]],["Horgörü","E","Urgot belli bir yöne hücum ederken bir kalkan kazanır ve şampiyonlar dışındaki rakipleri ezer. Bir rakip şampiyonu yakalarsa durur ve bu şampiyonu arkasına savurur.","img/abil/urgot-e.png",[16,15.5,15,14.5,14]],["Ölümden Beter","R","Urgot isabet ettiği ilk rakip şampiyona saplanan bir kimyasal delgi atar. Bu şampiyonun canı belli bir eşiğin altına düşerse Urgot onun zayıf olduğuna hüküm verip onu infaz edebilir.","img/abil/urgot-r.png",[100,85,70]]],"wk":"Urgot","p":"img/champ/urgot.png","tip":[["Ayrı ayrı bütün bacaklarının bekleme sürelerini iyi takip et çünkü verdiğin hasarın büyük kısmını bu bacaklara borçlusun.","İmha ile rakiplere kilitlenmek için Çürüten Bomba veya Horgorü yeteneklerini tuttur. Bu sayede birden fazla bacağını hızla tetikleyebilirsin.","Ölümden Beter yeteneğini, hayatta kalamayacak kadar zayıf olduğunu bildiğin rakiplere sakla. Bu yetenek özellikle kaçan rakipleri ayıklamak için birebirdir."],["Urgot, kendi bekleme sürelerine sahip ve sadece kendi doğrultularındaki saldırılarla tetiklenen bacaklarını kullanarak rakiplerini havaya uçurmaya büyük önem verir. Bu tür çok sayıda saldırıdan isabet almamaya özen göster.","Urgot, İmha yeteneğiyle büyük miktarda hasar verip soğurur ama ateş ettiği sırada yavaşlar.","Ölümden Beter yeteneğine yakalanırsan etkisi geçene kadar infaz eşiğinin altına (azami canının %25'i) düşmemek için canını dişine tak."]]},"varus":{"id":"Varus","k":110,"n":"Varus","en":"Varus","t":"İntikam Oku","cls":["Marksman","Mage"],"d":1,"res":"Mana","b":{"hp":600,"hpL":105,"ar":24,"arL":4,"mr":33,"mrL":1.1,"ad":59,"adL":3.4,"as":0.658,"asR":0.657999992370605,"asL":3.5,"rng":575,"ms":330,"t":"P"},"ab":[["Canlı İntikam","P","Katletme veya asist halinde Varus, geçici olarak saldırı gücü ve yetenek gücü kazanır. Rakip şampiyonsa bu ilave daha da büyük olur.","img/abil/varus-p.png"],["Deşen Ok","Q","Varus yayını gerer ve bırakmaya hazırlandığı süre arttıkça fazladan menzil ve hasar kazanan güçlü bir atış yapar.","img/abil/varus-q.png",[16,15,14,13,12]],["Maraz Sadağı","W","Pasif: Varus'un normal saldırıları ilave büyü hasarı verir ve Maraz bulaştırır. Varus'un diğer yetenekleri Maraz'ı patlatıp hedefin azami canına bağlı olarak büyü hasarı vermesini sağlar. Aktif: Varus bir sonraki Deşen Ok'unu güçlendirir.","img/abil/varus-w.png",[40,40,40,40,40]],["Ok Yağmuru","E","Varus'un ok yağmuru, alana fiziksel hasar vererek zemini habisleştirir. Habis zemin, rakiplerin hareket hızı ile kendi kendini iyileştirme ve yenilenme hızlarını azaltır.","img/abil/varus-e.png",[18,16,14,12,10]],["Musibet Zinciri","R","Varus çarptığı ilk şampiyonu hareketsiz bıraktıktan sonra, çevredeki etkilenmeyen şampiyonlara da yayılarak temas anında onları da hareketsiz bırakan bir musibet sarmaşığı fırlatır.","img/abil/varus-r.png",[100,80,60]]],"wk":"Varus","p":"img/champ/varus.png","tip":[["Maraz Sadağı oyunun başlarında rakibi rahatsız etmede ve minyonlara öldürücü darbeyi vurmada yardımcı olabilir.","Kısa menzilli dövüşlerde Deşen Ok'un tam gücünün dolmasını beklemek yerine çabucak ateşlemek daha iyidir.","Kaçmak üzereler iken ya da dövüşe girmeden önce Deşen Ok'un uzun menzilinin avantajını kullanmaya çalış."],["Maraz'dan etkilendiysen, Varus'un yetenekleri sana fazladan zarar verecektir.","Birini öldürür ya da asist yaparsa, Varus geçici bir süreliğine Saldırı Hızı kazanır ve çok daha tehlikeli olur.","Varus'un ultisi Musibet Zinciri sana ulaşırsa bir yerde bağlı kalırsın. Yeterince uzağa kaçabilirsen, zincirin sana ulaşmadan kopmasını sağlayabilirsin."]]},"vayne":{"id":"Vayne","k":67,"n":"Vayne","en":"Vayne","t":"Gece Avcısı","cls":["Marksman","Assassin"],"d":3,"res":"Mana","b":{"hp":580,"hpL":98,"ar":23,"arL":4.6,"mr":33,"mrL":1.1,"ad":60,"adL":2.35,"as":0.658,"asR":0.658,"asL":2.8,"rng":550,"ms":330,"t":"P"},"ab":[["Gece Avcısı","P","Vayne kötülük yapanları acımasızca avlarken yakındaki rakip şampiyonlara doğru ilerlediğinde hareket hızı kazanır.","img/abil/vayne-p.png"],["Takla","Q","Vayne bir sonraki atışında hedefi tutturmak için yuvarlanarak dikkatle pozisyon alır. Bir sonraki saldırısı ilave hasar verir.","img/abil/vayne-q.png",[6,5,4,3,2]],["Gümüş Ok","W","Vayne oklarının ucunu kötü varlıklara karşı zehirli olan, nadir bir madenle kaplar. Aynı hedefe yönelik art arda üçüncü saldırı ya da yeteneği, hedefin azami canının yüzdelik bir bölümü kadar ilave gerçek hasar verir.","img/abil/vayne-w.png",[0,0,0,0,0]],["Kazıkatar","E","Vayne sırtındaki ağır arbaleti çeker; fırlattığı devasa okla hedefini geri savurur ve ona hasar verir. Hedef araziye çarparsa mıhlanır ve ek hasar alarak sersemler.","img/abil/vayne-e.png",[20,18,16,14,12]],["Son Hazırlık","R","Destansı bir hesaplaşmaya hazırlanan Vayne saldırı gücü elde eder, Takla yeteneğini kullandığı sırada görünmez olur, Takla bekleme süresini azaltır ve şampiyonun Gece Avcısı yeteneğinden kazandığı ilave hareket hızı artar.","img/abil/vayne-r.png",[100,85,70]]],"wk":"Vayne","p":"img/champ/vayne.png","tip":[["Takla'nın birçok kullanımı vardır ama duvarlardan geçemez.","Kazıkatar hem öldürmeyi kesinleştirmek için hedefleri duvara çivilemekte hem de birinden kaçmak için kullanılabilir.","Büyük bir takım dövüşüne en önde girme. Önce takım arkadaşlarının girmesini bekle."],["Vayne narindir. Üzerine gidip baskı kurarsanız, o da daha temkinli oynamak zorunda kalacaktır.","Vayne'in sizi duvarlara kıstırmasına fırsat vermeyin."]]},"veigar":{"id":"Veigar","k":45,"n":"Veigar","en":"Veigar","t":"Kötülüğün Minik Efendisi","cls":["Mage"],"d":3,"res":"Mana","b":{"hp":580,"hpL":108,"ar":18,"arL":5.2,"mr":32,"mrL":1.3,"ad":52,"adL":2.7,"as":0.625,"asR":0.625,"asL":2.24,"rng":550,"ms":340,"t":"M"},"ab":[["Acayip Kötülük Gücü","P","Veigar Runeterra'yı gözüne kestirenler arasında gelmiş geçmiş en büyük Kötü ve her an gücüne güç katıyor! Bir rakibe büyü isabet ettirdiğinde veya rakip alt ettiğinde Veigar'ın yetenek gücü kalıcı olarak artar.","img/abil/veigar-p.png"],["Uğursuz Saldırı","Q","Veigar'ın gönderdiği karanlık enerji ışını, isabet ettiği ilk iki rakibe Büyü Hasarı verir. Katledilen her hedef için Veigar kalıcı olarak bir miktar Yetenek Gücü kazanır.","img/abil/veigar-q.png",[6,5.5,5,4.5,4]],["Karanlık Madde","W","Veigar'ın hedef noktaya gökten düşürdüğü büyük karanlık madde kütlesi, iniş anında büyü hasarı verir. Acayip Kötülük Gücü yükleri, Karanlık Madde'nin bekleme süresini azaltır.","img/abil/veigar-w.png",[0,0,0,0,0]],["Kara Delik","E","Veigar uzayı bükerek içinden geçen rakipleri sersemleten, duvarlarla çevrili bir alan oluşturur.","img/abil/veigar-e.png",[20,18.5,17,15.5,14]],["Ezeli Patlama","R","Hedefteki rakip şampiyona isabet ederek hedefin eksik can miktarına bağlı olarak artan, büyük miktarda büyü hasarı verir.","img/abil/veigar-r.png",[120,90,60]]],"wk":"Veigar","p":"img/champ/veigar.png","tip":[["Karanlık Madde'yi isabet ettirme şansını arttırmak için Kara Delik'i kullan.","Veigar, mana ve bekleme süresinde azalmaya olağanüstü bel bağlar. Pasifinin ve Uğursuz Saldırı yeteneğinin etkinliğini arttırmak için bu istatistiklere ağırlık ver.","Veigar çok hassastır. En azından bir sihirdar büyüsünü savunma amaçlı seçmek çok önemlidir."],["Karanlık Madde çok yüksek hasar verir ama atlatılabilir. Büyünün ne zaman nereye geleceğini sesli ve görsel belirtilerden anlamaya çalış.","Kara Delik yalnızca kenarda olan birimleri sersemletir. Büyünün içerisindeysen de hareket edip saldırabilirsin.","Veigar'ın ultisi, senin eksik can miktarına bağlı olarak hasar verir."]]},"velkoz":{"id":"Velkoz","k":161,"n":"Vel'Koz","en":"Vel'Koz","t":"Hiçlik'in Gözü","cls":["Mage","Support"],"d":3,"res":"Mana","b":{"hp":590,"hpL":102,"ar":22,"arL":4.7,"mr":30,"mrL":1.3,"ad":55,"adL":3.1416,"as":0.643,"asR":0.625,"asL":1.59,"rng":525,"ms":340,"t":"M"},"ab":[["Organik Yapıbozum","P","Vel'Koz'un yetenekleri, isabet ettikleri rakiplerde Organik Yapıbozum yükleri biriktirir. 3 yük biriktirilirse, rakip anlık gerçek hasar alır.","img/abil/velkoz-p.png"],["Plazma Ayrışması","Q","Vel'Koz'un yolladığı plazma ışını, yetenek tekrar etkinleştirildiğinde veya ışın bir rakibe isabet ettiğinde ikiye bölünür. Işın isabet halinde yavaşlatır ve hasar verir.","img/abil/velkoz-q.png",[7,7,7,7,7]],["Hiçlik'e Açılan Yarık","W","Vel'Koz'un Hiçlik'e açtığı yarık önce anlık hasar verir, bir süre sonra patlayarak ikinci defa hasar verir.","img/abil/velkoz-w.png",[1.5,1.5,1.5,1.5,1.5]],["Tektonik Bozucu","E","Vel'Koz bir bölgenin patlamasına; rakiplerin havaya, yakındaki rakiplerin biraz uzağa savrulmasına yol açar.","img/abil/velkoz-e.png",[12,11.5,11,10.5,10]],["Yaşam Formu Parçalama Şuası","R","Vel'Koz'un yönlendirdiği ışın 2,5 saniyeliğine imleci takip ederek rakiplerin büyü hasarı almasını sağlar. Organik Yapıbozum, araştırmaya tabi tuttuğu rakiplerin gerçek hasar almasını sağlar.","img/abil/velkoz-r.png",[100,90,80]]],"wk":"Vel'Koz","p":"img/champ/velkoz.png","tip":[["Koridorda ilerlerken, minyonları temizlemek için Hiçlik'e Açılan Yarık kullanarak, bir yandan rakibinin üzerinde Organik Yapıbozum yükleri biriktir. Devamında diğer yeteneklerini kullanabilirsin.","Her ne kadar zor da olsa, Plazma Ayrışması'nı çaprazlamasına atmak ve azami menzildeyken bölmek, ilk atışın menzili dışında kalan rakiplere de vurabilmeni sağlar.","Yaşam Formu Parçalama Şuası'nı kullanırken zamanlamaya özen göster. Bu büyüyü engelleyebilecek yeteneklere sahip pek çok şampiyon var."],["Vel'Koz, kendi haline bırakıldığında savaşlarda son derece tehlikelidir. Geç olmadan onu alt etmeye odaklan.","Vel'Koz'un hareket kabiliyeti çok yüksek değildir ve baskınlara karşı zayıftır.","Yaşam Formu Parçalama Şuası; sersemletme, susturma ve savurma aracılığı ile engellenebilir."]]},"vex":{"id":"Vex","k":711,"n":"Vex","en":"Vex","t":"Kasvetperver","cls":["Mage"],"d":2,"res":"Mana","b":{"hp":590,"hpL":104,"ar":23,"arL":4.45,"mr":28,"mrL":1.3,"ad":54,"adL":2.75,"as":0.669,"asR":0.625,"asL":1,"rng":550,"ms":335,"t":"M"},"ab":[["Kıyamet ve Kasvet","P","Vex düzenli aralıklarla güçlenerek bir sonraki temel yeteneğinin rakipleri korkutmasını ve atılmaları durdurmasını sağlar. Yakınındaki rakipler her atıldığında, Vex onlara ilave hasar vermek ve güçlenmiş halinin bekleme süresini azaltmak için tüketebileceği bir işaret uygular.","img/abil/vex-p.png"],["Buhran Dalgası","Q","Gönderdiği hasar veren atış, hareket ederken hızlanır.","img/abil/vex-q.png",[8,7,6,5,4]],["Kişisel Alan","W","Kalkan kazanır ve yakınındaki rakiplere hasar verir.","img/abil/vex-w.png",[16,15,14,13,12]],["Yaklaşan Karanlık","E","Hasar veren, yavaşlatan ve rakiplere Kasvet etkisi uygulayan bir bölge oluşturur.","img/abil/vex-e.png",[12,12,12,12,12]],["Gölge Akını","R","Rakip şampiyonu işaretleyen bir atış yapar. Yetenek yeniden kullanıldığında ona atılarak hasar verir.","img/abil/vex-r.png",[140,120,100]]],"wk":"Vex","p":"img/champ/vex.png","tip":[[],[]]},"vi":{"id":"Vi","k":254,"n":"Vi","en":"Vi","t":"Piltover Fedaisi","cls":["Fighter","Assassin"],"d":2,"res":"Mana","b":{"hp":655,"hpL":105,"ar":30,"arL":4.7,"mr":32,"mrL":2.05,"ad":61,"adL":3.5,"as":0.644,"asR":0.643999993801116,"asL":2,"rng":125,"ms":340,"t":"P"},"ab":[["Patlama Kalkanı","P","Vi zamanla bir kalkan biriktirir. Kalkan, bir yeteneği rakibe isabet ettirerek etkin hale getirilebilir.","img/abil/vi-p.png"],["Duvar Delen","Q","Vi'ın eldivenlerini yükleyerek attığı duvar delen yumruk, ileri doğru hareket etmesini sağlar. Vurduğu rakipler geri savrulur ve bir ezici darbe yükü alır.","img/abil/vi-q.png",[12,10.5,9,7.5,6]],["Ezici Darbeler","W","Vi'ın yumrukları rakibinin Zırhını parçalayarak ilave hasar verir ve Saldırı Hızı kazanmasını sağlar.","img/abil/vi-w.png",[0,0,0,0,0]],["Yılmaz Güç","E","Vi'ın sonraki saldırısı hedefi delip geçerek, arkasındaki rakiplere hasar verir.","img/abil/vi-e.png",[1,1,1,1,1]],["Son Uyarı","R","Vi yoluna çıkanı kenara savurarak bir rakibe doğru ilerler. Hedefe ulaştığında onu havaya savurur, arkasından zıplar ve hedefi yere geri mıhlar.","img/abil/vi-r.png",[140,115,90]]],"wk":"Vi","p":"img/champ/vi.png","tip":[["Duvar Delen tam güce ulaştığında iki kat hasar verir. Kaçan rakipleri yakalayıp işlerini bitirmek için birebirdir.","Yılmaz Güç, şok dalgasına yakalanan herkese tam hasar verir. Koridorda minyonların üstünde kullanarak onların arkasına saklanan rakiplere vur.","Son Uyarı, güçlü bir çatışma başlatma aracıdır ama yine de takımından fazla uzaklaşmamaya dikkat et."],["Tam yüklenmiş bir Duvar Delen, iki katı hasar verir; Vi'ın hücuma geçtiğini görürsen geri çekilmeli veya saldırıyı savuşturmaya çalışmalısın.","Vi sana üst üste üç kez vurmayı başarırsa, Zırhını eksiltir ve Saldırı Hızı kazanır. Onunla uzun dövüşlere girmemeye çalış.","Vi ulti yeteneğini kullanırken durdurulamaz. Yer değiştirme yeteneklerini, Vi'ın hücumundan sonrası için saklamaya çalış."]]},"viego":{"id":"Viego","k":234,"n":"Viego","en":"Viego","t":"Mahvolmuş Kral","cls":["Fighter","Assassin"],"d":2,"res":"Yok","b":{"hp":630,"hpL":109,"ar":34,"arL":4.6,"mr":32,"mrL":2.05,"ad":57,"adL":4,"as":0.658,"asR":0.658,"asL":2.75,"rng":200,"ms":345,"t":"P"},"ab":[["Kralın Hükmü","P","Viego'nun alt ettiği rakipler hortlağa dönüşür. Viego hortlağa saldırarak katledilen rakibin cesedini geçici olarak ele geçirir. Bu sırada hedefin azami canının yüzdelik bir bölümüne eşdeğer miktarda iyileşir ve onun temel yetenekleriyle eşyalarına erişebilir. Hedefin ultisini kendi ultisiyle değiştirir ve bunu bedelsiz kullanabilir.","img/abil/viego-p.png"],["Mahvolmuş Kralın Kılıcı","Q","Viego'nun hayalet kılıcı isabet halinde hedefin mevcut canının yüzdelik bir bölümüne eşdeğer miktarda ilave hasar verir ve kısa süre önce yeteneklerinden isabet alan rakiplere iki defa saldırarak can çalar. Viego bu yeteneği kullanarak kılıcını önündeki rakiplere saplayabilir.","img/abil/viego-q.png",[5,4.5,4,3.5,3]],["Hortlağın Dişleri","W","Viego ileri atılmadan önce yoğunlaşarak isabet ettiği ilk rakibi sersemleten, yoğun bir Kara Sis topu gönderir.","img/abil/viego-w.png",[8,8,8,8,8]],["Ecel Yolu","E","Viego Kara Sis'e hükmederek bir yüzey şekli parçasına musallat olur ve burayı çevreler. Viego sisin içinde hayalet olarak saklanıp kamuflaja bürünebilir, hareket hızı kazanabilir ve saldırı hızı elde edebilir.","img/abil/viego-e.png",[14,12,10,8,6]],["Kederli Yürek","R","Viego yakınındaki bir konuma ışınlanır ve hedef bölgeye ulaştığında bir rakip şampiyonu infaz eder. Kılıcı rakibin kalbini delerek yıkıcı bir şok dalgası oluşturur ve hedefin takım arkadaşlarını geri savurur.","img/abil/viego-r.png",[120,100,80]]],"wk":"Viego","p":"img/champ/viego.png","tip":[[],[]]},"viktor":{"id":"Viktor","k":112,"n":"Viktor","en":"Viktor","t":"Sihrin Elçisi","cls":["Mage"],"d":3,"res":"Mana","b":{"hp":600,"hpL":105,"ar":23,"arL":4.4,"mr":30,"mrL":1.3,"ad":53,"adL":3,"as":0.658,"asR":0.657999992370605,"asL":2.11,"rng":525,"ms":330,"t":"M"},"ab":[["Evrimin İhtişamı","P","Viktor katlettiği rakip başına hex parça kazanır. Biriktirdiği her 100 Hex Parça başına Viktor, bir aktif yeteneğini kalıcı olarak geliştirir. Tüm temel yeteneklerini geliştirdikten sonra 100 Hex Parça daha biriktirerek ultisini geliştirebilir.","img/abil/viktor-p.png"],["Güç Aktarımı","Q","Viktor bir rakip birime büyü hasarı vererek bir kalkan kazanır ve sonraki normal saldırısını güçlendirir. Geliştirme: Güç Aktarımı'nın kalkanı %60 artar ve Viktor yeteneği kullandıktan sonra ilave hareket hızı kazanır.","img/abil/viktor-q.png",[9,8,7,6,5]],["Çekim Alanı","W","Viktor etki alanına giren rakipleri yavaşlatan bir kütle çekimi alanı oluşturur. Bu alanda fazla kalan rakipler sersemler. Geliştirme: Viktor'un yetenekleri rakipleri yavaşlatır.","img/abil/viktor-w.png",[17,16,15,14,13]],["Hextech Işını","E","Viktor, biyomekanik kolunu kullanarak zemini bir hat üstünde kesen ve temas ettiği tüm rakiplere hasar veren bir Hextech Işını ateşler. Geliştirme: Hextech Işını'nı büyü hasarı veren bir dizi patlama takip eder.","img/abil/viktor-e.png",[12,11,10,9,8]],["Sihir Fırtınası","R","Viktor büyü hasarı veren ve rakiplerin yoğunlaşmalarını bozan bir Sihir Fırtınası oluşturur. Fırtına yakınındaki tüm rakiplere belli aralıklarla büyü hasarı verir ve Viktor tarafından yeniden yönlendirilebilir. Geliştirme: Sihir Fırtınası %25 daha hızlı hareket eder. Ayrıca bir şampiyon fırtınadan hasar aldıktan sonra katledilirse fırtına büyür ve süresini arttırır.","img/abil/viktor-r.png",[120,100,80]]],"wk":"Viktor","p":"img/champ/viktor.png","tip":[["Hextech Işını güçlü bir dürtme ve alan daraltma aracıdır. Rakibin konumunu kontrol etmek için bu yeteneği Çekim Alanı ile birlikte kullan.","Doğru geliştirmeyi doğru zamanda seçtiğinden emin ol."],["Viktor'u kendine ne kadar yaklaştırdığına dikkat et. Rakibine yakınlığı arttıkça Viktor'un savaş alanı kontrolü de artar.","Viktor'un sopasının rengine bakarak, kaç tane eklenti kullandığını ayırt edebilirsin (mor, sarı, mavi, kırmızı)."]]},"vladimir":{"id":"Vladimir","k":8,"n":"Vladimir","en":"Vladimir","t":"Kızıl Ölüm","cls":["Mage","Fighter"],"d":3,"res":"Kızıl Akım","b":{"hp":600,"hpL":110,"ar":24,"arL":4.5,"mr":30,"mrL":1.3,"ad":55,"adL":3,"as":0.658,"asR":0.657999992370605,"asL":2,"rng":450,"ms":330,"t":"M"},"ab":[["Kızıl Akit","P","Her 30 İlave Can, Vladimir'e 1 Yetenek Gücü ve her 1 Yetenek Gücü, Vladimir'e 1,6 İlave Can verir (kendi sağladığı avantaj birikmez).","img/abil/vladimir-p.png"],["Kan Nakli","Q","Vladimir hedefinden can çeker. Vladimir'in kaynağı dolduğunda, Kan Nakli kısa süreliğine büyük oranda hasar ve iyileştirme artışı sağlar.","img/abil/vladimir-q.png",[9,7.9,6.8,5.7,4.6]],["Kızıl Havuz","W","Vladimir bir kan havuzuna dalarak 2 saniyeliğine hedef alınamaz hale gelir. Ayrıca Vladimir havuzun üstünde duran rakipleri yavaşlatır ve onlardan can sömürür.","img/abil/vladimir-w.png",[28,25,22,19,16]],["Kan Yağmuru","E","Vladimir kendi canını feda ederek kan depolamaya başlar ve depolanan kan, serbest bırakıldığı zaman çevresindeki alana hasar verir; ancak rakipler tarafından engellenebilir.","img/abil/vladimir-e.png",[13,11,9,7,5]],["Kan Vebası","R","Vladimir belli bir bölgeye bulaşıcı bir hastalık yayar. Etkilenen rakipler, etki süresi boyunca artacak şekilde hasar alır. Kan Vebası, birkaç saniye sonra etkisi altındaki rakiplere büyü hasarı verir ve Vladimir'i hasar alan şampiyon başına iyileştirir.","img/abil/vladimir-r.png",[120,120,120]]],"wk":"Vladimir","p":"img/champ/vladimir.png","tip":[["Kan Nakli Vladimir'i iyileştirmeden önce hemen rakibe hasar verir ve bu onu oyundaki son darbeyi vuran en iyi araçlardan biri yapar.","Kan Vebası'nı en çok birimi etkileyecek yerde yap.","Kızıl Havuz, gelen menzilli saldırıları etkisiz kılar; bu yüzden de engellemeleri savuşturmada kullanılabilir."],["Kan Vebası patlamadan önce Vladimir'i alaşağı etmeye çalış, yoksa etkilenen her şampiyon başına iyileşir.","Vladimir'e Kızıl Havuz'u çatışma başında kullandırmak, yeteneğin can bedelini olabildiğince arttıracaktır.","Liandry'nin Eziyeti ve Mahvolmuş Kralın Kılıcı gibi can yüklemeye karşı etkili eşyalar Vladimir'in karşısında oldukça kuvvetlidir."]]},"volibear":{"id":"Volibear","k":106,"n":"Volibear","en":"Volibear","t":"Ebedi Fırtına","cls":["Fighter","Tank"],"d":1,"res":"Mana","b":{"hp":650,"hpL":104,"ar":35,"arL":5.2,"mr":32,"mrL":2.05,"ad":65,"adL":3.5,"as":0.625,"asR":0.7,"asL":2,"rng":150,"ms":340,"t":"P"},"ab":[["Ebedi Fırtına","P","Volibear'in saldırı ve yetenekleri saldırı hızı kazandırır ve saldırılarının zamanla yakındaki rakiplere ilave büyü hasarı vermesini sağlar.","img/abil/volibear-p.png"],["Şimşek Darbesi","Q","Volibear rakiplere doğru ilerlerken hız kazanır. Saldırdığı ilk hedefi sersemletir ve ona hasar verir.","img/abil/volibear-q.png",[12,11.5,11,10.5,10]],["Hırpalayan Vahşet","W","Volibear bir rakibe hasar vererek isabet etkilerini uygular ve onu işaretler. Bu yeteneği aynı hedef üstünde kullanmak ona ilave hasar verir ve Volibear'i iyileştirir.","img/abil/volibear-w.png",[5,5,5,5,5]],["Bulutların Gazabı","E","Volibear belli bir bölgeye yıldırım çağırarak rakiplere hasar verir ve onları yavaşlatır. Volibear yıldırım düşen alanın içindeyse kalkan kazanır.","img/abil/volibear-e.png",[16,16,16,16,16]],["Fırtınaçağıran","R","Volibear hedef konuma atlayarak ilave can kazanırken altındaki rakipleri yavaşlatır ve onlara hasar verir. İniş bölgesinin yakınındaki kuleler geçici olarak devre dışı kalır.","img/abil/volibear-r.png",[160,135,110]]],"wk":"Volibear","p":"img/champ/volibear.png","tip":[[],[]]},"warwick":{"id":"Warwick","k":19,"n":"Warwick","en":"Warwick","t":"Zaun'un Kafes Kaçkını Belası","cls":["Fighter","Tank"],"d":1,"res":"Mana","b":{"hp":620,"hpL":99,"ar":33,"arL":4.4,"mr":32,"mrL":2.05,"ad":65,"adL":2.5,"as":0.638,"asR":0.638000011444091,"asL":2,"rng":125,"ms":335,"t":"P"},"ab":[["Ebedi Açlık","P","Warwick'in normal saldırıları ilave büyü hasarı verir. Canı %50'nin altındaysa Warwick bu hasar kadar iyileşir. Canı %25'in altındaysa Warwick'in iyileşmesi üç katına çıkar.","img/abil/warwick-p.png"],["Cani Diş","Q","Warwick ileri atılarak hedefini ısırır, hedefin azami canına bağlı olarak hasar verir ve verdiği hasar kadar iyileşir.","img/abil/warwick-q.png",[8,7.5,7,6.5,6]],["Kan Peşinde","W","Warwick canı %50'nin altındaki rakipleri sezerek onlara doğru ilerlerken hareket hızı ve onlara karşı saldırı hızı kazanır. Rakibinin canı %25'in altına indiğinde Warwick kudurur ve kazandığı ilave etkiler üç katına çıkar.","img/abil/warwick-w.png",[80,70,60,50,40]],["Dehşetin Sesi","E","Warwick 2,5 saniyeliğine hasar azaltma kazanır. Bu sürenin sonunda veya yetenek yeniden kullanıldığında Warwick uluyarak yakındaki rakiplerin 1 saniyeliğine dehşet içinde kaçışmalarını sağlar.","img/abil/warwick-e.png",[15,14,13,12,11]],["Sonsuz Şiddet","R","Warwick belli bir yöne atılarak (atılma mesafesi, ilave hareket hızına bağlı olarak artar) karşısına çıkan ilk şampiyonu 1,5 saniye boyunca sindirir.","img/abil/warwick-r.png",[110,90,70]]],"wk":"Warwick","p":"img/champ/warwick.png","tip":[["Kan Peşinde'nin ortaya çıkardığı izleri takip ederek canı az olan şampiyonlara ulaşabilirsin.","Sonsuz Şiddet (R) ile kat ettiğin mesafe -takım arkadaşlarının ve sihirdar büyülerinin sağladıkları da dahil- edindiğin her tür hareket hızıyla artar.","Tuşunu basılı tuttuğun sürece Cani Diş (Q) kaçan, atılan veya ışınlanan rakipleri takip eder."],["Canı azaldığında yaptığı saldırılar Warwick'i iyileştirir. Engelleme yeteneklerini onun işini bitirmek için sakla.","Warwick canı az rakiplere karşı güçlenir. Onu dizginlemek için kendi canını iyi idare et.","Warwick'in ultisinin kullanım menzili hareket hızına bağlı olarak artar."]]},"xayah":{"id":"Xayah","k":498,"n":"Xayah","en":"Xayah","t":"Asi","cls":["Marksman"],"d":2,"res":"Mana","b":{"hp":630,"hpL":107,"ar":25,"arL":4.2,"mr":33,"mrL":1.1,"ad":60,"adL":3.5,"as":0.658,"asR":0.658,"asL":3.9,"rng":525,"ms":330,"t":"P"},"ab":[["Kusursuz Kesik","P","Xayah'nın bir yetenek kullandıktan sonraki normal saldırıları, yollarına çıkan bütün hedeflere isabet eder ve düştükleri yerde bir tüy bırakır.","img/abil/xayah-p.png"],["Çifte Hançer","Q","Xayah hasar veren iki hançer atar ve hançerler düştükleri yerde geri çağrılabilen tüyler bırakır.","img/abil/xayah-q.png",[10,9.5,9,8.5,8]],["Amansız Hiddet","W","Xayah saldırı hızı ve hasarını arttıran tüylerden bir fırtına oluşturur ve bu fırtına bir şampiyona saldırırsa Xayah'ya hareket hızı kazandırır.","img/abil/xayah-w.png",[18,17,16,15,14]],["Keskin Çekim","E","Xayah düşen tüylerinin hepsini geri çağırarak rakiplere hasar verip onları yerine sabitler.","img/abil/xayah-e.png",[12,11,10,9,8]],["Tüy Fırtınası","R","Xayah havaya sıçrayarak hedef alınmaz hâle gelir ve bir dizi bıçak yağdırır. Yağdırdığı bıçaklar düştükleri noktada geri çağrılabilen tüyler bırakır.","img/abil/xayah-r.png",[140,120,100]]],"wk":"Xayah","p":"img/champ/xayah.png","tip":[["Xayah'nın saldırı ve yetenekleri zeminde, sonradan çağırarak muazzam alan hasar ve kontrolü ortaya çıkaran tüyler bırakır.","Xayah neredeyse her yetenekten sıyrılıp bir sürü tüy ortaya çıkarmak için Tüy Fırtınası yeteneğini kullanabilir. Bu yeteneğin savunma ve saldırıya yönelik özelliklerinden en iyi şekilde faydalanmaya çalış."],["Xayah'nın Keskin Çekim yeteneği sadece 3 veya daha fazla dönen tüyden isabet alan rakipleri yerlerine sabitler.","Aynı yerde uzun süren çatışmalar Xayah'nın bir sürü tüy bırakmasına olanak sağlar. O yüzden sürekli hareket etmeye çalış!","Skor almaya karar verdiğinde hazırlıklarının tamam olmasına dikkat et. Tüy Fırtınası'yla hedef alınamaz hâle geldiğinde Xayah kurduğun pusuyu bir anda senin aleyhine çevirebilir."]]},"xerath":{"id":"Xerath","k":101,"n":"Xerath","en":"Xerath","t":"Yüksek Büyücü","cls":["Mage","Support"],"d":3,"res":"Mana","b":{"hp":575,"hpL":106,"ar":22,"arL":4.7,"mr":30,"mrL":1.3,"ad":55,"adL":3,"as":0.658,"asR":0.625,"asL":1.36,"rng":525,"ms":340,"t":"M"},"ab":[["Mana Akını","P","Xerath'ın normal saldırıları belli aralıklarla mana yeniler. Xerath bir birim katlettiğinde bu bekleme süresi azalır.","img/abil/xerath-p.png"],["Sihir Darbesi","Q","İsabet ettiği bütün rakiplere büyü hasarı veren, uzun menzilli bir enerji ışını ateşler.","img/abil/xerath-q.png",[9,8,7,6,5]],["Yıkım Bölgesi","W","Sihir enerjisiyle yoğun bir saldırı oluşturarak, belli bir bölgedeki bütün rakiplere büyü hasarı verir. Ortadaki hedefler ilave hasar alır ve daha ağır yavaşlatma etkisine maruz kalır.","img/abil/xerath-w.png",[14,13,12,11,10]],["Şok Küresi","E","Bir rakibin büyü hasarı almasına ve sersemlemesine yol açar.","img/abil/xerath-e.png",[13,12.5,12,11.5,11]],["Sihir Ayini","R","Xerath hareketsiz kalarak uzun menzilli atışlar yapar.","img/abil/xerath-r.png",[130,115,100]]],"wk":"Xerath","p":"img/champ/xerath.png","tip":[["Sihir Darbesi'ni yanlara kaçanlardan ziyade, sana doğru gelen ya da senden uzaklaşan rakibe isabet ettirmek daha kolaydır.","Yıkım Bölgesi hedefi yavaşlatacağından, Sihir Darbesi'ni isabet ettirmen kolaylaşır.","Bir rakibi Şok Küresi ile sersemletirsen, Yıkım Bölgesi ile garantili bir saldırı yap."],["Xerath'ın menzili korkutucu olabilir ama mesafeyi kapatabilen çoğu şampiyon ona karşı üstün duruma geçebilir.","Xerath'ın Sihir Ayini'ni etkinleştirmesi zaman alır. Büyü yapma animasyonunu izle ve savuşturmaya başla.","Banshee'nin Duvağı; Xerath'ın, Şok Küresi'ni isabet ettirmesini zorlaştıracaktır."]]},"xinzhao":{"id":"XinZhao","k":5,"n":"Xin Zhao","en":"Xin Zhao","t":"Demacia'nın Hizmetkârı","cls":["Fighter","Tank"],"d":1,"res":"Mana","b":{"hp":620,"hpL":106,"ar":35,"arL":4.4,"mr":32,"mrL":2.05,"ad":63,"adL":3,"as":0.645,"asR":0.644999980926513,"asL":3.5,"rng":175,"ms":345,"t":"P"},"ab":[["Mücadele Azmi","P","Her üçüncü saldırı ilave hasar verir ve Xin Zhao'yu iyileştirir.","img/abil/xinzhao-p.png"],["Üç Pençe Saldırısı","Q","Xin Zhao'nun sonraki 3 normal saldırısının verdiği hasar artarken üçüncü saldırı, rakibini havaya savurur.","img/abil/xinzhao-q.png",[7,6.5,6,5.5,5]],["Rüzgârdan Şimşeğe","W","Xin Zhao kargısıyla önündeki alanı biçer ve daha sonra onu ileri saplayarak etkilenen rakipleri yavaşlatır ve onlara meydan okur.","img/abil/xinzhao-w.png",[12,11,10,9,8]],["Yürekli Hücum","E","Xin Zhao bir rakibe hücum ederek saldırı hızı kazanır ve alandaki bütün birimlere hasar vererek onları kısa süreliğine yavaşlatır. Bu yetenek meydan okunmuş hedeflere karşı menzil kazanır.","img/abil/xinzhao-e.png",[11,11,11,11,11]],["Hilal Koruması","R","Xin Zhao kısa süre önce hasar verdiği bir rakibe pasif olarak meydan okur. Etkinleştirildiğinde Xin Zhao yakındaki rakiplere mevcut canlarına bağlı olarak hasar verip meydan okunmamış hedefleri geri savurur ve ortaya çıkan çemberin dışında kalan şampiyonlardan gelen hasardan etkilenmez.","img/abil/xinzhao-r.png",[120,110,100]]],"wk":"Xin Zhao","p":"img/champ/xinzhao.png","tip":[["Xin Zhao çatışma başlatmak için idealdir. Önden giderek çatışmayı başlat ve ultinle mümkün olan en yüksek hasarı ver.","Ultinin geri savurma etkisinden en iyi sonucu alacağın bir yere geçmeye çalış."],["Xin Zhao hem saldırısı hem de çevresindeki bütün birimlere hasar veren ultisiyle güçlü bir öncüdür. Ultisini kullanana kadar takımını dağınık tutmaya çalış.","Xin Zhao hasar ve bekleme süresinin sıfırlanması için Üç Pençe Saldırılarına bel bağlar; o yüzden kombosunu bitirmesine engel olmak işleri çok değiştirecektir."]]},"yasuo":{"id":"Yasuo","k":157,"n":"Yasuo","en":"Yasuo","t":"Günahkâr Kılıç","cls":["Fighter","Assassin"],"d":3,"res":"Akış","b":{"hp":590,"hpL":110,"ar":32,"arL":4.6,"mr":32,"mrL":2.05,"ad":60,"adL":2.5,"as":0.697,"asR":0.6700000166893,"asL":3.5,"rng":175,"ms":345,"t":"P"},"ab":[["Avarenin Yolu","P","Yasuo'nun kritik vuruş ihtimali artar. Ayrıca Yasuo, hareket ederken bir yandan da kalkan oluşturur. Bir şampiyondan ya da canavardan hasar aldığında, kalkan devreye girer.","img/abil/yasuo-p.png"],["Çelik Fırtına","Q","İleri fırlayarak bir hat üstündeki tüm rakiplere hasar verir. İsabet halinde, birkaç saniyeliğine bir Yaklaşan Kasırga yükü verir. 2 yük biriktiğinde, Çelik Fırtına'nın yolladığı hortum havaya savurur. Çelik Fırtına normal saldırı muamelesi görür ve normal saldırıları güçlendiren her şeyle birlikte güçlenir.","img/abil/yasuo-q.png",[4,4,4,4,4]],["Rüzgâr Duvarı","W","Oluşturduğu hareketli duvar, 4 saniyeliğine rakiplerden gelen tüm atışları engeller.","img/abil/yasuo-w.png",[25,23,21,19,17]],["Atılgan Kılıç","E","Hedef rakibi deşip geçerek ona büyü hasarı verir. Yeteneğin her kullanımı sonraki atılmanın hasarını belli bir miktara kadar arttırır. Aynı rakip üstünde birkaç saniye boyunca yeniden kullanılamaz. Çelik Fırtına yeteneği atılma esnasında kullanılırsa daire biçiminde bir alana isabet eder.","img/abil/yasuo-e.png",[0.5,0.4,0.3,0.2,0.1]],["Son Nefes","R","Havadaki bir rakip şampiyonun yanında belirerek ona fiziksel hasar verir ve bölgede bulunan tüm havadaki rakipleri havada tutar. Azami Akış verir ama Yaklaşan Kasırga'nın tüm yüklerini sıfırlar. Bunun ardından, Yasuo'nun kritik vuruşları ortalama bir süre boyunca önemli miktarda ilave zırh delme elde eder.","img/abil/yasuo-r.png",[70,50,30]]],"wk":"Yasuo","p":"img/champ/yasuo.png","tip":[["Rakibin kaçma ihtimaline karşı onu takip edebilmek için atılarak bir minyonu biçip Çelik Fırtına'yı hazırla; rakibe doğrudan atılarak, kaçış için bir minyonu saklayabilirsin.","18. seviyede, Yasuo'nun Çelik Fırtına'sı eşyalardan gelen %55 Saldırı Hızı ile Saldırı Hızı sınırına ulaşır.","Son Nefes, Yasuo ya da takım arkadaşları tarafından havaya savrulmuş olan tüm hedefler üstünde kullanılabilir."],["Çelik Fırtına çok dardır. Mümkünse yana doğru kaç.","Yasuo üst üste iki Çelik Fırtına isabet ettirdiğinde sonraki saldırısı hortum yollar. Bundan kaçınmak için dikkatli ol ve hortumun sesini dinle.","Yasuo kasırga yolladıktan hemen sonra çok zayıf kalır. Çatışmaya o zaman gir.","Yasuo'nun Akıbet kalkanı sadece 2 saniye sürer. Ona hasar verirsen kalkanı açılır. Kalkanı tükendikten sonra çatışmaya gir."]]},"yone":{"id":"Yone","k":777,"n":"Yone","en":"Yone","t":"Unutulmayan Kılıç","cls":["Fighter","Assassin"],"d":3,"res":"Akış","b":{"hp":620,"hpL":105,"ar":33,"arL":4.6,"mr":32,"mrL":2.05,"ad":62,"adL":2,"as":0.625,"asR":0.625,"asL":3.5,"rng":175,"ms":345,"t":"P"},"ab":[["Avcının Yolu","P","Yone gerçekleştirdiği her ikinci saldırıyla büyü hasarı verir. Ayrıca, kritik vuruş ihtimali artar.","img/abil/yone-p.png"],["Ölümcül Çelik","Q","İleri hücum ederek bir hat üstündeki tüm rakiplere hasar verir. İsabet halinde birkaç saniyeliğine Yaklaşan Kasırga yükü kazandırır. İki yüke ulaştığında Ölümcül Çelik, Yone'nin rüzgârla birlikte ileri atılarak rakipleri havaya savurmasını sağlar.","img/abil/yone-q.png",[4,4,4,4,4]],["Tayfbiçen","W","Yone kılıcını önündeki koni şeklindeki alanda savurarak tüm rakiplere hasar verir. Bu yetenek Yone'ye bir kalkan kazandırır. Kalkan miktarı isabet alan şampiyonların sayısına bağlı olarak artar. Tayfbiçen'in bekleme ve kullanım süresi saldırı hızı arttıkça azalır.","img/abil/yone-w.png",[14,14,14,14,14]],["Özgür Ruh","E","Yone'nin ruhu bedeninden ayrılarak hareket hızı kazanır. Bu yetenek sona erdiğinde Yone'nin ruhu bedenine geri döner ve Yone ruh olarak verdiği hasarın bir kısmını tekrar verir.","img/abil/yone-e.png",[22,19,16,13,10]],["Mühürlü Kader","R","Yone kılıçlarını tüm gücüyle savurarak bir hat üstünde duran son şampiyonun arkasında belirir ve isabet alan tüm rakipleri kendisine doğru çeker.","img/abil/yone-r.png",[120,100,80]]],"wk":"Yone","p":"img/champ/yone.png","tip":[[],[]]},"yorick":{"id":"Yorick","k":83,"n":"Yorick","en":"Yorick","t":"Ruhların Çobanı","cls":["Fighter","Tank"],"d":2,"res":"Mana","b":{"hp":650,"hpL":114,"ar":36,"arL":4.5,"mr":32,"mrL":2.05,"ad":62,"adL":5,"as":0.625,"asR":0.625,"asL":2,"rng":175,"ms":340,"t":"P"},"ab":[["Ruhların Çobanı","P","Lanetli Sürü: Yorick yakınındaki rakiplerin etrafını saran ve onlara saldıran Sis Gezginleri çağırır.","img/abil/yorick-p.png"],["Son Dua","Q","Yorick bir sonraki saldırısında ilave hasar verir ve kendini iyileştirir. Hedefi bir şampiyon veya büyük canavarsa veya hedefi katledilirse arkasında bir mezar bırakır.","img/abil/yorick-q.png",[6,5.5,5,4.5,4]],["Kara Tören","W","Yorick'in hedef konumda ortaya çıkardığı yıkılabilir duvar rakiplerin hareketini engeller.","img/abil/yorick-w.png",[20,18,16,14,12]],["Sisin Matemi","E","Yorick'in attığı Kara Sis kitlesi hasar verdiği hedeflerin zırhını azaltır ve onları yavaşlatarak işaretler. Yorick'in çağırdığı birimler işaretli hedeflere doğru ilerlerken hareket hızı kazanır.","img/abil/yorick-e.png",[12,11,10,9,8]],["Adaların Ağıdı","R","Yorick Sis'in Hanımı'nı çağırır ve Yorick'in yapacağı Sis'in Hanımı'nın hedefine yönelik saldırıları ilave hasar verir. Sis'in Hanımı da katledilen rakipleri komuta ihtiyaç duymadan Sis Gezgini olarak diriltir.","img/abil/yorick-r.png",[160,130,100]]],"wk":"Yorick","p":"img/champ/yorick.png","tip":[["Son Dua yeteneğini yeniden kullanabilmek için Uyanış kullanman şart değildir.","Sis'in Hanımı çatışmalarda sana yardımcı olmaya çalışır; bu yüzden hedeflerini iyi seç.","Sis'in Hanımı'nı bir koridora tek başına gönderebilirsin ama dikkatli ol; çatışma gücünün büyük bölümünü Sis'in Hanımı'na borçlu olduğun için bu, gücünden fedakârlık yapman anlamına gelebilir."],["Çarp büyüsünü hasar verme veya katletme amacıyla Sis Gezginleri ve Sis'in Hanımı üzerinde kullanabilirsin.","Yorick'le çatışmaya başlamadan önce minyonlarını azaltmaya çalış; Sis Gezginleri normal saldırı veya tek hedefli yeteneklerle katledilebilir.","Kara Tören'le ortaya çıkan duvarı saldırılarınla yıkabilirsin."]]},"yunara":{"id":"Yunara","k":804,"n":"Yunara","en":"Yunara","t":"Yıkılmaz İtikat","cls":["Marksman"],"d":2,"res":"Mana","b":{"hp":590,"hpL":110,"ar":25,"arL":4.4,"mr":33,"mrL":1.1,"ad":55,"adL":3,"as":0.65,"asR":0.65,"asL":2,"rng":575,"ms":325,"t":"P"},"ab":[["İlk Diyar'a Yemin","P","Yunara'nın kritik vuruşları ilave büyü hasarı verir.","img/abil/yunara-p.png"],["Ruh Filizleri","Q","Yunara saldırı hızı kazanır, isabet halinde ilave hasar verir ve saldırıları yakındaki rakiplere saçılır.","img/abil/yunara-q.png",[0,0,0,0,0]],["Yargı Kemeri | Yıkım Kemeri","W","Yunara, rakiplere hasar veren ve onları yavaşlatan bir dönen tespih boncuğu gönderir. Sınırları aşmışken rakiplere hasar veren ve onları yavaşlatan bir lazer ateşler.","img/abil/yunara-w.png",[10,10,10,10,10]],["Kanmei'nin Adımları | Dokunulmaz Gölge","E","Yunara hareket hızı ve hayalet etkisi kazanır. Sınırları aşmışken belli bir yönde atılır.","img/abil/yunara-e.png",[9,9,9,9,9]],["Sınırlarını Aş","R","Yunara sınırlarını aşarak temel yeteneklerini geliştirir.","img/abil/yunara-r.png",[100,90,80]]],"wk":"Yunara","p":"img/champ/yunara.png","tip":[[],[]]},"yuumi":{"id":"Yuumi","k":350,"n":"Yuumi","en":"Yuumi","t":"Sihirli Kedi","cls":["Support","Mage"],"d":1,"res":"Mana","b":{"hp":500,"hpL":69,"ar":25,"arL":4.2,"mr":25,"mrL":1.1,"ad":49,"adL":3.1,"as":0.625,"asR":0.625,"asL":1,"rng":425,"ms":330,"t":"M"},"ab":[["En İyi Arkedişim","P","Yuumi bir şampiyona normal saldırı veya yeteneklerle hasar verdiğinde belli aralıklarla kendi canını ve yapıştığı sonraki takım arkadaşının canını yeniler. Yuumi yapışık haldeyken takım arkadaşlarıyla özel bir bağ kurar. En güçlü bağa sahip takım arkadaşı Yuumi ona yapışıkken Yuumi'nin yeteneklerini güçlendirir.","img/abil/yuumi-p.png"],["Sinsi Atış","Q","Yuumi isabet ettiği ilk hedefe hasar veren ve onu yavaşlatan bir atış yapar. Bu atış ilave hasar verir ve hedefe ulaşması en az 1,35 saniye sürerse güçlendirilmiş yavaşlatma uygular. Yuumi en iyi arkadaşının üstündeyken daima güçlendirilmiş yavaşlatma uygular ve takım arkadaşının isabet halinde ilave hasar vermesini sağlar. Yuumi yapışık haldeyken atışı kısa süreliğine fareyle kontrol edebilir.","img/abil/yuumi-q.png",[6.5,6.5,6.5,6.5,6.5,6.5]],["Sen ve Ben!","W","Yuumi hedef takım arkadaşının üstüne atılarak kuleler dışındaki birimlerce hedef alınamaz hale gelir. En iyi arkadaşının üstündeyken iyileştirme ve kalkan gücü kazanır. Ayrıca takım arkadaşına isabet halinde iyileştirme sağlar.","img/abil/yuumi-w.png",[0,0,0,0,0]],["Çıldırrr","E","Yuumi'ye kalkan sağlar ve hareket hızı ile saldırı hızını arttırır. Yuumi bir takım arkadaşına yapışık haldeyse bu etkiyi ona aktarır.","img/abil/yuumi-e.png",[10,10,10,10,10]],["Son Sayfa","R","Yuumi yoğunlaşarak rakiplere hasar veren ve takım arkadaşlarını iyileştiren beş dalga gönderir. Yuumi yoğunlaşma esnasında hareket edebilir, bir şampiyona yapışabilir ve Çıldırrr yeteneğini kullanabilir. Ayrıca bu yetenek Yuumi en iyi arkadaşının üstündeyken fareyi takip eder.","img/abil/yuumi-r.png",[120,110,100]]],"wk":"Yuumi","p":"img/champ/yuumi.png","tip":[[],[]]},"zaahen":{"id":"Zaahen","k":904,"n":"Zaahen","en":"Zaahen","t":"Daimi","cls":["Fighter"],"d":1,"res":"Mana","b":{"hp":640,"hpL":114,"ar":36,"arL":5,"mr":32,"mrL":2.05,"ad":63,"adL":4,"as":0.625,"asR":0.625,"asL":2.5,"rng":175,"ms":345,"t":"P"},"ab":[["Savaş Filizleri","P","Zaahen'in rakip şampiyonlara yönelik saldırıları ve yetenekleri Kararlılık yükü kazandırır. Zaahen yük başına ilave saldırı gücü kazanır. Kararlılık ile dolduğunda Zaahen saldırı gücü artışı kazanır ve dirilebilir.","img/abil/zaahen-p.png"],["Darkin Mızrağı","Q","Zaahen bir sonraki saldırısında mızrağını iki kere savurarak ilave hasar verir ve kendini iyileştirir. Zaahen bu yeteneği yeniden kullanarak bir sonraki saldırısının ilave hasar verip hedefini havaya savurmasını sağlayabilir.","img/abil/zaahen-q.png",[8,7.5,7,6.5,6]],["Heybetli Dönüş","W","Zaahen mızrağını belli bir yöne doğru saplayarak isabet alan rakiplere hasar verir ve onları kendine doğru çeker.","img/abil/zaahen-w.png",[14,13.5,13,12.5,12]],["Yaldızlı Hücum","E","Zaahen hedef noktaya atılarak etrafına saldırır.","img/abil/zaahen-e.png",[10,9.5,9,8.5,8]],["Vahim Yargı","R","Zaahen yükselir ve mızrağını aşağıya doğru saplar. İsabet alan rakiplere hasar verir ve verdiği hasarın belli bir kısmına eşdeğer miktarda iyileşir.","img/abil/zaahen-r.png",[110,95,80]]],"wk":"Zaahen","p":"img/champ/zaahen.png","tip":[[],[]]},"zac":{"id":"Zac","k":154,"n":"Zac","en":"Zac","t":"Gizli Silah","cls":["Tank","Fighter"],"d":3,"res":"Yok","b":{"hp":685,"hpL":109,"ar":33,"arL":5.2,"mr":32,"mrL":2.05,"ad":60,"adL":3.4,"as":0.736,"asR":0.638000011444091,"asL":1.6,"rng":175,"ms":340,"t":"M"},"ab":[["Hücre Bölünmesi","P","Zac bir yeteneğiyle rakibe her vurduğunda kendinden bir parça bırakır. Bu parçayı geri alarak Can yenileyebilir. Ölümcül hasar aldığında Zac 4 pelte parçasına bölünür; bu parçalar tekrar birleşmeye çalışır. Sağlam kalan pelte parçaları olursa, Zac bu peltelerin Can değerlerine bağlı olarak değişen Can miktarıyla tekrar dirilir. Sağlam kalan her pelte parçası Zac'in azami Can, Zırh ve Büyü Direnci değerlerinin belli bir yüzdesine sahiptir. Bu yeteneğin bekleme süresi 5 dakikadır.","img/abil/zac-p.png"],["Esnek Saldırı","Q","Zac kollarından birini uzatarak bir rakibini yakalar. Başka bir rakibe saldırdığında iki hedefi tokuşturmak için birbirine doğru savurur.","img/abil/zac-q.png",[14,12.5,11,9.5,8]],["Maddenin Kararsız Hali","W","Zac yakınındaki rakiplere doğru patlayarak azami canlarının yüzdelik bir kısmını büyü hasarı olarak verir.","img/abil/zac-w.png",[5,5,5,5,5]],["Elastik Sapan","E","Zac kollarını yere sabitleyip geri geri gider, sonra kendini öne fırlatır.","img/abil/zac-e.png",[21,18,15,12,9]],["Hoplaya Zıplaya!","R","Zac dört kez zıplayarak isabet alan rakipleri havaya savurur ve yavaşlatır.","img/abil/zac-r.png",[120,105,90]]],"wk":"Zac","p":"img/champ/zac.png","tip":[["Pelte parçalarını toplamak, hayatta kalmak açısından büyük önem taşıyor.","Hücre Bölünmesi hazır olduğunda, rakip takımın, peltelerini yok etmesini zorlaştıracak bir konumda ölmeye çalış.","Elastik Sapan'ı savaş sisinden başlatmak, rakiplerin daha geç tepki vermesini sağlar."],["Zac kendisinden ayrılan pelte parçalarını toplayarak iyileşir. Pelte parçalarının üzerine basarak onları ezebilirsin.","Zac dağıldığında, tüm pelte parçalarını yok ederek Zac'in dirilmesini önle.","Susturma, sersemletme, sabitleme ve savurma etkileri, Zac'in Elastik Sapan'ını kullanmasını engelleyecektir."]]},"zed":{"id":"Zed","k":238,"n":"Zed","en":"Zed","t":"Gölgelerin Efendisi","cls":["Assassin"],"d":3,"res":"Enerji","b":{"hp":654,"hpL":99,"ar":32,"arL":4.7,"mr":29,"mrL":2.05,"ad":63,"adL":3.4,"as":0.651,"asR":0.651000022888183,"asL":3.3,"rng":125,"ms":345,"t":"P"},"ab":[["Düşene Tekme","P","Zed'in düşük cana sahip rakiplere yönelik normal saldırıları ilave büyü hasarı verir. Bu etki aynı rakip şampiyon üstünde sadece birkaç saniyede bir gerçekleşebilir.","img/abil/zed-p.png"],["Keskin Shuriken","Q","Zed ve gölgeleri shuriken'lerini fırlatır. Her bir shuriken isabet ettiği bütün rakiplere hasar verir.","img/abil/zed-q.png",[6,6,6,6,6]],["Canlı Gölge","W","Pasif: Zed ve gölgeleri bir rakibe aynı yeteneği isabet ettirdiğinde Zed enerji kazanır. Kullanılan her yetenek başına sadece bir defa enerji kazanılabilir. Aktif: Zed'in gölgesi ileri atılır ve birkaç saniye boyunca atıldığı noktada kalır. Canlı Gölge yeniden kullanıldığında Zed gölgesiyle yer değiştirir.","img/abil/zed-w.png",[20,19,18,17,16]],["Gölge Darbesi","E","Zed ve gölgeleri saldırarak yakındaki rakiplere hasar verir. Gölgeden isabet alan rakipler yavaşlar.","img/abil/zed-e.png",[5,4.5,4,3.5,3]],["Ölüm İşareti","R","Zed hedef alınamaz hale gelerek bir rakip şampiyonun üzerine atılır ve onu işaretler. İşaret 3 saniyenin ardından tetiklenir ve hedef işaretliyken Zed'in ona verdiği tüm hasarın bir bölümünü tekrarlar.","img/abil/zed-r.png",[120,110,100]]],"wk":"Zed","p":"img/champ/zed.png","tip":[["Enerji ve büyü bekleme sürelerini ultini kullanana kadar saklamak, Ölüm İşareti'nin hasarını azami seviyeye çıkaracaktır.","Canlı Gölge'ye hızla çift tıklamak, Zed'in derhal gölgesine ışınlanarak hızla kaçmasını sağlar.","Ölüm İşareti'ni kullanmadan önce bir Canlı Gölge yerleştirmek, Zed'in çatışmadan güvenli biçimde kaçmasına olanak tanır."],["Zed satın aldığı Saldırı Gücü eşyalarından ilave etkiler kazanır; o nedenle Zırh ona karşı çok etkilidir.","Hem hasarı hem de hareketliliği buna bağlı olduğundan, Zed Canlı Gölge'sini kullandıktan sonra en savunmasız durumundadır.","Zed'in Gölge Darbesi, sadece gölgesi sana vurursa seni yavaşlatabilir."]]},"zeri":{"id":"Zeri","k":221,"n":"Zeri","en":"Zeri","t":"Zaun'un Kıvılcımı","cls":["Marksman"],"d":2,"res":"Mana","b":{"hp":600,"hpL":110,"ar":24,"arL":4.2,"mr":33,"mrL":1.1,"ad":56,"adL":2,"as":0.658,"asR":0.625,"asL":2,"rng":550,"ms":330,"t":"P"},"ab":[["Canlı Batarya","P","Zeri'nin saldırıları büyü hasarı verir ve yetenek sayılır. Hareket etmek ve Taramalı yeteneğini kullanmak Zeri'nin kıvılcım cihazında enerji biriktirir. Tam yüke ulaştığında bir sonraki saldırısı ilave hasar verir.","img/abil/zeri-p.png"],["Taramalı","Q","Taramalı isabet ettiği ilk rakibe saldırı hasarı veren 7 atış yapar. Bu yetenek, saldırı sayılır.","img/abil/zeri-q.png",[0,0,0,0,0]],["Ultraşok Lazeri","W","Zeri isabet ettiği ilk rakibi yavaşlatan ve ona hasar veren bir elektrik dalgası gönderir. Dalga bir duvara isabet ederse, yayılarak uzun menzilli bir lazere dönüşür.","img/abil/zeri-w.png",[12,11,10,9,8]],["Kıvılcım Akımı","E","Zeri kısa bir mesafe atılır ve sonraki Taramalı atışını rakipleri deşip geçecek şekilde güçlendirir. Temas ettiği her yüzey şeklinin üstünden atlar ve kayarak ilerler.","img/abil/zeri-e.png",[24,22.5,21,19.5,18]],["Yıldırım Patlaması","R","Zeri bir elektrik patlaması oluşturur ve kendisini aşırı yükleyerek hasar artışı ve bir rakip şampiyona her saldırdığında yenilenen ve güçlenen, biriktirilebilir hareket hızı kazanır. Zeri aşırı yüklenmişken Taramalı atışları, daha hızlı ilerleyen ve rakiplerin arasında seken zincirleme yıldırımlar oluşturan bir üçlü atışa dönüşür.","img/abil/zeri-r.png",[80,75,70]]],"wk":"Zeri","p":"img/champ/zeri.png","tip":[[],[]]},"ziggs":{"id":"Ziggs","k":115,"n":"Ziggs","en":"Ziggs","t":"Sihirmayın Uzmanı","cls":["Mage"],"d":2,"res":"Mana","b":{"hp":606,"hpL":106,"ar":21,"arL":4.7,"mr":30,"mrL":1.3,"ad":55,"adL":3.1,"as":0.656,"asR":0.656000018119812,"asL":2,"rng":550,"ms":325,"t":"M"},"ab":[["Kısa Fitil","P","Düzenli aralıklarla Ziggs'in ilk normal saldırısı ek büyü hasarı verir. Bu bekleme süresi, Ziggs'in her yetenek kullanışında kısalır.","img/abil/ziggs-p.png"],["Seksek Bomba","Q","Ziggs sekerek ilerleyen ve büyü hasarı veren bir bomba fırlatır.","img/abil/ziggs-q.png",[6,5.5,5,4.5,4]],["Patlayıcı Lokumu","W","Ziggs kısa bir gecikmenin ardından ya da bu yetenek tekrar etkinleştirildiğinde infilak eden bir patlayıcı lokumu atar. Patlama, rakiplere büyü hasarı vererek onları uzağa savurur. Ziggs de uzağa savrulur ama hasar almaz. Ziggs, Patlayıcı Lokumu'nu kullanarak yıpranmış kuleleri hextech gücüyle patlatabilir.","img/abil/ziggs-w.png",[20,18,16,14,12]],["Sihirmayın Tarlası","E","Ziggs, hedef bölgeye rakibe temas ettiğinde patlayıp büyü hasarı veren ve rakibi yavaşlatan mayınlar döşer. Aynı hedefin art arda üstüne bastığı mayınlar daha az hasar verir.","img/abil/ziggs-e.png",[16,16,16,16,16]],["Cehennem Bombası","R","Ziggs en büyük eseri olan Cehennem Bombası'nı olağanüstü uzak bir mesafeye savurur. Patlama bölgesinin ortasında kalan rakipler, uzaktakilere göre daha fazla hasar alır.","img/abil/ziggs-r.png",[120,95,70]]],"wk":"Ziggs","p":"img/champ/ziggs.png","tip":[["Bir çatışmadan uzak olsan da Cehennem Bombası'yla yardım edebilirsin.","Sihirmayın Tarlası ile rakipleri yavaşlatmak, diğer yetenekleri isabet ettirmeyi kolaylaştırır.","Patlayıcı Lokumu'yla duvarların üzerinden atlamak hem kovalarken hem de kovalanırken işine yarayabilir."],["Ziggs'in mayınlarına basma! Mayınlar seni yavaşlatacak ve diğer yeteneklerini isabet ettirmesini çok daha kolay hale getirecektir.","Ziggs'in yeteneklerinin çoğunun bekleme süreleri uzundur. Onu, yeteneklerini kullandıktan sonra yakalamaya çalışın.","Ziggs'in ultisi Cehennem Bombası, patlamanın merkezine daha fazla hasar verir."]]},"zilean":{"id":"Zilean","k":26,"n":"Zilean","en":"Zilean","t":"Zaman Bekçisi","cls":["Support","Mage"],"d":2,"res":"Mana","b":{"hp":574,"hpL":96,"ar":24,"arL":5,"mr":30,"mrL":1.3,"ad":52,"adL":3,"as":0.658,"asR":0.625,"asL":2.13,"rng":550,"ms":335,"t":"M"},"ab":[["Zaman Kumbarası","P","Zilean zamanı deneyim olarak biriktirir ve onu takım arkadaşlarına aktarabilir. Takım arkadaşlarından birinin seviyesini tamamlamaya yetecek kadar deneyim biriktirdiğinde, takım arkadaşına sağ tıklayarak bunu aktarabilir. Zilean da aynı miktarda deneyim kazanır.","img/abil/zilean-p.png"],["Saatli Bomba","Q","Hedef bölgeye doğru fırlattığı bomba, yakınından geçen birimlere yapışır (Şampiyonlara öncelik verir). Bomba 3 saniye sonra patlayarak alan etkili hasar verir. Yerleştirilen Saatli Bomba, başka bir Saatli Bomba tarafından erken patlatılırsa, ek olarak rakipleri sersemletir.","img/abil/zilean-q.png",[10,9.5,9,8.5,8]],["Başa Sar","W","Zilean diğer temel yeteneklerinin bekleme sürelerini azaltarak kendini önündeki çatışmalara hazırlayabilir.","img/abil/zilean-w.png",[14,12,10,8,6]],["Zamanı Bük","E","Zilean herhangi bir birimin etrafında zamanı bükerek kısa süreliğine rakiplerin hareket hızını azaltır veya takım arkadaşlarının hareket hızını arttırır.","img/abil/zilean-e.png",[15,15,15,15,15]],["Zaman Kayması","R","Zilean dost bir şampiyonun üzerine koruyucu bir zaman rünü işler ve ölümcül hasar alması halinde, zamanda geri dönmesini sağlar.","img/abil/zilean-r.png",[120,90,60]]],"wk":"Zilean","p":"img/champ/zilean.png","tip":[["Saatli Bomba ve Başa Sar'ı birleştirerek iki Saatli Bomba'yı bir hedefe çabucak yerleştirebilirsin. İkinci bombayı yerleştirmek ilkini patlatır ve yakındaki tüm rakipleri sersemletir.","Zamanı Bük, takım arkadaşlarının rakipleri katletmesine yardımcı olabilir ya da kaybedilen bir savaştan kaçmaya yarayabilir.","Zaman Kayması takımının taşıyıcılarına saldıranları caydırmak için güçlü bir araçtır ama Zaman Kayması'nı çatışmada çok erken kullanmak rakibin erkenden hedef değiştirmesine ve yeteneğin etkisinin azalmasına neden olur."],["Zilean'ın hızını yakalayabilirsen, öldürücü darbeyi vurmadan önce ultisinin bitmesini beklemek bazen yararına olabilir.","Takım ona odaklanırsa Zilean zayıf bir şampiyondur; ama aksi halde öldürmesi çok zordur. Onu takım olarak öldürmeye çalışın."]]},"zoe":{"id":"Zoe","k":142,"n":"Zoe","en":"Zoe","t":"Alacakaranlığın Sureti","cls":["Mage"],"d":2,"res":"Mana","b":{"hp":630,"hpL":106,"ar":21,"arL":4.7,"mr":30,"mrL":1.3,"ad":58,"adL":3.3,"as":0.658,"asR":0.625,"asL":2.5,"rng":550,"ms":340,"t":"M"},"ab":[["Pırıltı Şenliği","P","Zoe'nin bir yetenek kullandıktan sonraki ilk normal saldırısı ilave büyü hasarı verir.","img/abil/zoe-p.png"],["Uçarı Yıldız","Q","Zoe havadayken yönlendirebildiği bir atış yapar. Atış düz bir hatta ne kadar çok ilerlerse o kadar fazla hasar verir.","img/abil/zoe-q.png",[8.5,8,7.5,7,6.5]],["Büyü Hırsızı","W","Zoe rakiplerinin sihirdar büyüsü ve aktife sahip eşya kalıntılarını toplayıp onları bir defalığına kullanabilir. Her sihirdar büyüsü kullanışında en yakındaki hedefe yönelen 3 atış yapar.","img/abil/zoe-w.png",[0.25,0.25,0.25,0.25,0.25]],["Hınzır Uyku Baloncuğu","E","Hedefi önce uyuşturur sonra uyutur. Uyurken hedefin büyü direnci azalır. Uykuyu bölen ilk hasar, belli bir sınıra kadar ikiye katlanır.","img/abil/zoe-e.png",[18,17,16,15,14]],["Bi' Ordayım Bi' Burda","R","1 saniyeliğine yakındaki bir konuma ışınlanır. Sonra ilk yerine döner.","img/abil/zoe-r.png",[11,8,5]]],"wk":"Zoe","p":"img/champ/zoe.png","tip":[["Uçarı Yıldız ne kadar uzağa uçarsa o kadar fazla hasar verir. Yeteneği arkandan kullanıp sonra yönlendirmek yığınla hasar sağlar.","Uykuda olan rakipler iki kat hasar aldığı için uykularını en büyük hasar kaynağınla boz.","Hınzır Uyku Baloncuğu duvarların üstünden daha uzağa gider. Uzaktan skor almak için saklanacak uygun bir yer bul."],["Zoe'nin Uçarı Yıldız'ı ne kadar uzağa uçarsa o kadar fazla hasar verir.","Bi' Ordayım Bi' Burda kullandıktan sonra Zoe başlangıç noktasına döndüğü sırada karşı saldırılardan çok etkilenir.","Hınzır Uyku Baloncuğu duvarların üstünden daha uzağa gider. Yeteneğiyle tuzak kurmasını önlemek için Zoe'nin savaş sisine saklanmasını engelle."]]},"zyra":{"id":"Zyra","k":143,"n":"Zyra","en":"Zyra","t":"Dikenli Cazibe","cls":["Mage","Support"],"d":3,"res":"Mana","b":{"hp":574,"hpL":93,"ar":29,"arL":4.2,"mr":30,"mrL":1.3,"ad":53,"adL":3.2,"as":0.681,"asR":0.625,"asL":2.11,"rng":575,"ms":340,"t":"M"},"ab":[["Diken Bahçesi","P","Zyra çevresine düzenli aralıklarla tohumlar eker. Bu tohumlar seviye atladıkça daha hızlı ekilir ve Zyra tohumların yakınında Ölümcül Sarmaşık veya Kapan Kökler yeteneklerini kullanarak kendisi için savaşan bitkiler filizlendirir.","img/abil/zyra-p.png"],["Ölümcül Sarmaşık","Q","Yere yayılan kalın, dikenli sarmaşıklar patlayarak çevredeki rakiplere büyü hasarı verir. Bir tohumun yakınında kullanılırsa, Ölümcül Sarmaşık rakiplere uzaktan saldıran bir Diken Tüküren bitkisi filizlendirir.","img/abil/zyra-q.png",[7,6.5,6,5.5,5]],["Aşırı Büyüme","W","Zyra'nın ektiği tohum, 60 saniyeye kadar varlığını korur. Tohumlar, yakınlarında Ölümcül Sarmaşık veya Kapan Kökler yetenekleri kullanıldığında filizlenerek Zyra için savaşan bitkilere dönüşür. Zyra aynı anda birden fazla tohum bulundurabilir ve rakip katletmek Aşırı Büyüme'nin yenilenme süresini azaltır.","img/abil/zyra-w.png",[0,0,0,0,0]],["Kapan Kökler","E","Zyra'nın yerden gönderdiği sarmaşıklar hedefi sarmalayarak ona hasar verir ve önüne çıkan rakipleri yere sabitler. Bir tohumun yakınında kullanılırsa, Kapan Kökler'den bir Sarmaşık Kamçı filizlenerek kısa mesafeli saldırılarla rakibin hareket hızını düşürür.","img/abil/zyra-e.png",[11,11,11,11,11]],["Boğardikenler","R","Zyra hedef alanda habis bir fide oluşturur; fide alana yayılırken tüm rakiplere hasar verir ve alandan çekilirken rakipleri havaya savurur. Fidenin içerisindeki bitkiler hiddetlenir.","img/abil/zyra-r.png",[110,100,90]]],"wk":"Zyra","p":"img/champ/zyra.png","tip":[["Büyü yaptıktan sonra geçiş yoluna yerleştireceğin tohum, büyük olasılıkla çok doğru bir yerde olacaktır.","Tohumlar takımına görüş sağlar.","Zyra pusu konusunda harikadır. Çalılığa tohumlardan oluşan bir tuzak kurup, rakipleri tuzağa çekmek için fırsat kolla."],["Zyra'nın tohumları, üzerlerine basılarak yok edilebilir. Sen üstlerine basarken, Zyra bitki filizlendirmeye yeltenirse son anda çekilmeye çalış.","Bitkileri kendisinden fazla uzağa yerleştiriyorsa Zyra'ya yaklaşmak akıllıca olabilir.","Bitkiler tıpkı totemler gibi saldırı ve etkilerden sabit hasar alır. Ayrıca kendi başlarına bırakıldıklarında kısa sürede yok olurlar.","Çatışmayı farklı bir alana taşırsan, Zyra'yı biriktirdiği tohumların sağladığı avantajdan mahrum bırakabilirsin.","Zyra'nın W yeteneğiyle ektiği tohumlar hem daha büyük ve farklı renklidir hem de Zyra'nın takımına bir miktar görüş sağlar."]]}};
